package engine

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/ccr"
)

const engineAXTreeFixture = `[
  {
    "nodeId": "1",
    "role": {"type": "role", "value": "RootWebArea"},
    "name": {"type": "computedString", "value": "Caveman Console"},
    "backendDOMNodeId": 1,
    "childIds": ["2", "3", "5"]
  },
  {
    "nodeId": "2",
    "ignored": true,
    "role": {"type": "role", "value": "generic"},
    "name": {"type": "computedString", "value": "noise wrapper"},
    "childIds": ["4"]
  },
  {
    "nodeId": "4",
    "role": {"type": "role", "value": "button"},
    "name": {"type": "computedString", "value": "Save settings"},
    "backendDOMNodeId": 42,
    "properties": [
      {"name": "disabled", "value": {"type": "boolean", "value": false}},
      {"name": "focused", "value": {"type": "boolean", "value": true}}
    ]
  },
  {
    "nodeId": "3",
    "role": {"type": "role", "value": "generic"},
    "name": {"type": "computedString", "value": ""},
    "childIds": ["6"]
  },
  {
    "nodeId": "6",
    "role": {"type": "role", "value": "textbox"},
    "name": {"type": "computedString", "value": "Email address"},
    "value": {"type": "string", "value": "ops@example.com"},
    "backendDOMNodeId": 43,
    "properties": [
      {"name": "editable", "value": {"type": "token", "value": "plaintext"}}
    ]
  },
  {
    "nodeId": "5",
    "role": {"type": "role", "value": "custom-widget"},
    "name": {"type": "computedString", "value": "Mystery"}
  }
]`

func TestAXTreeEngineForcedOnlyCCRRoundTrip(t *testing.T) {
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { store.Close() })

	eng := New(store, nil)
	if got := eng.Detect([]byte(engineAXTreeFixture)); got != TypeJSON {
		t.Fatalf("AX tree must stay forced-only; Detect = %q, want json", got)
	}
	res, err := eng.Compress([]byte(engineAXTreeFixture), Options{Mode: ModeCompress, Type: TypeA11y})
	if err != nil {
		t.Fatalf("compress: %v", err)
	}
	if res.RecoveryHandle == "" || res.Ratio <= 0 || res.Basis != BasisInferred || res.Method != TypeA11y {
		t.Fatalf("unexpected result: %+v", res)
	}
	if res.LosslessToModel == nil || *res.LosslessToModel {
		t.Fatalf("a11y view must be labeled lossy-to-model: %+v", res)
	}
	original, err := eng.Retrieve(res.RecoveryHandle)
	if err != nil {
		t.Fatalf("retrieve: %v", err)
	}
	if !bytes.Equal(original, []byte(engineAXTreeFixture)) {
		t.Fatal("CCR did not recover byte-exact original AX tree")
	}
	meta, err := eng.RetrieveMetadata(res.RecoveryHandle)
	if err != nil {
		t.Fatalf("retrieve metadata: %v", err)
	}
	var uidMeta struct {
		UIDs map[string]struct {
			BackendDOMNodeID int    `json:"backendDOMNodeId"`
			NodeID           string `json:"nodeId"`
		} `json:"uids"`
	}
	if err := json.Unmarshal(meta, &uidMeta); err != nil {
		t.Fatalf("decode uid map metadata: %v", err)
	}
	if got := uidMeta.UIDs["u16"].BackendDOMNodeID; got != 42 {
		t.Fatalf("uid map did not preserve action target: got backend id %d", got)
	}
}

func TestAXTreeNoCCRPassesThrough(t *testing.T) {
	eng := New(nil, nil)
	res, err := eng.Compress([]byte(engineAXTreeFixture), Options{Mode: ModeCompress, Type: TypeA11y})
	if err != nil {
		t.Fatalf("compress: %v", err)
	}
	if !bytes.Equal(res.Output, []byte(engineAXTreeFixture)) || res.RecoveryHandle != "" || res.Ratio != 0 {
		t.Fatalf("S4 compressor without CCR must pass through, got %+v", res)
	}
}

func TestAXTreeCapturedCDPFixtureReductionAndExactRecovery(t *testing.T) {
	// Captured from Chrome headless via Accessibility.getFullAXTree against a
	// local data: page. Keep this as real CDP shape coverage; high-noise curation
	// is covered separately in compressors/testdata/axtree_high_noise.json.
	input, err := os.ReadFile("compressors/testdata/axtree_cdp_local_page.json")
	if err != nil {
		t.Fatal(err)
	}
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { store.Close() })

	eng := New(store, nil)
	res, err := eng.Compress(input, Options{Mode: ModeCompress, Type: TypeA11y})
	if err != nil {
		t.Fatalf("compress: %v", err)
	}
	if res.Basis != BasisInferred || res.Ratio <= 0 || res.RecoveryHandle == "" {
		t.Fatalf("fixture should report inferred reduction with recovery: %+v", res)
	}
	original, err := eng.Retrieve(res.RecoveryHandle)
	if err != nil {
		t.Fatalf("retrieve: %v", err)
	}
	if !bytes.Equal(original, input) {
		t.Fatal("fixture recovery was not byte-exact")
	}
	meta, err := eng.RetrieveMetadata(res.RecoveryHandle)
	if err != nil {
		t.Fatalf("retrieve metadata: %v", err)
	}
	var uidMeta struct {
		UIDs map[string]struct {
			BackendDOMNodeID int `json:"backendDOMNodeId"`
		} `json:"uids"`
	}
	if err := json.Unmarshal(meta, &uidMeta); err != nil {
		t.Fatalf("decode uid metadata: %v", err)
	}
	if uidMeta.UIDs["ua"].BackendDOMNodeID != 10 {
		t.Fatalf("fixture uid map missing captured button target: %+v", uidMeta.UIDs["ua"])
	}
}

//go:build !js

package ccr

import (
	"errors"
	"testing"
	"time"
)

func TestRetryOnBusyCapsTotalBackoff(t *testing.T) {
	busy := errors.New("SQLITE_BUSY")
	now := time.Unix(0, 0)
	var slept time.Duration
	calls := 0
	err := retryOnBusy(
		func() error {
			calls++
			return busy
		},
		100*time.Millisecond,
		func() time.Time { return now },
		func(delay time.Duration) {
			slept += delay
			now = now.Add(delay)
		},
	)
	if !errors.Is(err, busy) {
		t.Fatalf("err=%v want SQLITE_BUSY", err)
	}
	if slept != 100*time.Millisecond {
		t.Fatalf("slept=%s want capped 100ms", slept)
	}
	if calls != 3 {
		t.Fatalf("calls=%d want 3 attempts before deadline", calls)
	}
}

func TestRetryOnBusyReturnsNonBusyErrorWithoutSleeping(t *testing.T) {
	want := errors.New("migration failed")
	slept := false
	err := retryOnBusy(
		func() error { return want },
		time.Second,
		time.Now,
		func(time.Duration) { slept = true },
	)
	if !errors.Is(err, want) {
		t.Fatalf("err=%v want %v", err, want)
	}
	if slept {
		t.Fatal("non-busy error must not sleep")
	}
}

//go:build !windows && !js

package ccr

import (
	"fmt"
	"os"
)

func validateSQLiteParentSecurity(path string, info os.FileInfo) error {
	// Sticky shared temp directories (/tmp, macOS /private/tmp) prevent another
	// user from replacing the 0600 file. Other group/world-writable parents do not.
	if info.Mode().Perm()&0o022 != 0 && info.Mode()&os.ModeSticky == 0 {
		return fmt.Errorf("sqlite parent %q is group/world writable", path)
	}
	return nil
}

//go:build windows && !js

package ccr

import (
	"fmt"
	"os"
	"unsafe"

	"golang.org/x/sys/windows"
)

func validateSQLiteParentSecurity(path string, _ os.FileInfo) error {
	descriptor, err := windows.GetNamedSecurityInfo(
		path,
		windows.SE_FILE_OBJECT,
		windows.DACL_SECURITY_INFORMATION,
	)
	if err != nil {
		return fmt.Errorf("inspect sqlite parent ACL %q: %w", path, err)
	}
	if descriptor == nil {
		return fmt.Errorf("sqlite parent %q has no security descriptor", path)
	}
	dacl, _, err := descriptor.DACL()
	if err != nil || dacl == nil {
		return fmt.Errorf("sqlite parent %q has no restrictive DACL", path)
	}
	broad, err := windowsACLGrantsBroadWrite(dacl)
	if err != nil {
		return fmt.Errorf("inspect sqlite parent ACL %q: %w", path, err)
	}
	if broad {
		return fmt.Errorf("sqlite parent %q grants broad Windows write access", path)
	}
	return nil
}

func windowsACLGrantsBroadWrite(dacl *windows.ACL) (bool, error) {
	broadSIDs := make([]*windows.SID, 0, 4)
	for _, sidType := range []windows.WELL_KNOWN_SID_TYPE{
		windows.WinWorldSid,
		windows.WinAuthenticatedUserSid,
		windows.WinBuiltinUsersSid,
		windows.WinBuiltinGuestsSid,
	} {
		sid, err := windows.CreateWellKnownSid(sidType)
		if err != nil {
			return false, err
		}
		broadSIDs = append(broadSIDs, sid)
	}
	const deleteChild windows.ACCESS_MASK = 0x00000040
	writeMask := windows.ACCESS_MASK(
		windows.FILE_WRITE_DATA|
			windows.FILE_APPEND_DATA|
			windows.DELETE|
			windows.WRITE_DAC|
			windows.WRITE_OWNER|
			windows.GENERIC_WRITE|
			windows.GENERIC_ALL,
	) | deleteChild
	for i := uint32(0); i < uint32(dacl.AceCount); i++ {
		var ace *windows.ACCESS_ALLOWED_ACE
		if err := windows.GetAce(dacl, i, &ace); err != nil {
			return false, err
		}
		if ace.Header.AceType != windows.ACCESS_ALLOWED_ACE_TYPE || ace.Header.AceFlags&windows.INHERIT_ONLY_ACE != 0 {
			continue
		}
		if ace.Mask&writeMask == 0 {
			continue
		}
		aceSID := (*windows.SID)(unsafe.Pointer(&ace.SidStart))
		for _, broadSID := range broadSIDs {
			if broadSID.Equals(aceSID) {
				return true, nil
			}
		}
	}
	return false, nil
}

//go:build windows && !js

package ccr

import (
	"testing"

	"golang.org/x/sys/windows"
)

func TestWindowsACLRejectsBroadWriteGrant(t *testing.T) {
	descriptor, err := windows.SecurityDescriptorFromString("D:(A;OICI;GA;;;WD)")
	if err != nil {
		t.Fatal(err)
	}
	dacl, _, err := descriptor.DACL()
	if err != nil {
		t.Fatal(err)
	}
	broad, err := windowsACLGrantsBroadWrite(dacl)
	if err != nil {
		t.Fatal(err)
	}
	if !broad {
		t.Fatal("Everyone generic-all ACE was accepted")
	}
}

func TestWindowsACLAllowsBroadReadOnlyGrant(t *testing.T) {
	descriptor, err := windows.SecurityDescriptorFromString("D:(A;OICI;GRGX;;;WD)")
	if err != nil {
		t.Fatal(err)
	}
	dacl, _, err := descriptor.DACL()
	if err != nil {
		t.Fatal(err)
	}
	broad, err := windowsACLGrantsBroadWrite(dacl)
	if err != nil {
		t.Fatal(err)
	}
	if broad {
		t.Fatal("Everyone read/execute ACE was rejected")
	}
}

// Package ccr is the Caveman Context Recovery store: it keeps the exact original
// bytes of every lossy (S4) compression, keyed by a handle, so retrieve(handle)
// returns the original byte-for-byte and nothing the engine compresses is ever
// destroyed.
//
// The handle is content-addressed (sha256 of the original), which makes the
// engine idempotent — compressing the same payload twice yields the same handle
// and stores it once.
//
// The Store implementation is platform-split: a local SQLite database on host
// platforms (store_sqlite.go) and a pure-Go in-memory map under js/wasm
// (store_wasm.go), since modernc.org/sqlite does not build for js/wasm. Both
// expose the same type and methods, so the engine is unaware of the difference.
package ccr

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"
)

// ErrNotFound is returned by Get when a handle is unknown. The store never
// guesses a recovery — an unknown handle is an explicit miss.
var ErrNotFound = errors.New("ccr: recovery handle not found")

// ErrBudgetExceeded means a new recovery was refused before publishing lossy
// bytes because the local store's configured payload budget would be exceeded.
// Existing handles remain intact and retrievable; callers must pass through.
var ErrBudgetExceeded = errors.New("ccr: storage budget exceeded")

// ObjectType is a closed typed-working-memory enum. Unknown values fail closed:
// adapters may preserve unknown native payloads outside CCR, but may not invent
// retrieval semantics for them.
type ObjectType string

const (
	ObjectFileObservation      ObjectType = "FileObservation"
	ObjectSearchResult         ObjectType = "SearchResult"
	ObjectCommandResult        ObjectType = "CommandResult"
	ObjectTestResult           ObjectType = "TestResult"
	ObjectBuildResult          ObjectType = "BuildResult"
	ObjectDiffSnapshot         ObjectType = "DiffSnapshot"
	ObjectTaskContract         ObjectType = "TaskContract"
	ObjectTaskDecision         ObjectType = "TaskDecision"
	ObjectExecutionState       ObjectType = "ExecutionState"
	ObjectDocumentationExcerpt ObjectType = "DocumentationExcerpt"
	ObjectBrowserSnapshot      ObjectType = "BrowserSnapshot"
	ObjectRepositoryMap        ObjectType = "RepositoryMap"
	ObjectEvidenceBundle       ObjectType = "EvidenceBundle"
)

type Currentness string

const (
	Current  Currentness = "current"
	Stale    Currentness = "stale"
	Archived Currentness = "archived"
)

type Lifecycle string

const (
	Hot               Lifecycle = "hot"
	Warm              Lifecycle = "warm"
	Cold              Lifecycle = "cold"
	LifecycleArchived Lifecycle = "archived"
)

// Object is one exact typed working-memory record. Data remains byte-exact;
// masking lives above this store and must retain ObjectID as its recovery path.
type Object struct {
	ID                 string      `json:"object_id"`
	Type               ObjectType  `json:"type"`
	ContentHash        string      `json:"content_hash"`
	Source             string      `json:"source"`
	CreatedAt          time.Time   `json:"created_at"`
	RepositoryState    string      `json:"repository_state"`
	SessionID          string      `json:"session_id"`
	TransformVersion   string      `json:"transform_version"`
	Currentness        Currentness `json:"currentness"`
	Lifecycle          Lifecycle   `json:"lifecycle"`
	Dependencies       []string    `json:"dependencies"`
	OriginalByteLength int         `json:"original_byte_length"`
	StoredByteLength   int         `json:"stored_byte_length"`
	Data               []byte      `json:"data"`
}

var objectTypes = map[ObjectType]struct{}{
	ObjectFileObservation: {}, ObjectSearchResult: {}, ObjectCommandResult: {},
	ObjectTestResult: {}, ObjectBuildResult: {}, ObjectDiffSnapshot: {},
	ObjectTaskContract: {}, ObjectTaskDecision: {}, ObjectExecutionState: {},
	ObjectDocumentationExcerpt: {}, ObjectBrowserSnapshot: {},
	ObjectRepositoryMap: {}, ObjectEvidenceBundle: {},
}

func prepareObject(obj Object) (Object, error) {
	if _, ok := objectTypes[obj.Type]; !ok {
		return Object{}, fmt.Errorf("ccr: unknown object type %q", obj.Type)
	}
	if strings.TrimSpace(obj.SessionID) == "" {
		return Object{}, errors.New("ccr: typed object session_id is required")
	}
	if obj.Currentness == "" {
		obj.Currentness = Current
	}
	if obj.Currentness != Current && obj.Currentness != Stale && obj.Currentness != Archived {
		return Object{}, fmt.Errorf("ccr: unknown currentness %q", obj.Currentness)
	}
	if obj.Lifecycle == "" {
		obj.Lifecycle = Hot
	}
	if obj.Lifecycle != Hot && obj.Lifecycle != Warm && obj.Lifecycle != Cold && obj.Lifecycle != LifecycleArchived {
		return Object{}, fmt.Errorf("ccr: unknown lifecycle %q", obj.Lifecycle)
	}
	if obj.CreatedAt.IsZero() {
		obj.CreatedAt = time.Now().UTC()
	} else {
		obj.CreatedAt = obj.CreatedAt.UTC()
	}
	dataSum := sha256.Sum256(obj.Data)
	computedHash := "sha256:" + hex.EncodeToString(dataSum[:])
	if obj.ContentHash == "" {
		obj.ContentHash = computedHash
	} else if obj.ContentHash != computedHash {
		return Object{}, errors.New("ccr: typed object content_hash does not match data")
	}
	if obj.OriginalByteLength == 0 {
		obj.OriginalByteLength = len(obj.Data)
	}
	if obj.StoredByteLength == 0 {
		obj.StoredByteLength = len(obj.Data)
	}
	if obj.OriginalByteLength < 0 || obj.StoredByteLength < 0 {
		return Object{}, errors.New("ccr: typed object byte lengths cannot be negative")
	}
	if obj.ID == "" {
		identity := strings.Join([]string{string(obj.Type), obj.SessionID, obj.Source, obj.RepositoryState, obj.ContentHash}, "\x00")
		sum := sha256.Sum256([]byte(identity))
		obj.ID = "ccr_obj_" + hex.EncodeToString(sum[:16])
	}
	obj.Dependencies = append([]string(nil), obj.Dependencies...)
	obj.Data = bytes.Clone(obj.Data)
	return obj, nil
}

// sameImmutableObject compares fields PutObject promises never to change.
// CreatedAt is assigned at first storage, while currentness and lifecycle have
// explicit mutation methods, so repeat puts intentionally do not compare them.
func sameImmutableObject(left, right Object) bool {
	return left.ID == right.ID &&
		left.Type == right.Type &&
		left.ContentHash == right.ContentHash &&
		left.Source == right.Source &&
		left.RepositoryState == right.RepositoryState &&
		left.SessionID == right.SessionID &&
		left.TransformVersion == right.TransformVersion &&
		slices.Equal(left.Dependencies, right.Dependencies) &&
		left.OriginalByteLength == right.OriginalByteLength &&
		left.StoredByteLength == right.StoredByteLength &&
		bytes.Equal(left.Data, right.Data)
}

func validateCurrentness(value Currentness) error {
	if value != Current && value != Stale && value != Archived {
		return fmt.Errorf("ccr: unknown currentness %q", value)
	}
	return nil
}

func validateLifecycle(value Lifecycle) error {
	if value != Hot && value != Warm && value != Cold && value != LifecycleArchived {
		return fmt.Errorf("ccr: unknown lifecycle %q", value)
	}
	return nil
}

// Recovery is one stored original payload plus the accounting needed for stats.
type Recovery struct {
	ContentType  string
	Compressor   string
	TokensBefore int
	TokensAfter  int
	Original     []byte
	Metadata     []byte
}

// Bucket is aggregate compression accounting for one content type (or the total).
type Bucket struct {
	Count        int     `json:"count"`
	TokensBefore int     `json:"tokens_before"`
	TokensAfter  int     `json:"tokens_after"`
	Ratio        float64 `json:"ratio"`
}

// Stats is the engine's aggregate view, drawn from stored recoveries.
type Stats struct {
	Totals        Bucket            `json:"totals"`
	ByContentType map[string]Bucket `json:"by_content_type"`
	// Basis identifies the local token-count basis used for these ratios.
	Basis string `json:"basis"`
	// StorageBytes is exact retained payload+metadata bytes, not SQLite file
	// overhead. MaxStorageBytes is the configured hard logical budget.
	StorageBytes    int64 `json:"storage_bytes,omitempty"`
	MaxStorageBytes int64 `json:"max_storage_bytes,omitempty"`
	StorageFull     bool  `json:"storage_full,omitempty"`
}

// Handle returns the content-addressed handle for a payload without storing it.
func Handle(original []byte) string {
	sum := sha256.Sum256(original)
	return "ccr_" + hex.EncodeToString(sum[:16])
}

func ratio(before, after int) float64 {
	if before <= 0 {
		return 0
	}
	return float64(before-after) / float64(before)
}

//go:build !js

package ccr

import (
	"bytes"
	"path/filepath"
	"strconv"
	"testing"
)

func TestPutObjectReturnsStorageFullInsteadOfMintingHandle(t *testing.T) {
	store, err := Open(filepath.Join(t.TempDir(), "ccr.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	var pages int
	if err := store.db.QueryRow(`PRAGMA page_count`).Scan(&pages); err != nil {
		t.Fatal(err)
	}
	if _, err := store.db.Exec(`PRAGMA max_page_count = ` + strconv.Itoa(pages)); err != nil {
		t.Fatal(err)
	}
	if _, err := store.PutObject(Object{
		Type: ObjectFileObservation, SessionID: "storage-full", Source: "test",
		Data: bytes.Repeat([]byte("exact-context"), 1024*1024),
	}); err == nil {
		t.Fatal("full CCR storage accepted object and could expose a false recovery handle")
	}
}

//go:build !js

package ccr

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

func TestOpenSecuresDatabaseAndSidecarPermissions(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX permission bits are not meaningful on Windows")
	}
	path := filepath.Join(t.TempDir(), "ccr.db")
	if err := os.WriteFile(path, []byte{}, 0o666); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, 0o666); err != nil {
		t.Fatal(err)
	}
	store, err := Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	for _, candidate := range []string{path, path + "-wal", path + "-shm"} {
		info, err := os.Stat(candidate)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			t.Fatal(err)
		}
		if got := info.Mode().Perm(); got != 0o600 {
			t.Fatalf("%s permissions = %04o, want 0600", candidate, got)
		}
	}
}

func TestOpenRejectsDatabaseSymlink(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlink creation requires privileges on Windows")
	}
	dir := t.TempDir()
	target := filepath.Join(dir, "target")
	if err := os.WriteFile(target, nil, 0o600); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(dir, "ccr.db")
	if err := os.Symlink(target, link); err != nil {
		t.Fatal(err)
	}
	if _, err := Open(link); err == nil {
		t.Fatal("symlink database accepted")
	}
}

func TestOpenRejectsWritableParentDirectory(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("POSIX writable-parent setup does not model a Windows DACL")
	}
	dir := filepath.Join(t.TempDir(), "shared")
	if err := os.Mkdir(dir, 0o777); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(dir, 0o777); err != nil {
		t.Fatal(err)
	}
	if _, err := Open(filepath.Join(dir, "ccr.db")); err == nil {
		t.Fatal("database in group/world-writable parent accepted")
	}
}

func TestOpenAllowsStickyTemporaryDirectory(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "sticky")
	if err := os.Mkdir(dir, 0o777); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(dir, 0o777|os.ModeSticky); err != nil {
		t.Fatal(err)
	}
	store, err := Open(filepath.Join(dir, "ccr.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
}

func TestOpenAllowsResolvedStickyParentSymlink(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlink creation requires privileges on Windows")
	}
	root := t.TempDir()
	target := filepath.Join(root, "sticky")
	if err := os.Mkdir(target, 0o777); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(target, 0o777|os.ModeSticky); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(root, "tmp-link")
	if err := os.Symlink(target, link); err != nil {
		t.Fatal(err)
	}
	store, err := Open(filepath.Join(link, "ccr.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
}

func TestOpenUsesCanonicalParentAfterSymlinkSwap(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlink creation requires privileges on Windows")
	}
	root := t.TempDir()
	validated := filepath.Join(root, "validated")
	redirected := filepath.Join(root, "redirected")
	if err := os.Mkdir(validated, 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.Mkdir(redirected, 0o700); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(root, "db-parent")
	if err := os.Symlink(validated, link); err != nil {
		t.Fatal(err)
	}
	store, err := openWithBudget(filepath.Join(link, "ccr.db"), DefaultMaxStorageBytes, func() {
		if err := os.Remove(link); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink(redirected, link); err != nil {
			t.Fatal(err)
		}
	})
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	if _, err := os.Stat(filepath.Join(validated, "ccr.db")); err != nil {
		t.Fatalf("validated database missing: %v", err)
	}
	if _, err := os.Stat(filepath.Join(redirected, "ccr.db")); !os.IsNotExist(err) {
		t.Fatalf("redirected database created: %v", err)
	}
}

//go:build !js

// The host (non-js/wasm) recovery store: a local SQLite database under
// ~/.caveman/. The js/wasm build uses the in-memory store in store_wasm.go.
package ccr

import (
	"bytes"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// Store is a SQLite-backed recovery store.
type Store struct {
	db       *sql.DB
	maxBytes int64
}

const DefaultMaxStorageBytes int64 = 512 << 20 // 512 MiB retained payloads

const schema = `
CREATE TABLE IF NOT EXISTS recoveries (
  handle TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  content_type TEXT NOT NULL,
  compressor TEXT NOT NULL,
  tokens_before INTEGER NOT NULL,
  tokens_after INTEGER NOT NULL,
  original BLOB NOT NULL,
  metadata BLOB
);
CREATE TABLE IF NOT EXISTS typed_objects (
  object_id TEXT PRIMARY KEY,
  object_type TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  source TEXT NOT NULL,
  created_at TEXT NOT NULL,
  repository_state TEXT NOT NULL,
  session_id TEXT NOT NULL,
  transform_version TEXT NOT NULL,
  currentness TEXT NOT NULL,
  lifecycle TEXT NOT NULL,
  dependencies_json TEXT NOT NULL,
  original_byte_length INTEGER NOT NULL,
  stored_byte_length INTEGER NOT NULL,
  data BLOB NOT NULL
);
CREATE INDEX IF NOT EXISTS typed_objects_session_created
  ON typed_objects(session_id, created_at DESC);`

// SQLiteDSN builds the driver DSN for path. The two pragmas are load-bearing,
// not tuning: this recovery store is opened once per CLI process (caveman-mcp,
// cavemem, caveman-engine, caveman-browse) yet several such processes share one
// ~/.caveman/*.db file. Without journal_mode(WAL) a reader is locked out while a
// write is in flight, and without busy_timeout a contender returns SQLITE_BUSY
// instead of waiting — a lost Put means an elided payload with no recoverable
// original, and a lost Get reads as an unknown handle. This mirrors the exact
// reasoning used by the other local SQLite store; the two must not diverge.
func SQLiteDSN(path string) string {
	const pragmas = "_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)"
	if path == ":memory:" {
		return "file::memory:?" + pragmas
	}
	// A file: URI so a path containing '?' or '#' cannot be truncated into a
	// different database file by the driver's DSN split.
	u := url.URL{Scheme: "file", OmitHost: true, Path: path}
	return u.String() + "?" + pragmas
}

// RetryOnBusy runs fn, retrying while SQLite reports the database is locked
// (SQLITE_BUSY). Short-lived local processes can initialize the same database
// concurrently, and a multi-statement migration can hold the write lock longer
// than a single connection's busy_timeout. Retries have a five-second wall-clock
// budget; one already-running SQLite call may finish after that deadline, but no
// new attempt starts after it.
// Runtime single-statement writes are covered by busy_timeout alone and must
// NOT route through here — a retry loop around ordinary contention would only
// mask a real stall.
func RetryOnBusy(fn func() error) error {
	return retryOnBusy(fn, 5*time.Second, time.Now, time.Sleep)
}

func retryOnBusy(fn func() error, maxWait time.Duration, now func() time.Time, sleep func(time.Duration)) error {
	const attempts = 40
	deadline := now().Add(maxWait)
	var err error
	for i := 0; i < attempts; i++ {
		if i > 0 && !now().Before(deadline) {
			return err
		}
		if err = fn(); err == nil || !isBusy(err) {
			return err
		}
		remaining := deadline.Sub(now())
		if remaining <= 0 {
			return err
		}
		delay := time.Duration(25*(i+1)) * time.Millisecond
		if delay > remaining {
			delay = remaining
		}
		sleep(delay)
	}
	return err
}

func isBusy(err error) bool {
	if err == nil {
		return false
	}
	s := err.Error()
	return strings.Contains(s, "database is locked") || strings.Contains(s, "SQLITE_BUSY")
}

// Open opens (creating if needed) the SQLite database at path and migrates the
// schema. Use ":memory:" for an ephemeral store (tests, the eval harness).
func Open(path string) (*Store, error) {
	maxBytes := DefaultMaxStorageBytes
	if raw := strings.TrimSpace(os.Getenv("CAVEMAN_CCR_MAX_BYTES")); raw != "" {
		parsed, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || parsed <= 0 {
			return nil, fmt.Errorf("CAVEMAN_CCR_MAX_BYTES must be a positive integer")
		}
		maxBytes = parsed
	}
	return OpenWithBudget(path, maxBytes)
}

// OpenWithBudget opens a persistent store with an explicit retained-payload
// budget. New writes fail with ErrBudgetExceeded; existing recovery rows are
// never evicted because an emitted transformed request may still reference any
// handle.
func OpenWithBudget(path string, maxBytes int64) (*Store, error) {
	return openWithBudget(path, maxBytes, nil)
}

func openWithBudget(path string, maxBytes int64, afterPrepare func()) (*Store, error) {
	if maxBytes <= 0 {
		return nil, fmt.Errorf("ccr max storage bytes must be positive")
	}
	canonicalPath, err := PrepareSQLitePathCanonical(path)
	if err != nil {
		return nil, err
	}
	if afterPrepare != nil {
		afterPrepare()
	}
	db, err := sql.Open("sqlite", SQLiteDSN(canonicalPath))
	if err != nil {
		return nil, fmt.Errorf("open sqlite %q: %w", canonicalPath, err)
	}
	// One writer connection. With a single connection every statement serializes
	// in-process (no self-contention) while busy_timeout absorbs cross-process
	// contention; it is also mandatory for an in-memory DSN, where a second
	// pooled connection would be a second, empty database.
	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(1)
	if err := RetryOnBusy(func() error { _, e := db.Exec(schema); return e }); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("migrate sqlite %q: %w", canonicalPath, err)
	}
	if err := RetryOnBusy(func() error { return ensureMetadataColumn(db) }); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("migrate sqlite metadata %q: %w", canonicalPath, err)
	}
	if err := configureStorageBudget(db, maxBytes); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("configure sqlite storage budget %q: %w", canonicalPath, err)
	}
	if err := secureSQLiteFiles(canonicalPath); err != nil {
		_ = db.Close()
		return nil, err
	}
	// CCR is one local embedded database. Serialize access through one connection:
	// this prevents SQLITE_BUSY under background capture and keeps :memory:
	// stores on the same schema-bearing connection.
	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(1)
	return &Store{db: db, maxBytes: maxBytes}, nil
}

// PrepareSQLitePath creates or tightens a persistent SQLite file before the
// driver sees it. Recovery databases can contain prompts, credentials, and tool
// results, so neither a permissive umask nor a caller-supplied symlink may widen
// access. Existing WAL/SHM files receive the same checks.
func PrepareSQLitePath(path string) error {
	_, err := PrepareSQLitePathCanonical(path)
	return err
}

// PrepareSQLitePathCanonical secures path and returns the one canonical path
// callers must use for every subsequent open and sidecar check. Returning the
// resolved parent closes the check/use gap from a swappable parent symlink.
func PrepareSQLitePathCanonical(path string) (string, error) {
	if path == ":memory:" {
		return path, nil
	}
	if strings.TrimSpace(path) == "" {
		return "", fmt.Errorf("ccr sqlite path is required")
	}
	parent := filepath.Dir(path)
	absoluteParent, err := filepath.Abs(parent)
	if err != nil {
		return "", fmt.Errorf("resolve sqlite parent %q: %w", parent, err)
	}
	resolvedParent, err := filepath.EvalSymlinks(absoluteParent)
	if err != nil {
		return "", fmt.Errorf("resolve sqlite parent %q: %w", parent, err)
	}
	parentInfo, err := os.Stat(resolvedParent)
	if err != nil {
		return "", fmt.Errorf("inspect sqlite parent %q: %w", resolvedParent, err)
	}
	if !parentInfo.IsDir() {
		return "", fmt.Errorf("sqlite parent %q must be a directory", resolvedParent)
	}
	if err := validateSQLiteParentSecurity(resolvedParent, parentInfo); err != nil {
		return "", err
	}
	canonicalPath := filepath.Join(resolvedParent, filepath.Base(path))
	if err := secureSQLiteFile(canonicalPath, true); err != nil {
		return "", fmt.Errorf("secure sqlite %q: %w", canonicalPath, err)
	}
	for _, suffix := range []string{"-wal", "-shm"} {
		if err := secureSQLiteFile(canonicalPath+suffix, false); err != nil {
			return "", fmt.Errorf("secure sqlite sidecar %q: %w", canonicalPath+suffix, err)
		}
	}
	return canonicalPath, nil
}

func secureSQLiteFiles(path string) error {
	if err := PrepareSQLitePath(path); err != nil {
		return err
	}
	return nil
}

func secureSQLiteFile(path string, create bool) error {
	info, err := os.Lstat(path)
	if errors.Is(err, os.ErrNotExist) && create {
		file, createErr := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_RDWR, 0o600)
		if createErr == nil {
			return file.Close()
		}
		if !errors.Is(createErr, os.ErrExist) {
			return createErr
		}
		info, err = os.Lstat(path)
	}
	if errors.Is(err, os.ErrNotExist) && !create {
		return nil
	}
	if err != nil {
		return err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return fmt.Errorf("refusing non-regular file")
	}
	file, err := os.OpenFile(path, os.O_RDWR, 0)
	if errors.Is(err, os.ErrNotExist) && !create {
		// The sidecar vanished between Lstat and open — a concurrent process
		// checkpointed the WAL and removed it. Nothing left to secure.
		return nil
	}
	if err != nil {
		return err
	}
	defer file.Close()
	opened, err := file.Stat()
	if err != nil {
		return err
	}
	if !os.SameFile(info, opened) {
		return fmt.Errorf("file changed while opening")
	}
	return file.Chmod(0o600)
}

func configureStorageBudget(db *sql.DB, maxBytes int64) error {
	var pageSize int64
	if err := db.QueryRow(`PRAGMA page_size`).Scan(&pageSize); err != nil {
		return fmt.Errorf("read page size: %w", err)
	}
	if pageSize <= 0 {
		return errors.New("invalid sqlite page size")
	}
	maxPages := maxBytes / pageSize
	if maxPages < 16 {
		return fmt.Errorf("budget %d is below SQLite minimum %d", maxBytes, 16*pageSize)
	}
	var applied int64
	if err := db.QueryRow(fmt.Sprintf(`PRAGMA max_page_count=%d`, maxPages)).Scan(&applied); err != nil {
		return err
	}
	if applied < maxPages {
		maxPages = applied
	}
	autoCheckpoint := maxPages / 16
	if autoCheckpoint < 1 {
		autoCheckpoint = 1
	}
	if _, err := db.Exec(fmt.Sprintf(`PRAGMA wal_autocheckpoint=%d`, autoCheckpoint)); err != nil {
		return err
	}
	_, err := db.Exec(fmt.Sprintf(`PRAGMA journal_size_limit=%d`, maxBytes/8))
	return err
}

func ensureMetadataColumn(db *sql.DB) error {
	rows, err := db.Query(`PRAGMA table_info(recoveries)`)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var cid int
		var name, typ string
		var notNull, pk int
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &typ, &notNull, &dflt, &pk); err != nil {
			return err
		}
		if name == "metadata" {
			return rows.Err()
		}
	}
	if err := rows.Err(); err != nil {
		return err
	}
	_, err = db.Exec(`ALTER TABLE recoveries ADD COLUMN metadata BLOB`)
	return err
}

// OpenMemory opens an ephemeral in-memory store.
func OpenMemory() (*Store, error) { return OpenWithBudget(":memory:", DefaultMaxStorageBytes) }

// Close closes the underlying database.
func (s *Store) Close() error { return s.db.Close() }

// Put stores a recovery and returns its handle. It is idempotent: storing the
// same original twice (the handle is derived from the bytes) overwrites the row
// with identical content and returns the same handle.
func (s *Store) Put(rec Recovery) (string, error) {
	handle := Handle(rec.Original)
	unchanged, err := s.recoveryUnchanged(handle, rec)
	if err != nil {
		return "", fmt.Errorf("ccr put: %w", err)
	}
	if unchanged {
		return handle, nil
	}
	if err := s.checkRecoveryBudget(handle, int64(len(rec.Original)+len(rec.Metadata))); err != nil {
		return "", fmt.Errorf("ccr put: %w", err)
	}
	_, err = s.db.Exec(
		`INSERT INTO recoveries (handle, created_at, content_type, compressor, tokens_before, tokens_after, original, metadata)
		 VALUES (?,?,?,?,?,?,?,?)
		 ON CONFLICT(handle) DO UPDATE SET
		   created_at=excluded.created_at,
		   content_type=CASE WHEN excluded.tokens_before = 0 AND recoveries.tokens_before > 0 THEN recoveries.content_type ELSE excluded.content_type END,
		   compressor=CASE WHEN excluded.tokens_before = 0 AND recoveries.tokens_before > 0 THEN recoveries.compressor ELSE excluded.compressor END,
		   tokens_before=CASE WHEN excluded.tokens_before = 0 AND recoveries.tokens_before > 0 THEN recoveries.tokens_before ELSE excluded.tokens_before END,
		   tokens_after=CASE WHEN excluded.tokens_before = 0 AND recoveries.tokens_before > 0 THEN recoveries.tokens_after ELSE excluded.tokens_after END,
		   original=excluded.original,
		   metadata=CASE
		     WHEN recoveries.metadata IS NULL OR length(recoveries.metadata) = 0 THEN excluded.metadata
		     ELSE recoveries.metadata
		   END`,
		handle, time.Now().UTC().Format(time.RFC3339Nano),
		rec.ContentType, rec.Compressor, rec.TokensBefore, rec.TokensAfter, rec.Original, rec.Metadata,
	)
	if err != nil {
		if isFull(err) {
			return "", fmt.Errorf("ccr put: %w", ErrBudgetExceeded)
		}
		return "", fmt.Errorf("ccr put: %w", err)
	}
	return handle, nil
}

func (s *Store) recoveryUnchanged(handle string, rec Recovery) (bool, error) {
	var contentType, compressor string
	var tokensBefore, tokensAfter int
	var original, metadata []byte
	err := s.db.QueryRow(
		`SELECT content_type, compressor, tokens_before, tokens_after, original, metadata
		 FROM recoveries WHERE handle=?`,
		handle,
	).Scan(&contentType, &compressor, &tokensBefore, &tokensAfter, &original, &metadata)
	if errors.Is(err, sql.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return contentType == rec.ContentType &&
		compressor == rec.Compressor &&
		tokensBefore == rec.TokensBefore &&
		tokensAfter == rec.TokensAfter &&
		bytes.Equal(original, rec.Original) &&
		bytes.Equal(metadata, rec.Metadata), nil
}

func (s *Store) checkRecoveryBudget(handle string, newBytes int64) error {
	used, err := s.storageBytes()
	if err != nil {
		return err
	}
	var existing int64
	err = s.db.QueryRow(`SELECT COALESCE(length(original),0)+COALESCE(length(metadata),0) FROM recoveries WHERE handle=?`, handle).Scan(&existing)
	if errors.Is(err, sql.ErrNoRows) {
		existing = 0
	} else if err != nil {
		return err
	}
	if used-existing+newBytes > s.maxBytes {
		return ErrBudgetExceeded
	}
	return nil
}

func (s *Store) storageBytes() (int64, error) {
	var used int64
	err := s.db.QueryRow(`SELECT
	  COALESCE((SELECT SUM(length(original)+COALESCE(length(metadata),0)) FROM recoveries),0) +
	  COALESCE((SELECT SUM(length(data)+length(dependencies_json)) FROM typed_objects),0)`).Scan(&used)
	return used, err
}

func isFull(err error) bool {
	if err == nil {
		return false
	}
	text := strings.ToLower(err.Error())
	return strings.Contains(text, "database or disk is full") || strings.Contains(text, "sqlite_full")
}

// Get returns the exact original bytes for a handle, or ErrNotFound.
func (s *Store) Get(handle string) ([]byte, error) {
	if strings.HasPrefix(handle, "ccr_obj_") {
		obj, err := s.GetObject(handle)
		if err != nil {
			return nil, err
		}
		return append([]byte(nil), obj.Data...), nil
	}
	var original []byte
	row := s.db.QueryRow(`SELECT original FROM recoveries WHERE handle = ?`, handle)
	switch err := row.Scan(&original); {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrNotFound
	case err != nil:
		return nil, fmt.Errorf("ccr get: %w", err)
	}
	return original, nil
}

// GetMetadata returns optional compressor metadata stored with a handle. A known
// handle with no metadata returns nil, nil; an unknown handle returns ErrNotFound.
func (s *Store) GetMetadata(handle string) ([]byte, error) {
	if strings.HasPrefix(handle, "ccr_obj_") {
		if _, err := s.GetObject(handle); err != nil {
			return nil, err
		}
		return nil, nil
	}
	var metadata []byte
	row := s.db.QueryRow(`SELECT metadata FROM recoveries WHERE handle = ?`, handle)
	switch err := row.Scan(&metadata); {
	case errors.Is(err, sql.ErrNoRows):
		return nil, ErrNotFound
	case err != nil:
		return nil, fmt.Errorf("ccr metadata get: %w", err)
	}
	return metadata, nil
}

// PutObject stores one immutable typed working-memory object. Repeated puts of
// the same content-derived ID are idempotent; currentness changes use
// SetObjectCurrentness so invalidation stays explicit.
func (s *Store) PutObject(input Object) (string, error) {
	obj, err := prepareObject(input)
	if err != nil {
		return "", err
	}
	deps, err := json.Marshal(obj.Dependencies)
	if err != nil {
		return "", fmt.Errorf("ccr typed object dependencies: %w", err)
	}
	used, err := s.storageBytes()
	if err != nil {
		return "", fmt.Errorf("ccr typed object budget: %w", err)
	}
	var existingBytes int64
	err = s.db.QueryRow(`SELECT length(data)+length(dependencies_json) FROM typed_objects WHERE object_id=?`, obj.ID).Scan(&existingBytes)
	if errors.Is(err, sql.ErrNoRows) {
		existingBytes = 0
	} else if err != nil {
		return "", fmt.Errorf("ccr typed object budget: %w", err)
	}
	if used-existingBytes+int64(len(obj.Data)+len(deps)) > s.maxBytes {
		return "", fmt.Errorf("ccr typed object put: %w", ErrBudgetExceeded)
	}
	result, err := s.db.Exec(
		`INSERT INTO typed_objects (
		 object_id, object_type, content_hash, source, created_at, repository_state,
		 session_id, transform_version, currentness, lifecycle, dependencies_json,
		 original_byte_length, stored_byte_length, data
		) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)
		ON CONFLICT(object_id) DO NOTHING`,
		obj.ID, obj.Type, obj.ContentHash, obj.Source, obj.CreatedAt.Format(time.RFC3339Nano),
		obj.RepositoryState, obj.SessionID, obj.TransformVersion, obj.Currentness,
		obj.Lifecycle, string(deps), obj.OriginalByteLength, obj.StoredByteLength, obj.Data,
	)
	if err != nil {
		if isFull(err) {
			return "", fmt.Errorf("ccr typed object put: %w", ErrBudgetExceeded)
		}
		return "", fmt.Errorf("ccr typed object put: %w", err)
	}
	inserted, err := result.RowsAffected()
	if err != nil {
		return "", fmt.Errorf("ccr typed object put rows: %w", err)
	}
	if inserted == 0 {
		existing, err := s.GetObject(obj.ID)
		if err != nil {
			return "", fmt.Errorf("ccr typed object collision lookup: %w", err)
		}
		if !sameImmutableObject(existing, obj) {
			return "", errors.New("ccr: typed object id collision")
		}
	}
	return obj.ID, nil
}

func scanObject(scanner interface{ Scan(...any) error }) (Object, error) {
	var obj Object
	var created, deps string
	if err := scanner.Scan(
		&obj.ID, &obj.Type, &obj.ContentHash, &obj.Source, &created, &obj.RepositoryState,
		&obj.SessionID, &obj.TransformVersion, &obj.Currentness, &obj.Lifecycle, &deps,
		&obj.OriginalByteLength, &obj.StoredByteLength, &obj.Data,
	); err != nil {
		return Object{}, err
	}
	parsed, err := time.Parse(time.RFC3339Nano, created)
	if err != nil {
		return Object{}, fmt.Errorf("ccr typed object created_at: %w", err)
	}
	obj.CreatedAt = parsed
	if err := json.Unmarshal([]byte(deps), &obj.Dependencies); err != nil {
		return Object{}, fmt.Errorf("ccr typed object dependencies decode: %w", err)
	}
	return obj, nil
}

const objectColumns = `object_id, object_type, content_hash, source, created_at,
 repository_state, session_id, transform_version, currentness, lifecycle,
 dependencies_json, original_byte_length, stored_byte_length, data`

func (s *Store) GetObject(id string) (Object, error) {
	obj, err := scanObject(s.db.QueryRow(`SELECT `+objectColumns+` FROM typed_objects WHERE object_id = ?`, id))
	if errors.Is(err, sql.ErrNoRows) {
		return Object{}, ErrNotFound
	}
	if err != nil {
		return Object{}, fmt.Errorf("ccr typed object get: %w", err)
	}
	return obj, nil
}

func (s *Store) SetObjectCurrentness(id string, currentness Currentness) error {
	if err := validateCurrentness(currentness); err != nil {
		return err
	}
	result, err := s.db.Exec(`UPDATE typed_objects SET currentness = ? WHERE object_id = ?`, currentness, id)
	if err != nil {
		return fmt.Errorf("ccr typed object currentness: %w", err)
	}
	n, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("ccr typed object currentness rows: %w", err)
	}
	if n == 0 {
		return ErrNotFound
	}
	return nil
}

func (s *Store) SetObjectLifecycle(id string, lifecycle Lifecycle) error {
	if err := validateLifecycle(lifecycle); err != nil {
		return err
	}
	result, err := s.db.Exec(`UPDATE typed_objects SET lifecycle = ? WHERE object_id = ?`, lifecycle, id)
	if err != nil {
		return fmt.Errorf("ccr typed object lifecycle: %w", err)
	}
	n, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("ccr typed object lifecycle rows: %w", err)
	}
	if n == 0 {
		return ErrNotFound
	}
	return nil
}

func (s *Store) ListSessionObjects(sessionID string, limit int) ([]Object, error) {
	if limit <= 0 {
		limit = 100
	}
	if limit > 10000 {
		limit = 10000
	}
	rows, err := s.db.Query(`SELECT `+objectColumns+` FROM typed_objects WHERE session_id = ? ORDER BY created_at DESC, object_id DESC LIMIT ?`, sessionID, limit)
	if err != nil {
		return nil, fmt.Errorf("ccr typed object list: %w", err)
	}
	defer rows.Close()
	objects := make([]Object, 0)
	for rows.Next() {
		obj, err := scanObject(rows)
		if err != nil {
			return nil, fmt.Errorf("ccr typed object list scan: %w", err)
		}
		objects = append(objects, obj)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("ccr typed object list rows: %w", err)
	}
	return objects, nil
}

// FindTaskDecision returns one Decision Ledger object by its stable decision
// ID. Callers still validate the versioned decision schema before rendering it.
func (s *Store) FindTaskDecision(decisionID string) (Object, error) {
	obj, err := scanObject(s.db.QueryRow(
		`SELECT `+objectColumns+` FROM typed_objects
		 WHERE object_type = ? AND json_extract(CAST(data AS TEXT), '$.decision_id') = ?
		 ORDER BY created_at DESC, object_id DESC LIMIT 1`,
		ObjectTaskDecision, decisionID,
	))
	if errors.Is(err, sql.ErrNoRows) {
		return Object{}, ErrNotFound
	}
	if err != nil {
		return Object{}, fmt.Errorf("ccr task decision find: %w", err)
	}
	return obj, nil
}

// Summary aggregates stored recoveries into totals + per-content-type buckets.
func (s *Store) Summary() (Stats, error) {
	out := Stats{ByContentType: map[string]Bucket{}, Basis: "inferred"}
	rows, err := s.db.Query(
		`SELECT content_type, COUNT(*), COALESCE(SUM(tokens_before),0), COALESCE(SUM(tokens_after),0)
		 FROM recoveries GROUP BY content_type`)
	if err != nil {
		return out, fmt.Errorf("ccr summary: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var ct string
		var b Bucket
		if err := rows.Scan(&ct, &b.Count, &b.TokensBefore, &b.TokensAfter); err != nil {
			return out, fmt.Errorf("ccr summary scan: %w", err)
		}
		b.Ratio = ratio(b.TokensBefore, b.TokensAfter)
		out.ByContentType[ct] = b
		out.Totals.Count += b.Count
		out.Totals.TokensBefore += b.TokensBefore
		out.Totals.TokensAfter += b.TokensAfter
	}
	if err := rows.Err(); err != nil {
		return out, fmt.Errorf("ccr summary rows: %w", err)
	}
	if err := rows.Close(); err != nil {
		return out, fmt.Errorf("ccr summary close: %w", err)
	}
	out.Totals.Ratio = ratio(out.Totals.TokensBefore, out.Totals.TokensAfter)
	used, err := s.storageBytes()
	if err != nil {
		return out, fmt.Errorf("ccr summary storage: %w", err)
	}
	out.StorageBytes = used
	out.MaxStorageBytes = s.maxBytes
	out.StorageFull = used >= s.maxBytes
	return out, nil
}

