		t.Fatal(err)
	}
	defer s.Close()
	created := time.Date(2026, 8, 8, 12, 0, 0, 123, time.UTC)
	id, err := s.PutObject(ccr.Object{
		Type:               ccr.ObjectFileObservation,
		Source:             "src/auth.ts:10-30",
