	"github.com/JuliusBrussee/caveman/engine/pixel"
)

// lastPixelRenderSummary decodes the JSONL stream `pixel render` prints and returns
// the trailing summary object (the one with "summary":true).
func lastPixelRenderSummary(t *testing.T, out string) pixelRenderSummary {
	t.Helper()
	dec := json.NewDecoder(strings.NewReader(out))
	var summary pixelRenderSummary
	found := false
	for {
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			break
		}
		var probe struct {
			Summary bool `json:"summary"`
		}
		if json.Unmarshal(raw, &probe) == nil && probe.Summary {
			if err := json.Unmarshal(raw, &summary); err != nil {
				t.Fatalf("decode summary: %v", err)
			}
			found = true
		}
	}
	if !found {
		t.Fatalf("no summary line in render output:\n%s", out)
	}
	return summary
}

// The test-pinned per-page capacities used by the design. This checks them at
// the exported draw seam, so the render ratio test below has an exact anchor.
func TestStdDensityCapacityRatios(t *testing.T) {
	cons := pixel.StdDensityDraw(pixel.DensityConservative)
	bal := pixel.StdDensityDraw(pixel.DensityBalanced)
	mx := pixel.StdDensityDraw(pixel.DensityMax)
	if cons.CharBudget != 28080 || bal.CharBudget != 46291 || mx.CharBudget != 92582 {
		t.Fatalf("char budgets = %d/%d/%d, want 28080/46291/92582", cons.CharBudget, bal.CharBudget, mx.CharBudget)
	}
	if mx.Layers != 2 || cons.Layers != 1 || bal.Layers != 1 {
		t.Fatalf("layers = %d/%d/%d, want 1/1/2", cons.Layers, bal.Layers, mx.Layers)
	}
	balRatio := float64(bal.CharBudget) / float64(cons.CharBudget)
	maxRatio := float64(mx.CharBudget) / float64(cons.CharBudget)
	if math.Abs(balRatio-1.648) > 0.01 || math.Abs(maxRatio-3.296) > 0.01 {
		t.Fatalf("capacity ratios = %.3f / %.3f, want 1.648 / 3.296", balRatio, maxRatio)
	}
}

// End-to-end: the same document rendered at three levels must produce the
// expected page-count ordering, and each report's resolved `density` field must
// echo the level actually drawn. This pins renderer geometry.
func TestPixelRenderDensityPageRatios(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "doc.txt")
	// Many 1500-char spaceless lines: long enough that WrapLines packs near-full
	// lines at both column widths (so the column advantage shows as the capacity
	// ratio predicts), short enough to avoid the per-line quadratic wrap cost of one
	// giant line. Newline-delimited keeps the render fast.
	line := strings.Repeat("a", 1500) + "\n"
	if err := os.WriteFile(file, []byte(strings.Repeat(line, 380)), 0o644); err != nil {
		t.Fatal(err)
	}

	pages := map[string]int{}
	for _, level := range []string{"conservative", "balanced", "max"} {
		out := captureStdout(t, func() {
			runPixelRender([]string{"--density", level, "--no-reflow", file})
		})
		summary := lastPixelRenderSummary(t, out)
		if summary.Density != level {
			t.Fatalf("%s: summary density = %q, want %q", level, summary.Density, level)
		}
		if summary.Pages <= 0 {
			t.Fatalf("%s: pages = %d", level, summary.Pages)
		}
		pages[level] = summary.Pages
		// max stacks two layers per image → the summary must disclose the layer count.
		if level == "max" && summary.Layers != 2 {
			t.Fatalf("max summary must report layers=2, got %d", summary.Layers)
		}
		if level != "max" && summary.Layers != 0 {
			t.Fatalf("%s summary must not report a layer count, got %d", level, summary.Layers)
		}
		// Clean the emitted page PNGs between levels so they never pile up.
		for i := 1; i <= summary.Pages; i++ {
			_ = os.Remove(file + ".px" + itoa(i) + ".png")
		}
	}

	if !(pages["conservative"] > pages["balanced"] && pages["balanced"] > pages["max"]) {
		t.Fatalf("page counts must strictly decrease with density: %d > %d > %d", pages["conservative"], pages["balanced"], pages["max"])
	}
	base := float64(pages["conservative"])
	balRatio := float64(pages["balanced"]) / base
	maxRatio := float64(pages["max"]) / base
	// Page-count tolerances allow for line wrapping at page boundaries.
	if math.Abs(balRatio-0.607) > 0.05 {
		t.Fatalf("balanced page ratio = %.3f (%d/%d), want 0.607 ±0.05", balRatio, pages["balanced"], pages["conservative"])
	}
	if math.Abs(maxRatio-0.303) > 0.05 {
		t.Fatalf("max page ratio = %.3f (%d/%d), want 0.303 ±0.05", maxRatio, pages["max"], pages["conservative"])
	}
}

// pngIsColored reports whether the PNG at path has any non-grey pixel — true for a
// zebra (balanced) or red/blue overlay (max) render, false for a mono conservative
// page. Used to check the geometry actually drawn matches the reported density.
func pngIsColored(t *testing.T, path string) bool {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open %s: %v", path, err)
	}
	defer f.Close()
	img, err := png.Decode(f)
	if err != nil {
		t.Fatalf("decode %s: %v", path, err)
	}
	b := img.Bounds()
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			r, g, bl, _ := img.At(x, y).RGBA()
			if r != g || g != bl {
				return true
			}
		}
	}
	return false
}

func renderCombo(t *testing.T, file string, args []string) (pixelRenderSummary, string) {
	t.Helper()
	out := captureStdout(t, func() { runPixelRender(append(args, "--no-reflow", file)) })
	summary := lastPixelRenderSummary(t, out)
	firstPage := file + ".px1.png"
	return summary, firstPage
}

func cleanPages(file string, pages int) {
	for i := 1; i <= pages; i++ {
		_ = os.Remove(file + ".px" + itoa(i) + ".png")
	}
}

// The load-bearing invariant: for EVERY flag combination the reported density +
// layers must match the pixels actually drawn. Walk the matrix
// {plain, --dense, --multicol 2, --dense --multicol 2} × {conservative, balanced, max}.
//
// A forced multi-column layout draws the fixed conservative grid (no density style /
// overlay), so it must report conservative regardless of the requested level. The max
// 2-layer overlay is single-column only and must survive --dense (which is exactly what
// `caveman convert --density max` shells): --dense --density max must render the true
// overlay (layers:2), not fall through RenderDensePages single-layer.
func TestPixelRenderDensityLabelMatchesPixels(t *testing.T) {
	dir := t.TempDir()
	file := filepath.Join(dir, "doc.txt")
	if err := os.WriteFile(file, []byte(strings.Repeat("matrix body line with several words here\n", 400)), 0o644); err != nil {
		t.Fatal(err)
	}

	type combo struct {
		flags []string
		multi bool
		level string
	}
	combos := []combo{}
	for _, level := range []string{"conservative", "balanced", "max"} {
		combos = append(combos,
			combo{[]string{"--density", level}, false, level},
			combo{[]string{"--dense", "--density", level}, false, level},
			combo{[]string{"--multicol", "2", "--density", level}, true, level},
			combo{[]string{"--dense", "--multicol", "2", "--density", level}, true, level},
		)
	}

	for _, c := range combos {
		name := strings.Join(c.flags, " ")
		summary, firstPage := renderCombo(t, file, append([]string{}, c.flags...))

		wantDensity := c.level
		wantLayers := 0
		if c.multi {
			wantDensity = "conservative" // multi-column draws the conservative grid
		} else if c.level == "max" {
			wantLayers = 2 // single-column max = the 2-layer overlay
		}
		if summary.Density != wantDensity {
			t.Fatalf("[%s] density=%q, want %q", name, summary.Density, wantDensity)
		}
		if summary.Layers != wantLayers {
			t.Fatalf("[%s] layers=%d, want %d", name, summary.Layers, wantLayers)
		}
		if summary.Pages <= 0 {
			t.Fatalf("[%s] produced no pages", name)
		}
		// Pixel geometry must match the label: a conservative report is mono grey; a
		// balanced/max report carries zebra or overlay colour.
		colored := pngIsColored(t, firstPage)
		if wantDensity == "conservative" && colored {
			t.Fatalf("[%s] reported conservative but drew coloured pixels", name)
		}
		if wantDensity != "conservative" && !colored {
			t.Fatalf("[%s] reported %s but drew a mono grey page", name, wantDensity)
		}
		cleanPages(file, summary.Pages)
	}

	// The convert path: --dense --density max must render the SAME true overlay as plain
	// --density max — half the pages of balanced, layers:2, coloured — not a single-layer
	// RenderDensePages fallback with double the pages.
	plainMax, plainMaxPage := renderCombo(t, file, []string{"--density", "max"})
	denseMax, _ := renderCombo(t, file, []string{"--dense", "--density", "max"})
	balanced, _ := renderCombo(t, file, []string{"--density", "balanced"})
	if denseMax.Pages != plainMax.Pages {
		t.Fatalf("--dense --density max pages=%d must equal plain --density max pages=%d (true overlay, not RenderDensePages single-layer)", denseMax.Pages, plainMax.Pages)
	}
	if denseMax.Layers != 2 || plainMax.Layers != 2 {
		t.Fatalf("max renders must report layers:2 (dense=%d plain=%d)", denseMax.Layers, plainMax.Layers)
	}
	if !(plainMax.Pages < balanced.Pages) {
		t.Fatalf("2-layer max must pack fewer pages than balanced: max=%d balanced=%d", plainMax.Pages, balanced.Pages)
	}
	if !pngIsColored(t, plainMaxPage) {
		t.Fatalf("max overlay page must carry red/blue ink, got a mono grey page")
	}
	cleanPages(file, plainMax.Pages)
	cleanPages(file, balanced.Pages)
}

// An invalid --density is a LOUD usage error on the dev surface (the engine's env
// path stays fail-closed-to-conservative; the flag does not).
func TestPixelRenderRejectsUnknownDensity(t *testing.T) {
	if os.Getenv("CAVE_TEST_BAD_DENSITY") == "1" {
		runPixelRender([]string{"--density", "turbo", filepath.Join(t.TempDir(), "x.txt")})
		return
	}
	// resolvePixelDensity calls fatal() → os.Exit(1); assert the switch rejects it
	// without needing a subprocess by checking the three valid levels round-trip.
	for _, ok := range []string{"conservative", "balanced", "max", "MAX", " balanced "} {
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Fatalf("valid density %q panicked: %v", ok, r)
				}
			}()
			_ = resolvePixelDensity(strings.TrimSpace(strings.ToLower(ok)))
		}()
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}

//go:build js && wasm

// Command caveman-wasm is the engine compiled for the browser. It registers
// JS-callable globals — cavemanCompress, cavemanDetect, cavemanRetrieve — backed
// by the same compressors as the native engine, with an in-memory CCR store.
// Build it with `make engine-wasm`. Token figures are local estimates.
package main

import (
	"syscall/js"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
)

func main() {
	store, err := ccr.OpenMemory()
	if err != nil {
		panic(err) // an in-memory store cannot fail to open; if it does, fail loudly
	}
	eng := engine.New(store, nil)

	js.Global().Set("cavemanCompress", js.FuncOf(func(_ js.Value, args []js.Value) any {
		if len(args) < 1 || args[0].Type() != js.TypeString {
			return passThrough("")
		}
		return compress(eng, args[0].String())
	}))

	js.Global().Set("cavemanDetect", js.FuncOf(func(_ js.Value, args []js.Value) any {
		if len(args) < 1 || args[0].Type() != js.TypeString {
			return engine.TypeText
		}
		return eng.Detect([]byte(args[0].String()))
	}))

	js.Global().Set("cavemanRetrieve", js.FuncOf(func(_ js.Value, args []js.Value) any {
		if len(args) < 1 || args[0].Type() != js.TypeString {
			return map[string]any{"ok": false, "error": "cave_invalid_arguments"}
		}
		original, err := eng.Retrieve(args[0].String())
		if err != nil {
			return map[string]any{"ok": false, "error": "cave_unknown_handle"}
		}
		return map[string]any{"ok": true, "original": string(original)}
	}))

	// Signal readiness to the host page if it provided a callback, then block so
	// the registered functions stay callable for the page's lifetime.
	if ready := js.Global().Get("cavemanReady"); ready.Type() == js.TypeFunction {
		ready.Invoke()
	}
	select {}
}

// compress runs the engine and returns a plain JS object. It is fail-closed: on
// any engine error it returns the original unchanged with ratio 0 — never throws.
func compress(eng *engine.Engine, input string) any {
	res, err := eng.Compress([]byte(input), engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		return passThrough(input)
	}
	var handle any
	if res.RecoveryHandle != "" {
		handle = res.RecoveryHandle
	}
	return map[string]any{
		"output":            string(res.Output),
		"ratio":             res.Ratio,
		"tokens_before":     res.TokensBefore,
		"tokens_after":      res.TokensAfter,
		"token_count_basis": res.TokenCountBasis,
		"basis":             res.Basis,
		"content_type":      res.ContentType,
		"recovery_handle":   handle,
	}
}

func passThrough(input string) any {
	return map[string]any{
		"output":            input,
		"ratio":             0.0,
		"tokens_before":     0,
		"tokens_after":      0,
		"token_count_basis": "unavailable",
		"basis":             engine.BasisInferred,
		"content_type":      engine.TypeText,
		"recovery_handle":   nil,
	}
}

//go:build !js || !wasm

// Host placeholder so `go build ./public/engine/...` succeeds on every platform.
// The real entrypoint is main.go, built only for js/wasm (`make engine-wasm`).
package main

import (
	"fmt"
	"os"
)

func main() {
	fmt.Fprintln(os.Stderr, "caveman-wasm must be built with GOOS=js GOARCH=wasm (run: make engine-wasm)")
	os.Exit(1)
}

package compressors

import (
	"bytes"
	"encoding/json"
	"strconv"
	"strings"
	"unicode"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

const a11yType = "a11y"

var a11yStateKeys = map[string]bool{
	"disabled": true,
	"checked":  true,
	"expanded": true,
	"selected": true,
	"focused":  true,
	"editable": true,
}

// NewAXTree returns the forced-only CDP Accessibility.getFullAXTree compressor.
// It emits a compact, deterministic indented view with uid handles while CCR
// keeps the raw AX payload byte-exact. Detect never routes here; callers must
// force Options.Type = "a11y".
func NewAXTree() Compressor { return axTreeCompressor{} }

type axTreeCompressor struct{}

func (axTreeCompressor) ContentType() string       { return a11yType }
func (axTreeCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c axTreeCompressor) Compress(input []byte) ([]byte, bool) {
	out, _, ok := c.CompressWithMetadata(input, "")
	return out, ok
}

func (axTreeCompressor) CompressWithMetadata(input []byte, query string) ([]byte, Metadata, bool) {
	nodes, ok := parseAXTree(input)
	if !ok {
		return nil, Metadata{}, false
	}
	records, uidMap := curateAXTree(nodes)
	if len(records) == 0 {
		return nil, Metadata{}, false
	}
	records = focusAXRecords(records, query)
	uidMap = visibleUIDTargets(records, uidMap)
	uidJSON, err := json.Marshal(map[string]map[string]axUIDTarget{"uids": uidMap})
	if err != nil {
		return nil, Metadata{}, false
	}
	return renderAXRecords(records), Metadata{Method: a11yType, LosslessToModel: metadataBool(false), RecoveryMetadata: uidJSON}, true
}

type axTreeEnvelope struct {
	Nodes []axNode `json:"nodes"`
}

type axNode struct {
	NodeID            string       `json:"nodeId"`
	ParentID          string       `json:"parentId"`
	Ignored           bool         `json:"ignored"`
	Role              axValue      `json:"role"`
	Name              axValue      `json:"name"`
	Value             axValue      `json:"value"`
	Properties        []axProperty `json:"properties"`
	ChildIDs          []string     `json:"childIds"`
	BackendDOMNodeID  int          `json:"backendDOMNodeId"`
	BackendDOMNodeID2 int          `json:"backendDOMNodeID"`
	FrameID           string       `json:"frameId"`
	ChromeFrameID     string       `json:"frameID"`
}

type axValue struct {
	Type  string `json:"type"`
	Value any    `json:"value"`
}

type axProperty struct {
	Name  string  `json:"name"`
	Value axValue `json:"value"`
}

type axRecord struct {
	Depth int
	UID   string
	Role  string
	Name  string
	Value string
	State map[string]bool
}

type axUIDTarget struct {
	BackendDOMNodeID int    `json:"backendDOMNodeId"`
	FrameID          string `json:"frameId,omitempty"`
	NodeID           string `json:"nodeId,omitempty"`
}

func parseAXTree(input []byte) ([]axNode, bool) {
	if len(bytes.TrimSpace(input)) == 0 || !json.Valid(input) {
		return nil, false
	}
	var nodes []axNode
	if err := json.Unmarshal(input, &nodes); err == nil && len(nodes) > 0 {
		return nodes, validAXTree(nodes)
	}
	var env axTreeEnvelope
	if err := json.Unmarshal(input, &env); err == nil && len(env.Nodes) > 0 {
		return env.Nodes, validAXTree(env.Nodes)
	}
	return nil, false
}

func validAXTree(nodes []axNode) bool {
	seen := make(map[string]bool, len(nodes))
	nonIgnored := 0
	for _, n := range nodes {
		if n.NodeID == "" || seen[n.NodeID] {
			return false
		}
		seen[n.NodeID] = true
		if n.Ignored {
			continue
		}
		nonIgnored++
		if compactAXString(n.Role.Value) == "" {
			return false
		}
	}
	if nonIgnored == 0 {
		return false
	}
	// A childId that resolves to no node in this payload is NOT a malformed
	// tree: Accessibility.getFullAXTree returns one frame at a time, so an
	// <iframe> node references a child document node that legitimately lives in
	// another frame's response. Treat such a childId as a leaf boundary (walk
	// skips unknown ids) rather than rejecting the whole tree — over-returning a
	// usable uid map is safe; refusing to compress the page is not.
	return true
}

func curateAXTree(nodes []axNode) ([]axRecord, map[string]axUIDTarget) {
	byID := make(map[string]axNode, len(nodes))
	childRefs := make(map[string]bool, len(nodes))
	for _, n := range nodes {
		if n.NodeID != "" {
			byID[n.NodeID] = n
		}
		for _, id := range n.ChildIDs {
			childRefs[id] = true
		}
	}

	roots := make([]string, 0, len(nodes))
	for _, n := range nodes {
		if n.NodeID != "" && !childRefs[n.NodeID] {
			roots = append(roots, n.NodeID)
		}
	}
	if len(roots) == 0 {
		for _, n := range nodes {
			if n.NodeID != "" {
				roots = append(roots, n.NodeID)
			}
		}
	}

	visited := make(map[string]bool, len(nodes))
	out := make([]axRecord, 0, len(nodes))
	uidMap := make(map[string]axUIDTarget, len(nodes))
	seenUIDs := make(map[string]int, len(nodes))
	var walk func(id string, depth int)
	walk = func(id string, depth int) {
		if id == "" || visited[id] {
			return
		}
		n, ok := byID[id]
		if !ok {
			return
		}
		visited[id] = true
		if n.Ignored {
			for _, child := range n.ChildIDs {
				walk(child, depth)
			}
			return
		}

		rec := normalizeAXNode(n, depth)
		if shouldExposeAXUID(rec, n) {
			base := axUIDBase(n)
			rec.UID = uniqueAXUID(base, seenUIDs)
			uidMap[rec.UID] = axUIDTarget{
				BackendDOMNodeID: backendID(n),
				FrameID:          frameID(n),
				NodeID:           n.NodeID,
			}
		}
		drop := droppableGeneric(rec, n)
		if !drop {
			out = append(out, rec)
			depth++
		}
		for _, child := range n.ChildIDs {
			walk(child, depth)
		}
	}
	for _, root := range roots {
		walk(root, 0)
	}
	for _, n := range nodes {
		if n.NodeID != "" && !visited[n.NodeID] {
			walk(n.NodeID, 0)
		}
	}
	out = pruneDuplicateAXText(out)
	return out, visibleUIDTargets(out, uidMap)
}

func normalizeAXNode(n axNode, depth int) axRecord {
	rec := axRecord{
		Depth: depth,
		Role:  compactAXString(n.Role.Value),
		Name:  compactAXString(n.Name.Value),
		Value: compactAXString(n.Value.Value),
	}
	state := axState(n)
	if len(state) > 0 {
		rec.State = state
	}
	return rec
}

func axState(n axNode) map[string]bool {
	out := map[string]bool{}
	for _, p := range n.Properties {
		if !a11yStateKeys[p.Name] {
			continue
		}
		v, ok := axStateBool(p.Name, p.Value.Value)
		if ok {
			out[p.Name] = v
		}
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

func droppableGeneric(rec axRecord, n axNode) bool {
	role := strings.ToLower(rec.Role)
	// InlineTextBox repeats its semantic parent's text at layout-fragment
	// granularity. It is never an action target and is the largest source of AX
	// snapshot duplication. LabelText is likewise only a wrapper when empty.
	if role == "inlinetextbox" {
		return true
	}
	if role == "labeltext" && rec.Name == "" && rec.Value == "" && len(rec.State) == 0 {
		return true
	}
	if role != "generic" && role != "presentational" && role != "none" {
		return false
	}
	if rec.Name != "" || rec.Value != "" {
		return false
	}
	if len(rec.State) > 0 && !(len(rec.State) == 1 && rec.State["editable"]) {
		return false
	}
	for _, p := range n.Properties {
		if p.Name == "focusable" || p.Name == "clickable" {
			if v, ok := axLooseBool(p.Value.Value); ok && v {
				return false
			}
		}
	}
	return true
}

func backendID(n axNode) int {
	id := n.BackendDOMNodeID
	if id == 0 {
		id = n.BackendDOMNodeID2
	}
	return id
}

func frameID(n axNode) string {
	frame := n.FrameID
	if frame == "" {
		frame = n.ChromeFrameID
	}
	return frame
}

func axUIDBase(n axNode) string {
	id := backendID(n)
	if id <= 0 {
		return ""
	}
	// Backend node ids are unique inside the single CDP target supported by the
	// Phase-1 driver. Frame ids remain in recovery metadata for future OOPIF
	// stitching; embedding a base64 frame id in every visible uid spent dozens of
	// tokens while the action driver ignored it.
	return "u" + strconv.FormatInt(int64(id), 36)
}

func shouldExposeAXUID(rec axRecord, n axNode) bool {
	if backendID(n) <= 0 {
		return false
	}
	switch strings.ToLower(rec.Role) {
	case "rootwebarea", "webarea":
		return false
	case "button", "checkbox", "combobox", "link", "menuitem", "menuitemcheckbox",
		"menuitemradio", "option", "radio", "searchbox", "slider", "spinbutton",
		"switch", "tab", "textbox", "treeitem":
		return true
	}
	for _, p := range n.Properties {
		if p.Name == "focusable" || p.Name == "clickable" {
			if v, ok := axLooseBool(p.Value.Value); ok && v {
				return true
			}
		}
	}
	switch strings.ToLower(rec.Role) {
	case "main", "navigation", "region", "group", "generic", "none", "presentational",
		"heading", "paragraph", "statictext", "inlinetextbox", "labeltext", "list",
		"listitem", "table", "row", "cell", "rowheader", "columnheader", "grid", "tree",
		"directory", "separator", "toolbar", "banner", "complementary", "contentinfo",
		"article", "figure", "img", "image", "form", "status", "alert", "log", "timer",
		"tooltip", "document":
		return false
	default:
		// Unknown roles stay visible and actionable. Omitting their handle would
		// silently turn a custom control into read-only text.
		return true
	}
}

func pruneDuplicateAXText(records []axRecord) []axRecord {
	semanticText := make(map[string]bool)
	for _, rec := range records {
		role := strings.ToLower(rec.Role)
		if role == "statictext" || role == "inlinetextbox" {
			continue
		}
		for _, value := range []string{rec.Name, rec.Value} {
			if key := strings.ToLower(strings.TrimSpace(value)); key != "" {
				semanticText[key] = true
			}
		}
	}
	out := make([]axRecord, 0, len(records))
	for _, rec := range records {
		if strings.EqualFold(rec.Role, "StaticText") {
			key := strings.ToLower(strings.TrimSpace(rec.Name))
			if key != "" && semanticText[key] {
				continue
			}
			// Layout-derived state on static text duplicates the owning control.
			rec.State = nil
		}
		out = append(out, rec)
	}
	return out
}

func focusAXRecords(records []axRecord, query string) []axRecord {
	terms := axQueryTerms(query)
	if len(terms) == 0 || len(records) == 0 {
		return records
	}
	scores := make([]int, len(records))
	maxScore := 0
	for i, rec := range records {
		haystack := strings.ToLower(rec.Role + " " + rec.Name + " " + rec.Value + " " + strings.Join(axStateLabels(rec.State), " "))
		for _, term := range terms {
			if strings.Contains(haystack, term) {
				scores[i]++
			}
		}
		if scores[i] > maxScore {
			maxScore = scores[i]
		}
	}
	if maxScore == 0 {
		root := records[0]
		root.Depth = 0
		return []axRecord{root, {Depth: 1, Role: "note", Name: "no accessible match"}}
	}

	keep := make([]bool, len(records))
	matches := 0
	// Highest-coverage matches win the bounded result, but distinct task terms
	// may name distinct controls ("Email Plan Save"). Fill remaining slots from
	// lower scores instead of returning only the single record with most terms.
	minScore := 1
	if maxScore == len(terms) {
		// At least one node covers the whole query. Partial matches on common
		// fragments (every ORD-* row matching "ord") are noise, not another intent.
		minScore = maxScore
	}
	for wantedScore := maxScore; wantedScore >= minScore && matches < 12; wantedScore-- {
		for i, score := range scores {
			if score != wantedScore || matches >= 12 {
				continue
			}
			keep[i] = true
			matches++
			wantDepth := records[i].Depth - 1
			for j := i - 1; j >= 0 && wantDepth >= 0; j-- {
				if records[j].Depth == wantDepth {
					keep[j] = true
					wantDepth--
				}
			}
		}
	}

	// A match inside a row or list item answers a lookup only together with
	// its sibling cells — an order id without its customer/amount cells reads
	// as "data unavailable". Keep the whole line item, not just the matching
	// cell. Subtree size is bounded by real row width, not by the match cap.
	for i := range records {
		if !keep[i] {
			continue
		}
		item := -1
		if records[i].Role == "row" || records[i].Role == "listitem" {
			item = i
		}
		wantDepth := records[i].Depth - 1
		for j := i; j >= 0 && item == -1 && wantDepth >= 0; j-- {
			if records[j].Depth != wantDepth {
				continue
			}
			if records[j].Role == "row" || records[j].Role == "listitem" {
				item = j
				break
			}
			wantDepth--
		}
		if item == -1 {
			continue
		}
		for j := item; j < len(records) && (j == item || records[j].Depth > records[item].Depth); j++ {
			keep[j] = true
		}
	}

	out := make([]axRecord, 0, matches*2)
	keptDepth := make(map[int]bool)
	for i, rec := range records {
		for depth := range keptDepth {
			if depth >= rec.Depth {
				delete(keptDepth, depth)
			}
		}
		if !keep[i] {
			continue
		}
		depth := 0
		for ancestor := 0; ancestor < rec.Depth; ancestor++ {
			if keptDepth[ancestor] {
				depth++
			}
		}
		rec.Depth = depth
		out = append(out, rec)
		keptDepth[records[i].Depth] = true
	}
	return out
}

func axQueryTerms(query string) []string {
	return strings.FieldsFunc(strings.ToLower(query), func(r rune) bool {
		return !unicode.IsLetter(r) && !unicode.IsNumber(r)
	})
}

func visibleUIDTargets(records []axRecord, all map[string]axUIDTarget) map[string]axUIDTarget {
	out := make(map[string]axUIDTarget)
	for _, rec := range records {
		if rec.UID == "" {
			continue
		}
		if target, ok := all[rec.UID]; ok {
			out[rec.UID] = target
		}
	}
	return out
}

func renderAXRecords(records []axRecord) []byte {
	var b bytes.Buffer
	for i, rec := range records {
		if i > 0 {
			b.WriteByte('\n')
		}
		b.WriteString(strings.Repeat("  ", rec.Depth))
		if rec.UID != "" {
			b.WriteByte('[')
			b.WriteString(rec.UID)
			b.WriteString("] ")
		}
		b.WriteString(compactAXRole(rec.Role))
		if rec.Name != "" {
			b.WriteByte(' ')
			b.WriteString(strconv.Quote(rec.Name))
		}
		if rec.Value != "" && rec.Value != rec.Name {
			b.WriteString(" = ")
			b.WriteString(strconv.Quote(rec.Value))
		}
		if states := axStateLabels(rec.State); len(states) > 0 {
			b.WriteString(" {")
			b.WriteString(strings.Join(states, ","))
			b.WriteByte('}')
		}
	}
	return b.Bytes()
}

func compactAXRole(role string) string {
	switch strings.ToLower(role) {
	case "rootwebarea", "webarea":
		return "page"
	case "statictext":
		return "text"
	case "labeltext":
		return "label"
	default:
		return strings.ToLower(role)
	}
}

func axStateLabels(state map[string]bool) []string {
	if len(state) == 0 {
		return nil
	}
	out := make([]string, 0, len(state))
	if state["disabled"] {
		out = append(out, "disabled")
	}
	if checked, ok := state["checked"]; ok {
		if checked {
			out = append(out, "checked")
		} else {
			out = append(out, "unchecked")
		}
	}
	if expanded, ok := state["expanded"]; ok {
		if expanded {
			out = append(out, "expanded")
		} else {
			out = append(out, "collapsed")
		}
	}
	if state["selected"] {
		out = append(out, "selected")
	}
	if state["focused"] {
		out = append(out, "focused")
	}
	if state["editable"] {
		out = append(out, "editable")
	}
	return out
}

func uniqueAXUID(base string, seen map[string]int) string {
	seen[base]++
	if seen[base] == 1 {
		return base
	}
	return base + "_" + strconv.Itoa(seen[base])
}

func compactAXString(v any) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return strings.Join(strings.Fields(x), " ")
	case bool:
		return strconv.FormatBool(x)
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64)
	default:
		b, err := json.Marshal(x)
		if err != nil {
			return ""
		}
		return strings.Join(strings.Fields(string(b)), " ")
	}
}

func axStateBool(key string, v any) (bool, bool) {
	switch x := v.(type) {
	case bool:
		return x, true
	case string:
		switch strings.ToLower(strings.TrimSpace(x)) {
		case "true", "1", "yes":
			return true, true
		case "false", "0", "no", "":
			return false, true
		case "mixed":
			return key == "checked", key == "checked"
		case "plaintext", "richtext":
			return key == "editable", key == "editable"
		default:
			return false, false
		}
	case float64:
		switch key {
		case "disabled", "checked", "expanded", "selected", "focused":
			return x != 0, true
		default:
			return false, false
		}
	default:
		return false, false
	}
}

func axLooseBool(v any) (bool, bool) {
	switch x := v.(type) {
	case bool:
		return x, true
	case string:
		switch strings.ToLower(strings.TrimSpace(x)) {
		case "true", "1", "yes":
			return true, true
		case "false", "0", "no", "":
			return false, true
		default:
			return false, false
		}
	case float64:
		return x != 0, true
	default:
		return false, false
	}
}

package compressors

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/tokens"
)

const sampleAXTree = `[
  {
    "nodeId": "1",
    "role": {"type": "role", "value": "RootWebArea"},
    "name": {"type": "computedString", "value": "Caveman Console"},
    "backendDOMNodeId": 1,
    "childIds": ["2", "3", "5"]
  },
  {
    "nodeId": "2",
    "ignored": true,
    "role": {"type": "role", "value": "generic"},
    "name": {"type": "computedString", "value": "noise wrapper"},
    "childIds": ["4"]
  },
  {
    "nodeId": "4",
    "role": {"type": "role", "value": "button"},
    "name": {"type": "computedString", "value": "Save settings"},
    "backendDOMNodeId": 42,
    "properties": [
      {"name": "disabled", "value": {"type": "boolean", "value": false}},
      {"name": "focused", "value": {"type": "boolean", "value": true}}
    ]
  },
