// map, with the iframe boundary treated as a leaf.
func TestAXTreeDanglingChildBecomesLeaf(t *testing.T) {
	input := `[
	  {"nodeId":"1","role":{"value":"RootWebArea"},"name":{"value":"Host Page"},"backendDOMNodeId":1,"childIds":["2","3"]},
