func TestCodeCommentRemove(t *testing.T) {
	src := `package main

// PackageDoc explains the package in a long comment that we want gone.
// Second line of the comment.

func Run() int {
	return 1
}
`
	// Default keeps the comment.
	def, ok := newCode().Compress([]byte(src))
	if !ok {
		t.Fatal("expected compression (default)")
	}
	if !bytes.Contains(def, []byte("PackageDoc explains")) {
		t.Error("default mode must keep top-level comments")
	}
	// CommentRemove drops it but keeps the signature and re-parses.
	rm, ok := newCodeWith(CodeOptions{Comments: CommentRemove}).Compress([]byte(src))
	if !ok {
		t.Fatal("expected compression (CommentRemove)")
	}
	if bytes.Contains(rm, []byte("PackageDoc explains")) {
		t.Errorf("CommentRemove must drop the comment, got:\n%s", rm)
	}
	if !bytes.Contains(rm, []byte("func Run()")) {
		t.Error("signature must survive comment removal")
	}
}

func TestCodePythonDocstringRemove(t *testing.T) {
	src := `"""Module docstring that should be removable."""
import os


class Worker:
    """Class docstring to drop."""

    def run(self):
        return os.getpid()
`
	rm, ok := newCodeWith(CodeOptions{Docstrings: CommentRemove}).Compress([]byte(src))
	if !ok {
		t.Fatal("expected compression")
	}
	if bytes.Contains(rm, []byte("Module docstring")) || bytes.Contains(rm, []byte("Class docstring")) {
		t.Errorf("docstrings should be removed, got:\n%s", rm)
	}
	if !bytes.Contains(rm, []byte("class Worker")) || !bytes.Contains(rm, []byte("import os")) {
		t.Error("structure must survive docstring removal")
	}
}

func TestCodeCommentRemovePreservesDirectives(t *testing.T) {
	// Directive comments carry build/embed/linkage semantics that survive a
	// re-parse — CommentRemove must keep them while still dropping prose.
	src := `//go:build linux && amd64
// +build linux,amd64

// PackageDoc is ordinary prose that may be removed.
package main

//go:embed banner.txt
var banner string

//go:generate stringer -type=T
func F() int { return 1 }
`
	out, ok := newCodeWith(CodeOptions{Comments: CommentRemove}).Compress([]byte(src))
	if !ok {
		t.Fatal("expected compression")
	}
	for _, must := range []string{"//go:build linux", "// +build linux,amd64", "//go:embed banner.txt", "//go:generate"} {
		if !bytes.Contains(out, []byte(must)) {
			t.Errorf("directive %q must NOT be removed, got:\n%s", must, out)
		}
	}
	if bytes.Contains(out, []byte("ordinary prose")) {
		t.Error("prose comment should still be removed")
	}
}

func TestCodePythonDocstringRejectsFStringAndBytes(t *testing.T) {
	// A leading f-string (may have side effects) or bytes literal is NOT a
	// docstring and must not be removed.
	src := `f"""evaluated {1 + 1} expression, not a docstring"""
import os


def run():
    return os.getpid()
`
	out, ok := newCodeWith(CodeOptions{Docstrings: CommentRemove}).Compress([]byte(src))
	// Compression may or may not trigger (the f-string isn't removable); if it
	// does, the f-string must survive.
	if ok && !bytes.Contains(out, []byte("evaluated")) {
		t.Errorf("leading f-string must not be removed as a docstring, got:\n%s", out)
	}
}

func TestCodePythonDocstringOnlyModulePreserved(t *testing.T) {
	// A module whose ONLY statement is a docstring must not be emptied (would be
	// invalid). Removing it is guarded; the compressor should pass through.
	src := strings.Repeat(`"""Only a docstring lives here, nothing else at all in this module file."""
`, 1)
	out, ok := newCodeWith(CodeOptions{Docstrings: CommentRemove}).Compress([]byte(src))
	if ok && !bytes.Contains(out, []byte("Only a docstring")) {
		t.Error("a sole-docstring module must not have its docstring removed")
	}
}

package compressors

import (
	"bytes"
	"strconv"
)

// Coding agents almost never hand a compressor a bare source file. They hand it
// a FILE LISTING: the file's text with every line prefixed by its line number,
// the shape `cat -n` and every Read tool emit (Claude Code writes "%d\t", other
// harnesses pad the number and use a tab or " | " gutter). Those prefixes are
// not valid syntax in any language, so a parser-based compressor sees a file it
// cannot parse and passes it through untouched — silently giving up on the
// single most common payload in an agent session.
//
// SplitLineNumberedListing recognizes that shape and separates it into the
// source text and the per-line numbers, so the compressor can work on real
// source and the caller can put the gutter back afterwards.
//
// It is deliberately strict, because a false positive would corrupt content that
// merely begins with digits: every non-blank line must carry a number, the
// numbers must be strictly increasing, and there must be enough of them for the
// shape to be a listing rather than a coincidence.
const (
	// minListingLines is the shortest run that can identify a listing. Below it
	// an ordinary numbered prose list would qualify.
	minListingLines = 8
	// maxListingGutter bounds how wide a line-number gutter may be, which caps
	// how much padding a false positive could hide behind.
	maxListingGutter = 12
)

// SplitLineNumberedListing reports whether input is a line-numbered file
// listing. On success it returns the source text with gutters removed and the
// line number each source line carried.
func SplitLineNumberedListing(input []byte) (source []byte, numbers []int, ok bool) {
	lines := bytes.Split(input, []byte("\n"))
	// A trailing newline yields a final empty element that is not a real line.
	trailingNewline := len(lines) > 1 && len(lines[len(lines)-1]) == 0
	if trailingNewline {
		lines = lines[:len(lines)-1]
	}
	if len(lines) < minListingLines {
		return nil, nil, false
	}

	source = make([]byte, 0, len(input))
	numbers = make([]int, 0, len(lines))
	previous := 0
	numbered := 0
	for i, line := range lines {
		number, rest, found := splitLineNumberGutter(line)
		if !found {
			// A blank line inside a listing may legitimately carry no gutter.
			if len(bytes.TrimSpace(line)) == 0 {
				numbers = append(numbers, previous)
				if i > 0 {
					source = append(source, '\n')
				}
				continue
			}
			return nil, nil, false
		}
		if number <= previous {
			return nil, nil, false // not a monotonically increasing listing
		}
		previous = number
		numbered++
		numbers = append(numbers, number)
		if i > 0 {
			source = append(source, '\n')
		}
		source = append(source, rest...)
	}
	if numbered < minListingLines {
		return nil, nil, false
	}
	if trailingNewline {
		source = append(source, '\n')
	}
	return source, numbers, true
}

// splitLineNumberGutter parses one listing line into its number and the source
// text after the gutter. Recognized gutters are `<spaces><digits>\t`,
// `<spaces><digits> | ` and `<spaces><digits>: ` — the forms coding agents and
// `cat -n` actually emit. Anything else is not a gutter.
func splitLineNumberGutter(line []byte) (number int, rest []byte, ok bool) {
	i := 0
	for i < len(line) && line[i] == ' ' {
		i++
	}
	start := i
	for i < len(line) && line[i] >= '0' && line[i] <= '9' {
		i++
	}
	if i == start || i-start > maxListingGutter {
		return 0, nil, false
	}
	value, err := strconv.Atoi(string(line[start:i]))
	if err != nil {
		return 0, nil, false
	}
	switch {
	case i < len(line) && line[i] == '\t':
		return value, line[i+1:], true
	case i+2 < len(line) && line[i] == ' ' && line[i+1] == '|' && line[i+2] == ' ':
		return value, line[i+3:], true
	case i+1 < len(line) && line[i] == ':' && line[i+1] == ' ':
		return value, line[i+2:], true
	case i == len(line):
		// A bare number on its own line — a numbered blank line.
		return value, nil, true
	}
	return 0, nil, false
}

// RestoreLineNumberedListing puts the gutter back on a compressed listing.
//
// Compression removes lines, so output line N is not source line N. Renumbering
// the output 1..n would hand the model line numbers that point at the wrong
// code — worse than none, because they look authoritative. Instead each output
// line is matched forward against the source lines it came from and keeps the
// number it actually had. The result is a listing with GAPS where content was
// elided, which is both correct and a legible signal that something was removed.
//
// Lines the compressor introduced (body-elision markers, reflowed formatting)
// match nothing; they take the number of the source line the cursor is sitting
// on, which is where the elided region began.
//
// Some transforms do not preserve lines at all — re-encoding a JSON document
// rewrites nearly every one — and there the original numbering describes
// nothing. Rather than decorate restructured output with numbers that merely
// look authoritative, this reports ok=false when too few output lines can be
// traced back, and the caller emits the compressed body with no gutter. The
// content is already disclosed as transformed by its CCR marker; an honest
// absence of line numbers beats a confident fiction.
func RestoreLineNumberedListing(compressed, source []byte, numbers []int) ([]byte, bool) {
	sourceLines := bytes.Split(source, []byte("\n"))
	// A trailing newline yields a final empty element that is not a real line —
	// split it off the same way splitLineNumberedListing did, or the alignment
	// check below rejects every listing that ends in a newline (i.e. all of them).
	if len(sourceLines) > 1 && len(sourceLines[len(sourceLines)-1]) == 0 {
		sourceLines = sourceLines[:len(sourceLines)-1]
	}
	if len(numbers) < len(sourceLines) {
		// Cannot align: hand back the compressed body ungutted rather than
		// attach numbers that were not aligned.
		return compressed, false
	}
	index := indexSourceLines(sourceLines)

	outLines := bytes.Split(compressed, []byte("\n"))
	trailingNewline := len(outLines) > 1 && len(outLines[len(outLines)-1]) == 0
	if trailingNewline {
		outLines = outLines[:len(outLines)-1]
	}

	var out bytes.Buffer
	out.Grow(len(compressed) + len(outLines)*6)
	cursor := 0
	traceable, tracked := 0, 0
	for i, line := range outLines {
		position := cursor
		if position >= len(numbers) {
			position = len(numbers) - 1
		}
		number := numbers[position]
		// Blank lines are matched by nothing in particular — they occur
		// everywhere, and a compressor that reflows formatting (gofmt collapsing
		// the gap a removed body left) emits them in places the source never had
		// one. Letting them drive the cursor skips it past real code and
		// mis-numbers everything after. They take the cursor's number instead.
		if len(bytes.TrimSpace(line)) > 0 {
			tracked++
			if at, found := nextMatch(index, string(line), cursor); found {
				number = numbers[at]
				cursor = at + 1
				traceable++
			}
		}
		if i > 0 {
			out.WriteByte('\n')
		}
		out.WriteString(strconv.Itoa(number))
		out.WriteByte('\t')
		out.Write(line)
	}
	if trailingNewline {
		out.WriteByte('\n')
	}
	if tracked > 0 && traceable*2 < tracked {
		// Fewer than half the substantive output lines came from a line this
		// source actually had. The transform restructured the content rather
		// than eliding parts of it, so the original numbering no longer
		// describes what the reader is looking at.
		return compressed, false
	}
	return out.Bytes(), true
}

// indexSourceLines maps each distinct source line to the ascending positions it
// occupies, so matching an output line is a lookup plus a short scan rather than
// a linear sweep of the whole file per line (quadratic on large listings).
func indexSourceLines(lines [][]byte) map[string][]int {
	index := make(map[string][]int, len(lines))
	for i, line := range lines {
		key := string(line)
		index[key] = append(index[key], i)
	}
	return index
}

// nextMatch finds the first occurrence of line at or after cursor.
func nextMatch(index map[string][]int, line string, cursor int) (int, bool) {
	positions, ok := index[line]
	if !ok {
		return 0, false
	}
	for _, position := range positions {
		if position >= cursor {
			return position, true
		}
	}
	return 0, false
}

package compressors

import (
	"strconv"
	"strings"
	"testing"
)

const listingSource = `package sample

import "fmt"

func alpha(a int) int {
	total := 0
	for i := 0; i < a; i++ {
		total += i
	}
	return total
}

func beta(b string) string {
	trimmed := b
	return trimmed + "!"
}
`

// gutter renders source the way a coding agent's read tool does.
func gutter(source, sep string) string {
	lines := strings.Split(strings.TrimSuffix(source, "\n"), "\n")
	var out []string
	for i, line := range lines {
		out = append(out, strconv.Itoa(i+1)+sep+line)
	}
	return strings.Join(out, "\n") + "\n"
}

func TestSplitLineNumberedListingRoundTrips(t *testing.T) {
	for _, sep := range []string{"\t", " | ", ": "} {
		source, numbers, ok := SplitLineNumberedListing([]byte(gutter(listingSource, sep)))
		if !ok {
			t.Fatalf("sep %q: listing not recognized", sep)
		}
		if string(source) != listingSource {
			t.Fatalf("sep %q: source mismatch:\n%q", sep, source)
		}
		if numbers[0] != 1 {
			t.Fatalf("sep %q: first number = %d, want 1", sep, numbers[0])
		}
	}
}

// Recognition must be strict: a false positive corrupts content that merely
// begins with digits.
func TestSplitLineNumberedListingRejectsNonListings(t *testing.T) {
	cases := map[string]string{
		"plain source":     listingSource,
		"too short":        "1\ta\n2\tb\n3\tc\n",
		"non-monotonic":    "1\ta\n2\tb\n2\tc\n4\td\n5\te\n6\tf\n7\tg\n8\th\n9\ti\n",
		"unnumbered line":  "1\ta\n2\tb\n3\tc\nplain\n5\te\n6\tf\n7\tg\n8\th\n9\ti\n",
		"no gutter after":  "1a\n2b\n3c\n4d\n5e\n6f\n7g\n8h\n9i\n",
		"prose numbering":  "1. first\n2. second\n3. third\n4. fourth\n5. fifth\n6. sixth\n7. seventh\n8. eighth\n",
		"decreasing after": "10\ta\n9\tb\n8\tc\n7\td\n6\te\n5\tf\n4\tg\n3\th\n",
	}
	for name, input := range cases {
		if _, _, ok := SplitLineNumberedListing([]byte(input)); ok {
			t.Errorf("%s: unexpectedly recognized as a listing", name)
		}
	}
}

// A line-eliding transform keeps the numbers the source actually had, gaps and
// all. Renumbering 1..n would point the model at the wrong code while looking
// authoritative.
func TestRestoreKeepsOriginalNumbersOnLineElidingOutput(t *testing.T) {
	sourceLines := strings.Split(strings.TrimSuffix(listingSource, "\n"), "\n")
	numbers := make([]int, len(sourceLines))
	for i := range numbers {
		numbers[i] = i + 1
	}
	// Elide the two function bodies, keeping every other line verbatim.
	var kept []string
	for _, line := range sourceLines {
		if strings.HasPrefix(line, "\t") {
			continue
		}
		kept = append(kept, line)
	}
	out, ok := RestoreLineNumberedListing([]byte(strings.Join(kept, "\n")), []byte(listingSource), numbers)
	if !ok {
		t.Fatal("line-eliding output was refused a gutter")
	}
	for _, line := range strings.Split(string(out), "\n") {
		number, rest, found := splitLineNumberGutter([]byte(line))
		if !found {
			t.Fatalf("output line lacks a gutter: %q", line)
		}
		if len(strings.TrimSpace(string(rest))) == 0 {
			continue
		}
		if sourceLines[number-1] != string(rest) {
			t.Errorf("line %q numbered %d, but source line %d is %q",
				rest, number, number, sourceLines[number-1])
		}
	}
}

// A restructuring transform (re-encoded JSON) leaves no line the original
// numbering describes. Decorating it with numbers would be a confident fiction,
// so the gutter is declined instead.
func TestRestoreDeclinesGutterOnRestructuredOutput(t *testing.T) {
	source := []byte("{\n  \"a\": 1,\n  \"b\": 2,\n  \"c\": 3,\n  \"d\": 4,\n  \"e\": 5,\n  \"f\": 6,\n  \"g\": 7\n}\n")
	numbers := []int{1, 2, 3, 4, 5, 6, 7, 8, 9}
	restructured := []byte(`{"a":1,"b":2,"c":3,"d":4,"e":5,"f":6,"g":7}`)
	out, ok := RestoreLineNumberedListing(restructured, source, numbers)
	if ok {
		t.Fatalf("restructured output was gutted with numbers that describe nothing: %q", out)
	}
	if string(out) != string(restructured) {
		t.Fatalf("declined restore altered the body: %q", out)
	}
}

//go:build !cgo

package compressors

import (
	"bytes"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// codeCompressor is the pure-Go (cgo-free / WASM) fallback. Without tree-sitter
// it compresses Go only — via the stdlib go/ast — by emptying function bodies
// while keeping every import, signature, and type declaration. Other languages
// pass through unchanged. It is S4 (lossy); the original is recoverable via CCR.
type codeCompressor struct{ opts CodeOptions }

func newCode() Compressor { return &codeCompressor{} }

// newCodeWith accepts options for build-tag symmetry with the cgo compressor.
// The pure-Go fallback only elides Go function bodies; comment/docstring modes
// are a no-op here (they require the tree-sitter build).
func newCodeWith(opts CodeOptions) Compressor { return &codeCompressor{opts: opts} }

func (c *codeCompressor) ContentType() string       { return "code" }
func (c *codeCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *codeCompressor) Compress(input []byte) ([]byte, bool) {
	if !bytes.Contains(input, []byte("package ")) || !bytes.Contains(input, []byte("func ")) {
		return nil, false // the pure-Go fallback only handles Go
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "", input, parser.SkipObjectResolution)
	if err != nil {
		return nil, false // malformed → pass-through
	}
	changed := false
	ast.Inspect(file, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			return true
		}
		if len(fn.Body.List) == 0 {
			return true // already empty → idempotent
		}
		fn.Body.List = nil
		changed = true
		return true
	})
	if !changed {
		return nil, false
	}
	var buf bytes.Buffer
	if err := (&printer.Config{Mode: printer.TabIndent, Tabwidth: 8}).Fprint(&buf, fset, file); err != nil {
		return nil, false
	}
	// gofmt the printed result to collapse the blank lines left where bodies
	// were. If gofmt cannot parse it back, the printed bytes are still valid Go.
	if formatted, err := format.Source(buf.Bytes()); err == nil {
		return formatted, true
	}
	return buf.Bytes(), true
}

package compressors

// CommentMode controls how the code compressor treats comments and docstrings.
// The zero value (CommentKeep) preserves the historical behavior: only function
// bodies are elided and comments/docstrings are left untouched.
type CommentMode int

const (
	// CommentKeep leaves comments / docstrings untouched (default).
	CommentKeep CommentMode = iota
	// CommentRemove elides comment (and, for Docstrings, Python docstring) nodes
	// entirely. Removal is always followed by the compressor's re-parse gate, so
	// any removal that would break the parse falls back to pass-through.
	CommentRemove
)

// CodeOptions configures the code compressor. The zero value is the historical
// behavior (bodies elided, comments and docstrings kept). A FirstLine mode is
// intentionally not offered yet: trimming a comment/docstring to its first line
// requires language-specific quote-style surgery that is high-risk for the
// marginal token win, and the re-parse gate cannot catch a semantically-wrong
// (but still parseable) truncation.
type CodeOptions struct {
	// Comments controls non-docstring comment nodes (all supported languages).
	Comments CommentMode
	// Docstrings controls Python module/class docstrings (string-literal
	// statements). Brace languages have no docstrings; this is a no-op for them.
	Docstrings CommentMode
}

package compressors_test

import (
	"bytes"
	"go/parser"
	"go/token"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
)

func codeCompressor(t *testing.T) compressors.Compressor {
	t.Helper()
	c, ok := compressors.Default().For("code")
	if !ok {
		t.Fatal("no code compressor registered")
	}
	return c
}

const goSource = `package demo

import "fmt"

// Add sums two ints.
func Add(a, b int) int {
	total := a + b
	fmt.Println(total)
	return total
}

func Mul(a, b int) int {
	result := 0
	for i := 0; i < b; i++ {
		result += a
	}
	return result
}
`

func TestCodeCompressorGoElidesBodiesKeepsSignatures(t *testing.T) {
	c := codeCompressor(t)
	out, ok := c.Compress([]byte(goSource))
	if !ok {
		t.Fatal("expected Go to compress")
	}
	if len(out) >= len(goSource) {
		t.Error("expected the source to shrink")
	}
	// Signatures and imports survive.
	for _, want := range []string{"func Add(a, b int) int", "func Mul(a, b int) int", `import "fmt"`} {
		if !bytes.Contains(out, []byte(want)) {
			t.Errorf("output must keep %q:\n%s", want, out)
		}
	}
	// Body detail is gone.
	if bytes.Contains(out, []byte("total := a + b")) {
		t.Error("function body should be elided")
	}
	// Output must still parse as valid Go.
	if _, err := parser.ParseFile(token.NewFileSet(), "", out, 0); err != nil {
		t.Errorf("compressed Go must re-parse: %v\n%s", err, out)
	}
}

func TestCodeCompressorGoIdempotent(t *testing.T) {
	c := codeCompressor(t)
	first, ok := c.Compress([]byte(goSource))
	if !ok {
		t.Fatal("expected compression")
	}
	if second, ok := c.Compress(first); ok && !bytes.Equal(first, second) {
		t.Errorf("not idempotent:\n first=%s\nsecond=%s", first, second)
	}
}

func TestCodeCompressorMalformedPassesThrough(t *testing.T) {
	c := codeCompressor(t)
	if _, ok := c.Compress([]byte("this is not source code at all, just words")); ok {
		t.Error("non-code must pass through (!ok)")
	}
	if _, ok := c.Compress([]byte("package x\nfunc broken( {\n")); ok {
		t.Error("unparseable Go must pass through (!ok)")
	}
}

// Package compressors holds the engine's content-type compressors and the
// registry that routes a content type to one. A compressor is a pure byte
// transform: it never counts tokens, stores recoveries, or talks to the
// network — the engine core does that around it. This keeps each compressor a
// self-contained, testable module and is why adding one is just a new file + its
// tests.
package compressors

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"sort"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// Compressor compresses one content type. Every compressor is structural,
// deterministic, idempotent, and fail-closed: on any parse problem it returns
// ok=false and the caller forwards the original bytes unchanged. Byte safety is
// derived from the compressor's safety class, not assumed for every compressor.
type Compressor interface {
	// ContentType is the type this compressor handles (e.g. "json").
	ContentType() string
	// SafetyClass is the compressor's inherent class on the S0–S4 ladder.
	SafetyClass() safety.Class
	// Compress returns the compressed bytes with ok=true on success. On any
	// parse problem (malformed input, an unsupported shape) it returns
	// (nil-or-input, false) and the caller MUST forward the original unchanged.
	Compress(input []byte) (out []byte, ok bool)
}

// Metadata describes what a compressor actually emitted for one successful
// transform. Composite compressors use it to report their chosen method.
type Metadata struct {
	Method           string
	LosslessToModel  *bool
	RecoveryMetadata []byte
}

// MetadataCompressor is an optional capability for compressors that can report
// per-result method metadata, or whose method differs from ContentType.
type MetadataCompressor interface {
	Compressor
	CompressWithMetadata(input []byte, query string) (out []byte, meta Metadata, ok bool)
}

func metadataBool(v bool) *bool { return &v }

// QueryAwareCompressor is an optional capability a compressor may implement to
// bias its output toward a query. The engine type-asserts for it and calls
// CompressQuery only when Options.Query is non-empty; compressors that do not
// implement it are unaffected and keep using Compress. Fail-closed behavior is unchanged:
// CompressQuery still returns ok=false on any parse problem so the caller
// forwards the original bytes unchanged, and a query never makes the output
// larger than the query-agnostic result would be.
type QueryAwareCompressor interface {
	Compressor
	// CompressQuery is Compress with an additional relevance query. An empty
	// query must behave exactly like Compress.
	CompressQuery(input []byte, query string) (out []byte, ok bool)
}

// Registry maps content types to compressors.
type Registry struct {
	m map[string]Compressor
}

// NewRegistry returns an empty registry.
func NewRegistry() *Registry { return &Registry{m: map[string]Compressor{}} }

// Register adds a compressor, keyed by its content type. A later registration
// for the same type replaces the earlier one.
func (r *Registry) Register(c Compressor) { r.m[c.ContentType()] = c }

// For returns the compressor for a content type, or (nil, false).
func (r *Registry) For(contentType string) (Compressor, bool) {
	c, ok := r.m[contentType]
	return c, ok
}

// Default returns a registry with the engine's built-in compressors registered:
// JSON, log, code, diff, search-result, text, HTML, tabular, config, tool-schema,
// lossless tool-schema, TOON, accessibility-tree, repetition, and terminal. The
// code compressor is selected at build time — a tree-sitter-backed one when cgo is
// enabled, a pure-Go go/ast one otherwise. HTML and terminal are auto-detected
// (Detect → "html"/"terminal"); tool-schema, lossless tool-schema, TOON,
// accessibility-tree, and repetition are never auto-detected and are reached only
// by forcing Options.Type.
func Default() *Registry {
	r := NewRegistry()
	r.Register(NewJSON())
	r.Register(NewLog())
	r.Register(newCode())
	r.Register(NewDiff())
	r.Register(NewSearchResult())
	r.Register(NewText())
	r.Register(NewHTML())
	r.Register(NewTabular())
	r.Register(NewConfig())
	r.Register(NewToolSchema())
	r.Register(NewToolSchemaAnnotations())
	r.Register(NewTOON())
	r.Register(NewAXTree())
	r.Register(NewRepetition())
	r.Register(NewTerminal())
	return r
}

// CapabilityRegistry is the public, content-blind transform ABI consumed by
// Cave Compiler. Its JSON field names match transform-capability.schema.json.
type CapabilityRegistry struct {
	SchemaVersion  int          `json:"schema_version"`
	RegistrySHA256 string       `json:"registry_sha256"`
	Capabilities   []Capability `json:"capabilities"`
}

// Capability describes one deterministic engine transform. Content bytes and
// customer identifiers never enter this manifest.
type Capability struct {
	TransformID           string     `json:"transform_id"`
	ImplementationVersion string     `json:"implementation_version"`
	SafetyClasses         []string   `json:"safety_classes"`
	Deterministic         bool       `json:"deterministic"`
	Recovery              string     `json:"recovery"`
	EligibleSegmentKinds  []string   `json:"eligible_segment_kinds"`
	RequiresEval          bool       `json:"requires_eval"`
	NotSmallerFallback    string     `json:"not_smaller_fallback"`
	Provenance            Provenance `json:"provenance"`
	ConformanceDigest     string     `json:"conformance_digest"`
}

// Provenance pins whether source is native or externally derived.
type Provenance struct {
	Kind                 string  `json:"kind"`
	SourceManifestSHA256 *string `json:"source_manifest_sha256"`
}

// manifestExcluded are compressors that are registered — reachable by forcing
// Options.Type — but deliberately NOT advertised in the transform-capability ABI
// Cave Compiler consumes. Advertising one rotates RegistrySHA256, which every
// already-built Cave Build lock pins; a lock that no longer matches fails the
// agent at RUN time. A compressor belongs here when a compiled plan can never
// route to it anyway, so the ABI would gain a row it can never use in exchange
// for invalidating every lock in the field.
var manifestExcluded = map[string]bool{
	toolSchemaAnnotationsType: true,
}

// Capabilities exports the default engine registry in stable transform-ID
// order. Unknown safety classes fail closed by returning no capability.
func (r *Registry) Capabilities() []Capability {
	out := make([]Capability, 0, len(r.m))
	for contentType, compressor := range r.m {
		if manifestExcluded[contentType] {
			continue
		}
		class := compressor.SafetyClass()
		if !class.Valid() {
			return nil
		}
		conformance := sha256.Sum256([]byte("caveman.engine." + contentType + ":v1"))
		out = append(out, Capability{
			TransformID:           "caveman.engine." + contentType + ".v1",
			ImplementationVersion: "1",
			SafetyClasses:         []string{class.String()},
			Deterministic:         true,
			Recovery:              "exact_ccr",
			EligibleSegmentKinds:  eligibleSegments(contentType),
			RequiresEval:          true,
			NotSmallerFallback:    "original",
			Provenance: Provenance{
				Kind:                 "native",
				SourceManifestSHA256: nil,
			},
			ConformanceDigest: hex.EncodeToString(conformance[:]),
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].TransformID < out[j].TransformID })
	return out
}

// CapabilityManifest returns canonical compact JSON. RegistrySHA256 hashes the
// ordered capabilities only, avoiding a self-referential digest.
func (r *Registry) CapabilityManifest() ([]byte, error) {
	capabilities := r.Capabilities()
	if capabilities == nil {
		return nil, safetyClassError{}
	}
	canonical, err := json.Marshal(capabilities)
	if err != nil {
		return nil, err
	}
	digest := sha256.Sum256(canonical)
	return json.Marshal(CapabilityRegistry{
		SchemaVersion:  1,
		RegistrySHA256: hex.EncodeToString(digest[:]),
		Capabilities:   capabilities,
	})
}

type safetyClassError struct{}

func (safetyClassError) Error() string { return "compressors: unknown safety class" }

func eligibleSegments(contentType string) []string {
	switch contentType {
	case "toolschema":
		return []string{"tool_schema"}
	case "a11y":
		return []string{"artifact", "tool_result"}
	case "repetition":
		return []string{"history", "tool_result"}
	default:
		return []string{"artifact", "history", "skill", "tool_result"}
	}
}

package compressors

import (
	"bytes"
	"fmt"
	"io"
	"regexp"
	"strings"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
	"gopkg.in/yaml.v3"
)

var (
	yamlKeyRe          = regexp.MustCompile(`^\s*(?:-\s*)?[A-Za-z0-9_.-]+\s*:\s*`)
	configAssignmentRe = regexp.MustCompile(`^\s*[A-Za-z0-9_.-]+\s*=\s*\S`)
	configSectionRe    = regexp.MustCompile(`^\s*\[[A-Za-z0-9_.:"' -]+\]\s*(?:[#;].*)?$`)
	configImportantRe  = regexp.MustCompile(`(?i)\b(ERROR|FAIL|FAILED|FATAL|PANIC|EXCEPTION|WARNING|SECURITY|SECRET|TOKEN|PASSWORD|DENIED|REJECTED|ROLLBACK)\b`)
	configMarkerRe     = regexp.MustCompile(`config lines elided \(caveman\)`)
	yamlBlockScalarRe  = regexp.MustCompile(`:\s*[|>][0-9+-]*\s*(?:#.*)?$`)
)

type configKind uint8

const (
	configYAML configKind = iota + 1
	configTOML
)

type configCompressor struct {
	minLines     int
	keepHead     int
	keepTail     int
	queryLimit   int
	relevanceMin float64
}

// NewConfig returns the deterministic YAML, TOML, and INI compressor.
func NewConfig() Compressor {
	return &configCompressor{minLines: 14, keepHead: 3, keepTail: 2, queryLimit: 16, relevanceMin: 0.30}
}

func (c *configCompressor) ContentType() string       { return "config" }
func (c *configCompressor) SafetyClass() safety.Class { return safety.S4 }
func (c *configCompressor) Compress(input []byte) ([]byte, bool) {
	return c.compress(input, "")
}
func (c *configCompressor) CompressQuery(input []byte, query string) ([]byte, bool) {
	return c.compress(input, query)
}

// LooksConfig recognizes only dense YAML/TOML/INI payloads. Low-confidence
// content stays ordinary text.
func LooksConfig(input []byte) bool {
	_, lines, ok := parseConfig(input)
	return ok && len(lines) >= 12
}

func (c *configCompressor) compress(input []byte, query string) ([]byte, bool) {
	if configMarkerRe.Match(input) {
		return nil, false
	}
	kind, lines, ok := parseConfig(input)
	if !ok || len(lines) < c.minLines {
		return nil, false
	}
	keep := make([]bool, len(lines))
	for i := 0; i < c.keepHead && i < len(lines); i++ {
		keep[i] = true
	}
	for i := len(lines) - c.keepTail; i < len(lines); i++ {
		if i >= 0 {
			keep[i] = true
		}
	}
	docs := make([]string, len(lines))
	for i, line := range lines {
		docs[i] = string(line)
		if configImportantRe.Match(line) {
			keep[i] = true
		}
		if kind == configYAML && indentation(line) == 0 && yamlKeyRe.Match(line) {
			keep[i] = true
		}
	}
	keepQueryRelevant(keep, docs, query, c.queryLimit, c.relevanceMin)
	keepNonRedundant(lines, keep)
	if kind == configYAML {
		expandYAMLContext(lines, keep)
	} else {
		expandSectionContext(lines, keep)
	}

	out := make([][]byte, 0, len(lines))
	dropped := 0
	flush := func() {
		if dropped == 0 {
			return
		}
		out = append(out, []byte(fmt.Sprintf("# … %d config lines elided (caveman) …", dropped)))
		dropped = 0
	}
	for i, line := range lines {
		if keep[i] {
			flush()
			out = append(out, line)
		} else {
			dropped++
		}
	}
	flush()
	if len(out) >= len(lines) {
		return nil, false
	}
	sep := []byte("\n")
	if bytes.Contains(input, []byte("\r\n")) {
		sep = []byte("\r\n")
	}
	result := bytes.Join(out, sep)
	if bytes.HasSuffix(input, sep) {
		result = append(result, sep...)
	}
	if len(result) >= len(input) {
		return nil, false
	}
	if kind == configYAML && !validYAML(result) {
		return nil, false
	}
	return result, true
}

func parseConfig(input []byte) (configKind, [][]byte, bool) {
	if !utf8.Valid(input) || len(bytes.TrimSpace(input)) == 0 {
		return 0, nil, false
	}
	normalized := bytes.ReplaceAll(input, []byte("\r\n"), []byte("\n"))
	lines := bytes.Split(bytes.TrimSuffix(normalized, []byte("\n")), []byte("\n"))
	yamlKeys, assignments, sections, prose := 0, 0, 0, 0
	yamlBlockScalar := false
	for _, raw := range lines {
		line := bytes.TrimSpace(raw)
		if len(line) == 0 || bytes.HasPrefix(line, []byte("#")) || bytes.HasPrefix(line, []byte(";")) {
			continue
		}
		if yamlBlockScalarRe.Match(line) {
			yamlBlockScalar = true
		}
		switch {
		case configSectionRe.Match(line):
			sections++
		case configAssignmentRe.Match(line):
			assignments++
		case yamlKeyRe.Match(line):
			yamlKeys++
		case bytes.HasPrefix(line, []byte("- ")):
			// YAML sequence item. Parent key density establishes confidence.
		default:
			prose++
		}
	}
	significant := yamlKeys + assignments + sections + prose
	if significant == 0 {
		return 0, nil, false
	}
	if sections >= 2 && assignments >= 4 && prose == 0 &&
		!bytes.Contains(input, []byte(`"""`)) && !bytes.Contains(input, []byte(`'''`)) {
		return configTOML, lines, true
	}
	if yamlKeys >= 6 && yamlKeys*2 >= significant && prose*4 <= significant &&
		!yamlBlockScalar && validYAML(input) {
		return configYAML, lines, true
	}
	return 0, nil, false
}

func validYAML(input []byte) bool {
	decoder := yaml.NewDecoder(bytes.NewReader(input))
	documents := 0
	for {
		var document any
		err := decoder.Decode(&document)
		if err == io.EOF {
			return documents > 0
		}
		if err != nil {
			return false
		}
		documents++
	}
}

func indentation(line []byte) int {
	n := 0
	for _, ch := range line {
		if ch == ' ' {
			n++
			continue
		}
		if ch == '\t' {
			n += 2
			continue
		}
		break
	}
	return n
}

func yamlParentLine(line []byte) bool {
	trimmed := strings.TrimSpace(string(line))
	return yamlKeyRe.Match(line) && (strings.HasSuffix(trimmed, ":") || strings.HasPrefix(trimmed, "- "))
}

func expandYAMLContext(lines [][]byte, keep []bool) {
	original := append([]bool(nil), keep...)
	for i, selected := range original {
		if !selected {
			continue
		}
		indent := indentation(lines[i])
		for parentIndent := indent - 1; parentIndent >= 0; {
			found := false
			for j := i - 1; j >= 0; j-- {
				candidateIndent := indentation(lines[j])
				if candidateIndent < indent && yamlParentLine(lines[j]) {
					keep[j] = true
					indent = candidateIndent
					parentIndent = indent - 1
					found = true
					break
				}
			}
			if !found {
				break
			}
		}
	}
	// Parent discovery above may newly select a sequence item such as
	// `- name: settlement-writer`. Expand children from the updated keep set so
	// query-relevant nested values stay attached to that item and YAML remains
	// semantically useful, not merely parseable.
	for i, selected := range keep {
		if !selected || !yamlParentLine(lines[i]) {
			continue
		}
		base := indentation(lines[i])
		for j := i + 1; j < len(lines) && j <= i+8; j++ {
			if len(bytes.TrimSpace(lines[j])) == 0 {
				continue
			}
			if indentation(lines[j]) <= base {
				break
			}
			keep[j] = true
		}
	}
}

func expandSectionContext(lines [][]byte, keep []bool) {
	section := -1
	for i, line := range lines {
		if configSectionRe.Match(line) {
			section = i
		}
		if keep[i] && section >= 0 {
			keep[section] = true
		}
	}
	original := append([]bool(nil), keep...)
	for i, selected := range original {
		if !selected || !configSectionRe.Match(lines[i]) {
			continue
		}
		for j := i + 1; j < len(lines) && j <= i+8; j++ {
			if configSectionRe.Match(lines[j]) {
				break
			}
			keep[j] = true
		}
	}
}

package compressors_test

import (
	"bytes"
	"fmt"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
	"github.com/JuliusBrussee/caveman/engine/safety"
	"gopkg.in/yaml.v3"
)

func yamlFixture() []byte {
	var b strings.Builder
	b.WriteString("service:\n  name: checkout\n  owner: payments\n  database:\n    host: db.internal\n    port: 5432\n")
	for i := 0; i < 50; i++ {
		fmt.Fprintf(&b, "  feature_%02d:\n    enabled: %t\n    rollout: %d\n", i, i%2 == 0, i)
	}
	b.WriteString("  incident:\n    status: ERROR\n    action: rollback\n")
	return []byte(b.String())
}

func TestConfigYAMLKeepsParentsImportantAndQueryRelevantLines(t *testing.T) {
	c, ok := compressors.NewConfig().(compressors.QueryAwareCompressor)
	if !ok {
		t.Fatal("config compressor must be query-aware")
	}
	if c.SafetyClass() != safety.S4 {
		t.Fatal("config compressor must be S4")
	}
	input := yamlFixture()
	out, ok := c.CompressQuery(input, "feature_37 rollout")
	if !ok {
		t.Fatal("expected YAML compression")
	}
	if len(out) >= len(input) {
		t.Fatal("expected YAML to shrink")
	}
	for _, want := range [][]byte{
		[]byte("service:"),
		[]byte("feature_37:"),
		[]byte("rollout: 37"),
		[]byte("status: ERROR"),
		[]byte("config lines elided (caveman)"),
	} {
		if !bytes.Contains(out, want) {
			t.Fatalf("compressed YAML missing %q:\n%s", want, out)
		}
	}
	var parsed any
	if err := yaml.Unmarshal(out, &parsed); err != nil {
		t.Fatalf("compressed YAML must remain valid: %v\n%s", err, out)
	}
	if second, ok := c.CompressQuery(out, "feature_37 rollout"); ok && !bytes.Equal(out, second) {
		t.Fatalf("compressed YAML must be idempotent:\nfirst=%s\nsecond=%s", out, second)
	}
}

func TestConfigYAMLQueryKeepsSequenceItemParent(t *testing.T) {
	var b strings.Builder
	b.WriteString("services:\n")
	for i := 0; i < 100; i++ {
		fmt.Fprintf(&b, "  - name: worker-%03d\n    environment: staging\n    max_inflight: 80\n    drift: false\n", i)
		if i == 61 {
			b.WriteString("  - name: settlement-writer\n    environment: production\n    max_inflight: 240\n    expected_max_inflight: 80\n    drift: true\n")
		}
	}
	input := []byte(b.String())
	c := compressors.NewConfig().(compressors.QueryAwareCompressor)
	out, ok := c.CompressQuery(input, "find production config drift expected actual")
	if !ok {
		t.Fatal("expected sequence-shaped YAML compression")
	}
	for _, want := range [][]byte{
		[]byte("- name: settlement-writer"),
		[]byte("environment: production"),
		[]byte("max_inflight: 240"),
		[]byte("expected_max_inflight: 80"),
		[]byte("drift: true"),
	} {
		if !bytes.Contains(out, want) {
			t.Fatalf("compressed YAML missing %q:\n%s", want, out)
		}
	}
	var parsed any
	if err := yaml.Unmarshal(out, &parsed); err != nil {
		t.Fatalf("compressed sequence YAML must remain valid: %v\n%s", err, out)
	}
}

func TestConfigTOMLKeepsSectionHeadersAndRelevantValue(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 30; i++ {
		fmt.Fprintf(&b, "[feature.%02d]\nenabled = %t\nowner = \"team-%02d\"\n", i, i%2 == 0, i)
	}
	input := []byte(b.String())
	c := compressors.NewConfig().(compressors.QueryAwareCompressor)
	out, ok := c.CompressQuery(input, "feature 17 team-17")
	if !ok {
		t.Fatal("expected TOML compression")
	}
	for _, want := range [][]byte{[]byte("[feature.17]"), []byte(`owner = "team-17"`), []byte("# …")} {
		if !bytes.Contains(out, want) {
			t.Fatalf("compressed TOML missing %q:\n%s", want, out)
		}
	}
}

func TestConfigINIStaysSectionShapedAndKeepsQueryValue(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 30; i++ {
		fmt.Fprintf(&b, "[feature.%02d]\nenabled = %t\nowner = team-%02d\n", i, i%2 == 0, i)
	}
	input := []byte(b.String())
	c := compressors.NewConfig().(compressors.QueryAwareCompressor)
	out, ok := c.CompressQuery(input, "feature 19 team-19")
	if !ok {
		t.Fatal("expected INI compression")
	}
	for _, want := range [][]byte{[]byte("[feature.19]"), []byte("owner = team-19"), []byte("# …")} {
		if !bytes.Contains(out, want) {
			t.Fatalf("compressed INI missing %q:\n%s", want, out)
		}
	}
	for _, line := range strings.Split(string(out), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, "[") || strings.Contains(line, "=") {
			continue
		}
		t.Fatalf("compressed INI contains malformed line %q", line)
	}
}

func TestConfigPreservesCRLFWithoutAddingTrailingNewline(t *testing.T) {
	input := bytes.ReplaceAll(bytes.TrimSuffix(yamlFixture(), []byte("\n")), []byte("\n"), []byte("\r\n"))
	out, ok := compressors.NewConfig().Compress(input)
	if !ok {
		t.Fatal("expected YAML compression")
	}
	if bytes.HasSuffix(out, []byte{'\r'}) || bytes.HasSuffix(out, []byte{'\n'}) {
		t.Fatalf("unexpected trailing newline bytes: %q", out[len(out)-4:])
	}
	if bytes.Contains(bytes.ReplaceAll(out, []byte("\r\n"), nil), []byte("\n")) {
		t.Fatal("compressed YAML mixed newline styles")
	}
}

func TestConfigInvalidTinyOrBinaryPassesThrough(t *testing.T) {
	c := compressors.NewConfig()
	var malformed strings.Builder
	malformed.WriteString("service:\n")
	for i := 0; i < 20; i++ {
		fmt.Fprintf(&malformed, "  feature_%02d: true\n", i)
	}
	malformed.WriteString("  broken: [one, two\n")

	var blockScalar strings.Builder
	blockScalar.WriteString("service:\n  script: |\n")
	for i := 0; i < 20; i++ {
		fmt.Fprintf(&blockScalar, "    echo step-%02d\n", i)
	}

	var multilineTOML strings.Builder
	for i := 0; i < 8; i++ {
		fmt.Fprintf(&multilineTOML, "[feature.%02d]\nenabled = true\n", i)
	}
	multilineTOML.WriteString("description = \"\"\"multi\nline\nvalue\"\"\"\n")

	for _, input := range [][]byte{
		[]byte("service:\n  port: 8080\n"),
		[]byte("this is prose\nwithout config syntax\nrepeated over lines\n"),
		[]byte(malformed.String()),
		[]byte(blockScalar.String()),
		[]byte(multilineTOML.String()),
		{0xff, 0xfe, 0xfd},
	} {
		if out, ok := c.Compress(input); ok {
			t.Fatalf("unsafe input must pass through, got %q", out)
		}
	}
}

package compressors

import (
	"bytes"
	"fmt"
	"regexp"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

var diffMarkerRe = regexp.MustCompile(`context lines elided \(caveman\)`)

func diffMarker(n int) string { return fmt.Sprintf("… %d context lines elided (caveman) …", n) }

// diffCompressor keeps file/hunk headers plus changed lines and collapses long
// runs of unchanged context. It is S4: full context is recoverable via CCR.
type diffCompressor struct {
	keepContext int
	minLines    int
}

// NewDiff returns the unified-diff compressor.
func NewDiff() Compressor { return &diffCompressor{keepContext: 2, minLines: 12} }

func (c *diffCompressor) ContentType() string       { return "diff" }
func (c *diffCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *diffCompressor) Compress(input []byte) ([]byte, bool) {
	if !utf8.Valid(input) {
		return nil, false
	}
	sep := []byte("\n")
	if bytes.Contains(input, []byte("\r\n")) {
		sep = []byte("\r\n")
	}
	trailing := bytes.HasSuffix(input, sep)
	body := input
	if trailing {
		body = body[:len(body)-len(sep)]
	}
	lines := bytes.Split(body, sep)
	if len(lines) < c.minLines {
		return nil, false
	}

	keep := make([]bool, len(lines))
	for i, line := range lines {
		if isDiffStructuralLine(line) || diffMarkerRe.Match(line) {
			keep[i] = true
			for j := max(0, i-c.keepContext); j <= min(len(lines)-1, i+c.keepContext); j++ {
				keep[j] = true
			}
		}
	}

	out := make([][]byte, 0, len(lines))
	dropped := 0
	for i, line := range lines {
		if keep[i] {
			if dropped > 0 {
				out = append(out, []byte(diffMarker(dropped)))
				dropped = 0
			}
			out = append(out, line)
		} else {
			dropped++
		}
	}
	if dropped > 0 {
		out = append(out, []byte(diffMarker(dropped)))
	}
	if len(out) == len(lines) {
		return nil, false
	}
	result := bytes.Join(out, sep)
	if trailing {
		result = append(result, sep...)
	}
	return result, true
}

func isDiffStructuralLine(line []byte) bool {
	return bytes.HasPrefix(line, []byte("diff --git ")) ||
		bytes.HasPrefix(line, []byte("index ")) ||
		bytes.HasPrefix(line, []byte("--- ")) ||
		bytes.HasPrefix(line, []byte("+++ ")) ||
		bytes.HasPrefix(line, []byte("@@ ")) ||
		(isChangedDiffLine(line))
}

func isChangedDiffLine(line []byte) bool {
	if len(line) < 2 {
		return false
	}
	if line[0] != '+' && line[0] != '-' {
		return false
	}
	return line[1] != '+' && line[1] != '-'
}

package compressors

import (
	"bytes"
	"regexp"
	"strconv"
	"strings"

	"golang.org/x/net/html"
	"golang.org/x/net/html/atom"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// HTMLType is the content type the HTML article extractor handles. It matches
// engine.TypeHTML and is reached via the content router (Detect → "html").
const HTMLType = "html"

var (
	htmlPositiveRe = regexp.MustCompile(`(?i)(article|body|content|entry|main|page|post|story|text|blog)`)
	htmlNegativeRe = regexp.MustCompile(`(?i)(comment|nav|sidebar|footer|header|menu|promo|banner|ad-|share|social|related|breadcrumb|cookie|popup|modal|widget)`)
)

// htmlCompressor extracts the main article text from an HTML document, dropping
// boilerplate (nav, sidebars, scripts, styles, footers) using a deterministic
// readability-style heuristic: block elements score by text volume and a
// class/id signal, scores propagate to their container, and the container is
// discounted by its link density (link-heavy nodes are navigation, not prose).
// It is pure-Go (works in the cgo and WASM builds alike) and S4 (lossy): the
// original is recoverable via CCR. It bails to pass-through on any doubt — a
// parse failure, no <body>, no clear main container, a link-dense winner, or an
// extraction that is too small — so it never claims a result it cannot stand by.
type htmlCompressor struct {
	minOutputBytes int
}

// NewHTML returns the default HTML article extractor.
func NewHTML() Compressor { return &htmlCompressor{minOutputBytes: 200} }

func (c *htmlCompressor) ContentType() string       { return HTMLType }
func (c *htmlCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *htmlCompressor) Compress(input []byte) ([]byte, bool) {
	if len(bytes.TrimSpace(input)) == 0 {
		return nil, false
	}
	doc, err := html.Parse(bytes.NewReader(input))
	if err != nil {
		return nil, false
	}
	stripNoise(doc)
	body := findFirst(doc, atom.Body)
	if body == nil {
		return nil, false // not a document we can localize content within
	}

	scores := map[*html.Node]int{}
	accumulateScores(body, scores)
	best := pickBest(body, scores)
	if best == nil || best == body {
		return nil, false // could not localize a main container → claim nothing
	}
	// Reject a link-dense winner (an index/nav block, not an article): bail when
	// at least half the text is anchor text.
	total, link := textLen(best), anchorTextLen(best)
	if total == 0 || link*2 >= total {
		return nil, false
	}

	text := strings.TrimSpace(renderText(best))
	if len(text) < c.minOutputBytes {
		return nil, false
	}
	out := []byte(text)
	if len(out) >= len(input) {
		return nil, false // extraction did not shrink the payload
	}
	return out, true
}

// stripNoise removes elements that never carry article content.
func stripNoise(n *html.Node) {
	var toRemove []*html.Node
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			if ch.Type == html.ElementNode {
				switch ch.DataAtom {
				case atom.Script, atom.Style, atom.Noscript, atom.Svg, atom.Iframe, atom.Form, atom.Button, atom.Input, atom.Template:
					toRemove = append(toRemove, ch)
					continue
				}
			}
			walk(ch)
		}
	}
	walk(n)
	for _, r := range toRemove {
		if r.Parent != nil {
			r.Parent.RemoveChild(r)
		}
	}
}

// isScorable reports whether an element's text volume should contribute a score.
func isScorable(a atom.Atom) bool {
	switch a {
	case atom.P, atom.Pre, atom.Td, atom.Blockquote, atom.Li,
		atom.H1, atom.H2, atom.H3, atom.H4, atom.H5, atom.H6:
		return true
	}
	return false
}

// isContainer reports whether an element can be a content container candidate.
func isContainer(a atom.Atom) bool {
	switch a {
	case atom.Div, atom.Article, atom.Main, atom.Section, atom.Td, atom.Body:
		return true
	}
	return false
}

// accumulateScores walks the document and adds a content score for each scorable
// block to its nearest container ancestor (full) and the next container up
// (half), then folds in the container's class/id signal once.
func accumulateScores(root *html.Node, scores map[*html.Node]int) {
	seen := map[*html.Node]bool{}
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode && isScorable(n.DataAtom) {
			txt := textContent(n)
			if len(strings.TrimSpace(txt)) >= 25 {
				base := 1 + strings.Count(txt, ",") + minInt(len(txt)/100, 3)
				// Credit every container ancestor (full), not just the nearest two,
				// so an outer container holding several sections always outscores any
				// single inner section — otherwise a multi-section article truncates
				// to its highest-scoring section. <body> is never credited: it is
				// excluded as a winner, and crediting it would make it the top scorer
				// (sum of everything) and force a spurious "couldn't localize" bail.
				for p := containerAncestor(n); p != nil; p = containerAncestor(p) {
					if p.DataAtom == atom.Body {
						continue
					}
					if !seen[p] {
						seen[p] = true
						scores[p] += classIDWeight(p)
					}
					scores[p] += base
				}
			}
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
	}
	walk(root)
}

// pickBest returns the highest-scoring container, discounting each by its link
// density. It walks in document order so ties resolve deterministically (first
// wins), never by map iteration order.
func pickBest(root *html.Node, scores map[*html.Node]int) *html.Node {
	var best *html.Node
	bestScore := 0
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if raw, ok := scores[n]; ok && raw > 0 {
			total := textLen(n)
			final := raw
			if total > 0 {
				final = raw * (total - anchorTextLen(n)) / total // integer link-density discount
			}
			if final > bestScore {
				bestScore = final
				best = n
			}
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
	}
	walk(root)
	return best
}

func classIDWeight(n *html.Node) int {
	var b strings.Builder
	for _, a := range n.Attr {
		if a.Key == "class" || a.Key == "id" {
			b.WriteByte(' ')
			b.WriteString(a.Val)
		}
	}
	s := b.String()
	if s == "" {
		return 0
	}
	w := 0
	if htmlPositiveRe.MatchString(s) {
		w += 25
	}
	if htmlNegativeRe.MatchString(s) {
		w -= 25
	}
	return w
}

// containerAncestor returns the nearest ancestor that can hold content.
func containerAncestor(n *html.Node) *html.Node {
	for p := n.Parent; p != nil; p = p.Parent {
		if p.Type == html.ElementNode && isContainer(p.DataAtom) {
			return p
		}
	}
	return nil
}

func findFirst(n *html.Node, a atom.Atom) *html.Node {
	if n.Type == html.ElementNode && n.DataAtom == a {
		return n
	}
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		if got := findFirst(ch, a); got != nil {
			return got
		}
	}
	return nil
}

func textContent(n *html.Node) string {
	var b strings.Builder
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.TextNode {
			b.WriteString(n.Data)
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
	}
	walk(n)
	return b.String()
}

func textLen(n *html.Node) int { return len(strings.TrimSpace(textContent(n))) }

func anchorTextLen(n *html.Node) int {
	total := 0
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode && n.DataAtom == atom.A {
			total += len(strings.TrimSpace(textContent(n)))
			return // do not double-count nested anchors
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
	}
	walk(n)
	return total
}

// renderText serializes a node subtree to readable plain text. Block-level
// elements introduce paragraph breaks; inline elements emit a space boundary so
// adjacent text never merges across a tag (e.g. "<b>fifty</b><i>dollars</i>"
// stays "fifty dollars", not "fiftydollars"). <pre> content is preserved
// verbatim (its whole contract is whitespace), protected from the collapse pass
// via a placeholder. Deterministic.
func renderText(n *html.Node) string {
	var b strings.Builder
	var pres []string
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode && n.DataAtom == atom.Pre {
			idx := len(pres)
			pres = append(pres, strings.Trim(textContent(n), "\n"))
			b.WriteString("\n\x00PRE")
			b.WriteString(strconv.Itoa(idx))
			b.WriteString("\x00\n")
			return // do not descend; pre text is captured verbatim
		}
		switch n.Type {
		case html.TextNode:
			b.WriteString(n.Data)
		case html.ElementNode:
			if isBlockLevel(n.DataAtom) {
				b.WriteString("\n")
			} else {
				b.WriteString(" ") // inline boundary
			}
		}
		for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
		if n.Type == html.ElementNode {
			if isBlockLevel(n.DataAtom) {
				b.WriteString("\n")
			} else {
				b.WriteString(" ")
			}
		}
	}
	walk(n)
	out := collapseWhitespace(b.String())
	for i, p := range pres {
		out = strings.Replace(out, "\x00PRE"+strconv.Itoa(i)+"\x00", p, 1)
	}
	return out
}

func isBlockLevel(a atom.Atom) bool {
	switch a {
	case atom.P, atom.Div, atom.Br, atom.Li, atom.Ul, atom.Ol, atom.Pre, atom.Blockquote,
		atom.Section, atom.Article, atom.H1, atom.H2, atom.H3, atom.H4, atom.H5, atom.H6,
		atom.Tr, atom.Table, atom.Hr:
		return true
	}
	return false
}

var (
	htmlSpaceRe = regexp.MustCompile(`[ \t]+`)
	htmlBlankRe = regexp.MustCompile(`\n[ \t]*\n[ \t]*(\n[ \t]*)*`)
)

func collapseWhitespace(s string) string {
	lines := strings.Split(s, "\n")
	for i, ln := range lines {
		lines[i] = strings.TrimSpace(htmlSpaceRe.ReplaceAllString(ln, " "))
	}
	joined := strings.Join(lines, "\n")
	return strings.TrimSpace(htmlBlankRe.ReplaceAllString(joined, "\n\n"))
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

package compressors_test

import (
	"bytes"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
)

const articleHTML = `<!doctype html>
<html><head><title>Test</title><style>.x{color:red}</style></head>
<body>
<nav class="site-nav"><a href="/">Home</a> <a href="/about">About</a> <a href="/blog">Blog</a> <a href="/contact">Contact</a></nav>
<header class="banner"><a href="/login">Log in</a> <a href="/signup">Sign up</a></header>
<article class="post-content">
<h1>The Title Of The Article</h1>
<p>This is the first substantial paragraph of the article body. It contains several sentences, with commas, and enough text to score well above the threshold the extractor uses.</p>
<p>Here is a second meaningful paragraph that continues the article, again with commas, clauses, and real prose so the container accrues a high content score.</p>
<p>A third paragraph rounds out the body with yet more sentence-level content, commas, and substance for the reader to consume.</p>
</article>
<aside class="sidebar"><a href="/a">Related 1</a><a href="/b">Related 2</a><a href="/c">Related 3</a></aside>
<footer class="site-footer"><a href="/tos">Terms</a> <a href="/privacy">Privacy</a> copyright notice here</footer>
<script>console.log("tracking pixel and analytics noise that should never survive")</script>
</body></html>`

func TestHTMLExtractsArticleDropsBoilerplate(t *testing.T) {
	c := compressors.NewHTML()
	out, ok := c.Compress([]byte(articleHTML))
	if !ok {
		t.Fatal("expected extraction of the article")
	}
	s := string(out)
	// Article content survives.
	for _, must := range []string{"The Title Of The Article", "first substantial paragraph", "third paragraph"} {
		if !strings.Contains(s, must) {
			t.Errorf("article content dropped: %q\n--- got ---\n%s", must, s)
		}
	}
	// Boilerplate and noise are gone.
	for _, gone := range []string{"tracking pixel", "color:red", "Sign up", "Privacy"} {
		if strings.Contains(s, gone) {
			t.Errorf("boilerplate %q should have been dropped:\n%s", gone, s)
		}
	}
	if len(out) >= len(articleHTML) {
		t.Error("expected real compression")
	}
}

func TestHTMLDeterministic(t *testing.T) {
	c := compressors.NewHTML()
	a, ok1 := c.Compress([]byte(articleHTML))
	b, ok2 := c.Compress([]byte(articleHTML))
	if !ok1 || !ok2 {
		t.Fatal("expected extraction")
	}
	if !bytes.Equal(a, b) {
		t.Errorf("non-deterministic:\n a=%s\n b=%s", a, b)
	}
}

func TestHTMLLinkFarmBails(t *testing.T) {
	// A nav/index page that is almost all links must bail (claim nothing) rather
	// than emit a link dump as if it were an article.
	var b strings.Builder
	b.WriteString("<!doctype html><html><body><div class=\"links\">")
	for i := 0; i < 40; i++ {
		b.WriteString(`<p><a href="/x">A link with a little text</a></p>`)
	}
	b.WriteString("</div></body></html>")
	if _, ok := compressors.NewHTML().Compress([]byte(b.String())); ok {
		t.Error("a link-dense page must bail to pass-through")
	}
}

func TestHTMLInlineTagsKeepWordBoundary(t *testing.T) {
	doc := `<!doctype html><html><body><article>
<h1>Pricing Headline Here For The Article Body</h1>
<p>The price is <b>fifty</b><i>dollars</i> total, and you can <a href="/x">read the docs</a>here for more information about everything involved.</p>
<p>A second paragraph with more than enough words and several commas, clauses, and content to score the container well above the extractor threshold here.</p>
</article></body></html>`
	out, ok := compressors.NewHTML().Compress([]byte(doc))
	if !ok {
		t.Fatal("expected extraction")
	}
	s := string(out)
	if strings.Contains(s, "fiftydollars") || strings.Contains(s, "docshere") {
		t.Errorf("inline tags must not join words:\n%s", s)
	}
}

func TestHTMLKeepsAllSections(t *testing.T) {
	doc := `<!doctype html><html><body><main>
<section><h1>INTRO_HEADLINE</h1><p>The introduction section has enough prose, with commas, to score, and it opens the piece with substance for the reader.</p></section>
<section><p>The middle section continues the article with more sentences, commas, and the kind of body text the extractor is built to keep around.</p></section>
<section><p>The outro section closes things out, again with real prose, commas, and a UNIQUE_OUTRO_MARKER token that must survive extraction.</p></section>
</main></body></html>`
	out, ok := compressors.NewHTML().Compress([]byte(doc))
	if !ok {
		t.Fatal("expected extraction")
	}
	s := string(out)
	for _, must := range []string{"INTRO_HEADLINE", "middle section", "UNIQUE_OUTRO_MARKER"} {
		if !strings.Contains(s, must) {
			t.Errorf("multi-section article truncated — %q dropped:\n%s", must, s)
		}
	}
}

func TestHTMLPreservesPreIndentation(t *testing.T) {
	doc := "<!doctype html><html><body><article>" +
		"<h1>Article With A Code Block Inside The Body Here</h1>" +
		"<p>Here is an explanatory paragraph with commas, clauses, and enough text to score the article container well above threshold for the reader.</p>" +
		"<pre>func main() {\n    if x == 1 {\n        run()\n    }\n}</pre>" +
		"</article></body></html>"
	out, ok := compressors.NewHTML().Compress([]byte(doc))
	if !ok {
		t.Fatal("expected extraction")
	}
	if !bytes.Contains(out, []byte("    if x == 1 {")) {
		t.Errorf("<pre> indentation must be preserved:\n%s", out)
	}
}

func TestHTMLNonDocumentBails(t *testing.T) {
	if _, ok := compressors.NewHTML().Compress([]byte("just a tiny <b>fragment</b>")); ok {
		t.Error("a tiny fragment with no real article must pass through")
	}
}

package compressors

import (
	"bytes"
	"encoding/json"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Class-invariant elision summaries.
//
// keepNonRedundant (redundancy.go) keeps one representative of every resemblance
// class and lets the rest elide against it, so a marker's dropped units are all
// near-duplicates of something still visible. The count alone does not say WHAT
// they had in common, and an agent that cannot tell stops trusting the surviving
// view: a compressed ledger can hide a fact that the marker could have stated,
// sending the agent into repeated recovery calls. The marker therefore reports
// facts computed from the elided units instead of only reporting their count.
//
// So a marker carries facts COMPUTED from the units it is replacing, at the
// moment it replaces them:
//
//   - a field whose value is byte-identical across EVERY elided unit is stated as
//     `name=value`;
//   - a field that varies, over a small set of short values, is enumerated in
//     full with exact counts — `status: fulfilled×15 shipped×3 processing×2`,
//     where a unit missing the field lands in its own `absent×N` bucket, so the
//     counts always sum to the elided count;
//   - a field present in every unit whose values all parse as numbers is stated
//     as `name=min..max`, using the ORIGINAL value strings of the extreme units —
//     never a reformatted or rounded number, so the bound can never be wider than
//     what was actually there.
//
// The enumeration is the fact set-logic questions actually turn on. If a varying
// state field is omitted because it is neither constant nor numeric, the agent
// cannot learn whether relevant rows were elided and will recover them anyway.
// The marker must describe the varying field when it can do so completely.
//
// Enumeration is all-or-nothing per field: over five distinct values, or one
// value too long or too free-text to print, and the field is withheld entirely.
// A partial list ("includes fulfilled, shipped") reads as complete and would be
// the one thing this file may never do — imply a fact it did not verify.
//
// Nothing else is claimed. A unit whose text yields no fields at all disables the
// summary for its whole run, and the marker is emitted byte-identically to the
// pre-existing one. A summary that would exceed the budget sheds whole entries —
// identifier-ish enumerations first, then ranges, then constants, class
// enumerations last, because the class enumeration is what a set-logic question
// needs — and never truncates one.
//
// An enumeration in which EVERY bucket holds exactly one unit is not enumerated:
// that is a list of identifiers, not a class invariant. It consumes the budget
// while crowding out state and range facts. Enumerations whose buckets average
// two units or fewer are still printed but shed first.
//
// Such a field instead gets a COVERAGE entry — `order_id: 25 distinct,
// ord-1000..ord-1024` — which answers the one question the other facts cannot:
// membership. A coverage entry settles whether a candidate identifier appeared
// in the elided set without pretending that the bounds form a contiguous set.
//
// The count sits next to the bounds deliberately: `25 distinct, a..z` says
// twenty-five values lie somewhere in that span and claims nothing about the
// gaps. Bounds are the byte-wise smallest and largest of the ORIGINAL value
// strings — no numeric parsing, no ordering assumption, no contiguity.
//
// A run too small to describe is not elided at all. A one-unit marker plus its
// recovery handle costs about what the unit costs, and it reads as a hole. A
// singleton marker can provoke a retrieve for one row. Below
// invariantMinElideUnits a run is only collapsed when it both summarizes and
// still halves its own bytes; otherwise the units are emitted verbatim and the
// compressor claims nothing for them.
//
// The summary spans exactly the units of one marker. Because a fact must hold for
// every unit in that run, a run that happens to span several resemblance classes
// simply yields fewer facts — never a fact true of only one class.
//
// Everything here is order-preserving and map-iteration-free in its output path:
// a compressed block must re-serialize identically on every later turn or the
// provider prefix cache is busted.

// field is one name/value pair extracted from an elided unit, carried as an
// ordered slice rather than a map so the rendered summary is deterministic.
type field struct{ name, value string }

const (
	// invariantMaxBytes caps the whole summary. It is small on purpose: the
	// marker must never eat the reduction it is annotating.
	invariantMaxBytes = 160
	// invariantMaxShareDen bounds the summary to 1/N of the bytes it replaced, so
	// a short run never pays a long annotation. At 1/4 the annotated run is still
	// a 4x reduction; the earlier 1/8 was strict enough to starve exactly the
	// small anomalous classes an agent most needs described, leaving a four-order
	// class with room for one useless identifier enum and nothing else.
	invariantMaxShareDen = 4
	// invariantMinBudget is the floor under that share. A small class is the one
	// worth describing completely — it is the anomaly, not the bulk — so it gets
	// room for a fact or two even when a quarter of its bytes would not buy one.
	// Bounded below by half the run either way, so the marker always shrinks it.
	// Raised from 64 once coverage entries existed: at ~38 bytes each, 64 could
	// not hold a constant pair AND a coverage entry, so a four-row ledger class
	// had to choose between describing its rows and locating them.
	invariantMinBudget = 96
	// invariantMinElideUnits is the smallest run that may be collapsed on the
	// strength of the count alone. Below it, collapsing must earn its place.
	invariantMinElideUnits = 3
	// invariantMinUnits is the smallest run worth annotating. A single elided
	// unit has no class to describe.
	invariantMinUnits = 2
	// invariantMaxValueBytes rejects values too long to belong in a one-line
	// marker (a stack trace, an embedded document).
	invariantMaxValueBytes = 40
	// invariantMaxNameBytes rejects implausible field names.
	invariantMaxNameBytes = 32
	// invariantMaxFieldsPerUnit bounds extraction work per unit.
	invariantMaxFieldsPerUnit = 24
	// invariantMaxTrackedFields bounds how many distinct field names one run
	// accumulates, so a heterogeneous run cannot grow the aggregate without limit.
	// Names past the limit are ignored in document order.
	invariantMaxTrackedFields = 48
	// invariantMaxEnumValues is the largest distinct-value set a varying field may
	// be enumerated over, counting the `absent` bucket. Past it the field says
	// nothing: a longer list stops being a fact an agent can hold and starts being
	// the data it replaced.
	invariantMaxEnumValues = 5
	// invariantMaxEnumValueBytes rejects enumerated values that look like free
	// text rather than a state token.
	invariantMaxEnumValueBytes = 24
	// invariantMaxCoverageValues bounds the distinct-value set a coverage entry
	// counts. Past it the exact count is no longer known, so nothing is claimed.
	invariantMaxCoverageValues = 4096
	// invariantMaxDenseDigits bounds the digit run a dense claim will parse, well
	// inside int64 so the arithmetic that verifies density cannot overflow.
	invariantMaxDenseDigits = 18
	// invariantMinCoverageValues is the smallest distinct set worth a coverage
	// entry: one value is a constant, and two bounds that are the same value say
	// nothing a reader could not already see.
	invariantMinCoverageValues = 2
	// invariantMaxCoverageEntries bounds how many identifier columns one summary
	// describes. A record typically carries several identifier columns, and each
	// entry can consume more of the marker budget than a useful state fact. Entries
	// past the cap are dropped in field order.
	// Entries past the cap are dropped in field order.
	invariantMaxCoverageEntries = 2
)

// invariantEnumAbsent names the bucket for units that lack the field entirely, so
// enumerated counts always sum to the run's elided count.
const invariantEnumAbsent = "absent"

// Entry kinds. kindEnum and kindEnumWeak render identically and in one section;
// they differ only in what gets shed first when the budget binds.
const (
	kindConstant = iota
	kindEnum
	kindEnumWeak
	kindCoverageDense
	kindCoverage
	kindRange
)

// entry is one rendered fact awaiting a place in the summary.
type entry struct {
	kind int
	text string
}

// invariantSecretFieldRe drops fields whose NAME suggests a credential. The
// values live in the elided bytes either way, but a marker is quoted, logged, and
// pasted far more freely than the body it replaced.
var invariantSecretFieldRe = regexp.MustCompile(`(?i)(secret|passw|token|api[_-]?key|authoriz|credential|cookie|session)`)

// summarizeElided renders the facts that hold across every unit of one elided
// run, or "" when there are none, extraction found no structure, or the summary
// would not fit its budget. elidedBytes is the size of the content the marker
// replaces and may be 0 to skip the proportional check.
func summarizeElided(units [][]field, elidedBytes int) string {
	if len(units) < invariantMinUnits {
		return ""
	}

	// One accumulator per field name, built in first-appearance order. A field is
	// registered wherever it first shows up, not only in the first unit: a field
	// that appears late cannot be a constant, but it can still be enumerated with
	// an `absent` bucket for the units that lacked it.
	type agg struct {
		seen           int
		constant       bool
		numeric        bool
		first          string
		minStr, maxStr string
		minVal, maxVal float64
		counts         map[string]int
		valueOrder     []string
		tooWide        bool // more distinct values than may ever be enumerated
		// Coverage tracking runs independently of the enum tally, because the
		// fields it describes are exactly the ones that blow past tooWide.
		covValues      map[string]struct{}
		covMin, covMax string
		covUsable      bool
	}
	aggs := make(map[string]*agg, invariantMaxTrackedFields)
	order := make([]string, 0, invariantMaxTrackedFields)

	for _, fields := range units {
		if len(fields) == 0 {
			// A unit we could not read is a unit we cannot make claims about.
			return ""
		}
		seenHere := make(map[string]bool, len(fields))
		for _, f := range fields {
			if seenHere[f.name] {
				continue // a repeated key within one unit: the first occurrence stands
			}
			seenHere[f.name] = true
			a := aggs[f.name]
			if a == nil {
				if len(order) >= invariantMaxTrackedFields {
					continue
				}
				value, err := strconv.ParseFloat(f.value, 64)
				a = &agg{
					constant:  true,
					numeric:   err == nil,
					first:     f.value,
					minStr:    f.value,
					maxStr:    f.value,
					minVal:    value,
					maxVal:    value,
					counts:    make(map[string]int, invariantMaxEnumValues+1),
					covValues: make(map[string]struct{}),
					covUsable: true,
				}
				aggs[f.name] = a
				order = append(order, f.name)
			}
			a.seen++
			if f.value != a.first {
				a.constant = false
			}
			if a.numeric {
				value, err := strconv.ParseFloat(f.value, 64)
				switch {
				case err != nil:
					a.numeric = false
				default:
					if value < a.minVal {
						a.minVal, a.minStr = value, f.value
					}
					if value > a.maxVal {
						a.maxVal, a.maxStr = value, f.value
					}
				}
			}
			if !a.tooWide {
				if _, known := a.counts[f.value]; !known {
					if len(a.counts) >= invariantMaxEnumValues {
						// A sixth distinct value: stop counting entirely rather than
						// keep a tally that could only ever render as a partial list.
						a.tooWide = true
					} else {
						a.valueOrder = append(a.valueOrder, f.value)
					}
				}
				if !a.tooWide {
					a.counts[f.value]++
				}
			}
			if a.covUsable {
				switch {
				case !invariantEnumValueUsable(f.value) || f.value == invariantEnumAbsent:
					// One free-text value and no range over this field is worth
					// printing — kill the whole entry, never a partial one. A
					// literal `absent` would also be unreadable next to the bucket
					// of the same name.
					a.covUsable = false
				case len(a.covValues) >= invariantMaxCoverageValues:
					a.covUsable = false // the exact distinct count is no longer known
				default:
					if _, known := a.covValues[f.value]; !known {
						a.covValues[f.value] = struct{}{}
						if len(a.covValues) == 1 {
							a.covMin, a.covMax = f.value, f.value
						} else {
							if f.value < a.covMin {
								a.covMin = f.value
							}
							if f.value > a.covMax {
								a.covMax = f.value
							}
						}
					}
				}
			}
		}
	}

	entries := make([]entry, 0, len(order))
	coverages := 0
	for _, name := range order {
		a := aggs[name]
		if name == "" || len(name) > invariantMaxNameBytes || invariantSecretFieldRe.MatchString(name) {
			continue
		}
		switch {
		case a.seen == len(units) && a.constant:
			if invariantValueUsable(a.first) {
				entries = append(entries, entry{kindConstant, name + "=" + a.first})
			}
		case a.seen == len(units) && a.numeric && a.minStr != a.maxStr:
			if invariantValueUsable(a.minStr) && invariantValueUsable(a.maxStr) {
				entries = append(entries, entry{kindRange, name + "=" + a.minStr + ".." + a.maxStr})
			}
		default:
			text, weak := enumerateField(name, a.counts, a.valueOrder, a.tooWide, len(units)-a.seen)
			if text != "" {
				kind := kindEnum
				if weak {
					kind = kindEnumWeak
				}
				entries = append(entries, entry{kind, text})
				continue
			}
			// No class to enumerate — the field has too many distinct values, or a
			// different one in every unit. Either way the useful fact left is which
			// values the run covers. It applies whether or not the values repeat:
			// A delivery identifier may appear more than once, so it is not an
			// identifier by the strict reading, yet its coverage can answer which
			// expected delivery has no event.
			if a.covUsable && coverages < invariantMaxCoverageEntries {
				if cov := coverageEntry(name, a.covValues, len(units)-a.seen, a.covMin, a.covMax); cov != "" {
					kind := kindCoverage
					if strings.HasSuffix(cov, " present") {
						kind = kindCoverageDense
					}
					entries = append(entries, entry{kind, cov})
					coverages++
				}
			}
		}
	}
	if len(entries) == 0 {
		return ""
	}

	budget := summaryBudget(elidedBytes)

	// Shed whole entries until the rendered summary fits: identifier-ish
	// enumerations first (they name units rather than describe them), then ranges,
	// then bounded coverage, then constants, then DENSE coverage, class
	// enumerations last.
	//
	// The two coverage forms are not worth the same and are not shed together. A
	// dense one (`wh-5000..wh-5059 all 60 present`) settles membership outright,
	// which is the entire question a set-difference task asks; a bounded one
	// (`55 distinct, a..z`) only rules values out. Dense coverage is retained later
	// because it can settle membership outright when the facts compete for space.
	//
	// Bounded coverage sits below constants because it runs ~50 bytes an entry
	// against ~16, and on a four-row ledger class promoting it above constants
	// bought `txn_id: 4 distinct, …` by shedding `all state=charged note=ok`,
	// trading the fact that answers "were any refunds in there?" for one naming
	// rows the neighbouring marker already bounds. A range only bounds a column, while
	// a class enumeration answers whether anything in state X was elided. Within a kind the latest field
	// goes first, so the head of a summary is stable as the tail is trimmed.
	selected := make([]bool, len(entries))
	for i := range selected {
		selected[i] = true
	}
	for {
		rendered := renderInvariants(entries, selected)
		if len(rendered) <= budget {
			return rendered
		}
		victim := -1
		for _, kind := range []int{kindEnumWeak, kindRange, kindCoverage, kindConstant, kindCoverageDense, kindEnum} {
			for i := len(entries) - 1; i >= 0; i-- {
				if selected[i] && entries[i].kind == kind {
					victim = i
					break
				}
			}
			if victim >= 0 {
				break
			}
		}
		if victim < 0 {
			return "" // nothing left to shed; the run buys no summary at all
		}
		selected[victim] = false
	}
}

// renderInvariants joins the selected entries into the marker summary: the
// constants as one `all …` section, each enumeration as its own `name: v×n …`
// section, the ranges as one `range …` section.
func renderInvariants(entries []entry, selected []bool) string {
	sections := make([]string, 0, len(entries))
	collect := func(kind int) []string {
		var out []string
		for i, e := range entries {
			if selected[i] && e.kind == kind {
				out = append(out, e.text)
			}
		}
		return out
	}
	if constants := collect(kindConstant); len(constants) > 0 {
		sections = append(sections, "all "+strings.Join(constants, " "))
	}
	// Every `name: …` entry — class enumerations, weak ones, and coverage —
	// renders in one group in field order, whatever the shed priority was.
	for i, e := range entries {
		if selected[i] && (e.kind == kindEnum || e.kind == kindEnumWeak || e.kind == kindCoverage || e.kind == kindCoverageDense) {
			sections = append(sections, e.text)
		}
	}
	if ranges := collect(kindRange); len(ranges) > 0 {
		sections = append(sections, "range "+strings.Join(ranges, " "))
	}
	return strings.Join(sections, "; ")
}

// enumerateField renders `name: value×count …` covering EVERY elided unit, or ""
// when the field cannot be enumerated in full. absent is how many units lacked
// the field; those get their own bucket so the counts always sum to the run size.
//
// Buckets are ordered by descending count (ties keep first-appearance order), so
// the dominant class reads first. Every rejection here is total: there is no
// shortened or partial enumeration, because a list that looks complete and is not
// would let an agent conclude that a value it cannot see was never there.
func enumerateField(name string, counts map[string]int, valueOrder []string, tooWide bool, absent int) (string, bool) {
	if tooWide || len(valueOrder) == 0 {
		return "", false
	}
	type bucket struct {
		value string
		count int
	}
	buckets := make([]bucket, 0, len(valueOrder)+1)
	for _, value := range valueOrder {
		if value == invariantEnumAbsent || !invariantEnumValueUsable(value) {
			return "", false
		}
		buckets = append(buckets, bucket{value, counts[value]})
	}
	if len(buckets)+min(absent, 1) > invariantMaxEnumValues {
		return "", false
	}
	// Real values by descending count (ties keep first-appearance order) so the
	// dominant class reads first; the absent bucket always trails, because it
	// describes the run rather than naming a value the field ever took.
	sort.SliceStable(buckets, func(i, j int) bool { return buckets[i].count > buckets[j].count })
	if absent > 0 {
		buckets = append(buckets, bucket{invariantEnumAbsent, absent})
	}

	// Buckets always sum to the run size, so "every bucket holds one unit" is
	// exactly "this field is a different value in every unit" — an identifier.
	// Enumerating it restates the data instead of describing it, and costs the
	// budget that the fields carrying an actual class would have used.
	units, singletons := 0, 0
	for _, bk := range buckets {
		units += bk.count
		if bk.count == 1 {
			singletons++
		}
	}
	if singletons == len(buckets) {
		return "", false
	}
	// Averaging two units or fewer per bucket is not an identifier but is close to
	// one: printed, but the first thing shed when the budget binds.
	weak := 2*len(buckets) >= units

	var b strings.Builder
	b.WriteString(name)
	b.WriteString(":")
	for _, bk := range buckets {
		b.WriteString(" ")
		b.WriteString(bk.value)
		b.WriteString("×")
		b.WriteString(strconv.Itoa(bk.count))
	}
	return b.String(), weak
}

// summaryBudget is how many bytes of summary a run that dropped elidedBytes may
// buy: a quarter of them, never under invariantMinBudget so a small anomalous
// class can still be described, never over half of them so the marker always
// shrinks what it replaced, and never over the absolute cap.
func summaryBudget(elidedBytes int) int {
	if elidedBytes <= 0 {
		return invariantMaxBytes
	}
	budget := elidedBytes / invariantMaxShareDen
	if budget < invariantMinBudget {
		budget = invariantMinBudget
	}
	if half := elidedBytes / 2; budget > half {
		budget = half
	}
	if budget > invariantMaxBytes {
		budget = invariantMaxBytes
	}
	return budget
}

// worthEliding reports whether a run of dropped units should become a marker at
// all. A run of invariantMinElideUnits or more always is. A shorter one must earn
// it: it has to carry a summary AND still halve its own bytes, because a marker
// plus a recovery handle that costs about what the units cost buys nothing and
// reads as a hole the agent feels obliged to fill.
func worthEliding(unitCount, markerBytes, elidedBytes int, summary string) bool {
	if unitCount >= invariantMinElideUnits {
		return true
	}
	return summary != "" && 2*markerBytes <= elidedBytes
}

// invariantEnumValueUsable holds an enumerated value to a tighter standard than a
// constant: it must read as a state token, not a sentence. Anything with a space,
// or longer than a short identifier, is free text and is not enumerated.
func invariantEnumValueUsable(value string) bool {
	if !invariantValueUsable(value) || len(value) > invariantMaxEnumValueBytes {
		return false
	}
	return !strings.ContainsAny(value, " \t")
}

// invariantValueUsable rejects values that do not belong in a one-line marker:
// empty, oversized, non-printable, or carrying marker syntax that a later pass
// would have to disambiguate.
func invariantValueUsable(value string) bool {
	if value == "" || len(value) > invariantMaxValueBytes || !utf8.ValidString(value) {
		return false
	}
	if strings.Contains(value, "caveman") || strings.Contains(value, "…") {
		return false
	}
	for _, r := range value {
		if unicode.IsControl(r) {
			return false
		}
	}
	return true
}

// logfmtPairRe matches a `key=value` token with an optionally quoted value. It is
// deliberately narrow: a key must look like an identifier, so prose containing an
// `=` does not parse as a field.
var logfmtPairRe = regexp.MustCompile(`(?:^|[\s,\[{(])([A-Za-z_][A-Za-z0-9_.\-]*)=("[^"]*"|'[^']*'|[^\s,\]})]+)`)

// lineFields reads one line of a line-oriented payload as whatever it is: a
// complete JSON object (an NDJSON event stream — webhook deliveries, audit
// events, structured application logs all ship this way) or a logfmt line.
//
// Without the JSON arm an NDJSON class can summarize to a bare line count while
// a related table states what was expected. The agent then knows nothing about
// what was delivered and has to recover the event stream to find out.
func lineFields(line []byte) []field {
	trimmed := bytes.TrimSpace(line)
	if len(trimmed) > 1 && trimmed[0] == '{' && trimmed[len(trimmed)-1] == '}' {
		decoder := json.NewDecoder(bytes.NewReader(trimmed))
		decoder.UseNumber()
		var event any
		if err := decoder.Decode(&event); err == nil && !decoder.More() {
			if fields := objectFields(event); len(fields) > 0 {
				return fields
			}
		}
	}
	return logfmtFields(line)
}

// logfmtFields extracts the `key=value` tokens of one log line, in order.
func logfmtFields(line []byte) []field {
	matches := logfmtPairRe.FindAllSubmatch(line, invariantMaxFieldsPerUnit)
	if len(matches) == 0 {
		return nil
	}
	fields := make([]field, 0, len(matches))
	for _, m := range matches {
		value := string(m[2])
		if len(value) >= 2 && (value[0] == '"' && value[len(value)-1] == '"' || value[0] == '\'' && value[len(value)-1] == '\'') {
			value = value[1 : len(value)-1]
		}
		if value == "" {
			continue
		}
		fields = append(fields, field{name: string(m[1]), value: value})
	}
	if len(fields) == 0 {
		return nil
	}
	return fields
}

// rowFields pairs a table row with its header, in column order. A row whose
// header cell is empty contributes nothing for that column: an unnamed field
// cannot be stated.
func rowFields(header, row []string) []field {
	fields := make([]field, 0, len(row))
	for i, cell := range row {
		if i >= len(header) || i >= invariantMaxFieldsPerUnit {
			break
		}
		name := strings.TrimSpace(header[i])
		value := strings.TrimSpace(cell)
		if name == "" || value == "" {
			continue
		}
		fields = append(fields, field{name: name, value: value})
	}
	if len(fields) == 0 {
		return nil
	}
	return fields
}

// objectFields extracts the scalar top-level members of a JSON object, in sorted
// key order (a decoded object has no inherent order, and sorting is what makes
// the rendered summary reproducible). Nested objects and arrays are skipped:
// stating a fact about a subtree would need a rule for how to render it, and a
// marker has no room for one.
func objectFields(v any) []field {
	object, ok := v.(map[string]any)
	if !ok || len(object) == 0 {
		return nil
	}
	names := make([]string, 0, len(object))
	for name := range object {
		names = append(names, name)
	}
	sort.Strings(names)
	fields := make([]field, 0, len(names))
	for _, name := range names {
		if len(fields) >= invariantMaxFieldsPerUnit {
			break
		}
		var value string
		switch t := object[name].(type) {
		case string:
			value = t
		case json.Number:
			value = t.String()
		case bool:
			value = strconv.FormatBool(t)
		default:
			continue // null, nested object, nested array
		}
		if value == "" {
			continue
		}
		fields = append(fields, field{name: name, value: value})
	}
	if len(fields) == 0 {
		return nil
	}
	return fields
}

// elisionNotePrefix opens the one-per-payload contract line. It is detected on
// re-entry, so the line is never elided and never appended twice.
const elisionNotePrefix = "… caveman: elided "

// elisionNoteMinElidedBytes is how much a payload must have actually dropped
// before it can afford the contract line. The threshold keeps the contract line
// smaller than the data it describes.
const elisionNoteMinElidedBytes = 4096

// wantsElisionNote reports whether a payload that dropped elidedBytes should
// carry the contract line.
func wantsElisionNote(elidedBytes int) bool { return elidedBytes >= elisionNoteMinElidedBytes }

// elisionNote is the single trailing line that tells the agent how to read a
// view that has had units elided. Every clause is a property the elider actually
// guarantees: keepNonRedundant only ever drops a unit that a surviving unit
// already represents, and summarizeElided only states facts it checks across the
// whole run.
// It is also kept short on purpose. It is paid once per tool result, so a
// paragraph would compete with the data it describes.
func elisionNote(unit string) string {
	return elisionNotePrefix + unit + " resemble shown " + unit +
		" and match the stated invariants — answer from this view; if you truly cannot, one broad caveman_retrieve …"
}

// coverageEntry renders what a run covers for a field with too many distinct
// values to enumerate. Every claim is about the DISTINCT set — how many different
// values the elided units held, and its bounds — never about how often each
// occurred.
//
// The default form, `name: N distinct, min..max`, claims exactly three things:
// how many distinct values the run held, the byte-wise smallest, and the
// byte-wise largest. The count sits next to the bounds so the span is never read
// as a contiguous set — twenty-five values lie SOMEWHERE in
// `ord-1000..ord-1024`, and which twenty-five is not claimed. That is enough to
// rule an id OUT (outside the bounds) but not to rule one IN, which is the
// question set-membership tasks ask: whether a candidate value is in the elided
// set or absent from the stream. The bounded form does not claim membership;
// dense coverage is needed for that.
//
// So when the run happens to be EXACTLY dense — every value one shared prefix
// plus a fixed-width integer, and the integers covering min..max with no gaps —
// it says so: `wh-5000..wh-5599 all 600 present`. That is a checkable literal
// claim (denseCoverage counts it; it is never guessed from the endpoints), and
// it settles membership without a retrieve.
//
// When the run is NOT dense the default form stands, and its own arithmetic is
// informative: `600 distinct, wh-5000..wh-5602` says three ids in that span are
// missing. WHICH three is not claimed and never will be — locating a gap needs
// the data, not the marker.
//
// Units lacking the field get the same `absent×N` bucket the enumerations use, so
// a reader can still account for the whole run. A run with absent units never
// takes the dense form: "all N present" next to "absent×1" reads as a
// contradiction even though the two count different things.
func coverageEntry(name string, values map[string]struct{}, absent int, minValue, maxValue string) string {
	distinct := len(values)
	if distinct < invariantMinCoverageValues || minValue == maxValue {
		return ""
	}
	if absent == 0 {
		if low, high, dense := denseCoverage(values); dense {
			return name + ": " + low + ".." + high + " all " + strconv.Itoa(distinct) + " present"
		}
	}
	text := name + ": " + strconv.Itoa(distinct) + " distinct, " + minValue + ".." + maxValue
	if absent > 0 {
		text += ", " + invariantEnumAbsent + "×" + strconv.Itoa(absent)
	}
	return text
}

// denseCoverage reports whether the DISTINCT values are exactly one shared prefix
// followed by a contiguous run of fixed-width integers, and returns its
// endpoints. `wh-5003..wh-5020 all 18 present` therefore says every one of those
// eighteen ids appears at least once among the elided units — which is what a
// membership question asks — and says nothing about how many times.
//
// Every condition is checked, none assumed:
//
//   - each value ends in digits, and the part before them is identical across all
//     of them (one id space, not two interleaved);
//   - the digit runs are all the SAME WIDTH. Mixed widths admit leading-zero
//     ambiguity — `wh-07` and `wh-7` may or may not be one value — and a claim
//     that turns on how a producer zero-pads is not a claim worth making;
//   - the integers parse exactly and span exactly len(values): max-min+1 equals
//     the distinct count, so there is no room for a gap.
//
// The result does not depend on map iteration order, so the rendered summary
// stays byte-stable across turns.
func denseCoverage(values map[string]struct{}) (string, string, bool) {
	if len(values) < invariantMinCoverageValues {
		return "", "", false
	}
	var (
		prefix          string
		width           int
		low, high       int64
		lowVal, highVal string
		started         bool
	)
	for value := range values {
		body, digits := splitTrailingDigits(value)
		if digits == "" || len(digits) > invariantMaxDenseDigits {
			return "", "", false
		}
		if !started {
			prefix, width = body, len(digits)
		} else if body != prefix || len(digits) != width {
			return "", "", false
		}
		n, err := strconv.ParseInt(digits, 10, 64)
		if err != nil {
			return "", "", false
		}
		switch {
		case !started:
			low, high, lowVal, highVal, started = n, n, value, value, true
		case n < low:
			low, lowVal = n, value
		case n > high:
			high, highVal = n, value
		}
	}
	// The only claim: the span holds exactly as many integers as we counted, so
	// every one of them is present.
	if high-low+1 != int64(len(values)) {
		return "", "", false
	}
	return lowVal, highVal, true
}

// splitTrailingDigits cuts a value into its leading text and its maximal run of
// trailing ASCII digits.
func splitTrailingDigits(value string) (string, string) {
	end := len(value)
	for end > 0 && value[end-1] >= '0' && value[end-1] <= '9' {
		end--
	}
	return value[:end], value[end:]
}

package compressors

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"testing"
)

// elidedBytesFor returns the run size that makes summaryBudget yield exactly
// want, so budget-pressure tests state the budget they mean instead of a magic
// multiple of it.
func elidedBytesFor(want int) int {
	if want < invariantMinBudget {
		return 2 * want
	}
	return 4 * want
}

func fields(pairs ...string) []field {
	out := make([]field, 0, len(pairs)/2)
	for i := 0; i+1 < len(pairs); i += 2 {
		out = append(out, field{name: pairs[i], value: pairs[i+1]})
	}
	return out
}

func TestSummarizeElidedStatesOnlyWhatHoldsEverywhere(t *testing.T) {
	for _, tc := range []struct {
		name  string
		units [][]field
		want  string
	}{
		{
			name: "constant field across every unit",
			units: [][]field{
				fields("state", "charged", "id", "1"),
				fields("state", "charged", "id", "2"),
				fields("state", "charged", "id", "3"),
			},
			want: "all state=charged; range id=1..3",
		},
		{
			name: "a field that varies non-numerically is enumerated in full",
			units: [][]field{
				fields("state", "charged", "region", "emea"),
				fields("state", "refunded", "region", "emea"),
				fields("state", "charged", "region", "emea"),
			},
			want: "all region=emea; state: charged×2 refunded×1",
		},
		{
			name: "units missing the field get their own absent bucket",
			units: [][]field{
				fields("state", "charged", "note", "retry"),
				fields("state", "charged"),
				fields("state", "charged"),
			},
			want: "all state=charged; note: retry×1 absent×2",
		},
		{
			name: "more distinct values than may be enumerated fall back to coverage",
			units: [][]field{
				fields("state", "a", "region", "emea"),
				fields("state", "b", "region", "emea"),
				fields("state", "c", "region", "emea"),
				fields("state", "d", "region", "emea"),
				fields("state", "e", "region", "emea"),
				fields("state", "f", "region", "emea"),
			},
			want: "all region=emea; state: 6 distinct, a..f",
		},
		{
			name: "a sparse identifier is covered by count and bounds",
			units: [][]field{
				fields("customer_id", "cust-2728", "currency", "EUR"),
				fields("customer_id", "cust-2765", "currency", "EUR"),
				fields("customer_id", "cust-2802", "currency", "EUR"),
				fields("customer_id", "cust-2839", "currency", "EUR"),
			},
			want: "all currency=EUR; customer_id: 4 distinct, cust-2728..cust-2839",
		},
		{
			name: "an exactly dense identifier says every value is present",
			units: [][]field{
				fields("delivery_id", "dlv-2000"),
				fields("delivery_id", "dlv-2001"),
				fields("delivery_id", "dlv-2002"),
				fields("delivery_id", "dlv-2003"),
			},
			want: "delivery_id: dlv-2000..dlv-2003 all 4 present",
		},
		{
			name: "coverage counts DISTINCT values, so a repeated id still goes dense",
			units: func() [][]field {
				var units [][]field
				for i := 0; i < 7; i++ {
					for _, st := range []string{"attempted", "delivered"} {
						units = append(units, fields("delivery_id", fmt.Sprintf("dlv-%04d", 2000+i), "status", st))
					}
				}
				return units
			}(),
			want: "delivery_id: dlv-2000..dlv-2006 all 7 present; status: attempted×7 delivered×7",
		},
		{
			name: "one gap and the dense claim is withheld, count and bounds stand",
			units: [][]field{
				fields("delivery_id", "dlv-2000"),
				fields("delivery_id", "dlv-2001"),
				fields("delivery_id", "dlv-2003"),
				fields("delivery_id", "dlv-2004"),
			},
			want: "delivery_id: 4 distinct, dlv-2000..dlv-2004",
		},
		{
			name: "mixed suffix widths are never called dense",
			units: [][]field{
				fields("seq", "n-8"),
				fields("seq", "n-9"),
				fields("seq", "n-10"),
			},
			want: "seq: 3 distinct, n-10..n-9",
		},
		{
			name: "two id spaces sharing a field are never called dense",
			units: [][]field{
				fields("ref", "a-001"),
				fields("ref", "a-002"),
				fields("ref", "b-003"),
			},
			want: "ref: 3 distinct, a-001..b-003",
		},
		{
			name: "values with no digits are never called dense",
			units: [][]field{
				fields("node", "alpha"),
				fields("node", "beta"),
				fields("node", "gamma"),
			},
			want: "node: 3 distinct, alpha..gamma",
		},
		{
			name: "units missing the field keep the counted form",
			units: [][]field{
				fields("delivery_id", "dlv-2000", "svc", "hooks"),
				fields("delivery_id", "dlv-2001", "svc", "hooks"),
				fields("delivery_id", "dlv-2002", "svc", "hooks"),
				fields("svc", "hooks"),
			},
			want: "all svc=hooks; delivery_id: 3 distinct, dlv-2000..dlv-2002, absent×1",
		},
		{
			name: "five distinct values including absent is the limit and still enumerates",
			units: [][]field{
				fields("state", "a"), fields("state", "a"),
				fields("state", "b"), fields("state", "b"),
				fields("state", "c"), fields("state", "c"),
				fields("state", "d"), fields("state", "d"),
				fields("other", "x"), fields("other", "x"),
			},
			want: "state: a×2 b×2 c×2 d×2 absent×2; other: x×2 absent×8",
		},
		{
			name: "free-text values are not enumerated",
			units: [][]field{
				fields("msg", "connection reset by peer", "region", "emea"),
				fields("msg", "upstream closed the stream", "region", "emea"),
			},
			want: "all region=emea",
		},
		{
			name: "a literal absent value would be indistinguishable from the bucket",
			units: [][]field{
				fields("state", "absent"),
				fields("state", "charged"),
			},
			want: "",
		},
		{
			name: "range uses the original extreme value strings, never a reformat",
			units: [][]field{
				fields("amount", "5.00"),
				fields("amount", "199.90"),
				fields("amount", "12.30"),
			},
			want: "range amount=5.00..199.90",
		},
		{
			name: "negative and exponent values order numerically",
			units: [][]field{
				fields("delta", "-3"),
				fields("delta", "1e2"),
				fields("delta", "0"),
			},
			want: "range delta=-3..1e2",
		},
		{
			name: "credential-shaped names are withheld",
			units: [][]field{
				fields("api_key", "abc", "state", "charged"),
				fields("api_key", "def", "state", "charged"),
			},
			want: "all state=charged",
		},
		{
			name:  "a single unit is not a class",
			units: [][]field{fields("state", "charged")},
			want:  "",
		},
		{
			name: "a unit with no extractable structure disables the summary",
			units: [][]field{
				fields("state", "charged"),
				nil,
				fields("state", "charged"),
			},
			want: "",
		},
		{
			name: "a numeric field that varies is ranged, not enumerated",
			units: [][]field{
				fields("code", "200"),
				fields("code", "500"),
				fields("code", "200"),
			},
			want: "range code=200..500",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := summarizeElided(tc.units, 1<<20); got != tc.want {
				t.Fatalf("summarizeElided = %q, want %q", got, tc.want)
			}
		})
	}
}

func TestSummarizeElidedRespectsItsBudget(t *testing.T) {
	wide := func() []field {
		var f []field
		for i := 0; i < 12; i++ {
			f = append(f, field{name: fmt.Sprintf("field_%02d", i), value: strings.Repeat("v", 30)})
		}
		return f
	}
	units := [][]field{wide(), wide(), wide()}

	got := summarizeElided(units, 1<<20)
	if got == "" {
		t.Fatal("a wide but perfectly constant run should still say something")
	}
	if len(got) > invariantMaxBytes {
		t.Fatalf("summary is %d bytes, over the %d cap: %q", len(got), invariantMaxBytes, got)
	}
	// Every entry that did survive the cap must still be a whole, true fact.
	for _, entry := range strings.Fields(strings.TrimPrefix(got, "all ")) {
		name, value, ok := strings.Cut(entry, "=")
		if !ok || !strings.HasPrefix(name, "field_") || value != strings.Repeat("v", 30) {
			t.Fatalf("cap truncated a fact into %q", entry)
		}
	}

	// However tight the run, the summary may never cost more than half the bytes
	// it replaced — the marker always has to shrink what it stands in for.
	for _, elided := range []int{20, 40, 80, 200, 4000} {
		got := summarizeElided([][]field{
			fields("state", "charged", "region", "emea", "tier", "gold"),
			fields("state", "charged", "region", "emea", "tier", "gold"),
		}, elided)
		if 2*len(got) > elided {
			t.Fatalf("a %d-byte run bought a %d-byte summary %q", elided, len(got), got)
		}
	}
}

// TestIdentifierEnumerationsAreShedFirst pins the budget priority. An enumeration
// averaging two units or fewer per bucket barely describes a class, so it goes
// before the range and the constants do.
func TestIdentifierEnumerationsAreShedFirst(t *testing.T) {
	var units [][]field
	for i := 0; i < 8; i++ {
		state := "fulfilled"
		if i >= 6 {
			state = "shipped"
		}
		units = append(units, fields(
			"status", state,
			"batch", fmt.Sprintf("b%d", i/2), // 4 buckets over 8 units: weak
		))
	}
	full := summarizeElided(units, 1<<20)
	if !strings.Contains(full, "status: fulfilled×6 shipped×2") || !strings.Contains(full, "batch:") {
		t.Fatalf("both enumerations should render unconstrained, got %q", full)
	}
	tight := summarizeElided(units, elidedBytesFor(len("status: fulfilled×6 shipped×2")))
	if tight != "status: fulfilled×6 shipped×2" {
		t.Fatalf("the weak enumeration must be shed before the strong one, got %q", tight)
	}
}

// TestBudgetShedsRangesBeforeEnumerations pins the shedding order. An enumeration
// answers whether anything in state X was elided; a range only bounds a column.
func TestBudgetShedsRangesBeforeEnumerations(t *testing.T) {
	var units [][]field
	for i := 0; i < 6; i++ {
		state := "fulfilled"
		if i > 3 {
			state = "shipped"
		}
		units = append(units, fields(
			"amount", fmt.Sprintf("%d.00", 100+i),
			"latency", fmt.Sprintf("%d", 10+i),
			"status", state,
		))
	}
	full := summarizeElided(units, 1<<20)
	if !strings.Contains(full, "status: fulfilled×4 shipped×2") || !strings.Contains(full, "range ") {
		t.Fatalf("expected both an enumeration and ranges unconstrained, got %q", full)
	}
	// A budget too tight for everything must keep the enumeration.
	tight := summarizeElided(units, elidedBytesFor(len("status: fulfilled×4 shipped×2")))
	if tight != "status: fulfilled×4 shipped×2" {
		t.Fatalf("under pressure the enumeration must be what survives, got %q", tight)
	}
}

// TestEnumeratedCountsCoverEveryElidedUnit is the honesty gate for enumeration:
// the counts must account for the whole run, or an agent reading them would
// conclude something about units the marker never saw.
func TestEnumeratedCountsCoverEveryElidedUnit(t *testing.T) {
	units := [][]field{
		fields("status", "fulfilled"), fields("status", "fulfilled"), fields("status", "fulfilled"),
		fields("status", "shipped"), fields("status", "shipped"),
		fields("status", "processing"),
		fields("other", "x"), fields("other", "x"),
	}
	summary := summarizeElided(units, 1<<20)
	for _, section := range strings.Split(summary, "; ") {
		name, body, ok := strings.Cut(section, ": ")
		if !ok {
			t.Fatalf("unexpected section %q", section)
		}
		total := 0
		for _, bucket := range strings.Fields(body) {
			value, count, ok := strings.Cut(bucket, "×")
			if !ok {
				t.Fatalf("bucket %q is not value×count", bucket)
			}
			n, err := strconv.Atoi(count)
			if err != nil {
				t.Fatalf("bucket %q has a non-numeric count", bucket)
			}
			// Re-derive the count from the units themselves.
			actual := 0
			for _, u := range units {
				present := false
				for _, f := range u {
					if f.name != name {
						continue
					}
					present = true
					if f.value == value {
						actual++
					}
				}
				if !present && value == invariantEnumAbsent {
					actual++
				}
			}
			if actual != n {
				t.Fatalf("%s: claimed %s×%d, actually %d", name, value, n, actual)
			}
			total += n
		}
		if total != len(units) {
			t.Fatalf("%s: buckets sum to %d, but %d units were elided", name, total, len(units))
		}
	}
}

