		"@inproceedings{smith2020ai,\n  author = {John Smith and Mary Jones},\n  title = {Advances in Artificial Intelligence for Natural Language Processing},\n  booktitle = {AI Conference},\n  year = {2020}",
		"@article{He2016,\n  author  = {He, Kaiming and Zhang, Xiangyu},\n  title   = {Deep Residual Learning for Image Recognition},\n  journal = {CVPR},\n  year    = {2016}",
		"@inproceedings{joshi2017triviaqa,\n  author = {Joshi, Mandar and Choi, Eunsol},\n  title = {TriviaQA: A Large Scale Distantly Supervised Challenge Dataset},\n  booktitle = {ACL},\n  year = {2017}",
	}
	return []byte(strings.Join(entries, "\n\n"))
}

// assertNothingElided checks the property that matters: not a byte of the payload
// was dropped. Some compressors report ok=true while returning their input
// unchanged and let the engine's "not actually smaller" check pass it through, so
// asserting on the ok flag alone would test the wrong layer.
func assertNothingElided(t *testing.T, input, out []byte, ok bool) {
	t.Helper()
	if ok && !bytes.Equal(out, input) {
		t.Fatalf("expected pass-through, but %d bytes became %d:\n%s", len(input), len(out), out)
	}
}

// A document of distinct records must survive intact. Eliding it deletes part of
// the answer and can force the agent to recover the source repeatedly.
func TestElisionRefusesDocumentOfDistinctRecords(t *testing.T) {
	input := bibliographyLike()
	out, ok := compressors.NewText().Compress(input)
	assertNothingElided(t, input, out, ok)
}

// The complement, and the reason this is a class rule rather than a refusal: a
// payload that is mostly repetition still elides, and the repeated class stays
// visible through one surviving representative.
func TestElisionKeepsOneRepresentativeOfEachClass(t *testing.T) {
	var sections []string
	sections = append(sections, "# Incident Report", "Summary: checkout latency increased.")
	for i := 0; i < 18; i++ {
		sections = append(sections, strings.Repeat(fmt.Sprintf("Background paragraph %02d with routine context. ", i), 8))
	}
	sections = append(sections, "Conclusion: monitor error rate for one hour.")
	input := []byte(strings.Join(sections, "\n\n"))

	out, ok := compressors.NewText().Compress(input)
	if !ok {
		t.Fatal("a payload of eighteen interchangeable paragraphs must still elide")
	}
	if len(out) >= len(input) {
		t.Fatalf("expected smaller output, got %d >= %d", len(out), len(input))
	}
	if !bytes.Contains(out, []byte("sections elided")) {
		t.Fatalf("expected an elision marker:\n%s", out)
	}
	survivors := 0
	for _, section := range bytes.Split(out, []byte("\n\n")) {
		if bytes.Contains(section, []byte("Background paragraph")) {
			survivors++
		}
	}
	if survivors != 1 {
		t.Fatalf("exactly one representative of the repeated class must survive, got %d:\n%s", survivors, out)
	}
}

// Repetition is recognised through the values that vary between copies, not
// despite them: two log lines differing only in a timestamp and a request id are
// the same class, so all but the first elide.
func TestElisionTreatsDigitVaryingLinesAsOneClass(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 200; i++ {
		fmt.Fprintf(&b, "2026-07-30T10:%02d:%02dZ level=INFO service=catalog request=req-%04d status=200 message=completed\n", i/60, i%60, i)
	}
	out, ok := compressors.NewLog().Compress([]byte(b.String()))
	if !ok {
		t.Fatal("expected repetitive log lines to elide")
	}
	if len(out)*4 > len(b.String()) {
		t.Fatalf("expected a large reduction on a single-class log, got %d of %d bytes", len(out), b.Len())
	}
}

// Distinct log lines are a document, not a stream, and must survive.
func TestElisionRefusesLogOfDistinctLines(t *testing.T) {
	lines := []string{
		"2026-07-30T10:00:01Z level=INFO starting migration of the accounts table",
		"2026-07-30T10:00:02Z level=INFO connected to primary replica in frankfurt",
		"2026-07-30T10:00:03Z level=INFO applying column rename for customer identifiers",
		"2026-07-30T10:00:04Z level=INFO backfilling nullable settlement references",
		"2026-07-30T10:00:05Z level=INFO rebuilding the composite ordering index",
		"2026-07-30T10:00:06Z level=INFO vacuuming dead tuples from the audit journal",
		"2026-07-30T10:00:07Z level=INFO switching traffic to the upgraded schema",
		"2026-07-30T10:00:08Z level=INFO retiring the legacy compatibility view",
		"2026-07-30T10:00:09Z level=INFO refreshing materialised revenue rollups",
		"2026-07-30T10:00:10Z level=INFO releasing the advisory migration lock",
		"2026-07-30T10:00:11Z level=INFO notifying downstream consumers of the cutover",
		"2026-07-30T10:00:12Z level=INFO archiving the pre-migration snapshot to cold storage",
	}
	input := []byte(strings.Join(lines, "\n"))
	out, ok := compressors.NewLog().Compress(input)
	assertNothingElided(t, input, out, ok)
}

// The array counterpart of the bibliography: rows that each say something
// different are a list of distinct entities, and dropping most of them deletes
// the answer to any question about the list.
func TestJSONElisionRefusesArrayOfDistinctRecords(t *testing.T) {
	input := []byte(`{"results":[` +
		`{"id":0,"name":"alice","team":"platform"},{"id":1,"name":"bob","team":"payments"},` +
		`{"id":2,"name":"carol","team":"identity"},{"id":3,"name":"dan","team":"search"},` +
		`{"id":4,"name":"erin","team":"checkout"},{"id":5,"name":"frank","team":"billing"},` +
		`{"id":6,"name":"grace","team":"catalog"},{"id":7,"name":"heidi","team":"fraud"},` +
		`{"id":8,"name":"ivan","team":"growth"},{"id":9,"name":"judy","team":"support"},` +
		`{"id":10,"name":"karl","team":"infra"},{"id":11,"name":"lena","team":"security"}]}`)
	out, ok := compressors.NewJSON().Compress(input)
	assertNothingElided(t, input, out, ok)
}

// A uniform array of the same event repeated is the shape elision exists for, and
// it must keep working.
func TestJSONElisionStillCollapsesRepeatedRecords(t *testing.T) {
	rows := make([]string, 0, 200)
	for i := 0; i < 200; i++ {
		rows = append(rows, fmt.Sprintf(`{"seq":%d,"status":"healthy","region":"eu-west-1"}`, i))
	}
	input := []byte(`{"events":[` + strings.Join(rows, ",") + `]}`)
	out, ok := compressors.NewJSON().Compress(input)
	if !ok || len(out) >= len(input) {
		t.Fatalf("a uniform array of repeated events must still elide (ok=%v, %d -> %d)", ok, len(input), len(out))
	}
	if !bytes.Contains(out, []byte(compressors.ElidedKey)) {
		t.Fatalf("expected an elision marker:\n%s", out)
	}
}

// The gate runs on the proxy hot path, so its cost has to stay bounded on the
// worst realistic input: a large payload with no repetition at all, where every
// unit is a candidate for promotion.
func BenchmarkElisionGateOnLargeDistinctPayload(b *testing.B) {
	var sb strings.Builder
	for i := 0; i < 5000; i++ {
		fmt.Fprintf(&sb, "line %d reporting a wholly distinct observation about subsystem %s with detail %s\n",
			i, strings.Repeat("x", i%17+1), strings.Repeat("y", i%23+1))
	}
	input := []byte(sb.String())
	b.ReportAllocs()
	for b.Loop() {
		compressors.NewLog().Compress(input)
	}
}

// A compressed block re-serializes on every later turn of a conversation; if the
// gate were order- or map-dependent the upstream prefix would rotate and every
// turn would miss the provider cache the previous turn paid to create.
func TestElisionIsDeterministic(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 120; i++ {
		fmt.Fprintf(&b, "worker-%02d processed batch %04d in %dms with status ok\n", i%7, i, 12+i%40)
	}
	for i := 0; i < 20; i++ {
		fmt.Fprintf(&b, "distinct finding %d: %s\n", i, strings.Repeat("x", i+1))
	}
	input := []byte(b.String())

	first, ok := compressors.NewLog().Compress(input)
	if !ok {
		t.Skip("payload did not elide; determinism is trivially held")
	}
	for i := 0; i < 5; i++ {
		again, ok := compressors.NewLog().Compress(input)
		if !ok || !bytes.Equal(first, again) {
			t.Fatalf("elision must be a pure function of content (run %d differed)", i)
		}
	}
}

package compressors

import (
	"sort"

	"github.com/JuliusBrussee/caveman/engine/contextwindow"
)

// keepQueryRelevant adds the highest-scoring BM25 documents to keep. Existing
// force-keeps are never removed. Selection is deterministic: score descending,
// source order for ties. threshold is relative to the best document score.
func keepQueryRelevant(keep []bool, docs []string, query string, limit int, threshold float64) {
	if query == "" || len(docs) == 0 || len(keep) != len(docs) || limit <= 0 {
		return
	}
	scores := contextwindow.BM25(query, docs)
	maxScore := 0.0
	for _, score := range scores {
		if score > maxScore {
			maxScore = score
		}
	}
	if maxScore == 0 {
		return
	}
	type candidate struct {
		index int
		score float64
	}
	candidates := make([]candidate, 0, len(docs))
	for i, score := range scores {
		if !keep[i] && score/maxScore >= threshold {
			candidates = append(candidates, candidate{index: i, score: score})
		}
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		if candidates[i].score == candidates[j].score {
			return candidates[i].index < candidates[j].index
		}
		return candidates[i].score > candidates[j].score
	})
	added := 0
	for _, candidate := range candidates {
		if added >= limit {
			break
		}
		keep[candidate.index] = true
		added++
	}
}

package compressors

import (
	"bytes"
	"fmt"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// RepetitionType is the forced content type for the repetition compressor. It is
// never returned by Detect (run-length elision is only ever applied on request),
// so it must not be added to the content router — reach it via Options.Type.
const RepetitionType = "repetition"

// repMarkerPrefix opens the elision marker. It is detected on re-entry so the
// compressor is idempotent (a marker line is never itself collapsed).
const repMarkerPrefix = "… caveman: "

func repMarker(n int) string {
	return fmt.Sprintf("%s%d identical lines elided …", repMarkerPrefix, n)
}

// repetitionCompressor collapses runs of consecutive identical lines to a single
// occurrence plus a count marker — the honest "stop paying to read the same thing
// twice" win for logs and echoed output (duplicated progress lines, repeated
// "PASSED", retry spam). It is deterministic (a single sequential scan) and S4
// (lossy): the dropped lines are recoverable in full via CCR. It only touches
// exactly-identical adjacent lines, so it never changes the order or content of
// distinct lines. On any problem — invalid UTF-8, too small, or nothing to
// collapse — it reports !ok and the caller forwards the bytes unchanged.
type repetitionCompressor struct {
	minRun   int // collapse a run only when it has at least this many identical lines
	minBytes int // skip inputs smaller than this
}

// NewRepetition returns the default repetition (run-length) compressor.
func NewRepetition() Compressor { return &repetitionCompressor{minRun: 3, minBytes: 200} }

func (c *repetitionCompressor) ContentType() string       { return RepetitionType }
func (c *repetitionCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *repetitionCompressor) Compress(input []byte) ([]byte, bool) {
	if len(input) < c.minBytes || !utf8.Valid(input) {
		return nil, false
	}
	lines := bytes.Split(input, []byte("\n"))
	out := make([][]byte, 0, len(lines))
	collapsed := false

	i := 0
	for i < len(lines) {
		j := i + 1
		for j < len(lines) && bytes.Equal(lines[j], lines[i]) {
			j++
		}
		runLen := j - i
		out = append(out, lines[i]) // always keep the first occurrence
		// Collapse only a long enough run of a non-blank line — collapsing one or
		// two lines, or a blank run, would not reliably shrink the token count. A
		// line that is itself an elision marker is never collapsed, so our own
		// markers survive a second pass unchanged (enforced idempotence).
		if runLen >= c.minRun && len(bytes.TrimSpace(lines[i])) > 0 &&
			!bytes.HasPrefix(lines[i], []byte(repMarkerPrefix)) {
			out = append(out, []byte(repMarker(runLen-1)))
			collapsed = true
		} else {
			for k := i + 1; k < j; k++ {
				out = append(out, lines[k])
			}
		}
		i = j
	}

	if !collapsed {
		return nil, false // nothing repeated → pass-through, claim nothing
	}
	result := bytes.Join(out, []byte("\n"))
	if len(result) >= len(input) {
		// The marker(s) did not actually shrink the payload (short lines / small
		// runs where the marker is longer than what it replaced) — claim nothing
		// rather than report a false win and lean on the engine's token guard.
		return nil, false
	}
	return result, true
}

package compressors_test

import (
	"bytes"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
)

func TestRepetitionCollapsesIdenticalRuns(t *testing.T) {
	c := compressors.NewRepetition()
	var b strings.Builder
	b.WriteString("starting build\n")
	for i := 0; i < 40; i++ {
		b.WriteString("downloading dependency... please wait\n")
	}
	b.WriteString("ERROR: undefined symbol caveman_main\n")
	b.WriteString("build failed\n")
	in := []byte(b.String())

	out, ok := c.Compress(in)
	if !ok {
		t.Fatal("expected collapse of the repeated run")
	}
	if len(out) >= len(in) {
		t.Error("expected output smaller than input")
	}
	// The unique error line and the surrounding context must survive.
	for _, must := range []string{"ERROR: undefined symbol caveman_main", "starting build", "build failed"} {
		if !bytes.Contains(out, []byte(must)) {
			t.Errorf("unique line dropped: %q", must)
		}
	}
	// The repeated line appears exactly once, plus an elision marker.
	if n := bytes.Count(out, []byte("downloading dependency")); n != 1 {
		t.Errorf("repeated line should remain once, found %d", n)
	}
	if !bytes.Contains(out, []byte("caveman:")) {
		t.Error("expected an elision marker")
	}
}

func TestRepetitionIdempotent(t *testing.T) {
	c := compressors.NewRepetition()
	in := []byte("head line\n" + strings.Repeat("same same same line\n", 30) + "tail line\n")
	first, ok := c.Compress(in)
	if !ok {
		t.Fatal("expected collapse")
	}
	second, ok := c.Compress(first)
	if ok {
		// A second pass that still reports a collapse must be byte-stable.
		if !bytes.Equal(first, second) {
			t.Errorf("not idempotent:\n first=%s\nsecond=%s", first, second)
		}
		return
	}
	// More commonly the second pass finds nothing to collapse → pass-through.
}

func TestRepetitionNoDuplicatesPassesThrough(t *testing.T) {
	c := compressors.NewRepetition()
	in := []byte("line one is unique\nline two is unique\nline three is unique\nand a fourth distinct line here\nplus a fifth one too for good measure\n")
	if _, ok := c.Compress(in); ok {
		t.Error("input with no repeated runs must pass through (ok=false)")
	}
}

func TestRepetitionTinyInputPassesThrough(t *testing.T) {
	c := compressors.NewRepetition()
	if _, ok := c.Compress([]byte("x\nx\nx\n")); ok {
		t.Error("tiny input must pass through (ok=false)")
	}
}

func TestRepetitionDeterministic(t *testing.T) {
	c := compressors.NewRepetition()
	in := []byte("alpha\n" + strings.Repeat("repeat me\n", 25) + "beta\n" + strings.Repeat("and me too\n", 25) + "gamma\n")
	a, ok1 := c.Compress(in)
	b, ok2 := c.Compress(in)
	if !ok1 || !ok2 {
		t.Fatal("expected collapse")
	}
	if !bytes.Equal(a, b) {
		t.Error("non-deterministic output")
	}
}

func TestRepetitionShortRunNotCollapsed(t *testing.T) {
	c := compressors.NewRepetition()
	// A run of 2 (< minRun=3) must not be collapsed, but the input must be large
	// enough to clear minBytes so the no-collapse path (not the size guard) is hit.
	in := []byte(strings.Repeat("a unique padding line that is reasonably long\n", 10) + "dup line\ndup line\nfinal unique line\n")
	out, ok := c.Compress(in)
	if ok && bytes.Contains(out, []byte("caveman:")) {
		// If it collapsed at all, the 2-line run must NOT be what produced a marker.
		if bytes.Count(out, []byte("dup line")) != 2 {
			t.Error("a run of 2 identical lines must not be collapsed")
		}
	}
}

package compressors

import (
	"bytes"
	"fmt"
	"regexp"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

var (
	searchResultMarkerRe    = regexp.MustCompile(`search result lines elided \(caveman\)`)
	searchResultImportantRe = regexp.MustCompile(`(?i)\b(ERROR|FAIL|FAILED|PANIC|ACTION|FOLLOWUP|SECURITY|SECRET|TOKEN|PASSWORD|KEY)\b`)
)

func searchResultMarker(n int) string {
	return fmt.Sprintf("… %d search result lines elided (caveman) …", n)
}

// searchResultCompressor keeps the top and bottom hits plus obviously important
// diagnostic/security lines, collapsing the middle of large grep/web result sets.
type searchResultCompressor struct {
	keepHead int
	keepTail int
	minLines int
}

// NewSearchResult returns the line-oriented search-result compressor.
func NewSearchResult() Compressor {
	return &searchResultCompressor{keepHead: 8, keepTail: 4, minLines: 18}
}

func (c *searchResultCompressor) ContentType() string       { return "search-result" }
func (c *searchResultCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *searchResultCompressor) Compress(input []byte) ([]byte, bool) {
	return c.compress(input, "")
}

func (c *searchResultCompressor) CompressQuery(input []byte, query string) ([]byte, bool) {
	return c.compress(input, query)
}

func (c *searchResultCompressor) compress(input []byte, query string) ([]byte, bool) {
	if !utf8.Valid(input) {
		return nil, false
	}
	sep := []byte("\n")
	if bytes.Contains(input, []byte("\r\n")) {
		sep = []byte("\r\n")
	}
	trailing := bytes.HasSuffix(input, sep)
	body := input
	if trailing {
		body = body[:len(body)-len(sep)]
	}
	lines := bytes.Split(body, sep)
	if len(lines) < c.minLines {
		return nil, false
	}

	keep := make([]bool, len(lines))
	for i, line := range lines {
		if i < c.keepHead || i >= len(lines)-c.keepTail || searchResultImportantRe.Match(line) || searchResultMarkerRe.Match(line) {
			keep[i] = true
		}
	}
	docs := make([]string, len(lines))
	for i, line := range lines {
		docs[i] = string(line)
	}
	keepQueryRelevant(keep, docs, query, 24, 0.30)
	keepNonRedundant(lines, keep)

	out := make([][]byte, 0, len(lines))
	dropped := 0
	for i, line := range lines {
		if keep[i] {
			if dropped > 0 {
				out = append(out, []byte(searchResultMarker(dropped)))
				dropped = 0
			}
			out = append(out, line)
		} else {
			dropped++
		}
	}
	if dropped > 0 {
		out = append(out, []byte(searchResultMarker(dropped)))
	}
	if len(out) == len(lines) {
		return nil, false
	}
	result := bytes.Join(out, sep)
	if trailing {
		result = append(result, sep...)
	}
	return result, true
}

package compressors

import (
	"bytes"
	"encoding/csv"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

var (
	markdownSeparatorCellRe = regexp.MustCompile(`^:?-{3,}:?$`)
	tabularImportantRe      = regexp.MustCompile(`(?i)\b(ERROR|FAIL|FAILED|FATAL|PANIC|EXCEPTION|WARNING|SECURITY|DENIED|REJECTED)\b`)
	tabularMarkerRe         = regexp.MustCompile(`rows elided \(caveman\)`)
)

// tabularMarker renders the elision marker cell for a run of dropped rows.
// summary is the class-invariant description of exactly those rows; when it is
// empty the marker is byte-identical to the pre-invariant one.
func tabularMarker(n int, summary string) string {
	if summary == "" {
		return fmt.Sprintf("… %d rows elided (caveman) …", n)
	}
	return fmt.Sprintf("… %d rows elided (caveman): %s …", n, summary)
}

// summarizeRowRun describes a run of dropped table rows by their header-named
// columns.
func summarizeRowRun(header []string, run [][]string) string {
	units := make([][]field, len(run))
	elidedBytes := 0
	for i, row := range run {
		units[i] = rowFields(header, row)
		elidedBytes += len(strings.Join(row, ",")) + 1
	}
	return summarizeElided(units, elidedBytes)
}

type tableKind uint8

const (
	tableCSV tableKind = iota + 1
	tableTSV
	tableMarkdown
)

type parsedTable struct {
	kind      tableKind
	rows      [][]string
	delimiter rune
	crlf      bool
}

type tabularCompressor struct {
	minRows      int
	keepFirst    int
	keepLast     int
	queryLimit   int
	relevanceMin float64
}

// NewTabular returns the deterministic CSV, TSV, and Markdown-table compressor.
func NewTabular() Compressor {
	return &tabularCompressor{minRows: 12, keepFirst: 3, keepLast: 2, queryLimit: 24, relevanceMin: 0.30}
}

func (c *tabularCompressor) ContentType() string       { return "tabular" }
func (c *tabularCompressor) SafetyClass() safety.Class { return safety.S4 }
func (c *tabularCompressor) Compress(input []byte) ([]byte, bool) {
	return c.compress(input, "")
}
func (c *tabularCompressor) CompressQuery(input []byte, query string) ([]byte, bool) {
	return c.compress(input, query)
}

// LooksTabular applies the same strict parser used by NewTabular. Detection may
// identify a small table that compression later passes through as not worth it.
func LooksTabular(input []byte) bool {
	table, ok := parseTable(input)
	return ok && len(table.rows) >= 8
}

func (c *tabularCompressor) compress(input []byte, query string) ([]byte, bool) {
	if tabularMarkerRe.Match(input) {
		return nil, false
	}
	table, ok := parseTable(input)
	if !ok {
		return nil, false
	}
	headerRows := 1
	if table.kind == tableMarkdown {
		headerRows = 2
	}
	if len(table.rows) < c.minRows || len(table.rows) <= headerRows+c.keepFirst+c.keepLast+1 {
		return nil, false
	}

	keep := make([]bool, len(table.rows))
	for i := 0; i < headerRows; i++ {
		keep[i] = true
	}
	for i := headerRows; i < headerRows+c.keepFirst && i < len(keep); i++ {
		keep[i] = true
	}
	for i := len(keep) - c.keepLast; i < len(keep); i++ {
		if i >= headerRows {
			keep[i] = true
		}
	}

	docs := make([]string, len(table.rows))
	for i, row := range table.rows {
		docs[i] = strings.Join(row, " ")
		if tabularImportantRe.MatchString(docs[i]) {
			keep[i] = true
		}
	}
	keepNumericExtrema(table.rows, headerRows, keep)
	keepQueryRelevant(keep, docs, query, c.queryLimit, c.relevanceMin)
	keepNonRedundant(docsAsUnits(docs), keep)

	shaped := make([][]string, 0, len(table.rows))
	var run [][]string
	elidedBytes := 0
	flush := func() {
		if len(run) == 0 {
			return
		}
		runBytes := 0
		for _, row := range run {
			runBytes += len(strings.Join(row, ",")) + 1
		}
		summary := summarizeRowRun(table.rows[0], run)
		text := tabularMarker(len(run), summary)
		if !worthEliding(len(run), len(text), runBytes, summary) {
			// Too small a run to describe and too small to be worth a recovery
			// handle: keep the rows themselves and claim nothing for them.
			shaped = append(shaped, run...)
			run = run[:0]
			return
		}
		marker := make([]string, len(table.rows[0]))
		marker[0] = text
		shaped = append(shaped, marker)
		elidedBytes += runBytes
		run = run[:0]
	}
	for i, row := range table.rows {
		if keep[i] {
			flush()
			shaped = append(shaped, row)
		} else {
			run = append(run, row)
		}
	}
	flush()
	if len(shaped) >= len(table.rows) {
		return nil, false
	}
	// The contract line rides as a final row so the table stays a table. Re-entry
	// is short-circuited by tabularMarkerRe above, so it can never be appended
	// twice.
	if wantsElisionNote(elidedBytes) {
		note := make([]string, len(table.rows[0]))
		note[0] = elisionNote("rows")
		shaped = append(shaped, note)
	}

	var out []byte
	if table.kind == tableMarkdown {
		var b strings.Builder
		for _, row := range shaped {
			b.WriteString("| ")
			b.WriteString(strings.Join(row, " | "))
			b.WriteString(" |\n")
		}
		out = []byte(b.String())
		if !bytes.HasSuffix(input, []byte("\n")) {
			out = bytes.TrimSuffix(out, []byte("\n"))
		}
		if table.crlf {
			out = bytes.ReplaceAll(out, []byte("\n"), []byte("\r\n"))
		}
	} else {
		var b bytes.Buffer
		writer := csv.NewWriter(&b)
		writer.Comma = table.delimiter
		writer.UseCRLF = table.crlf
		if err := writer.WriteAll(shaped); err != nil {
			return nil, false
		}
		writer.Flush()
		if err := writer.Error(); err != nil {
			return nil, false
		}
		out = b.Bytes()
		if !bytes.HasSuffix(input, []byte("\n")) {
			if table.crlf {
				out = bytes.TrimSuffix(out, []byte("\r\n"))
			} else {
				out = bytes.TrimSuffix(out, []byte("\n"))
			}
		}
	}
	if len(out) >= len(input) {
		return nil, false
	}
	return out, true
}

func parseTable(input []byte) (parsedTable, bool) {
	if !utf8.Valid(input) || len(bytes.TrimSpace(input)) == 0 {
		return parsedTable{}, false
	}
	if table, ok := parseMarkdownTable(input); ok {
		return table, true
	}
	firstLine := string(bytes.SplitN(bytes.TrimSpace(input), []byte("\n"), 2)[0])
	delimiter := ','
	kind := tableCSV
	if strings.Count(firstLine, "\t") >= 1 && strings.Count(firstLine, "\t") > strings.Count(firstLine, ",") {
		delimiter = '\t'
		kind = tableTSV
	}
	if strings.Count(firstLine, string(delimiter)) < 1 {
		return parsedTable{}, false
	}
	reader := csv.NewReader(bytes.NewReader(input))
	reader.Comma = delimiter
	reader.FieldsPerRecord = 0
	reader.ReuseRecord = false
	rows, err := reader.ReadAll()
	if err != nil || len(rows) < 2 {
		return parsedTable{}, false
	}
	fields := len(rows[0])
	if fields < 2 || fields > 128 {
		return parsedTable{}, false
	}
	for _, row := range rows {
		if len(row) != fields {
			return parsedTable{}, false
		}
	}
	return parsedTable{kind: kind, rows: rows, delimiter: delimiter, crlf: bytes.Contains(input, []byte("\r\n"))}, true
}

func parseMarkdownTable(input []byte) (parsedTable, bool) {
	crlf := bytes.Contains(input, []byte("\r\n"))
	normalized := bytes.ReplaceAll(input, []byte("\r\n"), []byte("\n"))
	raw := bytes.Split(bytes.TrimSuffix(normalized, []byte("\n")), []byte("\n"))
	if len(raw) < 3 {
		return parsedTable{}, false
	}
	rows := make([][]string, 0, len(raw))
	for _, line := range raw {
		text := strings.TrimSpace(string(line))
		if !strings.HasPrefix(text, "|") || !strings.HasSuffix(text, "|") {
			return parsedTable{}, false
		}
		parts := strings.Split(strings.Trim(text, "|"), "|")
		row := make([]string, len(parts))
		for i, part := range parts {
			row[i] = strings.TrimSpace(part)
		}
		rows = append(rows, row)
	}
	if len(rows[0]) < 2 || len(rows[1]) != len(rows[0]) {
		return parsedTable{}, false
	}
	for _, cell := range rows[1] {
		if !markdownSeparatorCellRe.MatchString(cell) {
			return parsedTable{}, false
		}
	}
	for _, row := range rows[2:] {
		if len(row) != len(rows[0]) {
			return parsedTable{}, false
		}
	}
	return parsedTable{kind: tableMarkdown, rows: rows, delimiter: '|', crlf: crlf}, true
}

func keepNumericExtrema(rows [][]string, start int, keep []bool) {
	if len(rows) == 0 || start >= len(rows) {
		return
	}
	for column := range rows[0] {
		numeric := 0
		minIndex, maxIndex := -1, -1
		minValue, maxValue := 0.0, 0.0
		for row := start; row < len(rows); row++ {
			value, err := strconv.ParseFloat(strings.TrimSpace(rows[row][column]), 64)
			if err != nil {
				continue
			}
			numeric++
			if minIndex == -1 || value < minValue {
				minIndex, minValue = row, value
			}
			if maxIndex == -1 || value > maxValue {
				maxIndex, maxValue = row, value
			}
		}
		if numeric*10 < (len(rows)-start)*7 {
			continue
		}
		keep[minIndex] = true
		keep[maxIndex] = true
	}
}

package compressors_test

import (
	"bytes"
	"encoding/csv"
	"fmt"
	"io"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
	"github.com/JuliusBrussee/caveman/engine/safety"
)

func csvFixture() []byte {
	var b strings.Builder
	b.WriteString("name,region,revenue,status\n")
	for i := 0; i < 80; i++ {
		status := "ok"
		if i == 43 {
			status = "FAILED chargeback review"
		}
		fmt.Fprintf(&b, "customer-%02d,%s,%d,%s\n", i, []string{"eu", "us", "apac"}[i%3], 100+i, status)
	}
	return []byte(b.String())
}

func TestTabularCSVStaysValidAndKeepsHeaderExtremaAndErrors(t *testing.T) {
	c := compressors.NewTabular()
	if c.SafetyClass() != safety.S4 {
		t.Fatal("tabular compressor must be S4")
	}
	out, ok := c.Compress(csvFixture())
	if !ok {
		t.Fatal("expected CSV compression")
	}
	if len(out) >= len(csvFixture()) {
		t.Fatalf("expected smaller output, got %d >= %d", len(out), len(csvFixture()))
	}
	rows, err := csv.NewReader(bytes.NewReader(out)).ReadAll()
	if err != nil {
		t.Fatalf("compressed CSV must remain valid: %v\n%s", err, out)
	}
	if got := rows[0]; len(got) != 4 || got[0] != "name" || got[2] != "revenue" {
		t.Fatalf("header changed: %#v", got)
	}
	for _, want := range [][]byte{
		[]byte("customer-00"),
		[]byte("customer-43"),
		[]byte("FAILED chargeback review"),
		[]byte("customer-79"),
		[]byte("rows elided (caveman)"),
	} {
		if !bytes.Contains(out, want) {
			t.Fatalf("compressed CSV missing %q:\n%s", want, out)
		}
	}
}

func TestTabularQueryKeepsRelevantMiddleRows(t *testing.T) {
	c, ok := compressors.NewTabular().(compressors.QueryAwareCompressor)
	if !ok {
		t.Fatal("tabular compressor must be query-aware")
	}
	input := csvFixture()
	out, ok := c.CompressQuery(input, "customer-37 apac")
	if !ok {
		t.Fatal("expected query-aware CSV compression")
	}
	if !bytes.Contains(out, []byte("customer-37")) {
		t.Fatalf("query-relevant row missing:\n%s", out)
	}
	if len(out) >= len(input) {
		t.Fatal("query-aware output must still shrink")
	}
}

func TestTabularTSVStaysValidAndKeepsQueryRow(t *testing.T) {
	var b strings.Builder
	b.WriteString("name\tregion\trevenue\tstatus\n")
	for i := 0; i < 50; i++ {
		fmt.Fprintf(&b, "customer-%02d\t%s\t%d\tok\n", i, []string{"eu", "us", "apac"}[i%3], 100+i)
	}
	input := []byte(b.String())
	c := compressors.NewTabular().(compressors.QueryAwareCompressor)
	out, ok := c.CompressQuery(input, "customer-31 us")
	if !ok {
		t.Fatal("expected TSV compression")
	}
	reader := csv.NewReader(bytes.NewReader(out))
	reader.Comma = '\t'
	rows, err := reader.ReadAll()
	if err != nil {
		t.Fatalf("compressed TSV must remain valid: %v\n%s", err, out)
	}
	if len(rows) >= 50 || !bytes.Contains(out, []byte("customer-31")) {
		t.Fatalf("TSV did not shrink around query row:\n%s", out)
	}
	for _, row := range rows {
		if len(row) != 4 {
			t.Fatalf("TSV row has %d fields, want 4: %#v", len(row), row)
		}
	}
}

func TestTabularMarkdownKeepsShapeAndIsIdempotent(t *testing.T) {
	var b strings.Builder
	b.WriteString("| name | region | revenue |\n| --- | --- | ---: |\n")
	for i := 0; i < 40; i++ {
		fmt.Fprintf(&b, "| customer-%02d | %s | %d |\n", i, []string{"eu", "us"}[i%2], 100+i)
	}
	c := compressors.NewTabular()
	first, ok := c.Compress([]byte(b.String()))
	if !ok {
		t.Fatal("expected Markdown table compression")
	}
	if !bytes.Contains(first, []byte("| --- | --- | ---: |")) {
		t.Fatalf("separator row missing:\n%s", first)
	}
	if !bytes.Contains(first, []byte("rows elided (caveman)")) {
		t.Fatalf("marker missing:\n%s", first)
	}
	if second, ok := c.Compress(first); ok && !bytes.Equal(first, second) {
		t.Fatalf("not idempotent:\nfirst=%s\nsecond=%s", first, second)
	}
}

func TestTabularMalformedOrTinyPassesThrough(t *testing.T) {
	c := compressors.NewTabular()
	for _, input := range [][]byte{
		[]byte("a,b\n1,2\n"),
		[]byte("a,b\n1,2\n3,\"unterminated\n4,5\n"),
		{0xff, 0xfe, 0xfd},
	} {
		if out, ok := c.Compress(input); ok {
			t.Fatalf("unsafe input must pass through, got %q", out)
		}
	}
}

func TestTabularCSVMarkerHasStableFieldCount(t *testing.T) {
	c := compressors.NewTabular()
	out, ok := c.Compress(csvFixture())
	if !ok {
		t.Fatal("expected compression")
	}
	r := csv.NewReader(bytes.NewReader(out))
	for {
		row, err := r.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		if len(row) != 4 {
			t.Fatalf("row has %d fields, want 4: %#v", len(row), row)
		}
	}
}

func TestTabularCSVPreservesCRLFWithoutAddingTrailingNewline(t *testing.T) {
	input := bytes.ReplaceAll(bytes.TrimSuffix(csvFixture(), []byte("\n")), []byte("\n"), []byte("\r\n"))
	out, ok := compressors.NewTabular().Compress(input)
	if !ok {
		t.Fatal("expected CSV compression")
	}
	if bytes.HasSuffix(out, []byte{'\r'}) || bytes.HasSuffix(out, []byte{'\n'}) {
		t.Fatalf("unexpected trailing newline bytes: %q", out[len(out)-4:])
	}
	if bytes.Contains(bytes.ReplaceAll(out, []byte("\r\n"), nil), []byte("\n")) {
		t.Fatal("compressed CSV mixed newline styles")
	}
}

package compressors

import (
	"bytes"
	"fmt"
	"regexp"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// TerminalType is the content type for terminal/command-output compression. It is
// auto-selected by Detect when a payload carries raw ANSI escapes (see
// engine/detect.go) and is forced by `caveman shrink`, which wraps a command and
// shrinks its output before a model reads it.
const TerminalType = "terminal"

var (
	// ansiRe matches ANSI/VT control sequences: CSI (ESC [ … final byte), OSC
	// (ESC ] … BEL/ST), and the standalone two-byte Fe escapes. These are
	// display-only noise a model never needs; the original — escapes and all —
	// stays byte-exact in CCR, so stripping them is recoverable, not destructive.
	ansiRe = regexp.MustCompile(`\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-Z\x5c-_]`)
	// termImportantRe keeps lines that carry signal: errors, failures, warnings,
	// stack-trace frames, compiler error locations, and non-zero exits. These are
	// never elided no matter where they sit in the output. The `[A-Za-z]+Error` /
	// `[A-Za-z]+Exception` alternatives catch camelCase types (AssertionError,
	// ValueError, NullPointerException) that a bare `\bERROR\b` would miss — the
	// most common way a real failure hides from naive head/tail sampling.
	termImportantRe = regexp.MustCompile(`(?i)(\b(ERROR|ERR|FATAL|PANIC|EXCEPTION|TRACEBACK|FAIL|FAILED|FAILURE|WARN|WARNING)\b|[A-Za-z]+Error\b|[A-Za-z]+Exception\b|^\s+at\s|^\s+File "|\.go:\d+|:\d+:\d+:|^\s*--->|caused by|\bexit status [1-9])`)
	// termMarkerRe recognizes our own elision marker so a second pass never
	// collapses it again — the compressor stays idempotent.
	termMarkerRe = regexp.MustCompile(`lines elided \(caveman\)`)
)

func termMarker(n int) string { return fmt.Sprintf("… %d lines elided (caveman) …", n) }

// terminalCompressor shrinks raw terminal/command output before a model reads it:
// it strips ANSI control sequences, collapses carriage-return progress redraws to
// their final visible state, and elides the boring middle while keeping the head,
// the tail, and every error/traceback/warning line verbatim. It is S4 (lossy):
// the byte-exact original — ANSI, progress frames, and all — is recoverable via
// CCR, so this is the recoverable counterpart to a crude shell rewriter. It is the
// engine primitive behind `caveman shrink`. Deterministic, idempotent, and
// fail-closed: on any anomaly, or when it cannot actually shrink the payload, it
// returns ok=false and the caller forwards the original bytes unchanged.
type terminalCompressor struct {
	keepHead int
	keepTail int
}

// NewTerminal returns the default terminal/command-output compressor.
func NewTerminal() Compressor { return &terminalCompressor{keepHead: 3, keepTail: 3} }

func (c *terminalCompressor) ContentType() string       { return TerminalType }
func (c *terminalCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *terminalCompressor) Compress(input []byte) ([]byte, bool) {
	if len(input) == 0 || !utf8.Valid(input) {
		return nil, false // empty or binary-ish content → pass-through
	}

	// Normalize CRLF to LF for analysis; the file's separator is restored on
	// output so we never silently rewrite line endings.
	crlf := bytes.Contains(input, []byte("\r\n"))
	work := input
	if crlf {
		work = bytes.ReplaceAll(work, []byte("\r\n"), []byte("\n"))
	}
	work = collapseCarriageReturns(work) // intra-line \r redraws → final state
	work = ansiRe.ReplaceAll(work, nil)  // strip display control sequences

	trailing := bytes.HasSuffix(work, []byte("\n"))
	body := work
	if trailing {
		body = body[:len(body)-1]
	}
	lines := bytes.Split(body, []byte("\n"))

	out := lines // < 4 lines: ANSI/\r cleanup alone may still have shrunk it
	if len(lines) >= 4 {
		out = elideMiddle(lines, c.keepHead, c.keepTail)
	}

	result := bytes.Join(out, []byte("\n"))
	if trailing {
		result = append(result, '\n')
	}
	if crlf {
		result = bytes.ReplaceAll(result, []byte("\n"), []byte("\r\n"))
	}
	if bytes.Equal(result, input) {
		return nil, false // cleanup and elision changed nothing → claim nothing
	}
	return result, true
}

// collapseCarriageReturns rewrites each physical line to its final redraw state.
// A bare \r rewinds the cursor to the start of the line, so a progress bar that
// reprints "10%\r20%\r100% done" was only ever showing "100% done" — the earlier
// frames are visual history, not content. It keeps the last non-empty \r segment.
func collapseCarriageReturns(b []byte) []byte {
	if !bytes.Contains(b, []byte("\r")) {
		return b
	}
	lines := bytes.Split(b, []byte("\n"))
	for i, ln := range lines {
		if !bytes.Contains(ln, []byte("\r")) {
			continue
		}
		chosen := []byte(nil)
		for _, seg := range bytes.Split(ln, []byte("\r")) {
			if len(seg) > 0 {
				chosen = seg
			}
		}
		lines[i] = chosen
	}
	return bytes.Join(lines, []byte("\n"))
}

// elideMiddle keeps the head, the tail, and every signal-bearing line, collapsing
// each run of dropped lines into a single marker. It mirrors the log compressor's
// proven head/tail/importance pass so terminal output and build logs elide the
// same way once the terminal-specific ANSI/\r noise is gone.
func elideMiddle(lines [][]byte, head, tail int) [][]byte {
	keep := make([]bool, len(lines))
	for i, ln := range lines {
		if i < head || i >= len(lines)-tail || termImportantRe.Match(ln) || termMarkerRe.Match(ln) {
			keep[i] = true
		}
	}
	keepNonRedundant(lines, keep)
	out := make([][]byte, 0, len(lines))
	dropped := 0
	flush := func() {
		if dropped > 0 {
			out = append(out, []byte(termMarker(dropped)))
			dropped = 0
		}
	}
	for i, ln := range lines {
		if keep[i] {
			flush()
			out = append(out, ln)
			continue
		}
		dropped++
	}
	flush()
	return out
}

package compressors

import (
	"bytes"
	"fmt"
	"strings"
	"testing"
)

func TestTerminalStripsANSI(t *testing.T) {
	in := []byte("\x1b[32mPASS\x1b[0m build ok\n")
	out, ok := NewTerminal().Compress(in)
	if !ok {
		t.Fatal("expected ANSI-bearing line to compress")
	}
	if bytes.ContainsRune(out, 0x1b) {
		t.Errorf("output still contains a raw ESC byte: %q", out)
	}
	if bytes.Contains(out, []byte("[32m")) || bytes.Contains(out, []byte("[0m")) {
		t.Errorf("output still contains ANSI artifacts: %q", out)
	}
	if !bytes.Contains(out, []byte("PASS build ok")) {
		t.Errorf("output dropped visible text: %q", out)
	}
}

func TestTerminalCollapsesCarriageReturns(t *testing.T) {
	in := []byte("Downloading\rDownloading 50%\rDownloading 100% done\n")
	out, ok := NewTerminal().Compress(in)
	if !ok {
		t.Fatal("expected carriage-return redraws to collapse")
	}
	if bytes.Contains(out, []byte("50%")) {
		t.Errorf("intermediate progress frame survived: %q", out)
	}
	if !bytes.Contains(out, []byte("Downloading 100% done")) {
		t.Errorf("final progress state lost: %q", out)
	}
	if bytes.ContainsRune(out, '\r') {
		t.Errorf("bare carriage return survived: %q", out)
	}
}

func TestTerminalKeepsSignalElidesMiddle(t *testing.T) {
	var b strings.Builder
	b.WriteString("$ npm test\n")
	b.WriteString("> project@1.0.0 test\n")
	for i := 0; i < 40; i++ {
		fmt.Fprintf(&b, "  \x1b[2m✓ passes assertion %d\x1b[0m\n", i)
	}
	b.WriteString("ERROR: assertion 'auth token expiry' failed\n")
	b.WriteString("  File \"auth.py\", line 42, in check\n")
	for i := 0; i < 40; i++ {
		fmt.Fprintf(&b, "  \x1b[2m✓ passes assertion %d\x1b[0m\n", 40+i)
	}
	b.WriteString("1 failed, 80 passed\n")
	in := []byte(b.String())

	out, ok := NewTerminal().Compress(in)
	if !ok {
		t.Fatal("expected long terminal output to compress")
	}
	if len(out) >= len(in) {
		t.Errorf("compression did not shrink: %d -> %d bytes", len(in), len(out))
	}
	for _, must := range []string{
		"ERROR: assertion 'auth token expiry' failed",
		"File \"auth.py\", line 42, in check",
		"1 failed, 80 passed",
		"lines elided (caveman)",
	} {
		if !bytes.Contains(out, []byte(must)) {
			t.Errorf("output dropped a line it must keep: %q\n--- got ---\n%s", must, out)
		}
	}
	if bytes.ContainsRune(out, 0x1b) {
		t.Errorf("ANSI escapes survived elision: %q", out)
	}
}

func TestTerminalPassesThroughPlainShort(t *testing.T) {
	if _, ok := NewTerminal().Compress([]byte("hello\nworld\n")); ok {
		t.Error("plain short output with nothing to strip or elide must pass through (ok=false)")
	}
	if _, ok := NewTerminal().Compress(nil); ok {
		t.Error("empty input must pass through (ok=false)")
	}
}

func TestTerminalIsIdempotent(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 30; i++ {
		fmt.Fprintf(&b, "\x1b[36mINFO\x1b[0m step %d ok\n", i)
	}
	b.WriteString("ERROR: boom\n")
	first, ok := NewTerminal().Compress([]byte(b.String()))
	if !ok {
		t.Fatal("first pass should compress")
	}
	if _, ok := NewTerminal().Compress(first); ok {
		t.Errorf("second pass must be a no-op (ok=false), got further change:\n%s", first)
	}
}

