import (
	"bytes"
	"fmt"
	"regexp"
	"strings"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

var (
	textMarkerRe    = regexp.MustCompile(`sections elided \(caveman\)`)
	htmlScriptRe    = regexp.MustCompile(`(?is)<script\b[^>]*>.*?</script>`)
	htmlStyleRe     = regexp.MustCompile(`(?is)<style\b[^>]*>.*?</style>`)
	htmlSVGRe       = regexp.MustCompile(`(?is)<svg\b[^>]*>.*?</svg>`)
	htmlCommentRe   = regexp.MustCompile(`(?s)<!--.*?-->`)
	paragraphSplit  = regexp.MustCompile(`\n\s*\n+`)
	textImportantRe = regexp.MustCompile(`(?i)\b(ERROR|WARNING|IMPORTANT|NOTE|ACTION|FOLLOWUP|SECURITY|SUMMARY|CONCLUSION|DECISION|RECOMMENDATION)\b`)
)

func textMarker(n int) string { return fmt.Sprintf("… %d sections elided (caveman) …", n) }

// textCompressor collapses long prose/HTML payloads by section while retaining
// headings, the opening/closing context, and explicitly important paragraphs.
type textCompressor struct {
	keepHead int
	keepTail int
	minBytes int
}

// NewText returns the long text / HTML compressor.
func NewText() Compressor { return &textCompressor{keepHead: 2, keepTail: 2, minBytes: 1600} }

func (c *textCompressor) ContentType() string       { return "text" }
func (c *textCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *textCompressor) Compress(input []byte) ([]byte, bool) {
	return c.compress(input, "")
}

func (c *textCompressor) CompressQuery(input []byte, query string) ([]byte, bool) {
	return c.compress(input, query)
}

func (c *textCompressor) compress(input []byte, query string) ([]byte, bool) {
	if !utf8.Valid(input) || len(bytes.TrimSpace(input)) < c.minBytes {
		return nil, false
	}
	normalized := input
	if looksHTML(input) {
		normalized = compressHTMLNoise(input)
	}
	sections := splitTextSections(normalized)
	if len(sections) <= c.keepHead+c.keepTail+2 {
		return nil, false
	}

	keep := make([]bool, len(sections))
	for i, section := range sections {
		if i < c.keepHead || i >= len(sections)-c.keepTail || isTextHeading(section) || textImportantRe.Match(section) || textMarkerRe.Match(section) {
			keep[i] = true
		}
	}
	docs := make([]string, len(sections))
	for i, section := range sections {
		docs[i] = string(section)
	}
	keepQueryRelevant(keep, docs, query, 12, 0.30)
	keepNonRedundant(sections, keep)

	out := make([][]byte, 0, len(sections))
	dropped := 0
	for i, section := range sections {
		if keep[i] {
			if dropped > 0 {
				out = append(out, []byte(textMarker(dropped)))
				dropped = 0
			}
			out = append(out, bytes.TrimSpace(section))
		} else {
			dropped++
		}
	}
	if dropped > 0 {
		out = append(out, []byte(textMarker(dropped)))
	}
	if len(out) == len(sections) {
		return nil, false
	}
	result := bytes.Join(out, []byte("\n\n"))
	return result, true
}

func looksHTML(input []byte) bool {
	s := strings.ToLower(string(bytes.TrimSpace(input)))
	return strings.HasPrefix(s, "<!doctype html") || strings.HasPrefix(s, "<html") || strings.Contains(s, "<body")
}

func compressHTMLNoise(input []byte) []byte {
	out := htmlScriptRe.ReplaceAll(input, []byte(textMarker(1)))
	out = htmlStyleRe.ReplaceAll(out, []byte(textMarker(1)))
	out = htmlSVGRe.ReplaceAll(out, []byte(textMarker(1)))
	out = htmlCommentRe.ReplaceAll(out, nil)
	return out
}

func splitTextSections(input []byte) [][]byte {
	if bytes.Contains(input, []byte("\n\n")) || bytes.Contains(input, []byte("\r\n\r\n")) {
		raw := paragraphSplit.Split(string(input), -1)
		sections := make([][]byte, 0, len(raw))
		for _, part := range raw {
			if trimmed := strings.TrimSpace(part); trimmed != "" {
				sections = append(sections, []byte(trimmed))
			}
		}
		return sections
	}
	lines := bytes.Split(input, []byte("\n"))
	sections := make([][]byte, 0, len(lines))
	for _, line := range lines {
		if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
			sections = append(sections, trimmed)
		}
	}
	return sections
}

func isTextHeading(section []byte) bool {
	trimmed := bytes.TrimSpace(section)
	if bytes.HasPrefix(trimmed, []byte("#")) {
		return true
	}
	if len(trimmed) > 96 || bytes.ContainsAny(trimmed, ".!?") {
		return false
	}
	words := bytes.Fields(trimmed)
	return len(words) > 0 && len(words) <= 8
}

package compressors

import (
	"bytes"
	"encoding/json"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// maxDescLen caps the non-constraint *lead* sentence of a kept description at this
// many bytes. A short lead keeps a selection hint; the rest of the prose is
// recoverable via CCR. Constraint-bearing sentences are never subject to this cap
// (see compressDescription) — dropping them would produce invalid tool calls.
const maxDescLen = 80

// schemaMetaDrop is the set of JSON-Schema annotation keys that never affect tool
// selection and carry the most bytes: examples, titles, comments, and the dialect
// marker. They are dropped outright. NOTE: these are only dropped where they are
// schema *metadata* — never where they are user-defined names (see
// compressSchema's userDefinedKeys handling for properties / $defs / definitions /
// patternProperties). `default` is deliberately NOT in this set: a default value
// is part of argument construction (an agent that omits it relies on it), so it is
// kept — see keepSchemaKeys.
var schemaMetaDrop = map[string]bool{
	"examples": true,
	"example":  true,
	"$comment": true,
	"title":    true,
	"$schema":  true,
}

// keepSchemaKeys is the set of schema keys that carry argument-construction meaning
// and are kept verbatim (no recursion, no truncation): enum and required are the
// selection surface; default is what an agent omits an argument to inherit — losing
// it silently changes the call. `const` pins a single valid value, same hazard.
var keepSchemaKeys = map[string]bool{
	"enum":     true,
	"required": true,
	"default":  true,
	"const":    true,
}

// userDefinedKeys are schema keys whose *child map keys* are user-controlled names
// (property names, $defs/definition names, patternProperties regexes, dependency
// property names), not schema vocabulary. Their keys must all survive verbatim —
// a definition or dependency named "title" is not metadata. Only schema values
// under these keys are compressed; string-array dependency values pass through.
var userDefinedKeys = map[string]bool{
	"properties":        true,
	"$defs":             true,
	"definitions":       true,
	"patternProperties": true,
	"dependentSchemas":  true,
	"dependentRequired": true,
	"dependencies":      true,
}

// toolSchemaCompressor compresses an MCP/OpenAI tool-definition catalog (or any
// JSON Schema) by dropping annotation metadata and reducing free-text descriptions
// to their selection lead plus every constraint-bearing sentence, while preserving
// every selection-relevant token verbatim — tool and parameter names, types, enums,
// required, defaults, and $ref targets.
//
// Two structural boundaries it upholds:
//   - selection surface: names/params/enums/required survive byte-for-byte. This
//     does not guarantee same-tool behavior because descriptions are model-visible
//     and reduced lossily; behavioral equivalence requires model evals.
//   - argument validity: a description sentence stating a constraint (must / required
//     / exactly one / rejected / format / ISO / RFC / absolute) is retained in full,
//     reducing the risk of invalid arguments. It does not *guarantee* argument
//     validity — only that recognised constraint sentences present in the source
//     are not dropped.
//
// It is S4 (lossy): dropped descriptive prose and metadata are recoverable through
// CCR. On any parse problem it reports !ok and the caller forwards bytes unchanged.
type toolSchemaCompressor struct{}

// NewToolSchema returns the tool-schema / tool-catalog compressor. It is selected
// by forcing the "toolschema" content type (engine.Options.Type); Detect never
// routes to it, so the proxy's generic JSON path is unaffected.
func NewToolSchema() Compressor { return &toolSchemaCompressor{} }

func (c *toolSchemaCompressor) ContentType() string       { return "toolschema" }
func (c *toolSchemaCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *toolSchemaCompressor) Compress(input []byte) ([]byte, bool) {
	dec := json.NewDecoder(bytes.NewReader(input))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return nil, false // malformed JSON → pass-through
	}
	if dec.More() {
		return nil, false // more than one value → not a single catalog payload
	}
	out, err := json.Marshal(c.compressDocument(v))
	if err != nil {
		return nil, false
	}
	return out, true
}

// compressDocument distinguishes provider tool envelopes from raw JSON Schema.
// Envelope fields are model-visible tool metadata, not JSON-Schema vocabulary:
// MCP annotations.title, vendor metadata, and cache hints must survive. Tool
// descriptions take the compressor's explicit description path; only declared
// schema-valued fields cross into compressSchema.
func (c *toolSchemaCompressor) compressDocument(v any) any {
	switch document := v.(type) {
	case []any:
		out := make([]any, len(document))
		for i, tool := range document {
			out[i] = c.compressToolEnvelope(tool)
		}
		return out
	case map[string]any:
		if tools, ok := document["tools"]; ok {
			out := cloneJSONMap(document)
			out["tools"] = c.compressToolEnvelope(tools)
			return out
		}
		if isToolEnvelope(document) {
			return c.compressToolEnvelope(document)
		}
		return c.compressSchema(document, false)
	default:
		return v
	}
}

func (c *toolSchemaCompressor) compressToolEnvelope(v any) any {
	switch envelope := v.(type) {
	case []any:
		out := make([]any, len(envelope))
		for i, tool := range envelope {
			out[i] = c.compressToolEnvelope(tool)
		}
		return out
	case map[string]any:
		out := cloneJSONMap(envelope)
		for key, value := range envelope {
			switch {
			case envelopeSchemaKeys[key]:
				out[key] = c.compressSchema(value, false)
			case envelopeNestKeys[key]:
				out[key] = c.compressToolEnvelope(value)
			case key == "description":
				// Tool descriptions are intentionally reduced by this lossy
				// compressor, but no generic schema metadata rule applies to
				// their surrounding envelope.
				if description, ok := value.(string); ok {
					out[key] = compressDescription(description)
				}
			}
		}
		return out
	default:
		return v
	}
}

func isToolEnvelope(value map[string]any) bool {
	if _, ok := value["name"]; ok {
		return true
	}
	for key := range value {
		if envelopeSchemaKeys[key] || envelopeNestKeys[key] {
			return true
		}
	}
	return false
}

func cloneJSONMap(value map[string]any) map[string]any {
	clone := make(map[string]any, len(value))
	for key, item := range value {
		clone[key] = item
	}
	return clone
}

// compressSchema walks a parsed JSON Schema / tool catalog. inUserKeys is true when
// the map is the value of a properties / $defs / definitions / patternProperties
// object, whose keys are user-defined names that must all survive verbatim — only
// their schema values are compressed. Everywhere else the map is a schema object
// whose annotation keys may be dropped, and whose descriptions are reduced.
func (c *toolSchemaCompressor) compressSchema(v any, inUserKeys bool) any {
	switch t := v.(type) {
	case map[string]any:
		m := make(map[string]any, len(t))
		for k, val := range t {
			if inUserKeys {
				// Keys here are user-defined names — keep every one; compress its
				// schema value as a normal schema object.
				m[k] = c.compressSchema(val, false)
				continue
			}
			switch {
			case schemaMetaDrop[k]:
				// Drop annotation metadata outright (recoverable via CCR).
			case k == "description":
				if s, ok := val.(string); ok {
					m[k] = compressDescription(s)
				} else {
					m[k] = c.compressSchema(val, false)
				}
			case keepSchemaKeys[k]:
				// Argument-construction meaning — keep verbatim, no recursion.
				m[k] = val
			case userDefinedKeys[k]:
				m[k] = c.compressSchema(val, true)
			default:
				m[k] = c.compressSchema(val, false)
			}
		}
		return m
	case []any:
		out := make([]any, len(t))
		for i, e := range t {
			out[i] = c.compressSchema(e, false)
		}
		return out
	default:
		return v
	}
}

// constraintRe matches an argument-construction constraint marker as a whole word
// or phrase. Matching is deliberately biased to OVER-keep: retaining an extra
// sentence only costs a little ratio, while dropping a constraint sentence produces
// an invalid tool call and a retry loop that costs more than the shrink saved. The
// set is broad on purpose — bound words (over/above/max/range/…), prohibition words
// (cannot/invalid/not allowed/…), and format anchors (iso/rfc/absolute) — so a
// constraint phrased without the word "must" is still retained. iso/rfc allow a
// trailing digit run so "RFC3339" and "ISO8601" match.
var constraintRe = regexp.MustCompile(`(?i)\b(?:` +
	`must|must not|cannot|can't|shall|` +
	`require\w*|reject\w*|disallow\w*|forbidden|` +
	`invalid|not allowed|not permitted|` +
	`exactly one|only one of|one of|at least|at most|` +
	`mutually exclusive|only|unique|case[- ]?sensitive|` +
	`max|min|maximum|minimum|range|between|` +
	`greater than|less than|more than|fewer than|no more than|no less than|` +
	`over|above|below|under|beyond|exceed\w*|` +
	`format\w*|iso[- ]?\d*|rfc[- ]?\d*|absolute` +
	`)\b`)

// hasConstraintMarker reports whether a sentence states an argument constraint.
func hasConstraintMarker(s string) bool { return constraintRe.MatchString(s) }

// smallDescBudget is the size below which a description is kept WHOLE, no sentence
// eliding at all. Below it, dropping a sentence saves too few bytes to justify any
// risk of under-keeping a constraint the marker set does not recognise — so short
// descriptions (the common case) pass through verbatim and only genuinely large
// ones are reduced.
const smallDescBudget = maxDescLen * 2

// compressDescription reduces a free-text description. A description that already
// fits smallDescBudget is kept whole — eliding it would save a handful of bytes
// while risking the loss of a constraint stated without a marker word. Only a
// genuinely large description is reduced: to its selection lead (the first
// non-constraint sentence, capped at maxDescLen on a rune boundary) plus every
// constraint-bearing sentence, in original order. Deterministic and idempotent:
// re-compressing its own output yields the same string.
func compressDescription(s string) string {
	s = strings.TrimSpace(s)
	if len(s) <= smallDescBudget {
		return s
	}
	sentences := splitSentences(s)
	var kept []string
	leadTaken := false
	for _, sent := range sentences {
		switch {
		case hasConstraintMarker(sent):
			kept = append(kept, sent) // never dropped, never capped
		case !leadTaken:
			kept = append(kept, capRunes(sent, maxDescLen))
			leadTaken = true
		default:
			// A non-constraint, non-lead sentence: drop (recoverable via CCR).
		}
	}
	return strings.Join(kept, " ")
}

// splitSentences breaks prose into sentences on a period that is followed by
// whitespace and an uppercase letter and does not end an abbreviation. This keeps
// "e.g.", "i.e.", "Node.js", "v1.2" and decimals ("3.14") intact: the last two are
// excluded because their period is not followed by whitespace, and the first two by
// the abbreviation guard. Sentences are returned with their trailing period.
func splitSentences(s string) []string {
	var out []string
	start := 0
	for i := 0; i < len(s); i++ {
		if s[i] != '.' {
			continue
		}
		j := i + 1
		if j >= len(s) || !isSpaceByte(s[j]) {
			continue // period not followed by whitespace → not a boundary
		}
		for j < len(s) && isSpaceByte(s[j]) {
			j++
		}
		if j >= len(s) {
			continue
		}
		r, _ := utf8.DecodeRuneInString(s[j:])
		if !unicode.IsUpper(r) {
			continue // next word not capitalised → not a sentence start
		}
		if endsWithAbbrev(s, i) {
			continue
		}
		if seg := strings.TrimSpace(s[start : i+1]); seg != "" {
			out = append(out, seg)
		}
		start = j
		i = j - 1 // resume scanning at the next sentence's first char
	}
	if seg := strings.TrimSpace(s[start:]); seg != "" {
		out = append(out, seg)
	}
	return out
}

// endsWithAbbrev reports whether the period at dotIdx terminates an abbreviation
// rather than a sentence: a single-letter initial ("A."), a token with an internal
// dot ("e.g", "i.e", "U.S"), or a known abbreviation word ("etc", "vs", "no").
func endsWithAbbrev(s string, dotIdx int) bool {
	k := dotIdx - 1
	for k >= 0 && (isLetterByte(s[k]) || s[k] == '.') {
		k--
	}
	word := strings.ToLower(strings.Trim(s[k+1:dotIdx], "."))
	if word == "" {
		return false
	}
	if len(word) == 1 { // an initial: "A. Name"
		return true
	}
	if strings.Contains(word, ".") { // "e.g", "i.e", "u.s"
		return true
	}
	return abbrevSet[word]
}

// abbrevSet is a conservative set of English/Latin abbreviations whose trailing
// period must not be read as a sentence boundary. Treating an ambiguous token as an
// abbreviation only over-joins (keeps more together), which is the safe direction.
var abbrevSet = map[string]bool{
	"e.g": true, "i.e": true, "eg": true, "ie": true, "etc": true,
	"vs": true, "cf": true, "al": true, "viz": true, "resp": true,
	"approx": true, "no": true, "fig": true, "figs": true, "dr": true,
	"mr": true, "mrs": true, "ms": true, "prof": true, "sr": true,
	"jr": true, "st": true, "inc": true, "ltd": true, "corp": true,
	"co": true, "dept": true, "est": true,
}

func isSpaceByte(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r' || b == '\v' || b == '\f'
}
func isLetterByte(b byte) bool { return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') }

// capRunes truncates s to at most maxBytes bytes without splitting a UTF-8 rune,
// so the compressor never emits a U+FFFD replacement character into the
// model-visible catalog. It backs off to the last word boundary when
// that still leaves a substantial lead, rather than emitting a mangled half-word.
// It is idempotent for already-short strings.
func capRunes(s string, maxBytes int) string {
	if len(s) <= maxBytes {
		return s
	}
	cut := s[:maxBytes]
	for len(cut) > 0 && !utf8.ValidString(cut) {
		cut = cut[:len(cut)-1]
	}
	if sp := strings.LastIndexByte(cut, ' '); sp > maxBytes/2 {
		cut = cut[:sp]
	}
	return strings.TrimRight(cut, " ")
}

package compressors

import (
	"encoding/json"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

// toolSchemaAnnotationsType is the forced content type for the annotation strip.
const toolSchemaAnnotationsType = "toolschema-annotations"

// annotationDropKeys are the four JSON-Schema annotation keywords the strip
// removes. Each is documentation-only: none constrains validation, none names a
// tool or a parameter. "description" is deliberately NOT here — truncating
// descriptions is a separate, separately gated decision.
var annotationDropKeys = map[string]bool{
	"$schema":    true,
	"title":      true,
	"examples":   true,
	"deprecated": true,
}

// envelopeSchemaKeys are the tool-definition fields whose value is a JSON Schema.
// They are the ONLY doors from a tool envelope into strippable territory.
var envelopeSchemaKeys = map[string]bool{
	"input_schema": true,
	"inputSchema":  true,
	"parameters":   true,
}

// envelopeNestKeys are tool-definition fields that wrap another tool envelope —
// the OpenAI `{"type":"function","function":{…}}` shape.
var envelopeNestKeys = map[string]bool{"function": true}

// schemaNameMapKeys are schema keywords whose object value is keyed by
// USER-DEFINED names. A member named "title" inside one of these is a property or
// definition name, not metadata; deleting it would change the schema and orphan
// any $ref pointing at it.
var schemaNameMapKeys = map[string]bool{
	"properties":        true,
	"patternProperties": true,
	"$defs":             true,
	"definitions":       true,
	"dependentSchemas":  true,
}

// schemaChildKeys are the JSON-Schema applicator keywords whose value is a schema
// or an array of schemas. Descent is an ALLOWLIST, not a default: a keyword that
// is not listed here (and not a name map) is left completely alone, values
// included. That is what keeps the strip honest around vendor extensions,
// instance data, and non-schema containers — "enum", "const", "default",
// "x-anything" and friends are never walked simply because they are not here.
var schemaChildKeys = map[string]bool{
	"items":                 true,
	"prefixItems":           true,
	"additionalItems":       true,
	"unevaluatedItems":      true,
	"additionalProperties":  true,
	"unevaluatedProperties": true,
	"propertyNames":         true,
	"contains":              true,
	"not":                   true,
	"if":                    true,
	"then":                  true,
	"else":                  true,
	"allOf":                 true,
	"anyOf":                 true,
	"oneOf":                 true,
}

// StripToolSchemaAnnotations removes the annotationDropKeys keywords from a
// serialized tool catalog (the provider `tools` array) and returns ok=false with
// the input unchanged on any parse anomaly.
//
// Scope is deliberately narrow. A tool envelope itself is never edited: every
// field on it — name, description, annotations, _meta, vendor extensions — is
// copied through, and the walk only enters the values of envelopeSchemaKeys.
// Inside a schema it descends only through schemaChildKeys and schemaNameMapKeys.
// MCP's `annotations.title` is a human-readable tool NAME that the model sees and
// may select on, so it is not an annotation in the JSON-Schema sense and is not
// touched.
//
// It is a targeted span deletion, not a re-serialization: every byte outside a
// removed key/value member is copied through untouched, so key order, whitespace,
// number formatting, and string escapes all survive exactly. Two properties the
// callers depend on follow from that:
//
//   - cache_control survives byte-for-byte. An Anthropic breakpoint usually rides
//     the LAST tool; re-serializing the catalog would move or reshape it and bust
//     the very cache this lever exists to preserve.
//   - the transform is deterministic and idempotent — same input bytes always
//     produce the same output bytes, and stripping a stripped catalog is a no-op
//     (ok=true, identical bytes), so the upstream prefix is stable across turns.
//
// Tool order is never changed: elements are only walked, never reordered or
// dropped.
func StripToolSchemaAnnotations(tools []byte) ([]byte, bool) {
	if !json.Valid(tools) {
		return tools, false
	}
	s := &annotationStripper{body: tools}
	start := skipSpace(tools, 0)
	end, ok := s.catalog(start)
	if !ok || skipSpace(tools, end) != len(tools) {
		return tools, false
	}
	if len(s.cuts) == 0 {
		return tools, true
	}
	out := s.apply()
	if out == nil || !json.Valid(out) {
		return tools, false
	}
	return out, true
}

// cutSpan is a half-open byte range to delete from the input.
type cutSpan struct{ start, end int }

// annotationStripper walks the catalog once and records the byte ranges to
// delete. Ranges come out in ascending order and never overlap, so applying them
// is a single copy pass over the untouched bytes.
type annotationStripper struct {
	body []byte
	cuts []cutSpan
}

// catalog walks the top-level value: an array of tool envelopes, or one envelope.
func (s *annotationStripper) catalog(i int) (int, bool) {
	if i >= len(s.body) {
		return 0, false
	}
	switch s.body[i] {
	case '[':
		return s.envelopeArray(i)
	case '{':
		return s.envelope(i)
	default:
		return skipValue(s.body, i)
	}
}

func (s *annotationStripper) envelopeArray(start int) (int, bool) {
	i := skipSpace(s.body, start+1)
	for i < len(s.body) && s.body[i] != ']' {
		end, ok := s.catalog(i)
		if !ok {
			return 0, false
		}
		i = skipSpace(s.body, end)
		if i < len(s.body) && s.body[i] == ',' {
			i = skipSpace(s.body, i+1)
		}
	}
	if i >= len(s.body) || s.body[i] != ']' {
		return 0, false
	}
	return i + 1, true
}

// envelope walks one tool definition. Nothing is ever deleted at this level; only
// the declared schema fields are entered.
func (s *annotationStripper) envelope(start int) (int, bool) {
	return s.walkObject(start, func(key string, valueStart int) (int, bool) {
		switch {
		case envelopeSchemaKeys[key]:
			return s.schema(valueStart)
		case envelopeNestKeys[key]:
			return s.catalog(valueStart)
		default:
			return skipValue(s.body, valueStart)
		}
	}, nil)
}

// schema walks one JSON Schema object, dropping annotation keywords and
// descending only through allowlisted schema positions.
func (s *annotationStripper) schema(start int) (int, bool) {
	if start >= len(s.body) {
		return 0, false
	}
	switch s.body[start] {
	case '{':
		return s.walkObject(start, func(key string, valueStart int) (int, bool) {
			switch {
			case schemaNameMapKeys[key]:
				return s.nameMap(valueStart)
			case schemaChildKeys[key]:
				return s.schema(valueStart)
			default:
				return skipValue(s.body, valueStart)
			}
		}, annotationDropKeys)
	case '[':
		// An array in a schema position holds schemas (allOf/anyOf/prefixItems,
		// or draft-4 tuple `items`).
		i := skipSpace(s.body, start+1)
		for i < len(s.body) && s.body[i] != ']' {
			end, ok := s.schema(i)
			if !ok {
				return 0, false
			}
			i = skipSpace(s.body, end)
			if i < len(s.body) && s.body[i] == ',' {
				i = skipSpace(s.body, i+1)
			}
		}
		if i >= len(s.body) || s.body[i] != ']' {
			return 0, false
		}
		return i + 1, true
	default:
		return skipValue(s.body, start)
	}
}

// nameMap walks an object whose keys are user-defined names: no key is ever
// dropped, and each value is a schema.
func (s *annotationStripper) nameMap(start int) (int, bool) {
	if start >= len(s.body) || s.body[start] != '{' {
		return skipValue(s.body, start)
	}
	return s.walkObject(start, func(_ string, valueStart int) (int, bool) {
		return s.schema(valueStart)
	}, nil)
}

// walkObject iterates one JSON object, handing each member's value to descend and
// recording a deletion for every key in drop (nil drop deletes nothing).
//
// Each deletion takes exactly one separator with it, chosen so the result stays
// valid whatever subset is dropped: a member with a surviving member before it
// swallows the comma on its LEFT (from the previous member's end), and a member
// with none swallows everything up to where the next member starts (or the
// closing brace). Deleting all members leaves "{}" plus the object's leading
// whitespace.
func (s *annotationStripper) walkObject(
	start int,
	descend func(key string, valueStart int) (int, bool),
	drop map[string]bool,
) (int, bool) {
	if start >= len(s.body) || s.body[start] != '{' {
		return 0, false
	}
	i := skipSpace(s.body, start+1)
	keptBefore := false
	prevValueEnd := -1
	for i < len(s.body) && s.body[i] != '}' {
		keyStart := i
		keyEnd, ok := stringEnd(s.body, i)
		if !ok {
			return 0, false
		}
		var key string
		if json.Unmarshal(s.body[keyStart:keyEnd], &key) != nil {
			return 0, false
		}
		i = skipSpace(s.body, keyEnd)
		if i >= len(s.body) || s.body[i] != ':' {
			return 0, false
		}
		valueStart := skipSpace(s.body, i+1)
		dropped := drop[key]
		var valueEnd int
		if dropped {
			valueEnd, ok = skipValue(s.body, valueStart)
		} else {
			valueEnd, ok = descend(key, valueStart)
		}
		if !ok {
			return 0, false
		}
		j := skipSpace(s.body, valueEnd)
		if j >= len(s.body) {
			return 0, false
		}
		var nextStart int
		switch s.body[j] {
		case ',':
			nextStart = skipSpace(s.body, j+1)
		case '}':
			nextStart = j
		default:
			return 0, false
		}
		if dropped {
			if keptBefore {
				s.cuts = append(s.cuts, cutSpan{prevValueEnd, valueEnd})
			} else {
				s.cuts = append(s.cuts, cutSpan{keyStart, nextStart})
			}
		} else {
			keptBefore = true
		}
		prevValueEnd = valueEnd
		i = nextStart
	}
	if i >= len(s.body) || s.body[i] != '}' {
		return 0, false
	}
	return i + 1, true
}

// apply copies everything outside the recorded ranges. A range that is out of
// order or out of bounds returns nil so the caller passes the original through.
func (s *annotationStripper) apply() []byte {
	out := make([]byte, 0, len(s.body))
	last := 0
	for _, cut := range s.cuts {
		if cut.start < last || cut.end > len(s.body) || cut.start > cut.end {
			return nil
		}
		out = append(out, s.body[last:cut.start]...)
		last = cut.end
	}
	return append(out, s.body[last:]...)
}

// skipValue returns the offset just past the JSON value at i without inspecting
// it. The input is pre-validated, so container nesting is tracked by depth and
// strings are skipped whole (a brace inside a string never moves the depth).
func skipValue(body []byte, i int) (int, bool) {
	if i >= len(body) {
		return 0, false
	}
	if body[i] == '"' {
		return stringEnd(body, i)
	}
	if body[i] == '{' || body[i] == '[' {
		depth := 0
		for j := i; j < len(body); j++ {
			switch body[j] {
			case '"':
				end, ok := stringEnd(body, j)
				if !ok {
					return 0, false
				}
				j = end - 1
			case '{', '[':
				depth++
			case '}', ']':
				depth--
				if depth == 0 {
					return j + 1, true
				}
			}
		}
		return 0, false
	}
	j := i
	for j < len(body) && !isJSONDelimiter(body[j]) {
		j++
	}
	return j, j > i
}

func stringEnd(body []byte, start int) (int, bool) {
	if start >= len(body) || body[start] != '"' {
		return 0, false
	}
	for i := start + 1; i < len(body); i++ {
		switch body[i] {
		case '\\':
			i++
		case '"':
			return i + 1, true
		}
	}
	return 0, false
}

func skipSpace(body []byte, i int) int {
	for i < len(body) && isJSONSpace(body[i]) {
		i++
	}
	return i
}

func isJSONSpace(c byte) bool {
	return c == ' ' || c == '\n' || c == '\r' || c == '\t'
}

func isJSONDelimiter(c byte) bool {
	return c == ',' || c == '}' || c == ']' || isJSONSpace(c)
}

// toolSchemaAnnotationsCompressor is the forced-only wrapper around
// StripToolSchemaAnnotations, reached only by forcing the
// "toolschema-annotations" content type; Detect never routes to it, and it is
// deliberately absent from the transform-capability manifest (see
// manifestExcluded) because it is not a compiled-plan transform.
//
// Safety class S4. The strip is semantics-preserving — it removes only annotation
// keywords that constrain nothing and name nothing — but it does change
// model-visible bytes, so it is not byte-safe and must never run on a byte-safe
// path. S4 is the honest class: it is the class defined as altering model-visible
// bytes, and its safety.Info.RequiresCCR forces the original into the recovery
// store before the transform may ship. That recovery requirement is exactly the
// local-wrap promotion clause (local wrap: recovery + CCR), the
// only clause under which this lever may ever default on. Unlike TOON it is not
// lossless-to-model: the dropped annotations are recoverable from CCR, never from
// the emitted bytes.
type toolSchemaAnnotationsCompressor struct{}

// NewToolSchemaAnnotations returns the tool-schema annotation strip.
func NewToolSchemaAnnotations() Compressor { return &toolSchemaAnnotationsCompressor{} }

func (c *toolSchemaAnnotationsCompressor) ContentType() string {
	return toolSchemaAnnotationsType
}

func (c *toolSchemaAnnotationsCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *toolSchemaAnnotationsCompressor) Compress(input []byte) ([]byte, bool) {
	return StripToolSchemaAnnotations(input)
}

package compressors_test

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
	"github.com/JuliusBrussee/caveman/engine/safety"
)

func TestStripToolSchemaAnnotations(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
		ok   bool
	}{
		{
			name: "drops the four annotation keywords inside a schema",
			in:   `[{"name":"Read","input_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Read args","deprecated":false,"examples":[{"path":"a.go"}],"type":"object"}}]`,
			want: `[{"name":"Read","input_schema":{"type":"object"}}]`,
			ok:   true,
		},
		{
			name: "keeps description untouched",
			in:   `[{"name":"Read","description":"Read a file. Returns its contents.","input_schema":{"description":"args","title":"x"}}]`,
			want: `[{"name":"Read","description":"Read a file. Returns its contents.","input_schema":{"description":"args"}}]`,
			ok:   true,
		},
		{
			name: "envelope fields are never edited",
			in:   `[{"name":"Read","title":"Read a file","deprecated":true,"examples":["read a.go"],"input_schema":{"title":"drop"}}]`,
			want: `[{"name":"Read","title":"Read a file","deprecated":true,"examples":["read a.go"],"input_schema":{}}]`,
			ok:   true,
		},
		{
			name: "MCP annotations.title is a tool name, not metadata",
			in:   `[{"name":"Read","annotations":{"title":"Read a file","readOnlyHint":true},"inputSchema":{"title":"drop","type":"object"}}]`,
			want: `[{"name":"Read","annotations":{"title":"Read a file","readOnlyHint":true},"inputSchema":{"type":"object"}}]`,
			ok:   true,
		},
		{
			name: "object-valued vendor extension on the envelope is untouched",
			in:   `[{"name":"Read","x-vendor":{"title":"vendor label","examples":[1],"nested":{"deprecated":true}},"_meta":{"title":"meta"},"input_schema":{"title":"drop"}}]`,
			want: `[{"name":"Read","x-vendor":{"title":"vendor label","examples":[1],"nested":{"deprecated":true}},"_meta":{"title":"meta"},"input_schema":{}}]`,
			ok:   true,
		},
		{
			name: "object-valued unknown keyword INSIDE a schema is untouched",
			in:   `[{"name":"Read","input_schema":{"type":"object","x-ui":{"title":"Widget","examples":[1]},"$comment":"kept","title":"drop"}}]`,
			want: `[{"name":"Read","input_schema":{"type":"object","x-ui":{"title":"Widget","examples":[1]},"$comment":"kept"}}]`,
			ok:   true,
		},
		{
			name: "openai function envelope is entered, its siblings are not",
			in:   `[{"type":"function","title":"envelope","function":{"name":"read","description":"d","strict":true,"parameters":{"title":"drop","type":"object"}}}]`,
			want: `[{"type":"function","title":"envelope","function":{"name":"read","description":"d","strict":true,"parameters":{"type":"object"}}}]`,
			ok:   true,
		},
		{
			name: "property named title survives",
			in:   `[{"name":"Write","input_schema":{"type":"object","title":"Write args","properties":{"title":{"type":"string","title":"The title"},"examples":{"type":"array","examples":[1]}},"required":["title"]}}]`,
			want: `[{"name":"Write","input_schema":{"type":"object","properties":{"title":{"type":"string"},"examples":{"type":"array"}},"required":["title"]}}]`,
			ok:   true,
		},
		{
			name: "definition named title survives with its $ref",
			in:   `[{"name":"T","input_schema":{"$defs":{"title":{"type":"string","title":"x"}},"properties":{"a":{"$ref":"#/$defs/title"}}}}]`,
			want: `[{"name":"T","input_schema":{"$defs":{"title":{"type":"string"}},"properties":{"a":{"$ref":"#/$defs/title"}}}}]`,
			ok:   true,
		},
		{
			name: "enum, const and default instance data are never walked",
			in:   `[{"name":"T","input_schema":{"properties":{"mode":{"enum":[{"title":"keep"},"deprecated"],"title":"Mode"},"a":{"const":{"title":"c"}},"b":{"default":{"examples":[1]}}}}}]`,
			want: `[{"name":"T","input_schema":{"properties":{"mode":{"enum":[{"title":"keep"},"deprecated"]},"a":{"const":{"title":"c"}},"b":{"default":{"examples":[1]}}}}}]`,
			ok:   true,
		},
		{
			name: "applicator keywords are descended",
			in:   `[{"name":"T","input_schema":{"anyOf":[{"title":"a","type":"string"},{"title":"b"}],"items":{"title":"i","type":"number"},"not":{"examples":[1]}}}]`,
			want: `[{"name":"T","input_schema":{"anyOf":[{"type":"string"},{}],"items":{"type":"number"},"not":{}}}]`,
			ok:   true,
		},
		{
			name: "cache_control on the last tool is preserved byte-for-byte",
			in:   `[{"name":"A","input_schema":{"title":"a"}},{"name":"B","input_schema":{"title":"b"},"cache_control":{"type":"ephemeral"}}]`,
			want: `[{"name":"A","input_schema":{}},{"name":"B","input_schema":{},"cache_control":{"type":"ephemeral"}}]`,
			ok:   true,
		},
		{
			name: "first member dropped",
			in:   `[{"name":"A","input_schema":{"title":"a","type":"object"}}]`,
			want: `[{"name":"A","input_schema":{"type":"object"}}]`,
			ok:   true,
		},
		{
			name: "every member dropped leaves an empty object",
			in:   `[{"name":"A","input_schema":{"title":"a","examples":[1]}}]`,
			want: `[{"name":"A","input_schema":{}}]`,
			ok:   true,
		},
		{
			// A catalog may spell "title" with a Unicode escape; a raw byte search
			// would miss it and leave the annotation on the wire.
			name: "escaped key spelling is still recognized",
			in:   "[{\"name\":\"A\",\"input_schema\":{\"\\u0074itle\":\"a\",\"type\":\"object\"}}]",
			want: `[{"name":"A","input_schema":{"type":"object"}}]`,
			ok:   true,
		},
		{
			name: "nothing to strip returns the input unchanged",
			in:   `[{"name":"A","description":"d","input_schema":{"type":"object"}}]`,
			want: `[{"name":"A","description":"d","input_schema":{"type":"object"}}]`,
			ok:   true,
		},
		{
			name: "malformed JSON passes through",
			in:   `[{"name":"A",`,
			want: `[{"name":"A",`,
			ok:   false,
		},
		{
			name: "trailing garbage passes through",
			in:   `[{"name":"A"}] {`,
			want: `[{"name":"A"}] {`,
			ok:   false,
		},
		{
			name: "empty input passes through",
			in:   ``,
			want: ``,
			ok:   false,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			out, ok := compressors.StripToolSchemaAnnotations([]byte(tc.in))
			if ok != tc.ok {
				t.Fatalf("ok = %v, want %v", ok, tc.ok)
			}
			if string(out) != tc.want {
				t.Fatalf("out = %s\nwant = %s", out, tc.want)
			}
			if !tc.ok {
				return
			}
			if !json.Valid(out) {
				t.Fatalf("output is not valid JSON: %s", out)
			}
			again, ok := compressors.StripToolSchemaAnnotations(out)
			if !ok || !bytes.Equal(again, out) {
				t.Fatalf("not idempotent: ok=%v second=%s first=%s", ok, again, out)
			}
		})
	}
}

// TestStripToolSchemaAnnotationsPreservesOrderAndSpacing pins the minimal-splice
// property: only the dropped members move, and every other byte — element order,
// indentation, number spelling, string escapes — is copied through untouched.
func TestStripToolSchemaAnnotationsPreservesOrderAndSpacing(t *testing.T) {
	in := "[\n  { \"name\" : \"First\" ,\n    \"input_schema\" : { \"type\" : \"object\" ,\n      \"title\" : \"drop me\" ,\n      \"maxItems\" : 1.50 } } ,\n" +
		"  { \"name\" : \"Second\" , \"description\" : \"tab\\there\" }\n]"
	want := "[\n  { \"name\" : \"First\" ,\n    \"input_schema\" : { \"type\" : \"object\" ,\n      \"maxItems\" : 1.50 } } ,\n" +
		"  { \"name\" : \"Second\" , \"description\" : \"tab\\there\" }\n]"
	out, ok := compressors.StripToolSchemaAnnotations([]byte(in))
	if !ok {
		t.Fatal("strip declined a well-formed catalog")
	}
	if string(out) != want {
		t.Fatalf("out = %q\nwant = %q", out, want)
	}
	var tools []map[string]any
	if err := json.Unmarshal(out, &tools); err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, tool := range tools {
		names = append(names, tool["name"].(string))
	}
	if strings.Join(names, ",") != "First,Second" {
		t.Fatalf("tool order changed: %v", names)
	}
}

// TestStripToolSchemaAnnotationsIsDeterministic pins the cache-stability property
// the proxy relies on: the same catalog bytes always produce the same output
// bytes, so a stripped prefix stays byte-identical on every later turn.
func TestStripToolSchemaAnnotationsIsDeterministic(t *testing.T) {
	in := []byte(`[{"name":"A","input_schema":{"title":"a","properties":{"p":{"title":"t","type":"string"}}}},{"name":"B","input_schema":{"examples":[1,2]},"cache_control":{"type":"ephemeral"}}]`)
	first, ok := compressors.StripToolSchemaAnnotations(in)
	if !ok {
		t.Fatal("strip declined a well-formed catalog")
	}
	for i := 0; i < 8; i++ {
		next, ok := compressors.StripToolSchemaAnnotations(in)
		if !ok || !bytes.Equal(next, first) {
			t.Fatalf("run %d diverged: ok=%v out=%s", i, ok, next)
		}
	}
}

func TestToolSchemaAnnotationsCompressorIsForcedOnlyAndS4(t *testing.T) {
	c, ok := compressors.Default().For("toolschema-annotations")
	if !ok {
		t.Fatal("toolschema-annotations is not registered")
	}
	if c.ContentType() != "toolschema-annotations" {
		t.Fatalf("content type = %q", c.ContentType())
	}
	if c.SafetyClass() != safety.S4 {
		t.Fatalf("safety class = %v, want S4", c.SafetyClass())
	}
	info, found := safety.Lookup(c.SafetyClass())
	if !found || info.ByteSafe || !info.RequiresCCR {
		t.Fatalf("class contract broken: %+v found=%v", info, found)
	}
	out, ok := c.Compress([]byte(`[{"name":"A","input_schema":{"title":"a","type":"object"}}]`))
	if !ok || string(out) != `[{"name":"A","input_schema":{"type":"object"}}]` {
		t.Fatalf("Compress = %s ok=%v", out, ok)
	}
	if _, bad := c.Compress([]byte(`{`)); bad {
		t.Fatal("malformed input must report !ok")
	}
}

package compressors

import (
	"bytes"
	"encoding/json"
	"net/url"
	"os"
	"strconv"
	"strings"
	"testing"
	"unicode/utf8"
)

// a verbose MCP-style tool catalog with long descriptions, annotation metadata,
// an enum, a required list, and — critically — a parameter literally named
// "description" that must survive (it is a property name, not metadata).
const sampleCatalog = `{
  "tools": [
    {
      "name": "search_files",
      "description": "Search the workspace for files. This tool walks the entire tree, honours .gitignore, and returns ranked matches with surrounding context lines so the agent can decide which file to open next.",
      "inputSchema": {
        "type": "object",
        "title": "SearchFilesArgs",
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "properties": {
          "query": {
            "type": "string",
            "description": "The search query string to match against file contents using ranked relevance.",
            "examples": ["needle", "func main"]
          },
          "mode": {
            "type": "string",
            "enum": ["regex", "literal", "glob"],
            "default": "literal",
            "description": "How to interpret the query."
          },
          "description": {
            "type": "string",
            "description": "A free-text note the caller may attach to the search for logging."
          }
        },
        "required": ["query"]
      }
    }
  ]
}`

func TestToolSchemaPreservesSelectionTokens(t *testing.T) {
	c := NewToolSchema()
	out, ok := c.Compress([]byte(sampleCatalog))
	if !ok {
		t.Fatal("expected ok=true on a valid catalog")
	}
	if !json.Valid(out) {
		t.Fatal("output is not valid JSON")
	}
	if len(out) >= len(sampleCatalog) {
		t.Fatalf("expected smaller output, got %d >= %d", len(out), len(sampleCatalog))
	}

	// Selectability invariant: names, enum values, and required must survive.
	for _, must := range []string{
		`"search_files"`,                 // tool name
		`"query"`,                        // parameter name
		`"mode"`,                         // parameter name
		`"regex"`, `"literal"`, `"glob"`, // enum values
		`"required"`,
	} {
		if !bytes.Contains(out, []byte(must)) {
			t.Errorf("selection token %s was dropped", must)
		}
	}

	// Annotation metadata must be dropped.
	for _, gone := range []string{`"examples"`, `"title"`, `"$schema"`, `"func main"`, `"SearchFilesArgs"`} {
		if bytes.Contains(out, []byte(gone)) {
			t.Errorf("metadata %s should have been dropped", gone)
		}
	}

	// Tool description reduction remains intentional; envelope metadata follows
	// a separate path so schema-only keys such as title are not dropped from it.
	if bytes.Contains(out, []byte("honours .gitignore")) {
		t.Error("long tool description tail should have been truncated")
	}
}

func TestToolSchemaPreservesEnvelopeAndMCPAnnotationTitle(t *testing.T) {
	input := []byte(`{"tools":[{"name":"Read","description":"Read one file with all provider-visible selection detail intact.","annotations":{"title":"Read a file","readOnlyHint":true},"_meta":{"title":"vendor title","examples":[1]},"inputSchema":{"title":"ReadArgs","type":"object","properties":{"path":{"type":"string","title":"Path","description":"Target path."}}}}],"title":"catalog title"}`)
	out, ok := NewToolSchema().Compress(input)
	if !ok {
		t.Fatal("expected ok=true")
	}
	var got map[string]any
	if err := json.Unmarshal(out, &got); err != nil {
		t.Fatal(err)
	}
	if got["title"] != "catalog title" {
		t.Fatalf("catalog envelope title changed: %s", out)
	}
	tools := got["tools"].([]any)
	tool := tools[0].(map[string]any)
	annotations := tool["annotations"].(map[string]any)
	if annotations["title"] != "Read a file" || annotations["readOnlyHint"] != true {
		t.Fatalf("MCP annotations changed: %s", out)
	}
	if tool["description"] != "Read one file with all provider-visible selection detail intact." {
		t.Fatalf("tool description changed: %s", out)
	}
	meta := tool["_meta"].(map[string]any)
	if meta["title"] != "vendor title" {
		t.Fatalf("vendor metadata changed: %s", out)
	}
	schema := tool["inputSchema"].(map[string]any)
	if _, present := schema["title"]; present {
		t.Fatalf("schema title was not removed: %s", out)
	}
	path := schema["properties"].(map[string]any)["path"].(map[string]any)
	if _, present := path["title"]; present {
		t.Fatalf("nested schema title was not removed: %s", out)
	}
}

func TestToolSchemaPropertyNamedDescriptionSurvives(t *testing.T) {
	c := NewToolSchema()
	out, ok := c.Compress([]byte(sampleCatalog))
	if !ok {
		t.Fatal("expected ok=true")
	}
	// The parameter literally named "description" lives inside properties; its
	// key must survive even though "description" is also a metadata key name.
	var parsed struct {
		Tools []struct {
			InputSchema struct {
				Properties map[string]any `json:"properties"`
			} `json:"inputSchema"`
		} `json:"tools"`
	}
	if err := json.Unmarshal(out, &parsed); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	props := parsed.Tools[0].InputSchema.Properties
	if _, present := props["description"]; !present {
		t.Fatal("the user-defined 'description' parameter was wrongly dropped as metadata")
	}
	if _, present := props["query"]; !present {
		t.Fatal("the 'query' parameter was dropped")
	}
}

func TestToolSchemaDependencyPropertyNamesSurvive(t *testing.T) {
	input := []byte(`{"type":"object","dependentSchemas":{"title":{"properties":{"example":{"type":"string"}}},"$comment":{"required":["title"]}},"dependentRequired":{"example":["title"],"$comment":["example"]},"dependencies":{"title":{"properties":{"$comment":{"type":"boolean"}}},"example":["title"]}}`)
	out, ok := NewToolSchema().Compress(input)
