// TestToolSchemaRefIntegrity guards reference integrity: a $defs / definitions entry whose
// name collides with a schema-metadata key must not be dropped, or every $ref that
// targets it dangles. It also asserts the general property that every $ref in the
// compressed output still resolves to an existing definition.
func TestToolSchemaRefIntegrity(t *testing.T) {
	c := NewToolSchema()
	input := []byte(`{"name":"t","inputSchema":{"type":"object","properties":{"x":{"$ref":"#/$defs/title"},"slash":{"$ref":"#/$defs/a~1b"},"tilde":{"$ref":"#/$defs/til~0de"}},"$defs":{"title":{"type":"string","enum":["a","b"]},"a/b":{"type":"number"},"til~de":{"type":"boolean"},"Widget":{"type":"object"}}}}`)
	out, ok := c.Compress(input)
	if !ok {
		t.Fatal("expected ok=true")
	}
	// The metadata-named definition and its selection surface must survive.
	if !bytes.Contains(out, []byte(`"title":{`)) {
		t.Fatalf("$defs.title (a metadata-named definition) was dropped; output=%s", out)
	}
	if !bytes.Contains(out, []byte(`"a","b"`)) {
		t.Fatalf("the enum on $defs.title was dropped with it; output=%s", out)
	}
	assertRefsResolve(t, out)
}

// assertRefsResolve walks parsed JSON and asserts every internal JSON-Pointer
// $ref resolves from its own schema-resource root. This is the $ref-integrity
// conformance guard the structural selection profile cannot provide (SelectionProfile
// never follows $ref), so the drop-a-definition class cannot pass silently again.
func assertRefsResolve(t *testing.T, out []byte) {
	t.Helper()
	var root any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatalf("unmarshal output: %v", err)
	}
	if unresolved := unresolvedInternalRefs(root); len(unresolved) > 0 {
		t.Fatalf("dangling internal $refs after compression: %v", unresolved)
	}
}

var embeddedToolSchemaKeys = map[string]bool{
	"inputSchema":  true,
	"input_schema": true,
	"parameters":   true,
}

// unresolvedInternalRefs resolves each local JSON Pointer from the schema
// resource that contains it: an embedded tool schema or the nearest subschema
// carrying its own $id. It deliberately does not search sibling schemas; the
// same $defs path in another tool cannot repair a dangling ref here.
func unresolvedInternalRefs(document any) []string {
	var unresolved []string
	var walk func(node, resourceRoot any, keysAreUserDefined bool)
	walk = func(node, resourceRoot any, keysAreUserDefined bool) {
		switch n := node.(type) {
		case map[string]any:
			currentRoot := resourceRoot
			if !keysAreUserDefined {
				if id, ok := n["$id"].(string); ok && id != "" {
					currentRoot = n
				}
				if ref, ok := n["$ref"].(string); ok && (ref == "#" || strings.HasPrefix(ref, "#/")) {
					if !jsonPointerResolves(currentRoot, ref) {
						unresolved = append(unresolved, ref)
					}
				}
			}
			for key, value := range n {
				if key == "$ref" && !keysAreUserDefined {
					continue
				}
				if keysAreUserDefined {
					walk(value, currentRoot, false)
					continue
				}
				if embeddedToolSchemaKeys[key] {
					if _, ok := value.(map[string]any); ok {
						walk(value, value, false)
						continue
					}
				}
				walk(value, currentRoot, userDefinedKeys[key])
			}
		case []any:
			for _, value := range n {
				walk(value, resourceRoot, false)
			}
		}
	}
	walk(document, document, false)
	return unresolved
}

func jsonPointerResolves(root any, ref string) bool {
	if ref == "#" {
		return true
	}
	pointer, err := url.PathUnescape(strings.TrimPrefix(ref, "#"))
	if err != nil || !strings.HasPrefix(pointer, "/") {
		return false
	}
	segments := strings.Split(strings.TrimPrefix(pointer, "/"), "/")
	current := root
	for _, encoded := range segments {
		segment, ok := decodeJSONPointerToken(encoded)
		if !ok {
			return false
		}
		switch node := current.(type) {
		case map[string]any:
			var exists bool
			current, exists = node[segment]
			if !exists {
				return false
			}
		case []any:
			if segment == "" || (len(segment) > 1 && segment[0] == '0') {
				return false
			}
			index, err := strconv.Atoi(segment)
			if err != nil || index < 0 || strconv.Itoa(index) != segment || index >= len(node) {
				return false
			}
			current = node[index]
		default:
			return false
		}
	}
	return true
}

func decodeJSONPointerToken(encoded string) (string, bool) {
	var decoded strings.Builder
	for index := 0; index < len(encoded); index++ {
		if encoded[index] != '~' {
			decoded.WriteByte(encoded[index])
			continue
		}
		if index+1 >= len(encoded) {
			return "", false
		}
		index++
		switch encoded[index] {
		case '0':
			decoded.WriteByte('~')
		case '1':
			decoded.WriteByte('/')
		default:
			return "", false
		}
	}
	return decoded.String(), true
}

// TestRefIntegrityGuardDetectsDrop checks that the $ref-integrity assertion catches:
// it must report a dropped definition as unresolvable and a present one as
// resolvable. Without this, TestToolSchemaRefIntegrity could pass vacuously.
func TestRefIntegrityGuardDetectsDrop(t *testing.T) {
	var root any
	if err := json.Unmarshal([]byte(`{"properties":{"x":{"$ref":"#/$defs/gone"}},"$defs":{"kept":{"type":"string"}}}`), &root); err != nil {
		t.Fatal(err)
	}
	if unresolved := unresolvedInternalRefs(root); len(unresolved) != 1 || unresolved[0] != "#/$defs/gone" {
		t.Fatalf("guard did not report dropped definition: %v", unresolved)
	}
	root = nil
	if err := json.Unmarshal([]byte(`{"properties":{"x":{"$ref":"#/$defs/kept"}},"$defs":{"kept":{"type":"string"}}}`), &root); err != nil {
		t.Fatal(err)
	}
	if unresolved := unresolvedInternalRefs(root); len(unresolved) != 0 {
		t.Fatalf("guard failed to resolve present definition: %v", unresolved)
	}
}

func TestRefIntegrityGuardDoesNotCrossToolSchemaRoots(t *testing.T) {
	var catalog any
	if err := json.Unmarshal([]byte(`{"tools":[{"name":"broken","inputSchema":{"properties":{"x":{"$ref":"#/$defs/shared"}},"$defs":{}}},{"name":"other","inputSchema":{"$defs":{"shared":{"type":"string"}}}}]}`), &catalog); err != nil {
		t.Fatal(err)
	}
	if unresolved := unresolvedInternalRefs(catalog); len(unresolved) != 1 || unresolved[0] != "#/$defs/shared" {
		t.Fatalf("sibling tool schema incorrectly satisfied dangling ref: %v", unresolved)
	}
}

func TestRefIntegrityGuardUsesNearestIDResourceRoot(t *testing.T) {
	var schema any
	if err := json.Unmarshal([]byte(`{"$defs":{"shared":{"type":"string"}},"properties":{"nested":{"$id":"nested.json","properties":{"x":{"$ref":"#/$defs/shared"}},"$defs":{}}}}`), &schema); err != nil {
		t.Fatal(err)
	}
	if unresolved := unresolvedInternalRefs(schema); len(unresolved) != 1 || unresolved[0] != "#/$defs/shared" {
		t.Fatalf("parent resource incorrectly satisfied nested $id ref: %v", unresolved)
	}
}

func TestRefIntegrityGuardRejectsNonCanonicalArrayIndex(t *testing.T) {
	var schema any
	if err := json.Unmarshal([]byte(`{"properties":{"x":{"$ref":"#/items/+0"}},"items":[{"type":"string"}]}`), &schema); err != nil {
		t.Fatal(err)
	}
	if unresolved := unresolvedInternalRefs(schema); len(unresolved) != 1 || unresolved[0] != "#/items/+0" {
		t.Fatalf("non-canonical array index incorrectly resolved: %v", unresolved)
	}
}

// TestToolSchemaPreservesArgumentConstraints is the call-VALIDITY conformance
// gate. A compressed catalog must not turn valid tool calls into invalid ones:
// every description sentence that states an argument constraint (RFC3339 format,
// mutual-exclusion "exactly one", absolute-path, required) survives, while pure
// filler prose is dropped. It pins the exact output against a golden file and
// separately asserts each individual constraint token, so a regression in either
// the split logic or the marker set fails loudly.
func TestToolSchemaPreservesArgumentConstraints(t *testing.T) {
	in, err := os.ReadFile("testdata/toolschema_constraints_catalog.json")
	if err != nil {
		t.Fatal(err)
	}
	c := NewToolSchema()
	out, ok := c.Compress(in)
	if !ok {
		t.Fatal("expected ok=true on the constraints fixture")
	}
	if !utf8.Valid(out) {
		t.Fatal("compressor emitted invalid UTF-8")
	}

	// Golden regression: exact output (pretty-printed for a readable diff).
	var pretty bytes.Buffer
	if err := json.Indent(&pretty, out, "", "  "); err != nil {
		t.Fatal(err)
	}
	pretty.WriteByte('\n')
	golden, err := os.ReadFile("testdata/toolschema_constraints_catalog.golden.json")
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(pretty.Bytes(), golden) {
		t.Fatalf("output drifted from golden.\n--- got ---\n%s\n--- want ---\n%s", pretty.String(), golden)
	}

	// Every constraint token must be present in the compressed catalog. These are
	// exactly the markers an agent needs to build a valid call; losing any one of
	// them yields an invalid argument and a retry loop that costs more than the
	// shrink saved.
	mustSurvive := []string{
		"must be an absolute path",         // absolute-path rule (large desc, elided)
		"exactly one of body",              // mutual exclusion (large desc, elided)
		"is required",                      // required-field rule
		"Rejected if body",                 // rejection rule
		"must be absolute",                 // second absolute rule
		"format must be RFC3339",           // RFC3339 timestamp constraint
		"are rejected",                     // timezone rejection
		"ISO 8601 duration",                // ISO 8601 constraint
		"Must match the P#DT",              // grammar constraint
		"must not be dropped",              // metadata-named $defs entry overlap
		`"default":"overwrite"`,            // default value kept, not dropped
		"Anything over 100 errors",         // marker-less bound in a SMALL desc (kept whole)
		"Values above 100 are not allowed", // bound constraint retained through ELISION
		"negative numbers are invalid",     // second bound retained through elision
	}
	for _, m := range mustSurvive {
		if !bytes.Contains(out, []byte(m)) {
			t.Errorf("constraint token %q did not survive compression", m)
		}
	}

	// Pure filler prose (only ever dropped from genuinely large descriptions) must go.
	for _, gone := range []string{
		"carries no rule and should be dropped", // write_file top-desc filler
		"paginates for you automatically",       // count lead filler past the cap
	} {
		if bytes.Contains(out, []byte(gone)) {
			t.Errorf("filler %q should have been dropped", gone)
		}
	}

	// $ref integrity across the whole fixture (the ISO8601Duration $ref must resolve).
	assertRefsResolve(t, out)

	// Idempotent: compressing the output again is a no-op.
	twice, ok := c.Compress(out)
	if !ok || !bytes.Equal(out, twice) {
		t.Fatalf("not idempotent on the constraints fixture")
	}
}

package compressors

import "github.com/JuliusBrussee/caveman/engine/safety"

type toonCompressor struct {
	opt EncodeOptions
}

// NewTOON returns the lossless TOON re-encoder. It is reached only by forcing
// Options.Type = "toon"; Detect never routes to it.
func NewTOON() Compressor {
	return &toonCompressor{opt: EncodeOptions{Delimiter: ','}}
}

func (c *toonCompressor) ContentType() string       { return "toon" }
func (c *toonCompressor) SafetyClass() safety.Class { return safety.S4 }

func (c *toonCompressor) Compress(input []byte) ([]byte, bool) {
	v, ok := parseJSONTOON(input)
	if !ok {
		return nil, false
	}
	return encodeTOON(v, c.opt)
}

func (c *toonCompressor) CompressWithMetadata(input []byte, _ string) ([]byte, Metadata, bool) {
	out, ok := c.Compress(input)
	return out, Metadata{Method: "toon", LosslessToModel: metadataBool(true)}, ok
}

package compressors

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type toonLine struct {
	indent int
	text   string
}

var (
	toonTabularLineRe = regexp.MustCompile(`^([A-Za-z_][A-Za-z0-9_.-]*)?\[(\d+)\]\{([^}]*)\}:$`)
	toonArrayLineRe   = regexp.MustCompile(`^([A-Za-z_][A-Za-z0-9_.-]*)?\[(\d+)\]:(?: (.*))?$`)
	toonKeyLineRe     = regexp.MustCompile(`^([A-Za-z_][A-Za-z0-9_.-]*):(?: (.*))?$`)
)

// DecodeTOON parses the supported TOON subset back into the JSON data model.
func DecodeTOON(in []byte) (any, bool) {
	return decodeTOON(in)
}

// DecodeJSONForTOONGrader parses JSON with the same json.Number-preserving
// path used by the TOON compressor, then converts it to comparable JSON values.
func DecodeJSONForTOONGrader(in []byte) (any, bool) {
	return canonicalJSONValue(in)
}

func decodeTOON(in []byte) (any, bool) {
	lines, ok := scanTOONLines(string(in))
	if !ok || len(lines) == 0 {
		return nil, false
	}
	if lines[0].indent != 0 {
		return nil, false
	}
	v, next, ok := parseTOONRoot(lines, 0)
	if !ok || next != len(lines) {
		return nil, false
	}
	return v, true
}

func scanTOONLines(s string) ([]toonLine, bool) {
	s = strings.TrimRight(s, "\n")
	if strings.TrimSpace(s) == "" {
		return nil, false
	}
	raw := strings.Split(s, "\n")
	lines := make([]toonLine, 0, len(raw))
	for _, line := range raw {
		if strings.TrimSpace(line) == "" {
			return nil, false
		}
		spaces := len(line) - len(strings.TrimLeft(line, " "))
		if spaces%2 != 0 {
			return nil, false
		}
		lines = append(lines, toonLine{indent: spaces / 2, text: line[spaces:]})
	}
	return lines, true
}

func parseTOONRoot(lines []toonLine, i int) (any, int, bool) {
	text := lines[i].text
	if text == "{}" {
		return map[string]any{}, i + 1, true
	}
	if text == "[]" {
		return []any{}, i + 1, true
	}
	if strings.HasPrefix(text, `"`) {
		v, ok := parseTOONScalar(text)
		return v, i + 1, ok
	}
	if strings.HasPrefix(text, "[") {
		return parseTOONArray(lines, i, 0)
	}
	if !strings.Contains(text, ":") {
		v, ok := parseTOONScalar(text)
		return v, i + 1, ok
	}
	return parseTOONObject(lines, i, 0)
}

func parseTOONObject(lines []toonLine, i, indent int) (map[string]any, int, bool) {
	out := map[string]any{}
	for i < len(lines) {
		if lines[i].indent < indent {
			break
		}
		if lines[i].indent > indent {
			return nil, i, false
		}
		text := lines[i].text
		if m := toonTabularLineRe.FindStringSubmatch(text); m != nil && m[1] != "" {
			if _, exists := out[m[1]]; exists {
				return nil, i, false
			}
			v, next, ok := parseTOONArray(lines, i, indent)
			if !ok {
				return nil, i, false
			}
			out[m[1]] = v
			i = next
			continue
		}
		if m := toonArrayLineRe.FindStringSubmatch(text); m != nil && m[1] != "" {
			if _, exists := out[m[1]]; exists {
				return nil, i, false
			}
			v, next, ok := parseTOONArray(lines, i, indent)
			if !ok {
				return nil, i, false
			}
			out[m[1]] = v
			i = next
			continue
		}
		m := toonKeyLineRe.FindStringSubmatch(text)
		if m == nil || m[1] == "" {
			return nil, i, false
		}
		key := m[1]
		rest := m[2]
		if _, exists := out[key]; exists {
			return nil, i, false
		}
		if rest == "{}" {
			out[key] = map[string]any{}
			i++
			continue
		}
		if rest == "" {
			if i+1 >= len(lines) || lines[i+1].indent != indent+1 {
				return nil, i, false
			}
			child, next, ok := parseTOONObject(lines, i+1, indent+1)
			if !ok {
				return nil, i, false
			}
			out[key] = child
			i = next
			continue
		}
		val, ok := parseTOONScalar(rest)
		if !ok {
			return nil, i, false
		}
		out[key] = val
		i++
	}
	return out, i, true
}

func parseTOONArray(lines []toonLine, i, indent int) ([]any, int, bool) {
	text := lines[i].text
	if m := toonTabularLineRe.FindStringSubmatch(text); m != nil {
		n, err := strconv.Atoi(m[2])
		if err != nil {
			return nil, i, false
		}
		fields := splitFields(m[3])
		if len(fields) == 0 {
			return nil, i, false
		}
		// Exactly n physical rows must follow. Refuse impossible claims before
		// allocating capacity, so a tiny untrusted input cannot request gigabytes.
		if n > len(lines)-i-1 {
			return nil, i, false
		}
		out := make([]any, 0, n)
		i++
		for row := 0; row < n; row++ {
			if i >= len(lines) || lines[i].indent != indent+1 {
				return nil, i, false
			}
			cells, ok := splitTOONCells(lines[i].text, ',')
			if !ok || len(cells) != len(fields) {
				return nil, i, false
			}
			obj := make(map[string]any, len(fields))
			for c, field := range fields {
				val, ok := parseTOONScalar(cells[c])
				if !ok {
					return nil, i, false
				}
				obj[field] = val
			}
			out = append(out, obj)
			i++
		}
		return out, i, true
	}
	m := toonArrayLineRe.FindStringSubmatch(text)
	if m == nil {
		return nil, i, false
	}
	n, err := strconv.Atoi(m[2])
	if err != nil {
		return nil, i, false
	}
	rest := m[3]
	if n == 0 {
		if rest != "[]" {
			return nil, i, false
		}
		return []any{}, i + 1, true
	}
	cells, ok := splitTOONCells(rest, ',')
	if !ok || len(cells) != n {
		return nil, i, false
	}
	out := make([]any, 0, n)
	for _, cell := range cells {
		val, ok := parseTOONScalar(cell)
		if !ok {
			return nil, i, false
		}
		out = append(out, val)
	}
	return out, i + 1, true
}

func splitFields(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	seen := make(map[string]struct{}, len(parts))
	for _, p := range parts {
		if !safeTOONKey(p) {
			return nil
		}
		if _, duplicate := seen[p]; duplicate {
			return nil
		}
		seen[p] = struct{}{}
	}
	return parts
}

func splitTOONCells(s string, delimiter byte) ([]string, bool) {
	var out []string
	var b strings.Builder
	inQuote := false
	escaped := false
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if escaped {
			b.WriteByte(ch)
			escaped = false
			continue
		}
		if inQuote && ch == '\\' {
			b.WriteByte(ch)
			escaped = true
			continue
		}
		if ch == '"' {
			b.WriteByte(ch)
			inQuote = !inQuote
			continue
		}
		if !inQuote && ch == delimiter {
			out = append(out, b.String())
			b.Reset()
			continue
		}
		b.WriteByte(ch)
	}
	if inQuote || escaped {
		return nil, false
	}
	out = append(out, b.String())
	return out, true
}

func parseTOONScalar(s string) (any, bool) {
	if s == "" {
		return nil, false
	}
	if strings.HasPrefix(s, `"`) {
		var out string
		if err := json.Unmarshal([]byte(s), &out); err != nil {
			return nil, false
		}
		return out, true
	}
	switch s {
	case "true":
		return true, true
	case "false":
		return false, true
	case "null":
		return nil, true
	}
	if validJSONNumber(s) {
		return json.Number(s), true
	}
	if strings.ContainsAny(s, "\n\r\t") {
		return nil, false
	}
	if strings.TrimSpace(s) != s {
		return nil, false
	}
	return s, true
}

func canonicalJSONValue(input []byte) (any, bool) {
	tv, ok := parseJSONTOON(input)
	if !ok {
		return nil, false
	}
	return toonValueToAny(tv), true
}

func toonValueToAny(v toonValue) any {
	switch v.kind {
	case toonNull:
		return nil
	case toonBool:
		return v.b
	case toonNumber:
		return json.Number(v.s)
	case toonString:
		return v.s
	case toonArray:
		out := make([]any, len(v.arr))
		for i, e := range v.arr {
			out[i] = toonValueToAny(e)
		}
		return out
	case toonObject:
		out := make(map[string]any, len(v.obj))
		for _, f := range v.obj {
			out[f.name] = toonValueToAny(f.value)
		}
		return out
	default:
		panic(fmt.Sprintf("unknown toon kind %d", v.kind))
	}
}

package compressors

// tabularEligibility reports what fraction of array elements sit inside
// uniform flat-object arrays, plus whether the top-level value is one.
func tabularEligibility(v any) (fraction float64, topLevelTabular bool) {
	tv, ok := asTOONValue(v)
	if !ok {
		return 0, false
	}
	eligible, total := countTabularEligibility(tv)
	_, _, topLevelTabular = tabularRows(tv.arr, ',')
	if total == 0 {
		return 0, topLevelTabular
	}
	return float64(eligible) / float64(total), topLevelTabular
}

func countTabularEligibility(v toonValue) (eligible, total int) {
	switch v.kind {
	case toonArray:
		total += len(v.arr)
		if _, _, ok := tabularRows(v.arr, ','); ok {
			eligible += len(v.arr)
		}
		for _, e := range v.arr {
			eEligible, eTotal := countTabularEligibility(e)
			eligible += eEligible
			total += eTotal
		}
	case toonObject:
		for _, f := range v.obj {
			fEligible, fTotal := countTabularEligibility(f.value)
			eligible += fEligible
			total += fTotal
		}
	}
	return eligible, total
}

package compressors

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

type toonKind int

const (
	toonNull toonKind = iota
	toonBool
	toonNumber
	toonString
	toonObject
	toonArray
)

type toonValue struct {
	kind   toonKind
	b      bool
	s      string
	obj    []toonField
	arr    []toonValue
	parsed bool
}

type toonField struct {
	name  string
	value toonValue
}

// EncodeOptions configures the focused TOON encoder.
type EncodeOptions struct {
	Delimiter byte
	FoldKeys  bool
}

var safeTOONKeyRe = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_.-]*$`)

// encodeTOON returns TOON bytes with ok=true only when v is in the supported,
// proven-round-trip subset. Unsupported shapes return ok=false so callers can
// pass the original bytes through unchanged.
func encodeTOON(v any, opt EncodeOptions) ([]byte, bool) {
	if opt.Delimiter == 0 {
		opt.Delimiter = ','
	}
	if opt.Delimiter != ',' && opt.Delimiter != '\t' {
		return nil, false
	}
	tv, ok := asTOONValue(v)
	if !ok {
		return nil, false
	}
	var b strings.Builder
	if !writeTOONValue(&b, tv, "", 0, opt) {
		return nil, false
	}
	return []byte(strings.TrimRight(b.String(), "\n")), true
}

func asTOONValue(v any) (toonValue, bool) {
	switch t := v.(type) {
	case toonValue:
		return t, true
	case nil:
		return toonValue{kind: toonNull}, true
	case bool:
		return toonValue{kind: toonBool, b: t}, true
	case json.Number:
		return toonValue{kind: toonNumber, s: t.String()}, true
	case string:
		return toonValue{kind: toonString, s: t}, true
	case []any:
		arr := make([]toonValue, 0, len(t))
		for _, e := range t {
			tv, ok := asTOONValue(e)
			if !ok {
				return toonValue{}, false
			}
			arr = append(arr, tv)
		}
		return toonValue{kind: toonArray, arr: arr}, true
	case map[string]any:
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		obj := make([]toonField, 0, len(keys))
		for _, k := range keys {
			tv, ok := asTOONValue(t[k])
			if !ok {
				return toonValue{}, false
			}
			obj = append(obj, toonField{name: k, value: tv})
		}
		return toonValue{kind: toonObject, obj: obj}, true
	default:
		return toonValue{}, false
	}
}

func parseJSONTOON(input []byte) (toonValue, bool) {
	dec := json.NewDecoder(bytes.NewReader(input))
	dec.UseNumber()
	v, err := readJSONTOONValue(dec)
	if err != nil {
		return toonValue{}, false
	}
	if tok, err := dec.Token(); err != io.EOF || tok != nil {
		return toonValue{}, false
	}
	return v, true
}

func readJSONTOONValue(dec *json.Decoder) (toonValue, error) {
	tok, err := dec.Token()
	if err != nil {
		return toonValue{}, err
	}
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			var fields []toonField
			seen := make(map[string]struct{})
			for dec.More() {
				keyTok, err := dec.Token()
				if err != nil {
					return toonValue{}, err
				}
				key, ok := keyTok.(string)
				if !ok {
					return toonValue{}, fmt.Errorf("object key is %T", keyTok)
				}
				if _, duplicate := seen[key]; duplicate {
					return toonValue{}, fmt.Errorf("duplicate object key %q", key)
				}
				seen[key] = struct{}{}
				val, err := readJSONTOONValue(dec)
				if err != nil {
					return toonValue{}, err
				}
				fields = append(fields, toonField{name: key, value: val})
			}
			end, err := dec.Token()
			if err != nil {
				return toonValue{}, err
			}
			if d, ok := end.(json.Delim); !ok || d != '}' {
				return toonValue{}, fmt.Errorf("object not closed")
			}
			return toonValue{kind: toonObject, obj: fields}, nil
		case '[':
			var arr []toonValue
			for dec.More() {
				val, err := readJSONTOONValue(dec)
				if err != nil {
					return toonValue{}, err
				}
				arr = append(arr, val)
			}
			end, err := dec.Token()
			if err != nil {
				return toonValue{}, err
			}
			if d, ok := end.(json.Delim); !ok || d != ']' {
				return toonValue{}, fmt.Errorf("array not closed")
			}
			return toonValue{kind: toonArray, arr: arr}, nil
		default:
			return toonValue{}, fmt.Errorf("unexpected delimiter %q", t)
		}
	case nil:
		return toonValue{kind: toonNull}, nil
	case bool:
		return toonValue{kind: toonBool, b: t}, nil
	case json.Number:
		return toonValue{kind: toonNumber, s: t.String()}, nil
	case string:
		return toonValue{kind: toonString, s: t}, nil
	default:
		return toonValue{}, fmt.Errorf("unsupported token %T", tok)
	}
}

func writeTOONValue(b *strings.Builder, v toonValue, name string, indent int, opt EncodeOptions) bool {
	switch v.kind {
	case toonObject:
		if name == "" {
			if len(v.obj) == 0 {
				b.WriteString("{}\n")
				return true
			}
			return writeTOONObject(b, v.obj, indent, opt)
		}
		if !safeTOONKey(name) {
			return false
		}
		if len(v.obj) == 0 {
			writeIndent(b, indent)
			fmt.Fprintf(b, "%s: {}\n", name)
			return true
		}
		writeIndent(b, indent)
		fmt.Fprintf(b, "%s:\n", name)
		return writeTOONObject(b, v.obj, indent+1, opt)
	case toonArray:
		return writeTOONArray(b, name, v.arr, indent, opt)
	default:
		encoded, ok := encodeTOONScalar(v, opt.Delimiter)
		if !ok {
			return false
		}
		writeIndent(b, indent)
		if name == "" {
			fmt.Fprintf(b, "%s\n", encoded)
		} else {
			if !safeTOONKey(name) {
				return false
			}
			fmt.Fprintf(b, "%s: %s\n", name, encoded)
		}
		return true
	}
}

func writeTOONObject(b *strings.Builder, fields []toonField, indent int, opt EncodeOptions) bool {
	ordered := append([]toonField(nil), fields...)
	sort.SliceStable(ordered, func(i, j int) bool {
		return ordered[i].name < ordered[j].name
	})
	for _, f := range ordered {
		if !safeTOONKey(f.name) {
			return false
		}
		if !writeTOONValue(b, f.value, f.name, indent, opt) {
			return false
		}
	}
	return true
}

func writeTOONArray(b *strings.Builder, name string, arr []toonValue, indent int, opt EncodeOptions) bool {
	if name != "" && !safeTOONKey(name) {
		return false
	}
	if len(arr) == 0 {
		writeIndent(b, indent)
		if name == "" {
			fmt.Fprintf(b, "[]\n")
		} else {
			fmt.Fprintf(b, "%s[0]: []\n", name)
		}
		return true
	}
	if scalarArray(arr) {
		cells := make([]string, 0, len(arr))
		for _, e := range arr {
			cell, ok := encodeTOONScalar(e, opt.Delimiter)
			if !ok {
				return false
			}
			cells = append(cells, cell)
		}
		writeIndent(b, indent)
		if name == "" {
			fmt.Fprintf(b, "[%d]: %s\n", len(arr), strings.Join(cells, string(opt.Delimiter)))
		} else {
			fmt.Fprintf(b, "%s[%d]: %s\n", name, len(arr), strings.Join(cells, string(opt.Delimiter)))
		}
		return true
	}
	fields, rows, ok := tabularRows(arr, opt.Delimiter)
	if !ok {
		return false
	}
	for _, f := range fields {
		if !safeTOONKey(f) {
			return false
		}
	}
	writeIndent(b, indent)
	if name == "" {
		fmt.Fprintf(b, "[%d]{%s}:\n", len(rows), strings.Join(fields, ","))
	} else {
		fmt.Fprintf(b, "%s[%d]{%s}:\n", name, len(rows), strings.Join(fields, ","))
	}
	for _, row := range rows {
		writeIndent(b, indent+1)
		fmt.Fprintf(b, "%s\n", strings.Join(row, string(opt.Delimiter)))
	}
	return true
}

func scalarArray(arr []toonValue) bool {
	for _, e := range arr {
		if !isScalar(e) {
			return false
		}
	}
	return true
}

func tabularRows(arr []toonValue, delimiter byte) ([]string, [][]string, bool) {
	if len(arr) == 0 || arr[0].kind != toonObject || len(arr[0].obj) == 0 {
		return nil, nil, false
	}
	fields := make([]string, 0, len(arr[0].obj))
	for _, f := range arr[0].obj {
		if !isScalar(f.value) {
			return nil, nil, false
		}
		fields = append(fields, f.name)
	}
	rows := make([][]string, 0, len(arr))
	for _, item := range arr {
		if item.kind != toonObject || len(item.obj) != len(fields) {
			return nil, nil, false
		}
		row := make([]string, 0, len(fields))
		for i, f := range item.obj {
			if f.name != fields[i] || !isScalar(f.value) {
				return nil, nil, false
			}
			cell, ok := encodeTOONScalar(f.value, delimiter)
			if !ok {
				return nil, nil, false
			}
			row = append(row, cell)
		}
		rows = append(rows, row)
	}
	return fields, rows, true
}

func isScalar(v toonValue) bool {
	return v.kind == toonNull || v.kind == toonBool || v.kind == toonNumber || v.kind == toonString
}

func encodeTOONScalar(v toonValue, delimiter byte) (string, bool) {
	switch v.kind {
	case toonNull:
		return "null", true
	case toonBool:
		if v.b {
			return "true", true
		}
		return "false", true
	case toonNumber:
		if !validJSONNumber(v.s) {
			return "", false
		}
		return v.s, true
	case toonString:
		if needsTOONQuote(v.s, delimiter) {
			out, err := json.Marshal(v.s)
			if err != nil {
				return "", false
			}
			return string(out), true
		}
		return v.s, true
	default:
		return "", false
	}
}

func needsTOONQuote(s string, delimiter byte) bool {
	if s == "" || strings.TrimSpace(s) != s {
		return true
	}
	if strings.ContainsAny(s, "\n\r\t\":") || strings.ContainsRune(s, rune(delimiter)) {
		return true
	}
	switch s[0] {
	case '[', '{', '"', '-':
		return true
	}
	if s[0] >= '0' && s[0] <= '9' {
		return true
	}
	switch s {
	case "true", "false", "null":
		return true
	}
	return validJSONNumber(s)
}

func validJSONNumber(s string) bool {
	var v any
	dec := json.NewDecoder(strings.NewReader(s))
	dec.UseNumber()
	if err := dec.Decode(&v); err != nil {
		return false
	}
	if _, ok := v.(json.Number); !ok {
		return false
	}
	return dec.Decode(&v) == io.EOF
}

func safeTOONKey(k string) bool {
	return safeTOONKeyRe.MatchString(k)
}

func writeIndent(b *strings.Builder, indent int) {
	for i := 0; i < indent; i++ {
		b.WriteString("  ")
	}
}

func normalizeDecodedJSON(v any) any {
	switch t := v.(type) {
	case map[string]any:
		out := make(map[string]any, len(t))
		for k, val := range t {
			out[k] = normalizeDecodedJSON(val)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normalizeDecodedJSON(val)
		}
		return out
	case float64:
		return json.Number(strconv.FormatFloat(t, 'g', -1, 64))
	default:
		return t
	}
}

