// Package engine is the Caveman Engine's core API. It detects what
// kind of content a payload is, routes it to a safety-classed compressor, counts the
// token reduction, and records the original for recovery — keeping what answers
// depend on and dropping the noise, before the bytes ever reach a model.
//
// The four-call surface (Compress, Retrieve, Detect, Stats) is the stable
// contract the proxy, SDKs, CLI, MCP server, and browser build all share.
// Simulate is an additional network-free dry run that reports what compression
// would do without changing stored state.
package engine

import (
	"bytes"
	"errors"
	"os"
	"strings"

	"github.com/JuliusBrussee/caveman/engine/ccr"
	"github.com/JuliusBrussee/caveman/engine/compressors"
	"github.com/JuliusBrussee/caveman/engine/safety"
	"github.com/JuliusBrussee/caveman/engine/tokens"
)

// Engine is the compression core. Construct it with New.
type Engine struct {
	registry *compressors.Registry
	counter  tokens.Counter
	store    *ccr.Store
}

// New builds an engine with the default compressor registry. store backs CCR
// recovery and stats and may be nil — without it the engine still detects and
// pass-through-compresses, but it will never run a lossy compressor, because a
// lossy result with no recovery would violate the reversibility contract.
// counter may be nil, in which case the default offline BPE counter is used.
func New(store *ccr.Store, counter tokens.Counter) *Engine {
	if counter == nil {
		counter = tokens.Default()
	}
	return &Engine{registry: defaultRegistry(counter), counter: counter, store: store}
}

// NewWithRegistry is New with a caller-supplied registry (for tests or embedders
// that register a custom compressor set).
func NewWithRegistry(store *ccr.Store, counter tokens.Counter, registry *compressors.Registry) *Engine {
	if counter == nil {
		counter = tokens.Default()
	}
	if registry == nil {
		registry = defaultRegistry(counter)
	}
	return &Engine{registry: registry, counter: counter, store: store}
}

func defaultRegistry(counter tokens.Counter) *compressors.Registry {
	registry := compressors.Default()
	if strings.EqualFold(os.Getenv("CAVE_ENGINE_TOON"), "best-of") {
		registry.Register(compressors.NewJSONStrategy(counter))
	}
	return registry
}

// Compress detects the content type, routes to the matching compressor, and
// returns the compressed result. It is fail-closed: in record mode, when no
// compressor matches, when the compressor reports a parse problem, when the
// result is not smaller, or when a lossy result cannot be made recoverable, it
// passes the original bytes through unchanged (no handle, zero ratio).
func (e *Engine) Compress(input []byte, opts Options) (Result, error) {
	body, listing := unwrapListing(input)
	ct := opts.Type
	if ct == "" {
		ct = e.Detect(body)
	}
	before := e.counter.Count(input)
	res := Result{
		Output:          input,
		ContentType:     ct,
		TokensBefore:    before,
		TokensAfter:     before,
		TokenCountBasis: e.counter.Name(),
		Basis:           BasisInferred,
	}

	// record mode never transforms.
	if opts.Mode.normalized() == ModeRecord {
		return res, nil
	}

	comp, ok := e.registry.For(ct)
	if !ok {
		return res, nil // no compressor for this type → pass-through
	}

	// A lossy (S4) compressor may only run if we can store the original for
	// recovery. Without a store, fail closed to pass-through.
	info, known := safety.Lookup(comp.SafetyClass())
	if !known {
		return res, nil // unknown safety class → fail closed
	}
	if info.RequiresCCR && e.store == nil && !opts.ExternalRecovery {
		return res, nil
	}

	out, meta, ok := compressWith(comp, body, opts.Query)
	if !ok || out == nil {
		return res, nil // parse problem → pass-through
	}
	out = listing.rewrap(out)
	after := e.counter.Count(out)
	if after >= before || bytes.Equal(out, input) {
		return res, nil // not actually smaller → pass-through, claim nothing
	}

	meta = normalizeMetadata(comp, meta, info)

	if info.RequiresCCR && !opts.ExternalRecovery {
		handle, err := e.store.Put(ccr.Recovery{
			ContentType:  ct,
			Compressor:   comp.ContentType(),
			TokensBefore: before,
			TokensAfter:  after,
			Original:     append([]byte(nil), input...),
			Metadata:     append([]byte(nil), meta.RecoveryMetadata...),
		})
		if err != nil {
			// Keep every result field pass-through on a failed recovery write. A
			// caller must never receive transformed bytes without a durable handle.
			return res, err
		}
		res.RecoveryHandle = handle
	}
	// Publish transformed metadata only after CCR has succeeded. This makes the
	// result fail closed if persistence is unavailable.
	res.Output = out
	res.TokensAfter = after
	res.Ratio = float64(before-after) / float64(before)
	res.Method = meta.Method
	res.LosslessToModel = meta.LosslessToModel
	return res, nil
}

// Simulate runs the same detect → route → compress → count pipeline as Compress
// but stores NOTHING (no CCR Put) and makes no network call: a pure dry-run that
// reports the token reduction a real Compress would achieve as a local estimate.
//
// It mirrors every pass-through condition Compress has (record mode, no matching
// compressor, unknown safety class, parse problem, not-actually-smaller) and claims
// nothing in those cases. The one deliberate difference: for a lossy (S4) compressor
// with no store, Compress fails closed to pass-through, but Simulate still reports
// the would-be reduction with Recoverable=false — showing that CCR is required
// before the transform can be emitted. The caller buckets by
// SafetyClass/Recoverable; the number is a token count of compressor output.
func (e *Engine) Simulate(input []byte, opts Options) SimResult {
	body, listing := unwrapListing(input)
	ct := opts.Type
	if ct == "" {
		ct = e.Detect(body)
	}
	before := e.counter.Count(input)
	res := SimResult{
		ContentType:     ct,
		TokensBefore:    before,
		TokensAfter:     before,
		TokenCountBasis: e.counter.Name(),
		Basis:           BasisInferred,
		Recoverable:     true, // pass-through is trivially recoverable (no transform)
	}

	if opts.Mode.normalized() == ModeRecord {
		return res // record mode never transforms
	}
	comp, ok := e.registry.For(ct)
	if !ok {
		return res // no compressor for this type → pass-through, claim nothing
	}
	info, known := safety.Lookup(comp.SafetyClass())
	if !known {
		return res // unknown safety class → fail closed, claim nothing
	}
	out, meta, ok := compressWith(comp, body, opts.Query)
	if !ok || out == nil {
		return res // parse problem → pass-through
	}
	out = listing.rewrap(out)
	after := e.counter.Count(out)
	if after >= before || bytes.Equal(out, input) {
		return res // not actually smaller → claim nothing
	}

	res.Compressor = comp.ContentType()
	res.SafetyClass = info.Name
	res.TokensAfter = after
	res.TokensSaved = before - after
	res.Ratio = float64(before-after) / float64(before)
	res.Recoverable = !info.RequiresCCR || e.store != nil
	meta = normalizeMetadata(comp, meta, info)
	res.Method = meta.Method
	res.LosslessToModel = meta.LosslessToModel
	res.RequiresCCR = info.RequiresCCR
	res.Lossy = meta.LosslessToModel != nil && !*meta.LosslessToModel
	return res
}

// compressWith dispatches to a compressor's query-aware path when a query is
// set and the compressor implements QueryAwareCompressor, else the plain byte
// transform. It is the single point that keeps Compress and Simulate in sync.
func compressWith(comp compressors.Compressor, input []byte, query string) ([]byte, compressors.Metadata, bool) {
	if mc, ok := comp.(compressors.MetadataCompressor); ok {
		return mc.CompressWithMetadata(input, query)
	}
	if query != "" {
		if qa, ok := comp.(compressors.QueryAwareCompressor); ok {
			out, ok := qa.CompressQuery(input, query)
			return out, compressors.Metadata{}, ok
		}
	}
	out, ok := comp.Compress(input)
	return out, compressors.Metadata{}, ok
}

func normalizeMetadata(comp compressors.Compressor, meta compressors.Metadata, info safety.Info) compressors.Metadata {
	if meta.Method == "" {
		meta.Method = comp.ContentType()
	}
	if meta.LosslessToModel == nil {
		meta.LosslessToModel = boolPtr(info.Reversible)
	}
	return meta
}

func boolPtr(v bool) *bool {
	return &v
}

// Retrieve returns the exact original bytes for a recovery handle.
//
// The CCR store holds two id spaces, and an agent cannot be expected to know
// which one minted the reference it was handed. Compression mints blob handles
// (`ccr_…`, store.Get); the native runtime's tool-output masking mints typed
// OBJECT ids and shows them as `ccr://<id>` (store.GetObject). So a lookup that
// misses the blob table falls through to the object table before it fails.
//
// Recovery must resolve every reference the runtime can emit. A handle that
// cannot resolve invites repeated retrieval attempts, especially when the failed
// retrieval result is itself eligible for masking. Resolve both blob and typed
// object handles before failing so recovery never points to another dead pointer.
func (e *Engine) Retrieve(handle string) ([]byte, error) {
	if e.store == nil {
		return nil, ccr.ErrNotFound
	}
	original, err := e.store.Get(handle)
	if err == nil {
		return original, nil
	}
	if !errors.Is(err, ccr.ErrNotFound) {
		return nil, err
	}
	object, objectErr := e.store.GetObject(handle)
	if objectErr == nil {
		return object.Data, nil
	}
	if !errors.Is(objectErr, ccr.ErrNotFound) {
		return nil, objectErr
	}
	return nil, err
}

// RetrieveMetadata returns optional compressor metadata stored beside a recovery
// handle. The raw Retrieve path remains byte-exact and never returns this wrapper
// data.
func (e *Engine) RetrieveMetadata(handle string) ([]byte, error) {
	if e.store == nil {
		return nil, ccr.ErrNotFound
	}
	return e.store.GetMetadata(handle)
}

// Stats returns aggregate compression accounting from the recovery store.
func (e *Engine) Stats() (ccr.Stats, error) {
	if e.store == nil {
		return ccr.Stats{ByContentType: map[string]ccr.Bucket{}, Basis: BasisInferred}, nil
	}
	return e.store.Summary()
}

package engine_test

import (
	"bytes"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
)

type bestOfCounter struct {
	toonTokens    int
	elisionTokens int
	inputTokens   int
}

func (c bestOfCounter) Name() string { return "best-of-test" }
func (c bestOfCounter) Count(b []byte) int {
	s := string(b)
	switch {
	case strings.Contains(s, "rows["):
		return c.toonTokens
	case strings.Contains(s, "__caveman_elided__"):
		return c.elisionTokens
	default:
		return c.inputTokens
	}
}

func newEngine(t *testing.T) *engine.Engine {
	t.Helper()
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatalf("open memory store: %v", err)
	}
	t.Cleanup(func() { _ = store.Close() })
	return engine.New(store, nil)
}

const arrayJSON = `{"results":[{"id":1},{"id":2},{"id":3},{"id":4},{"id":5},{"id":6},{"id":7},{"id":8},{"id":9},{"id":10},{"id":11},{"id":12}],"error":null}`

// bestOfJSONInput is a uniform, repetitive array: TOON-eligible, and redundant
// enough that elision is allowed to run at all. Rows that differ in every field
// are a list of distinct entities, which the elision path now declines to shorten
// (see compressors.keepNonRedundant), and these tests are about which method wins
// and what it reports — not about that rule.
const bestOfJSONInput = `{"rows":[{"id":1,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":2,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":3,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":4,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":5,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":6,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":7,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":8,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":9,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":10,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":11,"status":"healthy","region":"eu-west-1","tier":"standard"},{"id":12,"status":"healthy","region":"eu-west-1","tier":"standard"}]}`

func TestRecordModeIsPassThrough(t *testing.T) {
	e := newEngine(t)
	res, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.ModeRecord})
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(res.Output, []byte(arrayJSON)) {
		t.Error("record mode must return bytes unchanged")
	}
	if res.RecoveryHandle != "" || res.Ratio != 0 {
		t.Errorf("record mode must claim nothing: handle=%q ratio=%v", res.RecoveryHandle, res.Ratio)
	}
	if res.Basis != engine.BasisInferred {
		t.Errorf("basis = %q, want %q", res.Basis, engine.BasisInferred)
	}
}

func TestEmptyModeDefaultsToRecord(t *testing.T) {
	e := newEngine(t)
	res, err := e.Compress([]byte(arrayJSON), engine.Options{}) // no mode
	if err != nil {
		t.Fatal(err)
	}
	if !res.PassedThrough() {
		t.Error("empty mode must default to record (pass-through)")
	}
}

func TestUnknownModeFailsClosedToRecord(t *testing.T) {
	e := newEngine(t)
	res, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.Mode("turbo")})
	if err != nil {
		t.Fatal(err)
	}
	if !res.PassedThrough() {
		t.Error("unknown mode must fail closed to record")
	}
}

func TestCompressJSONReducesAndRecovers(t *testing.T) {
	e := newEngine(t)
	res, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if res.ContentType != engine.TypeJSON {
		t.Errorf("content type = %q, want json", res.ContentType)
	}
	if res.PassedThrough() {
		t.Fatal("expected the array JSON to compress")
	}
	if res.Ratio <= 0 || res.TokensAfter >= res.TokensBefore {
		t.Errorf("expected a positive ratio, got %v (%d->%d)", res.Ratio, res.TokensBefore, res.TokensAfter)
	}
	if res.TokenCountBasis == "" {
		t.Error("token_count_basis must disclose estimator")
	}
	if res.Method != "elision" {
		t.Errorf("method = %q, want elision", res.Method)
	}
	if res.LosslessToModel == nil || *res.LosslessToModel {
		t.Errorf("lossless_to_model = %v, want explicit false", res.LosslessToModel)
	}
	// Recovery must return the exact original.
	original, err := e.Retrieve(res.RecoveryHandle)
	if err != nil {
		t.Fatalf("retrieve: %v", err)
	}
	if !bytes.Equal(original, []byte(arrayJSON)) {
		t.Error("retrieve must return the byte-exact original")
	}
}

func TestRetrieveReturnsValidEmptyTypedObject(t *testing.T) {
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = store.Close() })
	id, err := store.PutObject(ccr.Object{
		ID:        "typed-empty-output",
		Type:      ccr.ObjectCommandResult,
		SessionID: "empty-output-session",
		Source:    "tool:empty",
		Data:      []byte{},
	})
	if err != nil {
		t.Fatal(err)
	}

	got, err := engine.New(store, nil).Retrieve(id)
	if err != nil {
		t.Fatalf("retrieve empty typed object: %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("retrieve empty typed object = %#v, want zero-byte result", got)
	}
}

func TestBestOfJSONUsesInjectedCounterAndReportsTOON(t *testing.T) {
	t.Setenv("CAVE_ENGINE_TOON", "best-of")
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = store.Close() })
	counter := bestOfCounter{inputTokens: 100, toonTokens: 10, elisionTokens: 20}
	e := engine.New(store, counter)
	input := []byte(bestOfJSONInput)

	res, err := e.Compress(input, engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if res.PassedThrough() {
		t.Fatal("expected best-of compression")
	}
	if res.Method != "toon" {
		t.Fatalf("method = %q, want toon (same injected counter must choose it)", res.Method)
	}
	if res.TokensAfter != 10 {
		t.Fatalf("tokens_after = %d, want injected toon count 10", res.TokensAfter)
	}
	if res.TokenCountBasis != "best-of-test" {
		t.Fatalf("token_count_basis = %q, want best-of-test", res.TokenCountBasis)
	}
	if res.LosslessToModel == nil || !*res.LosslessToModel {
		t.Fatalf("lossless_to_model = %v, want explicit true", res.LosslessToModel)
	}
}

func TestBestOfJSONCanChooseElisionAndReportsExplicitFalse(t *testing.T) {
	t.Setenv("CAVE_ENGINE_TOON", "best-of")
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = store.Close() })
	counter := bestOfCounter{inputTokens: 100, toonTokens: 20, elisionTokens: 10}
	e := engine.New(store, counter)
	input := []byte(bestOfJSONInput)

	res, err := e.Compress(input, engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if res.Method != "elision" {
		t.Fatalf("method = %q, want elision", res.Method)
	}
	if res.LosslessToModel == nil || *res.LosslessToModel {
		t.Fatalf("lossless_to_model = %v, want explicit false", res.LosslessToModel)
	}
}

func TestMalformedInputPassesThrough(t *testing.T) {
	e := newEngine(t)
	bad := []byte(`{"results":[1,2,3,  <-- not json`)
	res, err := e.Compress(bad, engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(res.Output, bad) || !res.PassedThrough() {
		t.Error("malformed input must pass through byte-identical with no handle")
	}
}

func TestPlainTextPassesThrough(t *testing.T) {
	e := newEngine(t)
	text := []byte("just an ordinary sentence with nothing to compress")
	res, err := e.Compress(text, engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if res.ContentType != engine.TypeText || !res.PassedThrough() {
		t.Errorf("plain text must detect as text and pass through; got %q passthrough=%v", res.ContentType, res.PassedThrough())
	}
}

func TestCompressIsIdempotent(t *testing.T) {
	e := newEngine(t)
	first, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	second, err := e.Compress(first.Output, engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(second.Output, first.Output) {
		t.Errorf("compress must be idempotent:\n first=%s\nsecond=%s", first.Output, second.Output)
	}
}

func TestNilStoreFailsClosedNoLossyCompression(t *testing.T) {
	// Without a recovery store, a lossy (S4) result would be unrecoverable, so
	// the engine must pass through rather than compress.
	e := engine.New(nil, nil)
	res, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if !res.PassedThrough() {
		t.Error("with no CCR store, lossy compression must fail closed to pass-through")
	}
}

func TestCCRWriteFailureReturnsPassThroughResult(t *testing.T) {
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	e := engine.New(store, nil)
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}
	input := []byte(arrayJSON)
	res, err := e.Compress(input, engine.Options{Mode: engine.ModeCompress})
	if err == nil {
		t.Fatal("closed CCR store must fail the compression")
	}
	if !bytes.Equal(res.Output, input) || res.RecoveryHandle != "" || res.Method != "" ||
		res.TokensAfter != res.TokensBefore || res.Ratio != 0 {
		t.Fatalf("CCR failure must return an untouched pass-through result: %+v", res)
	}
}

func TestExternalRecoveryAllowsS4WithoutLocalCCRHandle(t *testing.T) {
	e := engine.New(nil, nil)
	res, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress, ExternalRecovery: true})
	if err != nil {
		t.Fatal(err)
	}
	if res.PassedThrough() {
		t.Fatal("external recovery caller should be able to emit S4 output")
	}
	if res.RecoveryHandle != "" {
		t.Fatalf("external recovery must not create local CCR handle, got %q", res.RecoveryHandle)
	}
	if res.Method != "elision" {
		t.Fatalf("method = %q, want elision", res.Method)
	}
}

// TestRetrieveQueryNarrowsToRelevantSections checks query-targeted recovery
// path: empty query is byte-exact, a query returns only the BM25-relevant sections,
// and an unknown handle still fails closed.
func TestRetrieveQueryNarrowsToRelevantSections(t *testing.T) {
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatalf("open memory store: %v", err)
	}
	t.Cleanup(func() { _ = store.Close() })
	e := engine.New(store, nil)

	original := []byte(`{"model":"m","messages":[{"role":"user","content":"Section about kubernetes pod scheduling and node affinity."},{"role":"user","content":"Section about postgres vacuum tuning and autovacuum thresholds."},{"role":"user","content":"Section about redis eviction policies and maxmemory."}]}`)
	handle, err := store.Put(ccr.Recovery{ContentType: "request", Compressor: "proxy-content", Original: original})
	if err != nil {
		t.Fatalf("put: %v", err)
	}

	full, err := e.RetrieveQuery(handle, "")
	if err != nil {
		t.Fatalf("full retrieve: %v", err)
	}
	if !bytes.Equal(full, original) {
		t.Errorf("empty query must return the byte-exact original")
	}

	narrowed, err := e.RetrieveQuery(handle, "postgres autovacuum tuning")
	if err != nil {
		t.Fatalf("query retrieve: %v", err)
	}
	if !strings.Contains(string(narrowed), "vacuum") {
		t.Errorf("query-targeted retrieve must include the relevant section, got: %s", narrowed)
	}
	if strings.Contains(string(narrowed), "kubernetes") || strings.Contains(string(narrowed), "redis eviction") {
		t.Errorf("query-targeted retrieve must drop irrelevant sections, got: %s", narrowed)
	}
	if len(narrowed) >= len(full) {
		t.Errorf("narrowed (%d bytes) must be smaller than full recovery (%d bytes)", len(narrowed), len(full))
	}

	if _, err := e.RetrieveQuery("no_such_handle", "anything"); err == nil {
		t.Errorf("unknown handle must fail closed, got nil error")
	}
}

