// Package inventory tracks items and computes rollups for a region.
package inventory

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Item is a single tracked unit.
type Item struct {
	ID    int
	Name  string
	Score float64
	Tags  []string
}

// ErrEmpty is returned when a rollup is requested over no items.
var ErrEmpty = errors.New("inventory: no items")

// Rollup summarizes a set of items by tag.
type Rollup struct {
	ByTag map[string]int
	Total int
	Top   string
}

// Summarize groups items by tag, totals them, and finds the highest scorer.
// It returns ErrEmpty when there is nothing to summarize.
func Summarize(items []Item) (Rollup, error) {
	if len(items) == 0 {
		return Rollup{}, ErrEmpty
	}
	r := Rollup{ByTag: map[string]int{}}
	best := -1.0
	for _, it := range items {
		r.Total++
		for _, t := range it.Tags {
			r.ByTag[strings.ToLower(t)]++
		}
		if it.Score > best {
			best = it.Score
			r.Top = it.Name
		}
	}
	return r, nil
}

// FilterByTag returns the items carrying the given tag, sorted by score
// descending so the most relevant items come first.
func FilterByTag(items []Item, tag string) []Item {
	tag = strings.ToLower(tag)
	var out []Item
	for _, it := range items {
		for _, t := range it.Tags {
			if strings.ToLower(t) == tag {
				out = append(out, it)
				break
			}
		}
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Score > out[j].Score
	})
	return out
}

// Format renders a rollup as a stable, human-readable string.
func (r Rollup) Format() string {
	keys := make([]string, 0, len(r.ByTag))
	for k := range r.ByTag {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	fmt.Fprintf(&b, "total=%d top=%s\n", r.Total, r.Top)
	for _, k := range keys {
		fmt.Fprintf(&b, "  %s: %d\n", k, r.ByTag[k])
	}
	return b.String()
}

"""Inventory rollups: group items by tag and compute simple summaries."""

from dataclasses import dataclass, field
from typing import Dict, List, Optional


@dataclass
class Item:
    """A single tracked unit."""

    id: int
    name: str
    score: float
    tags: List[str] = field(default_factory=list)


@dataclass
class Rollup:
    by_tag: Dict[str, int]
    total: int
    top: Optional[str]


def summarize(items: List[Item]) -> Rollup:
    """Group items by tag, total them, and find the highest scorer."""
    if not items:
        raise ValueError("inventory: no items")
    by_tag: Dict[str, int] = {}
    total = 0
    best = -1.0
    top = None
    for it in items:
        total += 1
        for tag in it.tags:
            key = tag.lower()
            by_tag[key] = by_tag.get(key, 0) + 1
        if it.score > best:
            best = it.score
            top = it.name
    return Rollup(by_tag=by_tag, total=total, top=top)


def filter_by_tag(items: List[Item], tag: str) -> List[Item]:
    """Return items carrying the tag, most relevant first."""
    tag = tag.lower()
    matched = [it for it in items if any(t.lower() == tag for t in it.tags)]
    matched.sort(key=lambda it: it.score, reverse=True)
    return matched


def format_rollup(rollup: Rollup) -> str:
    """Render a rollup as a stable, human-readable string."""
    lines = [f"total={rollup.total} top={rollup.top}"]
    for key in sorted(rollup.by_tag):
        lines.append(f"  {key}: {rollup.by_tag[key]}")
    return "\n".join(lines)

// Inventory rollups: group items by tag and compute simple summaries.

export interface Item {
  id: number;
  name: string;
  score: number;
  tags: string[];
}

export interface Rollup {
  byTag: Record<string, number>;
  total: number;
  top: string | null;
}

/** Group items by tag, total them, and find the highest scorer. */
export function summarize(items: Item[]): Rollup {
  if (items.length === 0) {
    throw new Error("inventory: no items");
  }
  const byTag: Record<string, number> = {};
  let total = 0;
  let best = -1;
  let top: string | null = null;
  for (const it of items) {
    total += 1;
    for (const tag of it.tags) {
      const key = tag.toLowerCase();
      byTag[key] = (byTag[key] ?? 0) + 1;
    }
    if (it.score > best) {
      best = it.score;
      top = it.name;
    }
  }
  return { byTag, total, top };
}

/** Return items carrying the tag, most relevant first. */
export function filterByTag(items: Item[], tag: string): Item[] {
  const needle = tag.toLowerCase();
  const matched = items.filter((it) =>
    it.tags.some((t) => t.toLowerCase() === needle),
  );
  matched.sort((a, b) => b.score - a.score);
  return matched;
}

/** Render a rollup as a stable, human-readable string. */
export function formatRollup(rollup: Rollup): string {
  const lines = [`total=${rollup.total} top=${rollup.top}`];
  for (const key of Object.keys(rollup.byTag).sort()) {
    lines.push(`  ${key}: ${rollup.byTag[key]}`);
  }
  return lines.join("\n");
}

