// Package evals is the engine's local eval harness: it replays a fixture set
// through the engine behind quality graders and reports the realized ratio and
// a pass/fail verdict, so no ratio claim ships unproven. It mirrors
// the canonical fail-closed grader contract from public/evals — an unknown
// grader type never silently passes.
package evals

import (
	"bytes"
	"encoding/json"
	"fmt"
	"reflect"
	"regexp"
	"strings"

	"github.com/JuliusBrussee/caveman/engine/compressors"
)

// Subject is what a grader judges: one fixture compressed by the engine.
type Subject struct {
	Input         []byte
	Output        []byte
	Ratio         float64
	ContentType   string
	Method        string
	PassedThrough bool
}

// Grader is one quality check from a fixture manifest.
type Grader struct {
	Type      string         `yaml:"type" json:"type"`
	Min       float64        `yaml:"min" json:"min,omitempty"`
	Max       float64        `yaml:"max" json:"max,omitempty"`
	Value     string         `yaml:"value" json:"value,omitempty"`
	Reference any            `yaml:"reference" json:"reference,omitempty"`
	Options   map[string]any `yaml:"options" json:"options,omitempty"`
}

// Verdict is a grader outcome (mirrors public/evals GradeResult).
type Verdict struct {
	Passed bool
	Reason string
}

func pass(reason string) Verdict { return Verdict{Passed: true, Reason: reason} }
func fail(reason string) Verdict { return Verdict{Passed: false, Reason: reason} }

// Grade runs one grader against a subject. The default branch fails closed: an
// unknown or misspelled grader type is never treated as a pass.
func Grade(g Grader, s Subject) Verdict {
	switch g.Type {
	case "exact_match":
		want := graderString(g)
		if strings.TrimSpace(string(s.Output)) == strings.TrimSpace(want) {
			return pass("output exactly matches expected value")
		}
		return fail(fmt.Sprintf("output %q != expected %q", strings.TrimSpace(string(s.Output)), strings.TrimSpace(want)))
	case "ratio_threshold":
		if s.Ratio < g.Min {
			return fail(fmt.Sprintf("ratio %.4f below min %.4f", s.Ratio, g.Min))
		}
		if g.Max > 0 && s.Ratio > g.Max {
			return fail(fmt.Sprintf("ratio %.4f above max %.4f", s.Ratio, g.Max))
		}
		return pass(fmt.Sprintf("ratio %.4f within [%.4f,%.4f]", s.Ratio, g.Min, g.Max))
	case "valid_json":
		if json.Valid(s.Output) {
			return pass("output is valid JSON")
		}
		return fail("output is not valid JSON")
	case "json_or_toon_round_trip":
		if json.Valid(s.Output) {
			return pass("output is valid JSON")
		}
		if s.Method != "toon" {
			return fail("output is not valid JSON and method is not TOON")
		}
		return gradeTOONRoundTrip(s)
	case "json_schema":
		var candidate any
		if err := json.Unmarshal(s.Output, &candidate); err != nil {
			return fail("output is not JSON: " + err.Error())
		}
		schema, ok := graderSchema(g)
		if !ok {
			return fail("json_schema requires options.schema or reference schema")
		}
		if reason := validateJSONSchema(candidate, schema, "$"); reason != "" {
			return fail(reason)
		}
		return pass("output satisfies JSON schema")
	case "tool_sequence":
		want := graderStringList(g.Options["tools"])
		if len(want) == 0 {
			want = graderStringList(g.Options["sequence"])
		}
		if len(want) == 0 {
			want = graderReferenceStringList(g.Reference)
		}
		if len(want) == 0 {
			return fail("tool_sequence requires a non-empty tools sequence")
		}
		got := extractToolSequence(s.Output)
		if reflect.DeepEqual(got, want) {
			return pass("tool call sequence matches")
		}
		return fail(fmt.Sprintf("tool sequence %v != expected %v", got, want))
	case "contains":
		if bytes.Contains(s.Output, []byte(g.Value)) {
			return pass(fmt.Sprintf("output contains %q", g.Value))
		}
		return fail(fmt.Sprintf("output missing %q", g.Value))
	case "not_contains":
		if !bytes.Contains(s.Output, []byte(g.Value)) {
			return pass(fmt.Sprintf("output omits %q", g.Value))
		}
		return fail(fmt.Sprintf("output still contains %q", g.Value))
	case "byte_identical":
		if bytes.Equal(s.Input, s.Output) {
			return pass("output is byte-identical to input")
		}
		return fail("output differs from input")
	case "compressed":
		if !s.PassedThrough {
			return pass("payload was compressed (not passed through)")
		}
		return fail("payload passed through unchanged")
	case "toon_round_trip":
		if s.PassedThrough {
			return fail("TOON round-trip requires a compressed TOON output")
		}
		return gradeTOONRoundTrip(s)
	case "recall_keys":
		// Checks that must-keep tokens survived compression. Fail-closed: an empty
		// must_contain list is a configuration error, not a pass.
		musts := graderStringList(g.Options["must_contain"])
		if len(musts) == 0 {
			return fail("recall_keys requires a non-empty options.must_contain list")
		}
		minRecall := 1.0
		switch v := g.Options["min_recall"].(type) {
		case float64:
			minRecall = v
		case int:
			minRecall = float64(v)
		}
		kept := 0
		var missing []string
		for _, m := range musts {
			if bytes.Contains(s.Output, []byte(m)) {
				kept++
			} else {
				missing = append(missing, m)
			}
		}
		recall := float64(kept) / float64(len(musts))
		if recall >= minRecall {
			return pass(fmt.Sprintf("recall %.2f ≥ %.2f (%d/%d kept)", recall, minRecall, kept, len(musts)))
		}
		return fail(fmt.Sprintf("recall %.2f < %.2f, missing %v", recall, minRecall, missing))
	default:
		// Fail closed: an unknown grader type is a gate failure, never a pass.
		return fail("unknown grader type: " + strings.TrimSpace(g.Type))
	}
}

func gradeTOONRoundTrip(s Subject) Verdict {
	want, ok := compressors.DecodeJSONForTOONGrader(s.Input)
	if !ok {
		return fail("input is not valid JSON for TOON round-trip")
	}
	got, ok := compressors.DecodeTOON(s.Output)
	if !ok {
		return fail("output is not decodable TOON")
	}
	if reflect.DeepEqual(got, want) {
		return pass("TOON decodes to the original JSON value")
	}
	return fail("TOON output does not round-trip to the original JSON value")
}

// graderStringList coerces a YAML-decoded option sequence into a string slice.
// Scalar entries that are not strings (e.g. an unquoted numeric error code like
// 503) are stringified rather than silently dropped — dropping them would make
// the recall_keys gate fail OPEN (claim full recall while a must-keep token was
// never checked). Nested collections are skipped: a must-keep entry is a scalar.
func graderStringList(v any) []string {
	arr, ok := v.([]any)
	if !ok {
		if ss, ok := v.([]string); ok {
			return append([]string(nil), ss...)
		}
		return nil
	}
	out := make([]string, 0, len(arr))
	for _, e := range arr {
		switch t := e.(type) {
		case string:
			out = append(out, t)
		case nil, []any, map[string]any:
			// skip: not a scalar token
		default:
			out = append(out, fmt.Sprint(t))
		}
	}
	return out
}

func graderString(g Grader) string {
	if g.Value != "" {
		return g.Value
	}
	if s, ok := g.Reference.(string); ok {
		return s
	}
	return fmt.Sprint(g.Reference)
}

func graderSchema(g Grader) (map[string]any, bool) {
	if g.Options != nil {
		if schema, ok := mapAny(g.Options["schema"]); ok {
			return schema, true
		}
	}
	if schema, ok := mapAny(g.Reference); ok {
		return schema, true
	}
	if raw, ok := g.Reference.(string); ok && strings.TrimSpace(raw) != "" {
		var schema map[string]any
		if json.Unmarshal([]byte(raw), &schema) == nil {
			return schema, true
		}
	}
	return nil, false
}

func mapAny(v any) (map[string]any, bool) {
	switch m := v.(type) {
	case map[string]any:
		return m, true
	case map[any]any:
		out := make(map[string]any, len(m))
		for k, v := range m {
			ks, ok := k.(string)
			if !ok {
				return nil, false
			}
			out[ks] = v
		}
		return out, true
	default:
		return nil, false
	}
}

func validateJSONSchema(v any, schema map[string]any, path string) string {
	if enum, ok := schema["enum"].([]any); ok {
		for _, allowed := range enum {
			if reflect.DeepEqual(v, allowed) {
				return ""
			}
		}
		return fmt.Sprintf("%s not in enum %v", path, enum)
	}
	if c, ok := schema["const"]; ok && !reflect.DeepEqual(v, c) {
		return fmt.Sprintf("%s != const %v", path, c)
	}
	if types := schemaTypeSet(schema["type"]); len(types) > 0 && !valueMatchesAnyType(v, types) {
		return fmt.Sprintf("%s has wrong type, want %v", path, types)
	}
	switch x := v.(type) {
	case map[string]any:
		if req := graderStringList(schema["required"]); len(req) > 0 {
			for _, key := range req {
				if _, ok := x[key]; !ok {
					return fmt.Sprintf("%s missing required property %q", path, key)
				}
			}
		}
		if props, ok := mapAny(schema["properties"]); ok {
			for key, rawSchema := range props {
				child, ok := x[key]
				if !ok {
					continue
				}
				childSchema, ok := mapAny(rawSchema)
				if !ok {
					return fmt.Sprintf("%s.properties.%s is not a schema", path, key)
				}
				if reason := validateJSONSchema(child, childSchema, path+"."+key); reason != "" {
					return reason
				}
			}
		}
		if allow, ok := schema["additionalProperties"].(bool); ok && !allow {
			props, _ := mapAny(schema["properties"])
			for key := range x {
				if _, ok := props[key]; !ok {
					return fmt.Sprintf("%s has additional property %q", path, key)
				}
			}
		}
	case []any:
		if min, ok := number(schema["minItems"]); ok && len(x) < int(min) {
			return fmt.Sprintf("%s has %d items, below minItems %.0f", path, len(x), min)
		}
		if max, ok := number(schema["maxItems"]); ok && len(x) > int(max) {
			return fmt.Sprintf("%s has %d items, above maxItems %.0f", path, len(x), max)
		}
		if itemSchema, ok := mapAny(schema["items"]); ok {
			for i, child := range x {
				if reason := validateJSONSchema(child, itemSchema, fmt.Sprintf("%s[%d]", path, i)); reason != "" {
					return reason
				}
			}
		}
	case string:
		if min, ok := number(schema["minLength"]); ok && len(x) < int(min) {
			return fmt.Sprintf("%s length below minLength %.0f", path, min)
		}
		if max, ok := number(schema["maxLength"]); ok && len(x) > int(max) {
			return fmt.Sprintf("%s length above maxLength %.0f", path, max)
		}
		if pattern, ok := schema["pattern"].(string); ok {
			re, err := regexp.Compile(pattern)
			if err != nil {
				return fmt.Sprintf("%s has invalid pattern %q", path, pattern)
			}
			if !re.MatchString(x) {
				return fmt.Sprintf("%s does not match pattern %q", path, pattern)
			}
		}
	case float64:
		if min, ok := number(schema["minimum"]); ok && x < min {
			return fmt.Sprintf("%s %.4f below minimum %.4f", path, x, min)
		}
		if max, ok := number(schema["maximum"]); ok && x > max {
			return fmt.Sprintf("%s %.4f above maximum %.4f", path, x, max)
		}
	}
	return ""
}

func schemaTypeSet(v any) map[string]bool {
	out := map[string]bool{}
	switch x := v.(type) {
	case string:
		out[x] = true
	case []any:
		for _, e := range x {
			if s, ok := e.(string); ok {
				out[s] = true
			}
		}
	}
	return out
}

func valueMatchesAnyType(v any, types map[string]bool) bool {
	for typ := range types {
		switch typ {
		case "object":
			if _, ok := v.(map[string]any); ok {
				return true
			}
		case "array":
			if _, ok := v.([]any); ok {
				return true
			}
		case "string":
			if _, ok := v.(string); ok {
				return true
			}
		case "number":
			if _, ok := v.(float64); ok {
				return true
			}
		case "integer":
			if n, ok := v.(float64); ok && n == float64(int64(n)) {
				return true
			}
		case "boolean":
			if _, ok := v.(bool); ok {
				return true
			}
		case "null":
			if v == nil {
				return true
			}
		}
	}
	return false
}

func number(v any) (float64, bool) {
	switch x := v.(type) {
	case float64:
		return x, true
	case int:
		return float64(x), true
	case int64:
		return float64(x), true
	default:
		return 0, false
	}
}

func graderReferenceStringList(v any) []string {
	if out := graderStringList(v); len(out) > 0 {
		return out
	}
	if s, ok := v.(string); ok {
		return splitToolNames(s)
	}
	return nil
}

func extractToolSequence(raw []byte) []string {
	var v any
	if json.Unmarshal(raw, &v) == nil {
		if out := toolNamesFromValue(v); len(out) > 0 {
			return out
		}
	}
	return splitToolNames(string(raw))
}

func toolNamesFromValue(v any) []string {
	switch x := v.(type) {
	case []any:
		out := make([]string, 0, len(x))
		for _, e := range x {
			out = append(out, toolNamesFromValue(e)...)
		}
		return out
	case map[string]any:
		for _, key := range []string{"tool_calls", "calls", "steps", "tools"} {
			if calls, ok := x[key]; ok {
				return toolNamesFromValue(calls)
			}
		}
		for _, key := range []string{"name", "tool", "tool_name"} {
			if name, ok := x[key].(string); ok && strings.TrimSpace(name) != "" {
				return []string{strings.TrimSpace(name)}
			}
		}
		if fn, ok := mapAny(x["function"]); ok {
			if name, ok := fn["name"].(string); ok && strings.TrimSpace(name) != "" {
				return []string{strings.TrimSpace(name)}
			}
		}
	case string:
		return splitToolNames(x)
	}
	return nil
}

func splitToolNames(s string) []string {
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return r == ',' || r == '\n' || r == '\t' || r == '>' || r == '|'
	})
	out := make([]string, 0, len(fields))
	for _, f := range fields {
		f = strings.TrimSpace(strings.Trim(f, "-"))
		if f != "" {
			out = append(out, f)
		}
	}
	return out
}

package evals

import (
	"bytes"
	"context"
	"embed"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
)

//go:embed fixtures
var fixturesFS embed.FS

// Fixture is one entry in the manifest: a payload file plus the graders that
// must pass when the engine compresses it.
type Fixture struct {
	Name           string           `yaml:"name"`
	File           string           `yaml:"file"`
	Type           string           `yaml:"type"`  // force a content type; empty = auto-detect
	Mode           string           `yaml:"mode"`  // "compress" (default) or "record"
	Query          string           `yaml:"query"` // optional relevance query for query-aware compressors
	Probes         []RetentionProbe `yaml:"probes"`
	Graders        []Grader         `yaml:"graders"`
	QualityGraders []Grader         `yaml:"quality_graders"`
	QualityTask    QualityTask      `yaml:"quality_task"`
}

// Manifest is the fixture set.
type Manifest struct {
	Fixtures []Fixture `yaml:"fixtures"`
}

// TransformResult is one system-under-test transform result.
type TransformResult struct {
	Output          []byte
	ContentType     string
	Method          string
	TokensBefore    int
	TokensAfter     int
	Ratio           float64
	Basis           string
	PassedThrough   bool
	Recoverable     bool
	LosslessToModel *bool
}

// TransformRunner lets non-Caveman systems run through the same fixture,
// quality, and reporting path.
type TransformRunner interface {
	Transform(context.Context, Fixture, []byte) (TransformResult, error)
}

// FixtureReport is the outcome for one fixture.
type FixtureReport struct {
	Name            string         `json:"name"`
	ContentType     string         `json:"content_type"`
	TokensBefore    int            `json:"tokens_before"`
	TokensAfter     int            `json:"tokens_after"`
	Ratio           float64        `json:"ratio"`
	WordsBefore     int            `json:"words_before"`
	WordsAfter      int            `json:"words_after"`
	WordRatio       float64        `json:"word_ratio"`
	Basis           string         `json:"basis"`
	Passed          bool           `json:"passed"`
	ByteRecoverable bool           `json:"byte_recoverable"`
	Failures        []string       `json:"failures,omitempty"`
	Probes          []ProbeResult  `json:"probes,omitempty"`
	ProbeSummary    *ProbeSummary  `json:"probe_summary,omitempty"`
	Quality         *QualityReport `json:"quality,omitempty"`
}

// Report is the harness result.
type Report struct {
	Passed       bool            `json:"passed"`
	TokensBefore int             `json:"tokens_before"`
	TokensAfter  int             `json:"tokens_after"`
	TokenRatio   float64         `json:"token_ratio"`
	WordsBefore  int             `json:"words_before"`
	WordsAfter   int             `json:"words_after"`
	WordRatio    float64         `json:"word_ratio"`
	Probes       ProbeSummary    `json:"probes"`
	Quality      *QualitySummary `json:"quality,omitempty"`
	Fixtures     []FixtureReport `json:"fixtures"`
}

// Run replays the embedded fixture set behind its graders and returns the
// report. It runs the engine's configured quality gate.
func Run() (Report, error) {
	var m Manifest
	raw, err := fixturesFS.ReadFile("fixtures/manifest.yaml")
	if err != nil {
		return Report{}, fmt.Errorf("read manifest: %w", err)
	}
	if err := yaml.Unmarshal(raw, &m); err != nil {
		return Report{}, fmt.Errorf("parse manifest: %w", err)
	}
	read := func(name string) ([]byte, error) {
		return fixturesFS.ReadFile("fixtures/" + name)
	}
	return RunManifest(m, read)
}

// RunDir replays a caller-supplied fixture directory containing manifest.yaml.
// Manifest file paths are slash-separated, relative, and confined to root even
// through symlinks; a custom empty corpus is a configuration error, never green.
func RunDir(root string) (Report, error) {
	resolvedRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		return Report{}, fmt.Errorf("resolve fixture directory: %w", err)
	}
	manifestRaw, err := os.ReadFile(filepath.Join(resolvedRoot, "manifest.yaml"))
	if err != nil {
		return Report{}, fmt.Errorf("read manifest: %w", err)
	}
	var m Manifest
	if err := yaml.Unmarshal(manifestRaw, &m); err != nil {
		return Report{}, fmt.Errorf("parse manifest: %w", err)
	}
	if len(m.Fixtures) == 0 {
		return Report{}, fmt.Errorf("manifest has no fixtures")
	}
	read := func(name string) ([]byte, error) {
		if !fs.ValidPath(name) || name == "." {
			return nil, fmt.Errorf("invalid fixture path %q", name)
		}
		candidate, err := filepath.EvalSymlinks(filepath.Join(resolvedRoot, filepath.FromSlash(name)))
		if err != nil {
			return nil, err
		}
		rel, err := filepath.Rel(resolvedRoot, candidate)
		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			return nil, fmt.Errorf("fixture path escapes root: %q", name)
		}
		return os.ReadFile(candidate)
	}
	return RunManifest(m, read)
}

// RunWithQuality replays the embedded fixture set and also sends baseline and
// compressed prompts through a model runner before grading the answers.
func RunWithQuality(ctx context.Context, opts QualityOptions) (Report, error) {
	m, err := EmbeddedManifest()
	if err != nil {
		return Report{}, err
	}
	read := func(name string) ([]byte, error) {
		return fixturesFS.ReadFile("fixtures/" + name)
	}
	return RunManifestWithQuality(ctx, m, read, opts)
}

// EmbeddedManifest returns the built-in fixture manifest.
func EmbeddedManifest() (Manifest, error) {
	var m Manifest
	raw, err := fixturesFS.ReadFile("fixtures/manifest.yaml")
	if err != nil {
		return Manifest{}, fmt.Errorf("read manifest: %w", err)
	}
	if err := yaml.Unmarshal(raw, &m); err != nil {
		return Manifest{}, fmt.Errorf("parse manifest: %w", err)
	}
	return m, nil
}

// ReadEmbeddedFixture reads one built-in fixture file.
func ReadEmbeddedFixture(name string) ([]byte, error) {
	return fixturesFS.ReadFile("fixtures/" + name)
}

// RunManifest replays an arbitrary manifest, reading fixture files via read.
// It is exported so tests can seed a deliberately-failing manifest and assert
// the gate fails closed.
func RunManifest(m Manifest, read func(name string) ([]byte, error)) (Report, error) {
	return runManifest(context.Background(), m, read, nil)
}

// RunManifestWithQuality is RunManifest plus the LLM-in-the-loop quality layer.
// The runner is injected so CI can use a deterministic local runner while release
// jobs can call a real gateway/model.
func RunManifestWithQuality(ctx context.Context, m Manifest, read func(name string) ([]byte, error), opts QualityOptions) (Report, error) {
	if opts.Runner == nil {
		return Report{}, fmt.Errorf("quality runner is required")
	}
	return runManifest(ctx, m, read, &opts)
}

// RunManifestWithSystem runs a caller-supplied system-under-test through the
// same graders and optional quality layer as the built-in engine.
func RunManifestWithSystem(ctx context.Context, m Manifest, read func(name string) ([]byte, error), system TransformRunner, opts *QualityOptions) (Report, error) {
	if system == nil {
		return Report{}, fmt.Errorf("system runner is required")
	}
	if opts != nil && opts.Runner == nil {
		return Report{}, fmt.Errorf("quality runner is required")
	}
	return runManifestWithSystem(ctx, m, read, system, opts)
}

func runManifest(ctx context.Context, m Manifest, read func(name string) ([]byte, error), quality *QualityOptions) (Report, error) {
	store, err := ccr.OpenMemory()
	if err != nil {
		return Report{}, fmt.Errorf("open recovery store: %w", err)
	}
	defer store.Close()
	eng := engine.New(store, nil)
	return runManifestWithSystem(ctx, m, read, engineSystem{eng: eng}, quality)
}

func runManifestWithSystem(ctx context.Context, m Manifest, read func(name string) ([]byte, error), system TransformRunner, quality *QualityOptions) (Report, error) {
	report := Report{Passed: true}
	for _, f := range m.Fixtures {
		input, err := read(f.File)
		if err != nil {
			return Report{}, fmt.Errorf("read fixture %q: %w", f.File, err)
		}
		res, err := system.Transform(ctx, f, input)
		if err != nil {
			return Report{}, fmt.Errorf("compress fixture %q: %w", f.Name, err)
		}
		subject := Subject{
			Input:         input,
			Output:        res.Output,
			Ratio:         res.Ratio,
			ContentType:   res.ContentType,
			Method:        res.Method,
			PassedThrough: res.PassedThrough,
		}
		fr := FixtureReport{
			Name:            f.Name,
			ContentType:     res.ContentType,
			TokensBefore:    res.TokensBefore,
			TokensAfter:     res.TokensAfter,
			Ratio:           res.Ratio,
			WordsBefore:     CountWords(input),
			WordsAfter:      CountWords(res.Output),
			Basis:           res.Basis,
			Passed:          true,
			ByteRecoverable: res.Recoverable,
		}
		fr.WordRatio = ratio(fr.WordsBefore, fr.WordsAfter)
		probeResults, probeSummary, probeFailures := classifyProbes(f.Probes, res.Output, res.Recoverable)
		fr.Probes = probeResults
		if len(f.Probes) > 0 {
			fr.ProbeSummary = &probeSummary
		}
		if len(probeFailures) > 0 {
			fr.Passed = false
			fr.Failures = append(fr.Failures, probeFailures...)
		}
		mergeProbeSummary(&report.Probes, probeSummary)
		// A fixture with no graders is a configuration error, not a free pass.
		if len(f.Graders) == 0 {
			fr.Passed = false
			fr.Failures = append(fr.Failures, "no graders configured")
		}
		for _, g := range f.Graders {
			if v := Grade(g, subject); !v.Passed {
				fr.Passed = false
				fr.Failures = append(fr.Failures, v.Reason)
			}
		}
		if !fr.Passed {
			report.Passed = false
		}
		if quality != nil {
			qr, err := runQuality(ctx, *quality, f, input, res.Output, res.ContentType, res.Ratio, res.PassedThrough)
			if err != nil {
				return Report{}, fmt.Errorf("quality fixture %q: %w", f.Name, err)
			}
			fr.Quality = &qr
		}
		report.TokensBefore += fr.TokensBefore
		report.TokensAfter += fr.TokensAfter
		report.WordsBefore += fr.WordsBefore
		report.WordsAfter += fr.WordsAfter
		report.Fixtures = append(report.Fixtures, fr)
	}
	report.TokenRatio = ratio(report.TokensBefore, report.TokensAfter)
	report.WordRatio = ratio(report.WordsBefore, report.WordsAfter)
	if quality != nil {
		report.Quality = summarizeQuality(report.Fixtures, *quality)
		if !report.Quality.Passed {
			report.Passed = false
		}
	}
	return report, nil
}

type engineSystem struct {
	eng *engine.Engine
}

func (s engineSystem) Transform(_ context.Context, f Fixture, input []byte) (TransformResult, error) {
	mode := engine.ModeCompress
	if f.Mode == string(engine.ModeRecord) {
		mode = engine.ModeRecord
	}
	res, err := s.eng.Compress(input, engine.Options{Mode: mode, Type: f.Type, Query: f.Query})
	if err != nil {
		return TransformResult{}, err
	}
	recoverable := bytes.Equal(input, res.Output)
	if res.RecoveryHandle != "" {
		original, err := s.eng.Retrieve(res.RecoveryHandle)
		recoverable = err == nil && bytes.Equal(original, input)
	}
	return TransformResult{
		Output:          res.Output,
		ContentType:     res.ContentType,
		Method:          res.Method,
		TokensBefore:    res.TokensBefore,
		TokensAfter:     res.TokensAfter,
		Ratio:           res.Ratio,
		Basis:           res.Basis,
		PassedThrough:   res.PassedThrough(),
		Recoverable:     recoverable,
		LosslessToModel: res.LosslessToModel,
	}, nil
}

// FixtureFiles lists the embedded fixture file names (excluding the manifest),
// for tests and tooling.
func FixtureFiles() ([]string, error) {
	entries, err := fs.ReadDir(fixturesFS, "fixtures")
	if err != nil {
		return nil, err
	}
	var names []string
	for _, e := range entries {
		if e.Name() != "manifest.yaml" {
			names = append(names, e.Name())
		}
	}
	return names, nil
}

package evals_test

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/evals"
)

func TestRunDirUsesNamedCorpusAndRejectsEscapes(t *testing.T) {
	root := t.TempDir()
	manifest := "fixtures:\n  - name: named-failure\n    file: input.txt\n    mode: record\n    graders:\n      - {type: contains, value: absent-marker}\n"
	if err := os.WriteFile(filepath.Join(root, "manifest.yaml"), []byte(manifest), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "input.txt"), []byte("caller supplied corpus"), 0o600); err != nil {
		t.Fatal(err)
	}
	report, err := evals.RunDir(root)
	if err != nil {
		t.Fatal(err)
	}
	if report.Passed || len(report.Fixtures) != 1 || report.Fixtures[0].Name != "named-failure" {
		t.Fatalf("custom failing corpus was not authoritative: %+v", report)
	}

	escape := "fixtures:\n  - name: escape\n    file: ../outside.txt\n    mode: record\n    graders:\n      - {type: contains, value: x}\n"
	if err := os.WriteFile(filepath.Join(root, "manifest.yaml"), []byte(escape), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := evals.RunDir(root); err == nil {
		t.Fatal("fixture traversal must fail closed")
	}
}

