package evals

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"
)

const (
	ProbeRetained    = "retained"
	ProbeRecoverable = "recoverable"
	ProbeLost        = "lost"
)

// RetentionProbe names one critical value that a transform must keep visible or
// make byte-exactly recoverable. Values come from committed fixture manifests;
// reports carry only their hashes so hidden-suite answers are not disclosed.
type RetentionProbe struct {
	Dimension string `yaml:"dimension"`
	Value     string `yaml:"value"`
}

// ProbeResult is one classified probe. ValueSHA256 identifies which committed value
// was checked without copying hidden fixture answers into signed public reports.
type ProbeResult struct {
	Dimension   string `json:"dimension"`
	ValueSHA256 string `json:"value_sha256"`
	State       string `json:"state"`
}

// ProbeTally is a retained/recoverable/lost count.
type ProbeTally struct {
	Total       int `json:"total"`
	Retained    int `json:"retained"`
	Recoverable int `json:"recoverable"`
	Lost        int `json:"lost"`
}

// ProbeSummary aggregates probe outcomes without erasing per-fixture detail.
type ProbeSummary struct {
	ProbeTally
	ByDimension map[string]ProbeTally `json:"by_dimension,omitempty"`
}

func classifyProbes(probes []RetentionProbe, output []byte, recoverable bool) ([]ProbeResult, ProbeSummary, []string) {
	if len(probes) == 0 {
		return nil, ProbeSummary{}, nil
	}
	results := make([]ProbeResult, 0, len(probes))
	summary := ProbeSummary{ByDimension: map[string]ProbeTally{}}
	var failures []string
	for i, probe := range probes {
		value := probe.Value
		if value == "" {
			failures = append(failures, fmt.Sprintf("retention probe %d has empty value", i))
			continue
		}
		dimension := strings.TrimSpace(probe.Dimension)
		if dimension == "" {
			dimension = "unspecified"
		}
		state := ProbeLost
		if bytes.Contains(output, []byte(value)) {
			state = ProbeRetained
		} else if recoverable {
			state = ProbeRecoverable
		}
		sum := sha256.Sum256([]byte(value))
		results = append(results, ProbeResult{
			Dimension:   dimension,
			ValueSHA256: "sha256:" + hex.EncodeToString(sum[:]),
			State:       state,
		})
		addProbeState(&summary.ProbeTally, state)
		tally := summary.ByDimension[dimension]
		addProbeState(&tally, state)
		summary.ByDimension[dimension] = tally
		if state == ProbeLost {
			failures = append(failures, fmt.Sprintf("retention probe %s was lost", dimension))
		}
	}
	return results, summary, failures
}

func addProbeState(tally *ProbeTally, state string) {
	tally.Total++
	switch state {
	case ProbeRetained:
		tally.Retained++
	case ProbeRecoverable:
		tally.Recoverable++
	case ProbeLost:
		tally.Lost++
	}
}

func mergeProbeSummary(dst *ProbeSummary, src ProbeSummary) {
	dst.Total += src.Total
	dst.Retained += src.Retained
	dst.Recoverable += src.Recoverable
	dst.Lost += src.Lost
	if len(src.ByDimension) == 0 {
		return
	}
	if dst.ByDimension == nil {
		dst.ByDimension = map[string]ProbeTally{}
	}
	for dimension, srcTally := range src.ByDimension {
		dstTally := dst.ByDimension[dimension]
		dstTally.Total += srcTally.Total
		dstTally.Retained += srcTally.Retained
		dstTally.Recoverable += srcTally.Recoverable
		dstTally.Lost += srcTally.Lost
		dst.ByDimension[dimension] = dstTally
	}
}

package evals

import (
	"context"
	"fmt"
	"strings"

	"github.com/JuliusBrussee/caveman/engine/tokens"
)

// ModelUsage is model-side accounting for one fixture prompt.
type ModelUsage struct {
	InputTokens  int     `json:"input_tokens"`
	OutputTokens int     `json:"output_tokens"`
	CostUSD      float64 `json:"cost_usd,omitempty"`
	Source       string  `json:"source,omitempty"`
}

// ModelRequest is one baseline or compressed prompt sent through a model runner.
type ModelRequest struct {
	FixtureName    string  `json:"fixture_name"`
	Variant        string  `json:"variant"` // baseline or compressed
	Model          string  `json:"model,omitempty"`
	ContentType    string  `json:"content_type"`
	Question       string  `json:"question,omitempty"`
	ExpectedAnswer string  `json:"expected_answer,omitempty"`
	Seed           int     `json:"seed"`        // sampling seed for multi-seed runs
	Temperature    float64 `json:"temperature"` // sampling temperature; 0 = deterministic
	Prompt         []byte  `json:"-"`
}

// ModelResponse is the answer and optional usage returned by a model runner.
type ModelResponse struct {
	Output []byte     `json:"-"`
	Usage  ModelUsage `json:"usage"`
}

// ModelRunner is the LLM-in-the-loop seam. CI can use EchoModel; release runs
// can provide a gateway-backed runner without changing the harness.
type ModelRunner interface {
	Complete(context.Context, ModelRequest) (ModelResponse, error)
}

// AnswerGrader grades one model answer. LocalGrader is the offline fallback;
// gateway/authoritative runs can inject the canonical optimizer grader service.
type AnswerGrader interface {
	Grade(context.Context, Grader, Subject) (Verdict, error)
}

// LocalGrader uses the engine's local fail-closed grader subset.
type LocalGrader struct{}

func (LocalGrader) Grade(_ context.Context, g Grader, s Subject) (Verdict, error) {
	return Grade(g, s), nil
}

// EchoModel is deterministic and network-free: it returns the prompt as the
// answer. It exercises the quality gate and accounting path without pretending to
// be a vendor model.
type EchoModel struct{}

func (EchoModel) Complete(_ context.Context, req ModelRequest) (ModelResponse, error) {
	return ModelResponse{Output: append([]byte(nil), req.Prompt...)}, nil
}

// QualityOptions configures the model-answer quality layer.
type QualityOptions struct {
	Runner       ModelRunner
	Model        string
	Mode         string
	Floor        float64
	RequireUsage bool
	Grader       AnswerGrader
	// Seed is the sampling seed for this pass. Multi-seed callers vary it across
	// passes; the deterministic offline runner ignores it.
	Seed int
	// Temperature is the sampling temperature for this pass. 0 keeps single-seed
	// runs deterministic; multi-seed runs raise it so seeds actually diverge.
	Temperature float64
}

// QualityTask defines the actual model-answer task for a fixture. It is separate
// from compression graders so payload-shape checks cannot masquerade as quality.
type QualityTask struct {
	Question string   `yaml:"question" json:"question"`
	Graders  []Grader `yaml:"graders" json:"graders"`
}

// QualityReport is the per-fixture LLM-in-the-loop result.
type QualityReport struct {
	Graders            []string   `json:"graders"`
	BaselinePassed     bool       `json:"baseline_passed"`
	CompressedPassed   bool       `json:"compressed_passed"`
	Retention          float64    `json:"retention"`
	BaselineFailures   []string   `json:"baseline_failures,omitempty"`
	CompressedFailures []string   `json:"compressed_failures,omitempty"`
	BaselineUsage      ModelUsage `json:"baseline_usage"`
	CompressedUsage    ModelUsage `json:"compressed_usage"`
}

// QualitySummary is the aggregate quality-preservation gate.
type QualitySummary struct {
	Mode                   string   `json:"mode"`
	Model                  string   `json:"model,omitempty"`
	Floor                  float64  `json:"floor"`
	BaselinePassRate       float64  `json:"baseline_pass_rate"`
	CompressedPassRate     float64  `json:"compressed_pass_rate"`
	Retention              float64  `json:"retention"`
	Passed                 bool     `json:"passed"`
	BaselineFailures       int      `json:"baseline_failures"`
	CompressedFailures     int      `json:"compressed_failures"`
	BaselineInputTokens    int      `json:"baseline_input_tokens"`
	BaselineOutputTokens   int      `json:"baseline_output_tokens"`
	CompressedInputTokens  int      `json:"compressed_input_tokens"`
	CompressedOutputTokens int      `json:"compressed_output_tokens"`
	BaselineCostUSD        float64  `json:"baseline_cost_usd,omitempty"`
	CompressedCostUSD      float64  `json:"compressed_cost_usd,omitempty"`
	UsageSource            string   `json:"usage_source"`
	CostSource             string   `json:"cost_source,omitempty"`
	TasksTotal             int      `json:"tasks_total"`
	TasksPassed            int      `json:"tasks_passed"`
	BaselineCpCTUSD        float64  `json:"baseline_cpct_usd,omitempty"`
	CompressedCpCTUSD      float64  `json:"compressed_cpct_usd,omitempty"`
	CostSavingsRatio       float64  `json:"cost_savings_ratio"`
	GraderTypes            []string `json:"grader_types"`
}

func runQuality(ctx context.Context, opts QualityOptions, f Fixture, input, compressed []byte, contentType string, compressionRatio float64, passedThrough bool) (QualityReport, error) {
	graders := qualityGraders(f)
	names := make([]string, 0, len(graders))
	for _, g := range graders {
		names = append(names, g.Type)
	}

	report := QualityReport{Graders: names}
	if len(graders) == 0 {
		report.BaselineFailures = append(report.BaselineFailures, "no quality graders configured")
		report.CompressedFailures = append(report.CompressedFailures, "no quality graders configured")
		return report, nil
	}
	if strings.TrimSpace(f.QualityTask.Question) == "" {
		report.BaselineFailures = append(report.BaselineFailures, "no quality question configured")
		report.CompressedFailures = append(report.CompressedFailures, "no quality question configured")
		return report, nil
	}
	expected := expectedAnswer(graders)

	baselinePrompt := qualityPrompt(f.QualityTask.Question, input)
	compressedPrompt := qualityPrompt(f.QualityTask.Question, compressed)
	baseline, err := opts.Runner.Complete(ctx, ModelRequest{
		FixtureName:    f.Name,
		Variant:        "baseline",
		Model:          opts.Model,
		ContentType:    contentType,
		Question:       f.QualityTask.Question,
		ExpectedAnswer: expected,
		Seed:           opts.Seed,
		Temperature:    opts.Temperature,
		Prompt:         baselinePrompt,
	})
	if err != nil {
		return QualityReport{}, fmt.Errorf("baseline model call: %w", err)
	}
	compressedResp, err := opts.Runner.Complete(ctx, ModelRequest{
		FixtureName:    f.Name,
		Variant:        "compressed",
		Model:          opts.Model,
		ContentType:    contentType,
		Question:       f.QualityTask.Question,
		ExpectedAnswer: expected,
		Seed:           opts.Seed,
		Temperature:    opts.Temperature,
		Prompt:         compressedPrompt,
	})
	if err != nil {
		return QualityReport{}, fmt.Errorf("compressed model call: %w", err)
	}

	counter := tokens.Default()
	report.BaselineUsage, err = fillUsage(counter, baselinePrompt, baseline, opts.RequireUsage)
	if err != nil {
		return QualityReport{}, fmt.Errorf("baseline usage: %w", err)
	}
	report.CompressedUsage, err = fillUsage(counter, compressedPrompt, compressedResp, opts.RequireUsage)
	if err != nil {
		return QualityReport{}, fmt.Errorf("compressed usage: %w", err)
	}

	baseSubject := Subject{Input: input, Output: baseline.Output, ContentType: contentType, PassedThrough: true}
	compSubject := Subject{Input: input, Output: compressedResp.Output, Ratio: compressionRatio, ContentType: contentType, PassedThrough: passedThrough}
	grader := opts.Grader
	if grader == nil {
		grader = LocalGrader{}
	}
	report.BaselineFailures, err = gradeFailures(ctx, grader, graders, baseSubject)
	if err != nil {
		return QualityReport{}, fmt.Errorf("baseline grading: %w", err)
	}
	report.CompressedFailures, err = gradeFailures(ctx, grader, graders, compSubject)
	if err != nil {
		return QualityReport{}, fmt.Errorf("compressed grading: %w", err)
	}
	report.BaselinePassed = len(report.BaselineFailures) == 0
	report.CompressedPassed = len(report.CompressedFailures) == 0
	if report.BaselinePassed && report.CompressedPassed {
		report.Retention = 1
	}
	return report, nil
}

func fillUsage(counter tokens.Counter, prompt []byte, resp ModelResponse, requireRunnerUsage bool) (ModelUsage, error) {
	usage := resp.Usage
	if usage.InputTokens > 0 && usage.OutputTokens > 0 {
		usage.Source = "runner"
		return usage, nil
	}
	if requireRunnerUsage {
		return ModelUsage{}, fmt.Errorf("runner did not return input/output token usage")
	}
	if usage.InputTokens == 0 {
		usage.InputTokens = counter.Count(prompt)
	}
	if usage.OutputTokens == 0 {
		usage.OutputTokens = counter.Count(resp.Output)
	}
	usage.Source = "local_tokenizer"
	return usage, nil
}

func gradeFailures(ctx context.Context, runner AnswerGrader, graders []Grader, subject Subject) ([]string, error) {
	var failures []string
	for _, g := range graders {
		v, err := runner.Grade(ctx, g, subject)
		if err != nil {
			return nil, err
		}
		if !v.Passed {
			failures = append(failures, v.Reason)
		}
	}
	return failures, nil
}

func qualityGraders(f Fixture) []Grader {
	if len(f.QualityTask.Graders) > 0 {
		return append([]Grader(nil), f.QualityTask.Graders...)
	}
	if len(f.QualityGraders) > 0 {
		return append([]Grader(nil), f.QualityGraders...)
	}
	return nil
}

func summarizeQuality(fixtures []FixtureReport, opts QualityOptions) *QualitySummary {
	floor := opts.Floor
	if floor == 0 {
		floor = 0.99
	}
	mode := strings.TrimSpace(opts.Mode)
	if mode == "" {
		mode = "deterministic-local"
	}
	s := &QualitySummary{Mode: mode, Model: opts.Model, Floor: floor, TasksTotal: len(fixtures)}
	if len(fixtures) == 0 {
		return s
	}
	var baselinePass, compressedPass int
	seenGraders := map[string]bool{}
	for _, f := range fixtures {
		if f.Quality == nil {
			continue
		}
		q := f.Quality
		for _, name := range q.Graders {
			if !seenGraders[name] {
				seenGraders[name] = true
				s.GraderTypes = append(s.GraderTypes, name)
			}
		}
		if q.BaselinePassed {
			baselinePass++
		} else {
			s.BaselineFailures++
		}
		if q.CompressedPassed {
			compressedPass++
			s.TasksPassed++
		} else {
			s.CompressedFailures++
		}
		s.BaselineInputTokens += q.BaselineUsage.InputTokens
		s.BaselineOutputTokens += q.BaselineUsage.OutputTokens
		s.CompressedInputTokens += q.CompressedUsage.InputTokens
		s.CompressedOutputTokens += q.CompressedUsage.OutputTokens
		s.BaselineCostUSD += q.BaselineUsage.CostUSD
		s.CompressedCostUSD += q.CompressedUsage.CostUSD
		if s.UsageSource == "" {
			s.UsageSource = q.CompressedUsage.Source
		} else if s.UsageSource != q.CompressedUsage.Source {
			s.UsageSource = "mixed"
		}
	}
	total := float64(len(fixtures))
	s.BaselinePassRate = float64(baselinePass) / total
	s.CompressedPassRate = float64(compressedPass) / total
	if baselinePass > 0 {
		s.Retention = float64(compressedPass) / float64(baselinePass)
		s.BaselineCpCTUSD = s.BaselineCostUSD / float64(baselinePass)
	}
	if compressedPass > 0 {
		s.CompressedCpCTUSD = s.CompressedCostUSD / float64(compressedPass)
	}
	if s.BaselineCostUSD > 0 && s.CompressedCostUSD < s.BaselineCostUSD {
		s.CostSavingsRatio = (s.BaselineCostUSD - s.CompressedCostUSD) / s.BaselineCostUSD
	}
	s.Passed = s.BaselineFailures == 0 && s.Retention >= floor
	return s
}

func qualityPrompt(question string, context []byte) []byte {
	return []byte("Use the context to answer the question.\n\nContext:\n" + string(context) + "\n\nQuestion:\n" + strings.TrimSpace(question) + "\n\nAnswer only.")
}

func expectedAnswer(graders []Grader) string {
	for _, g := range graders {
		if g.Type == "exact_match" {
			return graderString(g)
		}
	}
	return ""
}

// AnswerKeyModel is an explicit offline smoke runner. It never calls a provider;
// it returns the fixture's expected answer and labels usage as local.
type AnswerKeyModel struct{}

func (AnswerKeyModel) Complete(_ context.Context, req ModelRequest) (ModelResponse, error) {
	if strings.TrimSpace(req.ExpectedAnswer) == "" {
		return ModelResponse{}, fmt.Errorf("answer-key runner requires expected answer")
	}
	return ModelResponse{Output: []byte(req.ExpectedAnswer)}, nil
}

package evals

import "unicode"

// CountWords is the tokenizer-independent denominator for eval reporting.
// It treats contiguous letters/digits as one word and ignores punctuation.
func CountWords(b []byte) int {
	var n int
	inWord := false
	for _, r := range string(b) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			if !inWord {
				n++
				inWord = true
			}
			continue
		}
		inWord = false
	}
	return n
}

func ratio(before, after int) float64 {
	if before <= 0 || after >= before {
		return 0
	}
	return float64(before-after) / float64(before)
}

// Package image is the engine's deterministic, offline image-token reducer. It
// does NOT implement the byte-stream compressors.Compressor interface — image
// blocks live inside multimodal message arrays and the decision needs provider
// context (which detail knob exists) and query context (what the user asked).
// No production gateway path calls Decide or Apply today. They are an offline,
// opt-in primitive; any future wire path must store the original for recovery.
//
// Everything here is deterministic and pure-stdlib (no model weights, no
// network): supported token math is bound to provider+model+effective detail, the router
// is a keyword + dimension heuristic, and resize is an integer area-average box
// filter re-encoded as PNG (deterministic; token cost is dimension-based, so the
// PNG-vs-JPEG byte size does not affect token estimates). Counts here are local;
// provider usage is authoritative. The router fails safe toward keeping full
// detail: a miss costs reduction, never quality.
package image

import (
	"bytes"
	"image"
	"image/color"
	_ "image/gif"  // register GIF decoder
	_ "image/jpeg" // register JPEG decoder
	"image/png"
	"regexp"
	"strings"
)

// Props is the cheap, decode-light analysis of an image (dimensions + format).
type Props struct {
	Width  int
	Height int
	Format string
}

// maxPixels bounds the declared image area we will handle. A header can claim
// enormous dimensions (a decode bomb); rejecting them here keeps the downstream
// full image.Decode in Apply from attempting a huge allocation.
const maxPixels = 100_000_000 // 100 megapixels

// Analyze reads only the image header for dimensions and format. It returns
// ok=false on anything it cannot decode or that declares an unreasonable pixel
// area, so callers pass the image through unchanged.
func Analyze(b []byte) (Props, bool) {
	cfg, format, err := image.DecodeConfig(bytes.NewReader(b))
	if err != nil || cfg.Width <= 0 || cfg.Height <= 0 {
		return Props{}, false
	}
	if int64(cfg.Width)*int64(cfg.Height) > maxPixels {
		return Props{}, false // decode-bomb guard
	}
	return Props{Width: cfg.Width, Height: cfg.Height, Format: format}, true
}

// Action is the chosen image transform.
type Action string

const (
	// ActionPassthrough keeps the image untouched (the fail-safe default).
	ActionPassthrough Action = "passthrough"
	// ActionDetailLow asks the gateway to set the provider's low-detail flag
	// (OpenAI detail:"low" / Gemini media_resolution:"low"). The bytes are
	// unchanged; the provider downsamples server-side.
	ActionDetailLow Action = "detail-low"
	// ActionResize downscales the pixels to ResizeLong on the long edge — the
	// only lever for providers without a detail flag (e.g. Anthropic).
	ActionResize Action = "resize"
)

// Plan is the deterministic decision for one image. SafetyClass is always S4
// when Action != passthrough (model-visible content changes; CCR must hold the
// original), expressed by the gateway, not here.
type Plan struct {
	Action       Action
	ResizeLong   int // long-edge target px when Action == ActionResize
	Provider     string
	Model        string
	BeforeDetail string // effective detail/media resolution before this transform
}

var (
	// Queries that need full detail: text/OCR, fine detail, counting, exactness.
	keepHighRe = regexp.MustCompile(`(?i)\b(read|reads?|text|ocr|transcrib\w*|serial|number|numbers|code|sign|signage|label|labels|caption|chart|charts|axis|axes|table|tables|diagram|legend|fine print|count|counting|how many|exact\w*|digit\w*|spelling|verbatim)\b`)
	// Queries safe for a low-detail thumbnail: gist, scene, description.
	allowLowRe = regexp.MustCompile(`(?i)\b(describe|description|what is this|what's in|whats in|is there|are there|overall|scene|setting|mood|colou?r|colou?rs|background|roughly|gist|summar\w*|general(ly)?|vibe)\b`)
)

// Decide chooses a transform for an image given the sibling query text, the
// provider, and the model. It is fail-safe by construction: an empty or
// ambiguous query, any text/precision signal, or an unknown situation yields
// ActionPassthrough — a router miss keeps full detail.
func Decide(p Props, query, provider, model string) Plan {
	return DecideWithDetail(p, query, provider, model, "default")
}

// DecideWithDetail is Decide with explicit effective provider detail/media
// resolution. Ambiguous or unsupported model-detail tuples pass through.
func DecideWithDetail(p Props, query, provider, model, beforeDetail string) Plan {
	provider = strings.ToLower(strings.TrimSpace(provider))
	model = strings.ToLower(strings.TrimSpace(model))
	beforeDetail = strings.ToLower(strings.TrimSpace(beforeDetail))
	plan := Plan{Action: ActionPassthrough, Provider: provider, Model: model, BeforeDetail: beforeDetail}

	q := strings.TrimSpace(query)
	// Keep full detail unless the query is explicitly a low-detail-safe ask AND
	// carries no precision signal.
	if q == "" || keepHighRe.MatchString(q) || !allowLowRe.MatchString(q) {
		return plan
	}
	before, supported := EstimateTokensForModel(provider, model, beforeDetail, p.Width, p.Height)
	if !supported || before <= 0 {
		return plan
	}

	longEdge := p.Width
	if p.Height > longEdge {
		longEdge = p.Height
	}

	switch provider {
	case "openai":
		low, ok := EstimateTokensForModel(provider, model, "low", p.Width, p.Height)
		if ok && meaningfulTokenReduction(before, low) {
			return Plan{Action: ActionDetailLow, Provider: provider, Model: model, BeforeDetail: beforeDetail}
		}
		return plan
	case "google", "gemini":
		low, ok := EstimateTokensForModel(provider, model, "low", p.Width, p.Height)
		if ok && meaningfulTokenReduction(before, low) {
			return Plan{Action: ActionDetailLow, Provider: provider, Model: model, BeforeDetail: beforeDetail}
		}
		return plan
	case "anthropic":
		if longEdge > 768 {
			afterW, afterH := scaleToLong(p.Width, p.Height, 768)
			after, ok := EstimateTokensForModel(provider, model, beforeDetail, afterW, afterH)
			if ok && meaningfulTokenReduction(before, after) {
				return Plan{Action: ActionResize, ResizeLong: 768, Provider: provider, Model: model, BeforeDetail: beforeDetail}
			}
		}
		return plan
	default:
		return plan
	}
}

func meaningfulTokenReduction(before, after int) bool {
	// S4 changes model-visible input. A marginal inferred delta cannot justify
	// that quality risk; require at least 25% before any future caller can act.
	return before > 0 && after > 0 && int64(after)*4 <= int64(before)*3
}

// Apply executes a plan. For ActionResize it returns the downscaled image (PNG,
// deterministic). For ActionDetailLow it returns the original bytes unchanged
// (the gateway sets the provider flag) with the low-detail token estimate. It
// returns ok=false when nothing useful happened (passthrough, decode failure, or
// a resize that would not actually reduce tokens), so the caller claims nothing.
func Apply(orig []byte, plan Plan) (out []byte, tokensBefore, tokensAfter int, ok bool) {
	props, okp := Analyze(orig)
	if !okp {
		return nil, 0, 0, false
	}
	tokensBefore, ok = EstimateTokensForModel(plan.Provider, plan.Model, plan.BeforeDetail, props.Width, props.Height)
	if !ok || tokensBefore <= 0 {
		return nil, 0, 0, false
	}

	switch plan.Action {
	case ActionResize:
		img, _, err := image.Decode(bytes.NewReader(orig))
		if err != nil {
			return nil, 0, 0, false
		}
		nw, nh := scaleToLong(props.Width, props.Height, plan.ResizeLong)
		if nw >= props.Width && nh >= props.Height {
			return nil, 0, 0, false // not actually smaller
		}
		var buf bytes.Buffer
		if err := png.Encode(&buf, downscale(img, nw, nh)); err != nil {
			return nil, 0, 0, false
		}
		tokensAfter, ok = EstimateTokensForModel(plan.Provider, plan.Model, plan.BeforeDetail, nw, nh)
		if !ok || !meaningfulTokenReduction(tokensBefore, tokensAfter) {
			return nil, 0, 0, false
		}
		return buf.Bytes(), tokensBefore, tokensAfter, true
	case ActionDetailLow:
		low, supported := EstimateTokensForModel(plan.Provider, plan.Model, "low", props.Width, props.Height)
		if !supported || low <= 0 {
			// The provider has no low-detail tier (e.g. Anthropic) — a detail-low
			// plan is not applicable. Return failure rather than report a reduction
			// with the bytes unchanged. (Decide never emits this plan
			// for such providers; Apply must not trust a plan blindly.)
			return nil, 0, 0, false
		}
		tokensAfter = low
		if !meaningfulTokenReduction(tokensBefore, tokensAfter) {
			return nil, 0, 0, false
		}
		return orig, tokensBefore, tokensAfter, true // bytes unchanged; gateway sets the flag
	default:
		return orig, tokensBefore, tokensBefore, false
	}
}

func scaleToLong(w, h, long int) (int, int) {
	if w >= h {
		if w <= long {
			return w, h
		}
		nh := h * long / w
		if nh < 1 {
			nh = 1
		}
		return long, nh
	}
	if h <= long {
		return w, h
	}
	nw := w * long / h
	if nw < 1 {
		nw = 1
	}
	return nw, long
}

// downscale is a deterministic integer area-average (box) filter. Each
// destination pixel averages the source pixels in its mapped region. Pure
// arithmetic in a fixed traversal order → byte-identical output for the same
// input on every platform.
func downscale(src image.Image, nw, nh int) image.Image {
	b := src.Bounds()
	sw, sh := b.Dx(), b.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, nw, nh))
	for y := 0; y < nh; y++ {
		sy0 := b.Min.Y + y*sh/nh
		sy1 := b.Min.Y + (y+1)*sh/nh
		if sy1 <= sy0 {
			sy1 = sy0 + 1
		}
		for x := 0; x < nw; x++ {
			sx0 := b.Min.X + x*sw/nw
			sx1 := b.Min.X + (x+1)*sw/nw
			if sx1 <= sx0 {
				sx1 = sx0 + 1
			}
			var r, g, bl, a, cnt uint64
			for yy := sy0; yy < sy1; yy++ {
				for xx := sx0; xx < sx1; xx++ {
					// Convert to straight (non-premultiplied) alpha before averaging.
					// RGBA() is alpha-premultiplied, which darkens semi-transparent
					// pixels when written back as straight-alpha NRGBA.
					c := color.NRGBA64Model.Convert(src.At(xx, yy)).(color.NRGBA64)
					r += uint64(c.R)
					g += uint64(c.G)
					bl += uint64(c.B)
					a += uint64(c.A)
					cnt++
				}
			}
			if cnt == 0 {
				cnt = 1
			}
			// NRGBA64 channels are 16-bit straight-alpha; shift back to 8-bit.
			dst.Set(x, y, color.NRGBA{
				R: uint8((r / cnt) >> 8),
				G: uint8((g / cnt) >> 8),
				B: uint8((bl / cnt) >> 8),
				A: uint8((a / cnt) >> 8),
			})
		}
	}
	return dst
}

package image_test

import (
	"bytes"
	"image"
	"image/color"
	"image/png"
	"testing"

	cvimage "github.com/JuliusBrussee/caveman/engine/image"
)

func genPNG(t *testing.T, w, h int) []byte {
	t.Helper()
	img := image.NewNRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.Set(x, y, color.NRGBA{uint8(x % 256), uint8(y % 256), uint8((x + y) % 256), 255})
		}
	}
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func TestAnalyze(t *testing.T) {
	p, ok := cvimage.Analyze(genPNG(t, 800, 600))
	if !ok || p.Width != 800 || p.Height != 600 || p.Format != "png" {
		t.Fatalf("Analyze = %+v ok=%v", p, ok)
	}
	if _, ok := cvimage.Analyze([]byte("not an image")); ok {
		t.Error("non-image must report ok=false")
	}
}

func TestEstimateTokensRequiresModelAndEffectiveDetail(t *testing.T) {
	if got := cvimage.EstimateTokens("openai", 1024, 1024); got != 0 {
		t.Fatalf("legacy provider-only estimate = %d, want honest zero", got)
	}
	cases := []struct {
		provider, model, detail string
		want                    int
		ok                      bool
	}{
		{"openai", "gpt-4o", "high", 765, true},
		{"openai", "gpt-4o-2024-08-06", "high", 765, true},
		{"openai", "gpt-4o-20garbage", "high", 0, false},
		{"openai", "gpt-4o-mini", "low", 2833, true},
		{"openai", "gpt-5.6", "original", 1024, true},
		{"openai", "gpt-5.6", "auto", 1024, true},
		{"openai", "gpt-5.6", "default", 1024, true},
		{"openai", "gpt-5.6", "low", 256, true},
		{"anthropic", "claude-sonnet-4-6", "default", 1369, true},
		{"anthropic", "claude-opus-4-20250514", "default", 1369, true},
		{"anthropic", "claude-opus-4-8-anything", "default", 0, false},
		{"anthropic", "claude-sonnet-4-9", "default", 0, false},
		{"anthropic", "claude-opus-99-1", "default", 0, false},
		{"anthropic", "claude-fable-5", "default", 1369, true},
		{"google", "gemini-3.6-flash", "default", 1120, true},
		{"gemini", "gemini-3.6-flash", "low", 280, true},
		{"google", "gemini-2.5-pro", "low", 64, true},
		{"google", "gemini-2.5-pro", "default", 0, false},
		{"google", "gemini-3-audio", "default", 0, false},
		{"google", "gemini-3.6-flash-anything", "default", 0, false},
		{"openai", "gpt-4.1-mini", "high", 0, false},
		{"openai", "unknown", "high", 0, false},
		{"unknown", "anything", "default", 0, false},
	}
	for _, c := range cases {
		got, ok := cvimage.EstimateTokensForModel(c.provider, c.model, c.detail, 1024, 1024)
		if got != c.want || ok != c.ok {
			t.Errorf("EstimateTokensForModel(%q,%q,%q) = (%d,%v), want (%d,%v)", c.provider, c.model, c.detail, got, ok, c.want, c.ok)
		}
	}
	if got, ok := cvimage.EstimateTokensForModel("google", "gemini-3.6-flash", "default", 100_000_001, 1); ok || got != 0 {
		t.Fatalf("oversized estimate = (%d,%v), want unavailable", got, ok)
	}
	if got, ok := cvimage.EstimateTokensForModel("anthropic", "claude-sonnet-4-6", "default", 1920, 1080); !ok || got != 1560 {
		t.Fatalf("Claude standard 1920x1080 = (%d,%v), want (1560,true)", got, ok)
	}
	if got, ok := cvimage.EstimateTokensForModel("anthropic", "claude-opus-4-7", "default", 1920, 1080); !ok || got != 2691 {
		t.Fatalf("Claude Opus 4.7 high-res 1920x1080 = (%d,%v), want (2691,true)", got, ok)
	}
	if got, ok := cvimage.EstimateTokensForModel("anthropic", "claude-opus-4-20250514", "default", 1920, 1080); !ok || got != 1560 {
		t.Fatalf("Claude 4.0 dated snapshot 1920x1080 = (%d,%v), want (1560,true)", got, ok)
	}
	if got, ok := cvimage.EstimateTokensForModel("anthropic", "claude-opus-4-1-20250805", "default", 1920, 1080); !ok || got != 1560 {
		t.Fatalf("Claude 4.1 dated snapshot 1920x1080 = (%d,%v), want (1560,true)", got, ok)
	}
	if got, ok := cvimage.EstimateTokensForModel("anthropic", "claude-opus-4-8", "default", 1920, 1080); !ok || got != 2691 {
		t.Fatalf("Claude 4.8 1920x1080 = (%d,%v), want (2691,true)", got, ok)
	}
}

func TestDecideFailsSafeTowardKeepingDetail(t *testing.T) {
	p := cvimage.Props{Width: 1024, Height: 1024}
	keep := []string{
		"",                         // empty → keep
		"read the serial number",   // text/OCR → keep
		"how many people are here", // counting → keep
		"transcribe the sign",      // OCR → keep
		"tell me about this image", // ambiguous (no allow-low signal) → keep
	}
	for _, q := range keep {
		if plan := cvimage.Decide(p, q, "openai", "gpt-4o"); plan.Action != cvimage.ActionPassthrough {
			t.Errorf("query %q should keep full detail, got %s", q, plan.Action)
		}
	}
}

func TestDecideLowDetailAndResize(t *testing.T) {
	p := cvimage.Props{Width: 1024, Height: 1024}
	if plan := cvimage.DecideWithDetail(p, "describe the overall scene", "openai", "gpt-4o", "high"); plan.Action != cvimage.ActionDetailLow {
		t.Errorf("openai gpt-4o describe → detail-low, got %s", plan.Action)
	}
	if plan := cvimage.Decide(p, "what is in the background", "anthropic", "claude-sonnet-4-6"); plan.Action != cvimage.ActionResize {
		t.Errorf("anthropic describe → resize, got %s", plan.Action)
	}
	// GPT-4o-mini uses a much larger base than GPT-4o, but high detail adds
	// per-tile tokens to that same base. Exact model math still permits low.
	big := cvimage.Props{Width: 1600, Height: 1200}
	if plan := cvimage.DecideWithDetail(big, "describe the scene", "openai", "gpt-4o-mini", "high"); plan.Action != cvimage.ActionDetailLow {
		t.Errorf("gpt-4o-mini exact high-to-low comparison should choose detail-low, got %s", plan.Action)
	}
	if plan := cvimage.DecideWithDetail(p, "describe the scene", "openai", "future-model", "high"); plan.Action != cvimage.ActionPassthrough {
		t.Errorf("unknown model must pass through, got %s", plan.Action)
	}
	if plan := cvimage.Decide(p, "describe the scene", "openai", "gpt-4o"); plan.Action != cvimage.ActionPassthrough {
		t.Errorf("ambiguous default detail must pass through, got %s", plan.Action)
	}
}

func TestApplyResizeShrinksAndIsDeterministic(t *testing.T) {
	orig := genPNG(t, 1024, 1024)
	plan := cvimage.Plan{Action: cvimage.ActionResize, ResizeLong: 768, Provider: "anthropic", Model: "claude-sonnet-4-6", BeforeDetail: "default"}
	a, tb, ta, ok := cvimage.Apply(orig, plan)
	if !ok {
		t.Fatal("expected a resize result")
	}
	if ta >= tb {
		t.Errorf("tokens should drop: before=%d after=%d", tb, ta)
	}
	props, _ := cvimage.Analyze(a)
	if props.Width != 768 || props.Height != 768 {
		t.Errorf("resized dims = %dx%d, want 768x768", props.Width, props.Height)
	}
	b, _, _, _ := cvimage.Apply(orig, plan)
	if !bytes.Equal(a, b) {
		t.Error("resize is not deterministic")
	}
}

func TestApplyDetailLowKeepsBytes(t *testing.T) {
	orig := genPNG(t, 1024, 1024)
	plan := cvimage.Plan{Action: cvimage.ActionDetailLow, Provider: "openai", Model: "gpt-4o", BeforeDetail: "high"}
	out, tb, ta, ok := cvimage.Apply(orig, plan)
	if !ok {
		t.Fatal("expected detail-low result")
	}
	if !bytes.Equal(out, orig) {
		t.Error("detail-low must leave the image bytes unchanged (gateway sets the flag)")
	}
	if ta != 85 || tb <= ta {
		t.Errorf("detail-low tokens before=%d after=%d (want after=85, before>after)", tb, ta)
	}
}

