package image

import (
	"math"
	"strconv"
	"strings"
	"time"
)

// EstimateTokens retains its signature only; returning zero is a deliberate
// semantic break from the former provider-wide estimate. Current providers use
// model- and media-detail-specific regimes, so callers must migrate to
// EstimateTokensForModel. Honest zero prevents stale math from authorizing a
// lossy transform.
func EstimateTokens(provider string, w, h int) int {
	return 0
}

// EstimateTokensForModel returns documented input-image tokens only when
// provider, model family, and effective detail/media-resolution form a closed
// supported tuple. ok=false means unavailable, never zero-cost. Counts remain
// inferred until provider usage confirms them.
func EstimateTokensForModel(provider, model, detail string, w, h int) (tokens int, ok bool) {
	if w <= 0 || h <= 0 || int64(w) > int64(maxPixels)/int64(h) {
		return 0, false
	}
	provider = normalizeProvider(provider)
	model = normalizeModel(model)
	detail = strings.ToLower(strings.TrimSpace(detail))
	if model == "" || detail == "" {
		return 0, false
	}

	switch provider {
	case "openai":
		return estimateOpenAI(model, detail, w, h)
	case "anthropic":
		return estimateAnthropic(model, detail, w, h)
	case "google":
		return estimateGemini(model, detail)
	default:
		return 0, false
	}
}

func normalizeProvider(p string) string {
	p = strings.ToLower(strings.TrimSpace(p))
	if p == "gemini" {
		return "google"
	}
	return p
}

func normalizeModel(model string) string {
	model = strings.ToLower(strings.TrimSpace(model))
	if i := strings.LastIndex(model, "/"); i >= 0 {
		model = model[i+1:]
	}
	if i := strings.IndexByte(model, '@'); i >= 0 {
		model = model[:i]
	}
	if i := strings.IndexByte(model, ':'); i >= 0 {
		model = model[:i]
	}
	if i := strings.Index(model, "claude-"); i > 0 {
		model = model[i:]
	}
	return strings.TrimSpace(model)
}

func aliasOrDateSnapshot(model, base string) bool {
	if model == base {
		return true
	}
	suffix := strings.TrimPrefix(model, base+"-")
	if suffix == model {
		return false
	}
	_, err := time.Parse("2006-01-02", suffix)
	return err == nil
}

func estimateOpenAI(model, detail string, w, h int) (int, bool) {
	switch {
	case aliasOrDateSnapshot(model, "gpt-4o-mini"):
		switch detail {
		case "low":
			return 2833, true
		case "high":
			return openAITileTokens(w, h, 2833, 5667), true
		default:
			return 0, false
		}
	case aliasOrDateSnapshot(model, "gpt-4o"), aliasOrDateSnapshot(model, "gpt-4.1"), aliasOrDateSnapshot(model, "gpt-4.5"):
		switch detail {
		case "low":
			return 85, true
		case "high":
			return openAITileTokens(w, h, 85, 170), true
		default:
			return 0, false
		}
	case aliasOrDateSnapshot(model, "gpt-5.6"), aliasOrDateSnapshot(model, "gpt-5.6-sol"), aliasOrDateSnapshot(model, "gpt-5.6-terra"), aliasOrDateSnapshot(model, "gpt-5.6-luna"):
		switch detail {
		case "low":
			return 16 * 16, true // provider renders low detail at 512×512, 32px patches
		case "default", "auto", "original":
			return ceilDiv(w, 32) * ceilDiv(h, 32), true
		default:
			// GPT-5.6 high has finite resizing limits not published here; refusing
			// is safer than treating it as original.
			return 0, false
		}
	default:
		return 0, false
	}
}

func estimateAnthropic(model, detail string, w, h int) (int, bool) {
	if detail != "default" {
		return 0, false
	}
	family, major, minor, known := anthropicVersion(model)
	if !known {
		return 0, false
	}
	maxPx, maxTokens := 1568, 1568
	switch {
	case major == 3:
		// Current reference keeps Claude 3.x on the standard profile.
	case major == 4 && minor <= 6:
		// Current reference keeps Claude <=4.6 on the standard profile.
	case major == 4 && family == "opus" && (minor == 7 || minor == 8):
		maxPx, maxTokens = 2576, 4784
	case major == 5 && minor == 0 && (family == "fable" || family == "mythos" || family == "sonnet"):
		maxPx, maxTokens = 2576, 4784
	default:
		// Never infer a future model generation's vision contract.
		return 0, false
	}
	return anthropicPatchTokens(w, h, maxPx, maxTokens), true
}

func anthropicVersion(model string) (family string, major, minor int, ok bool) {
	parts := strings.Split(model, "-")
	if len(parts) < 3 || parts[0] != "claude" {
		return "", 0, 0, false
	}
	// Provider snapshots use an optional YYYYMMDD suffix, and Bedrock may add
	// -vN after it. Strip only those exact suffixes; arbitrary suffixes are not
	// members of a documented model tier.
	if len(parts) >= 2 && isAnthropicRevision(parts[len(parts)-1]) {
		if len(parts) < 3 || !isYYYYMMDD(parts[len(parts)-2]) {
			return "", 0, 0, false
		}
		parts = parts[:len(parts)-2]
	} else if isYYYYMMDD(parts[len(parts)-1]) {
		parts = parts[:len(parts)-1]
	}
	parseVersion := func(s string, allowZero bool) (int, bool) {
		if len(s) < 1 || len(s) > 2 {
			return 0, false
		}
		v, err := strconv.Atoi(s)
		return v, err == nil && (v > 0 || allowZero)
	}
	switch len(parts) {
	case 3: // claude-{family}-{major} or claude-{major}-{family}
		if isAnthropicFamily(parts[1]) {
			family = parts[1]
			major, ok = parseVersion(parts[2], false)
		} else if isAnthropicFamily(parts[2]) {
			family = parts[2]
			major, ok = parseVersion(parts[1], false)
		}
	case 4: // claude-{family}-{major}-{minor} or claude-{major}-{minor}-{family}
		if isAnthropicFamily(parts[1]) {
			family = parts[1]
			major, ok = parseVersion(parts[2], false)
			if ok {
				minor, ok = parseVersion(parts[3], true)
			}
		} else if isAnthropicFamily(parts[3]) {
			family = parts[3]
			major, ok = parseVersion(parts[1], false)
			if ok {
				minor, ok = parseVersion(parts[2], true)
			}
		}
	}
	return family, major, minor, ok
}

func isAnthropicFamily(s string) bool {
	switch s {
	case "sonnet", "opus", "haiku", "fable", "mythos":
		return true
	default:
		return false
	}
}

func isYYYYMMDD(s string) bool {
	if len(s) != 8 {
		return false
	}
	_, err := time.Parse("20060102", s)
	return err == nil
}

func isAnthropicRevision(s string) bool {
	if len(s) < 2 || s[0] != 'v' {
		return false
	}
	_, err := strconv.Atoi(s[1:])
	return err == nil
}

func estimateGemini(model, detail string) (int, bool) {
	switch {
	case isGemini3ImageModel(model):
		switch detail {
		case "low":
			return 280, true
		case "medium":
			return 560, true
		case "default", "high":
			return 1120, true
		case "ultra_high", "ultra-high":
			return 2240, true
		default:
			return 0, false
		}
	case isGemini25ImageModel(model):
		switch detail {
		case "low":
			return 64, true
		case "medium":
			return 256, true
		default:
			// High/default may add pan-and-scan crops; dimensions alone cannot
			// reproduce provider tokenization.
			return 0, false
		}
	default:
		return 0, false
	}
}

func isGemini3ImageModel(model string) bool {
	switch model {
	case "gemini-3-pro", "gemini-3-pro-preview",
		"gemini-3-flash", "gemini-3-flash-preview",
		"gemini-3.1-pro-preview", "gemini-3.1-flash-lite", "gemini-3.1-flash-lite-preview",
		"gemini-3.5-flash", "gemini-3.5-flash-lite", "gemini-3.6-flash":
		return true
	default:
		return false
	}
}

func isGemini25ImageModel(model string) bool {
	switch model {
	case "gemini-2.5-pro", "gemini-2.5-flash", "gemini-2.5-flash-lite":
		return true
	default:
		return false
	}
}

// openAITileTokens scales to fit 2048², then short side to 768px, then bills
// provider-specific base + per-tile tokens.
func openAITileTokens(w, h, base, perTile int) int {
	if w > 2048 || h > 2048 {
		w, h = fitWithin(w, h, 2048)
	}
	short := w
	if h < short {
		short = h
	}
	if short > 768 {
		w, h = scaleShortSideTo(w, h, 768)
	}
	tiles := ceilDiv(w, 512) * ceilDiv(h, 512)
	return base + perTile*tiles
}

func anthropicPatchTokens(w, h, maxPx, maxTokens int) int {
	fits := func(fw, fh int) bool {
		return ceilDiv(fw, 28)*28 <= maxPx && ceilDiv(fh, 28)*28 <= maxPx && ceilDiv(fw, 28)*ceilDiv(fh, 28) <= maxTokens
	}
	if !fits(w, h) {
		swapped := h > w
		if swapped {
			w, h = h, w
		}
		aspect := float64(w) / float64(h)
		lo, hi := 1, w
		for lo+1 < hi {
			mid := lo + (hi-lo)/2
			mh := max(1, int(math.Round(float64(mid)/aspect)))
			if fits(mid, mh) {
				lo = mid
			} else {
				hi = mid
			}
		}
		w, h = lo, max(1, int(math.Round(float64(lo)/aspect)))
		if swapped {
			w, h = h, w
		}
	}
	return ceilDiv(w, 28) * ceilDiv(h, 28)
}

func fitWithin(w, h, max int) (int, int) {
	long := w
	if h > long {
		long = h
	}
	if long <= max {
		return w, h
	}
	nw := w * max / long
	nh := h * max / long
	if nw < 1 {
		nw = 1
	}
	if nh < 1 {
		nh = 1
	}
	return nw, nh
}

func scaleShortSideTo(w, h, target int) (int, int) {
	short := w
	if h < short {
		short = h
	}
	if short <= target {
		return w, h
	}
	nw := w * target / short
	nh := h * target / short
	if nw < 1 {
		nw = 1
	}
	if nh < 1 {
		nh = 1
	}
	return nw, nh
}

func ceilDiv(a, b int) int {
	if b <= 0 {
		return 0
	}
	return (a + b - 1) / b
}

package engine

import "github.com/JuliusBrussee/caveman/engine/compressors"

// Coding agents do not hand this engine files. They hand it what their read tool
// printed: the file with every line prefixed by its number — `1\t{`, `2\t  "unit"`.
// That gutter is part of the presentation, not part of the content, and it defeats
// Detect on the way in. A JSON document arrives not starting with `{`, so
// json.Valid fails and it never reaches the JSON compressor; source arrives
// unparseable, so it never reaches the code compressor. Both fall through to
// `text` and compress nothing.
//
// Unwrapping belongs here rather than inside a compressor, because the gutter is
// orthogonal to content type: it wraps JSON, source, logs, CSV and config alike,
// and each one has to be routed on what it actually is.
type listingWrapper struct {
	source  []byte
	numbers []int
	present bool
}

// unwrapListing separates a line-number gutter from the content it decorates.
// When the input is not a listing it returns the input unchanged and a wrapper
// that rewraps to a no-op, so callers need no branches.
func unwrapListing(input []byte) ([]byte, listingWrapper) {
	source, numbers, ok := compressors.SplitLineNumberedListing(input)
	if !ok {
		return input, listingWrapper{}
	}
	return source, listingWrapper{source: source, numbers: numbers, present: true}
}

// rewrap puts the gutter back on compressed output, keeping each surviving
// line's ORIGINAL number so the numbers still point at the file the agent read.
// It declines when the transform restructured the content rather than eliding
// parts of it — re-encoded JSON has no line that the original numbering
// describes — and then returns the compressed body bare. That is honest: the
// payload already carries a CCR marker saying it was transformed, and no line
// numbers beat numbers that merely look authoritative.
func (l listingWrapper) rewrap(out []byte) []byte {
	if !l.present {
		return out
	}
	rewrapped, ok := compressors.RestoreLineNumberedListing(out, l.source, l.numbers)
	if !ok {
		return out
	}
	return rewrapped
}

package engine

import (
	"encoding/json"
	"strconv"
	"strings"
	"testing"
)

// gutterLines renders content the way a coding agent's read tool prints a file.
func gutterLines(content string) string {
	lines := strings.Split(strings.TrimSuffix(content, "\n"), "\n")
	out := make([]string, len(lines))
	for i, line := range lines {
		out[i] = strconv.Itoa(i+1) + "\t" + line
	}
	return strings.Join(out, "\n") + "\n"
}

func jsonFixture(t *testing.T) string {
	t.Helper()
	type row struct {
		ID     int    `json:"id"`
		Name   string `json:"name"`
		Region string `json:"region"`
		Active bool   `json:"active"`
	}
	rows := make([]row, 60)
	for i := range rows {
		rows[i] = row{ID: i, Name: "node-" + strconv.Itoa(i), Region: "eu-west-1", Active: i%2 == 0}
	}
	raw, err := json.MarshalIndent(map[string]any{"nodes": rows}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	return string(raw) + "\n"
}

// Detect runs on the content, not on the read tool's gutter. Before this, a
// guttered JSON document did not start with '{', json.Valid failed, and it
// routed to text — compressing nothing.
func TestDetectSeesThroughTheReadToolGutter(t *testing.T) {
	e := New(nil, nil)
	content := jsonFixture(t)
	if got := e.Detect([]byte(content)); got != TypeJSON {
		t.Fatalf("plain content detected as %q, want %q", got, TypeJSON)
	}
	if got := e.Detect([]byte(gutterLines(content))); got != TypeJSON {
		t.Fatalf("guttered content detected as %q, want %q — the gutter is hiding the content type", got, TypeJSON)
	}
}

// The whole point: a file the agent read compresses about as well as the file
// itself. Accounting stays against the bytes the caller actually supplied.
func TestGutteredContentCompressesLikeItsContent(t *testing.T) {
	e := New(nil, nil)
	content := jsonFixture(t)

	plain := e.Simulate([]byte(content), Options{Mode: ModeCompress})
	guttered := e.Simulate([]byte(gutterLines(content)), Options{Mode: ModeCompress})

	if plain.TokensSaved == 0 {
		t.Fatal("fixture does not compress at all; the test proves nothing")
	}
	if guttered.TokensSaved == 0 {
		t.Fatal("guttered content compressed nothing — the read tool's gutter is still hiding it")
	}
	// Within a wide band: the gutter itself costs tokens, so the ratios differ.
	if guttered.Ratio < plain.Ratio/2 {
		t.Fatalf("guttered ratio %.3f is far below plain %.3f", guttered.Ratio, plain.Ratio)
	}
	if guttered.TokensBefore != e.counter.Count([]byte(gutterLines(content))) {
		t.Fatal("TokensBefore must count the bytes the caller supplied, gutter included")
	}
}

// Guttered source must reach the code compressor too — that path is what a
// coding agent's Read of a source file produces.
func TestGutteredSourceReachesTheCodeCompressor(t *testing.T) {
	e := New(nil, nil)
	source := `package sample

import "fmt"

func alpha(a int) int {
	total := 0
	for i := 0; i < a; i++ {
		total += i * 3
	}
	fmt.Println(total)
	return total
}

func beta(b string) string {
	trimmed := b + "-suffix"
	return trimmed + "!"
}
`
	res := e.Simulate([]byte(gutterLines(source)), Options{Mode: ModeCompress})
	if res.ContentType != TypeCode {
		t.Fatalf("guttered source detected as %q, want %q", res.ContentType, TypeCode)
	}
	if res.TokensSaved == 0 {
		t.Fatal("guttered source compressed nothing")
	}
}

// Content that is not a listing must be completely unaffected.
func TestNonListingContentIsUntouched(t *testing.T) {
	content := jsonFixture(t)
	body, wrapper := unwrapListing([]byte(content))
	if wrapper.present {
		t.Fatal("plain content was mistaken for a listing")
	}
	if string(body) != content {
		t.Fatal("plain content was altered")
	}
	if got := string(wrapper.rewrap([]byte("unchanged"))); got != "unchanged" {
		t.Fatalf("rewrap on a non-listing altered output: %q", got)
	}
}

// record mode never transforms, gutter or no gutter.
func TestRecordModeStillNeverTransformsAListing(t *testing.T) {
	e := New(nil, nil)
	input := []byte(gutterLines(jsonFixture(t)))
	res, err := e.Compress(input, Options{Mode: ModeRecord})
	if err != nil {
		t.Fatal(err)
	}
	if string(res.Output) != string(input) {
		t.Fatal("record mode transformed a listing")
	}
	if res.TokensAfter != res.TokensBefore {
		t.Fatal("record mode claimed a reduction")
	}
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"os"
	"regexp"
	"strings"
)

var variantTagRE = regexp.MustCompile(`\[[^\]]*\]`)

func AllowedModelBases() []string {
	raw, ok := os.LookupEnv("CAVE_PIXEL_MODELS")
	if !ok || strings.TrimSpace(raw) == "" {
		return []string{"claude-fable-5", "gpt-5.6"}
	}
	trimmed := strings.TrimSpace(raw)
	if falseyModelList(trimmed) {
		return []string{}
	}
	parts := strings.Split(trimmed, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		if s := strings.TrimSpace(part); s != "" {
			out = append(out, s)
		}
	}
	return out
}

func Allowed(model string) bool {
	if model == "" {
		return false
	}
	for _, candidate := range modelCandidates(variantTagRE.ReplaceAllString(model, "")) {
		for _, base := range AllowedModelBases() {
			if candidate == base || strings.HasPrefix(candidate, base+"-") {
				return true
			}
		}
	}
	return false
}

func falseyModelList(v string) bool {
	switch strings.ToLower(strings.TrimSpace(v)) {
	case "0", "false", "no", "off", "none":
		return true
	default:
		return false
	}
}

func modelCandidates(model string) []string {
	segs := strings.FieldsFunc(model, func(r rune) bool { return r == '.' || r == '/' })
	out := make([]string, 0, 1+len(segs)*4)
	out = appendModelCandidate(out, model)
	for i := range segs {
		if segs[i] == "" {
			continue
		}
		out = appendModelCandidate(out, strings.Join(segs[i:], "."))
		out = appendModelCandidate(out, strings.Join(segs[i:], "/"))
		if i == len(segs)-1 {
			out = appendModelCandidate(out, segs[i])
		}
	}
	return out
}

func appendModelCandidate(out []string, candidate string) []string {
	if candidate == "" {
		return out
	}
	out = append(out, candidate)
	if base, _, ok := strings.Cut(candidate, "@"); ok && base != "" {
		out = append(out, base)
	}
	return out
}

