func TestAllowedDefaultModels(t *testing.T) {
	t.Setenv("CAVE_PIXEL_MODELS", "")
	if !reflect.DeepEqual(AllowedModelBases(), []string{"claude-fable-5", "gpt-5.6"}) {
		t.Fatalf("default bases = %#v", AllowedModelBases())
