	if !strings.Contains(sheet, "DEPLOY-77 ×3") || !strings.Contains(sheet, "×N marks a token that occurs N times") || strings.Contains(sheet, "9d121ac ×") {
		t.Fatalf("repeat annotation mismatch: %s", sheet)
