func TestFactSheetAllPagesCounts(t *testing.T) {
	lines := make([]string, 300)
	for i := range lines {
		lines[i] = fmt.Sprintf("2026-07-26T09:40:41Z WARN svc=ingest req=%x shard=12 msg=processed batch %d ok", 0x10000000+i*7919, 10000+i)
	}
	lines[137] += " AUDIT-ZX9"
	lines[201] += " AUDIT-ZX9"
	entries := ExtractFactSheetEntries(strings.Join(lines, "\n"))
	if hit := findEntry(entries, "AUDIT-ZX9"); hit == nil || hit.Count != 2 {
		t.Fatalf("AUDIT-ZX9 count mismatch: %#v", hit)
	}
	page := strings.Repeat("x", 90) + " TICK-42 "
	kept, _ := ExtractFactSheetEntriesAllPages(strings.Repeat(page, 5), 100)
	if hit := findEntry(kept, "TICK-42"); hit == nil || hit.Count != 5 {
		t.Fatalf("TICK-42 all-pages count mismatch: %#v", hit)
	}
}

func containsString(list []string, want string) bool {
	for _, got := range list {
		if got == want {
			return true
		}
	}
	return false
}

func findEntry(entries []FactSheetEntry, token string) *FactSheetEntry {
	for i := range entries {
		if entries[i].Token == token {
			return &entries[i]
		}
	}
	return nil
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import "math"

const (
	ImageCostSafetyMargin = 1.10
	CacheCreateRate       = 1.25
	CacheReadRate         = 0.10
	CharsPerToken         = 4.0
	SlabCharsPerToken     = 2.0
	HistoryCharsPerToken  = 2.0
)

var LinesPerImage = max(1, (MaxHeightPx-2*PadY)/CellH)

type GateEval struct {
	ImageTokens, TextTokens     float64
	BurnImageSide, BurnTextSide float64
	Profitable                  bool
}

func singleColWidthPx(cols int) int {
	return 2*PadX + cols*CellW
}

func multiColWidthPx(cols, numCols int) int {
	n := max(1, numCols)
	if n == 1 {
		return singleColWidthPx(cols)
	}
	return MultiColWidth(cols, n)
}

// heightForRows is the reference page height for a page holding `rows` rows at
// the given pitch and glyph height: 2*pad + (rows-1)*pitch + glyphH.
func heightForRows(rows, pitch, glyphH int) int {
	if rows <= 0 {
		return 2 * PadY
	}
	return 2*PadY + (rows-1)*pitch + glyphH
}

func imageTokensForRows(visualRows, cols, numCols, imageCountCap, maxCharsPerImage int, rp renderParams) float64 {
	if visualRows <= 0 {
		return 0
	}
	n := max(1, numCols)
	if maxCharsPerImage <= 0 {
		maxCharsPerImage = ReadableCharsPerImage
	}
	// The multi-column renderer draws at conservative geometry (CellW/CellH, std
	// tier) and never honours density levers, so price it that way. Single-column
	// pages price the profile's actual geometry — cell-advance width, pitch, tier
	// canvas height — so the gate prices exactly the page that will render.
	var widthPx, pitch, glyphH int
	tier := rp.Tier
	if n > 1 {
		widthPx = multiColWidthPx(cols, n)
		pitch, glyphH = CellH, CellH
		tier = StandardPixelTier
	} else {
		widthPx = rp.pageWidthPx(cols)
		pitch, glyphH = rp.PitchY, CellH
	}
	// Rows-per-image, columns and layers all flow from the one shared seam so the
	// gate, the splitter and the truncator agree. A 2-layer (max) image stacks
	// `layers` text layers into the SAME pixel height, so it holds `layers×` the
	// lines per image while costing the same per-image tokens as a single-layer
	// page — the gate parity that makes max profitable exactly where balanced is.
	rowsPerImage, _, layers := rp.imageRowGeometry(cols, n, maxCharsPerImage)
	linesPerImage := rowsPerImage * n * layers
	imagesNeeded := int(math.Ceil(float64(visualRows) / float64(linesPerImage)))
	if imageCountCap > 0 && imagesNeeded > imageCountCap {
		imagesNeeded = imageCountCap
	}
	fullImages := max(0, imagesNeeded-1)
	linesInLast := visualRows - fullImages*linesPerImage
	rowsInLast := min(max(1, linesInLast), rowsPerImage)
	fullImageHeight := heightForRows(rowsPerImage, pitch, glyphH)
	lastImageHeight := heightForRows(rowsInLast, pitch, glyphH)
	// Each rendered image is a separate Anthropic image block, priced (and
	// capped) independently on its own patch grid; sum the per-image tokens,
	// then apply the conservative safety margin once.
	perFull := AnthropicImageTokens(widthPx, fullImageHeight, tier)
	perLast := AnthropicImageTokens(widthPx, lastImageHeight, tier)
	totalTokens := fullImages*perFull + perLast
	return math.Ceil(float64(totalTokens) * ImageCostSafetyMargin)
}

func imageTokensCost(text string, cols, numCols, imageCountCap int, shrinkWidth bool, maxCharsPerImage int, rp renderParams) float64 {
	effectiveCols := cols
	if shrinkWidth {
		effectiveCols = MeasureContentCols(text, cols, 1)
	}
	rows := CountVisualRows(text, effectiveCols)
	return imageTokensForRows(rows, effectiveCols, numCols, imageCountCap, maxCharsPerImage, rp)
}

func EvalCompressionProfitability(text string, cols, imageCountCap, numCols int, charsPerToken, priorWarmTokens, priorWarmImageTokens float64, shrinkWidth bool, rp renderParams) *GateEval {
	if text == "" {
		return nil
	}
	cpt := charsPerToken
	if !isFinitePositive(cpt) {
		cpt = CharsPerToken
	}
	// Price against the profile's full-page character budget so single-column
	// pages fill the tier's canvas; the multi-column renderer stays on the fixed
	// readable cap. For std-conservative both are 28080, preserving old pricing.
	budget := rp.charBudget()
	if max(1, numCols) > 1 {
		budget = ReadableCharsPerImage
	}
	imageTokens := imageTokensCost(text, cols, max(1, numCols), imageCountCap, shrinkWidth, budget, rp)
	textTokens := float64(jsLen(text)) / cpt
	burnImageSide := 0.0
	if isFinitePositive(priorWarmTokens) {
		burnImageSide = priorWarmTokens * (CacheCreateRate - CacheReadRate)
	}
	burnTextSide := 0.0
	if isFinitePositive(priorWarmImageTokens) {
		burnTextSide = priorWarmImageTokens * (CacheCreateRate - CacheReadRate)
	}
	return &GateEval{
		ImageTokens:   imageTokens,
		TextTokens:    textTokens,
		BurnImageSide: burnImageSide,
		BurnTextSide:  burnTextSide,
		Profitable:    imageTokens+burnImageSide < textTokens+burnTextSide,
	}
}

func IsCompressionProfitable(text string, cols, imageCountCap, numCols int, cpt, priorWarm, priorWarmImage float64, shrinkWidth bool, maxCharsPerImage int, rp renderParams) bool {
	if text == "" {
		return false
	}
	if cols == 0 {
		cols = DefaultCols
	}
	if maxCharsPerImage == 0 {
		maxCharsPerImage = ReadableCharsPerImage
	}
	if !isFinitePositive(cpt) {
		cpt = CharsPerToken
	}
	imageTokens := imageTokensCost(text, cols, max(1, numCols), imageCountCap, shrinkWidth, maxCharsPerImage, rp)
	textTokens := float64(jsLen(text)) / cpt
	burnImageSide := 0.0
	if isFinitePositive(priorWarm) {
		burnImageSide = priorWarm * (CacheCreateRate - CacheReadRate)
	}
	burnTextSide := 0.0
	if isFinitePositive(priorWarmImage) {
		burnTextSide = priorWarmImage * (CacheCreateRate - CacheReadRate)
	}
	return imageTokens+burnImageSide < textTokens+burnTextSide
}

func IsCompressionProfitableAmortized(text string, cols, imageCountCap, numCols int, charsPerToken float64, horizon int, priorWarmTokens, priorWarmImageTokens float64, shrinkWidth bool, maxCharsPerImage int, rp renderParams) bool {
	if horizon <= 1 {
		return IsCompressionProfitable(text, cols, imageCountCap, numCols, charsPerToken, priorWarmTokens, priorWarmImageTokens, shrinkWidth, maxCharsPerImage, rp)
	}
	if text == "" {
		return false
	}
	if maxCharsPerImage == 0 {
		maxCharsPerImage = ReadableCharsPerImage
	}
	cpt := charsPerToken
	if !isFinitePositive(cpt) {
		cpt = CharsPerToken
	}
	n := max(1, numCols)
	imageTokens := imageTokensCost(text, cols, n, imageCountCap, shrinkWidth, maxCharsPerImage, rp)
	textTokens := float64(jsLen(text)) / cpt
	N := max(2, horizon)
	imageLifetime := imageTokens * (CacheCreateRate + CacheReadRate*float64(N-1))
	textLifetime := textTokens * CacheReadRate * float64(N)
	burnImageSide := 0.0
	if isFinitePositive(priorWarmTokens) {
		burnImageSide = priorWarmTokens * (CacheCreateRate - CacheReadRate)
	}
	burnTextSide := 0.0
	if isFinitePositive(priorWarmImageTokens) {
		burnTextSide = priorWarmImageTokens * (CacheCreateRate - CacheReadRate)
	}
	return imageLifetime+burnImageSide < textLifetime+burnTextSide
}

func isFinitePositive(v float64) bool {
	return !math.IsNaN(v) && !math.IsInf(v, 0) && v > 0
}

func MaxCharsPerImage(cols int) int {
	return min(cols*LinesPerImage, ReadableCharsPerImage)
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"math"
	"strings"
	"testing"
)

func TestGateAntiFlap(t *testing.T) {
	if !IsCompressionProfitable(strings.Repeat("x", 50000), 100, 0, 2, 4, 0, 0, true, ReadableCharsPerImage, conservativeStdParams) {
		t.Fatal("clearly-profitable cold case rejected")
	}

	text := strings.Repeat("x", 12000)
	cold := IsCompressionProfitable(text, 100, 0, 2, 4, 0, 0, true, ReadableCharsPerImage, conservativeStdParams)
	warmText := IsCompressionProfitable(text, 100, 0, 2, 4, 50000, 0, true, ReadableCharsPerImage, conservativeStdParams)
	if cold && warmText {
		t.Fatal("warm text side did not pin session in text mode")
	}

	cheapText := strings.Repeat("hello", 500)
	if IsCompressionProfitable(cheapText, 100, 0, 1, 50, 0, 0, true, ReadableCharsPerImage, conservativeStdParams) {
		t.Fatal("cold cheap-text case accepted")
	}
	if !IsCompressionProfitable(cheapText, 100, 0, 1, 50, 0, 60000, true, ReadableCharsPerImage, conservativeStdParams) {
		t.Fatal("warm image side did not pin session in image mode")
	}

	both := IsCompressionProfitable(text, 100, 0, 2, 4, 25000, 25000, true, ReadableCharsPerImage, conservativeStdParams)
	if both != cold {
		t.Fatalf("symmetric burn changed verdict: both=%v cold=%v", both, cold)
	}
}

func TestEvalCompressionProfitability(t *testing.T) {
	samples := []struct {
		text     string
		warmText float64
		warmImg  float64
	}{
		{strings.Repeat("x", 50000), 0, 0},
		{strings.Repeat("x", 12000), 50000, 0},
		{strings.Repeat("hello", 500), 0, 60000},
		{strings.Repeat("x", 12000), 25000, 25000},
	}
	for _, sample := range samples {
		e := EvalCompressionProfitability(sample.text, 100, 0, 2, 4, sample.warmText, sample.warmImg, true, conservativeStdParams)
		if e == nil {
			t.Fatal("EvalCompressionProfitability returned nil")
		}
		verdict := IsCompressionProfitable(sample.text, 100, 0, 2, 4, sample.warmText, sample.warmImg, true, ReadableCharsPerImage, conservativeStdParams)
		if e.Profitable != verdict {
			t.Fatalf("eval verdict = %v, want %v", e.Profitable, verdict)
		}
	}

	e := EvalCompressionProfitability(strings.Repeat("x", 12000), 100, 0, 2, 4, 40000, 60000, true, conservativeStdParams)
	if e == nil {
		t.Fatal("nil eval")
	}
	if math.Abs(e.BurnImageSide-40000*1.15) > 0.00001 {
		t.Fatalf("BurnImageSide = %f", e.BurnImageSide)
	}
	if math.Abs(e.BurnTextSide-60000*1.15) > 0.00001 {
		t.Fatalf("BurnTextSide = %f", e.BurnTextSide)
	}
	if e.ImageTokens <= 0 || e.TextTokens <= 0 {
		t.Fatalf("non-positive token terms: %+v", e)
	}
	if EvalCompressionProfitability("", 100, 0, 1, 4, 0, 0, true, conservativeStdParams) != nil {
		t.Fatal("empty text eval should be nil")
	}
}

func TestGateAmortizedAndMaxChars(t *testing.T) {
	text := strings.Repeat("x", 50000)
	cold := IsCompressionProfitableAmortized(text, 100, 0, 2, 4, 1, 0, 0, true, ReadableCharsPerImage, conservativeStdParams)
	base := IsCompressionProfitable(text, 100, 0, 2, 4, 0, 0, true, ReadableCharsPerImage, conservativeStdParams)
	if cold != base {
		t.Fatalf("horizon=1 = %v, want base %v", cold, base)
	}
	if MaxCharsPerImage(100) != 9000 {
		t.Fatalf("MaxCharsPerImage(100) = %d, want 9000", MaxCharsPerImage(100))
	}
	if MaxCharsPerImage(313) != ReadableCharsPerImage {
		t.Fatalf("MaxCharsPerImage(313) = %d, want %d", MaxCharsPerImage(313), ReadableCharsPerImage)
	}
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"bytes"
	"compress/gzip"
	"os"
	"path/filepath"
	"testing"
)

// intendedGlyphs holds the caveman-local glyph surgery applied on top of the
// pxpipe 5x8 atlas (both the 1-bit and grayscale planes carry identical
// 0/255 coverage for these ASCII glyphs). Mirrors the intent of the upstream
// (which the sandbox has no network to fetch byte-for-byte):
//   - backtick and apostrophe are made unambiguous — backtick is a top-left
//     stroke leaning down-right (a grave accent), apostrophe a top-right stroke
//     leaning down-left. Readers were confusing the two.
//   - K gains real diagonal arms so it can no longer read as H (they previously
//     differed by a single pixel).
//
// TestGlyphAtlasSurgery asserts the embedded atlas matches these; run
// TestRegenGlyphAtlas with REGEN_GLYPHS=1 to re-derive the .bin.gz assets.
var intendedGlyphs = map[rune][8]string{
	'`': {
		"#....",
		".#...",
		".....",
		".....",
		".....",
		".....",
		".....",
		".....",
	},
	'\'': {
		"...#.",
		"..#..",
		".#...",
		".....",
		".....",
		".....",
		".....",
		".....",
	},
	'K': {
		".....",
		"#..#.",
		"#.#..",
		"##...",
		"##...",
		"#.#..",
		"#..#.",
		".....",
	},
}

// glyphH is the unchanged H, kept here so the tests can prove K stays distinct
// from it without depending on the embedded bytes it is being compared against.
var glyphH = [8]string{
	".....",
	"#..#.",
	"#..#.",
	"####.",
	"#..#.",
	"#..#.",
	"#..#.",
	".....",
}

func glyphBits(cp rune) [8]string {
	rank := AtlasRank(cp)
	var out [8]string
	for row := 0; row < AtlasCellH; row++ {
		line := make([]byte, AtlasCellW)
		for col := 0; col < AtlasCellW; col++ {
			if atlasBit(rank, row, col) == 1 {
				line[col] = '#'
			} else {
				line[col] = '.'
			}
		}
		out[row] = string(line)
	}
	return out
}

func symDiff(a, b [8]string) int {
	n := 0
	for row := 0; row < AtlasCellH; row++ {
		for col := 0; col < AtlasCellW; col++ {
			if (a[row][col] == '#') != (b[row][col] == '#') {
				n++
			}
		}
	}
	return n
}

func TestGlyphAtlasSurgery(t *testing.T) {
	// Each edited glyph must match the intended bitmap in BOTH atlas planes.
	for cp, want := range intendedGlyphs {
		rank := AtlasRank(cp)
		grank := AtlasGrayRank(cp)
		if rank < 0 || grank < 0 {
			t.Fatalf("%q missing from atlas (rank=%d gray=%d)", string(cp), rank, grank)
		}
		for row := 0; row < AtlasCellH; row++ {
			for col := 0; col < AtlasCellW; col++ {
				on := want[row][col] == '#'
				if (atlasBit(rank, row, col) == 1) != on {
					t.Fatalf("%q 1-bit (%d,%d) = %d, want %v", string(cp), row, col, atlasBit(rank, row, col), on)
				}
				gray := atlasGrayByte(grank, row, col)
				if on && gray != 255 {
					t.Fatalf("%q gray (%d,%d) = %d, want 255", string(cp), row, col, gray)
				}
				if !on && gray != 0 {
					t.Fatalf("%q gray (%d,%d) = %d, want 0", string(cp), row, col, gray)
				}
			}
		}
	}

	// H must be untouched, so K vs H distinctness is measured against the real H.
	if got := glyphBits('H'); got != glyphH {
		t.Fatalf("H changed unexpectedly: %v", got)
	}

	// Distinctness: the whole point of the surgery.
	if d := symDiff(intendedGlyphs['`'], intendedGlyphs['\'']); d < 4 {
		t.Fatalf("backtick vs apostrophe differ by only %d pixels", d)
	}
	if d := symDiff(intendedGlyphs['K'], glyphH); d < 4 {
		t.Fatalf("K vs H differ by only %d pixels", d)
	}
	// K must carry diagonal ink in the interior columns (1..3) that H lacks —
	// that is what makes it read as a K and not an H.
	interiorK := 0
	for row := 1; row < 7; row++ {
		for col := 1; col < 4; col++ {
			if intendedGlyphs['K'][row][col] == '#' && glyphH[row][col] != '#' {
				interiorK++
			}
		}
	}
	if interiorK < 2 {
		t.Fatalf("K has only %d diagonal pixels absent in H", interiorK)
	}
}

// TestRegenGlyphAtlas rewrites atlas-pixels.bin.gz and atlasgray-pixels.bin.gz
// with intendedGlyphs applied. Glyph dimensions are unchanged, so the offset,
// codepoint and wide-flag tables stay valid — only the two pixel planes move.
func TestRegenGlyphAtlas(t *testing.T) {
	if os.Getenv("REGEN_GLYPHS") == "" {
		t.Skip("set REGEN_GLYPHS=1 to regenerate the glyph atlas")
	}
	loadAtlas()
	pix := append([]uint8(nil), atlasPixels...)
	gpix := append([]uint8(nil), atlasGrayPixels...)

	for cp, want := range intendedGlyphs {
		rank := AtlasRank(cp)
		grank := AtlasGrayRank(cp)
		if atlasWideFlags[rank] != 0 || atlasGrayWideFlags[grank] != 0 {
			t.Fatalf("%q is wide; surgery assumes 5x8", string(cp))
		}
		bitBase := int(atlasOffsets[rank])
		grayBase := int(atlasGrayOffsets[grank])
		for row := 0; row < AtlasCellH; row++ {
			for col := 0; col < AtlasCellW; col++ {
				on := want[row][col] == '#'
				bitIdx := bitBase + row*AtlasCellW + col
				mask := byte(1) << (7 - (bitIdx & 7))
				if on {
					pix[bitIdx>>3] |= mask
				} else {
					pix[bitIdx>>3] &^= mask
				}
				gidx := grayBase + row*AtlasGrayCellW + col
				if on {
					gpix[gidx] = 255
				} else {
					gpix[gidx] = 0
				}
			}
		}
	}

	writeGzip(t, filepath.Join("assets", "atlas-pixels.bin.gz"), pix)
	writeGzip(t, filepath.Join("assets", "atlasgray-pixels.bin.gz"), gpix)
}

func writeGzip(t *testing.T, path string, raw []byte) {
	t.Helper()
	var buf bytes.Buffer
	zw, err := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := zw.Write(raw); err != nil {
		t.Fatal(err)
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
}

