		t.Fatalf("chat history synthetic intro missing")
	}
	if !strings.Contains(serialized, openAILiveMarker) {
		t.Fatalf("chat live prompt should stay text")
	}
}

func openAIPlainTurns(n, chars int) []GptHistoryTurn {
	out := make([]GptHistoryTurn, n)
	for i := 0; i < n; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		out[i] = GptHistoryTurn{Text: "--- " + role + " ---\n" + strings.Repeat("x", chars)}
	}
	return out
}

func openAITurnsWithUser(n int, userIndices map[int]bool) []GptHistoryTurn {
	out := make([]GptHistoryTurn, n)
	for i := 0; i < n; i++ {
		isUser := userIndices[i]
		role := "assistant"
		body := "assistant work " + strconvItoa(i) + " " + strings.Repeat("alpha beta gamma delta epsilon ", 60)
		if isUser {
			role = "user"
			body = "USER REQUEST " + strconvItoa(i) + " " + strings.Repeat("alpha beta gamma delta epsilon ", 60)
		}
		turn := GptHistoryTurn{Text: "<" + role + " t=\"" + strconvItoa(i) + "\">\n" + body + "\n</" + role + ">"}
		if isUser {
			text := body
			turn.UserText = &text
		}
		out[i] = turn
	}
	return out
}

func buildOpenAIResponsesInput(turns int) []any {
	items := []any{map[string]any{"role": "user", "content": strings.Repeat(openAIOpeningMarker+" ", 40)}}
	for i := 0; i < turns; i++ {
		id := "call_" + strconvItoa(i)
		items = append(items,
			map[string]any{"role": "assistant", "content": strings.Repeat("Working on step "+strconvItoa(i)+". ", 30)},
			map[string]any{"type": "function_call", "call_id": id, "name": "read", "arguments": `{"path":"f` + strconvItoa(i) + `"}`},
			map[string]any{"type": "function_call_output", "call_id": id, "output": strings.Repeat("result "+strconvItoa(i)+" ", 50)},
		)
		content := strings.Repeat("Continue with "+strconvItoa(i)+". ", 20)
		if i == turns-1 {
			content = strings.Repeat(openAILiveMarker+" ", 20)
		}
		items = append(items, map[string]any{"role": "user", "content": content})
	}
	return items
}

func buildOpenAIChatMessages(turns int) []any {
	msgs := []any{
		map[string]any{"role": "system", "content": strings.Repeat("You are a coding agent with detailed instructions. ", 80)},
		map[string]any{"role": "user", "content": strings.Repeat(openAIOpeningMarker+" ", 40)},
	}
	for i := 0; i < turns; i++ {
		id := "call_" + strconvItoa(i)
		msgs = append(msgs,
			map[string]any{
				"role":    "assistant",
				"content": strings.Repeat("Working on step "+strconvItoa(i)+". ", 30),
				"tool_calls": []any{map[string]any{
					"id":       id,
					"type":     "function",
					"function": map[string]any{"name": "read", "arguments": `{"path":"f` + strconvItoa(i) + `"}`},
				}},
			},
			map[string]any{"role": "tool", "tool_call_id": id, "content": strings.Repeat("result "+strconvItoa(i)+" ", 50)},
		)
		content := strings.Repeat("Continue with "+strconvItoa(i)+". ", 20)
		if i == turns-1 {
			content = strings.Repeat(openAILiveMarker+" ", 20)
		}
		msgs = append(msgs, map[string]any{"role": "user", "content": content})
	}
	return msgs
}

func reflectStringSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func unmarshalJSONTest(t *testing.T, b []byte) any {
	t.Helper()
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

#!/usr/bin/env node
import { gzipSync } from 'node:zlib';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, join, resolve } from 'node:path';

const HEADER = {
  atlas: { ATLAS_CELL_W: 5, ATLAS_CELL_H: 8 },
  gray: { ATLAS_GRAY_CELL_W: 5, ATLAS_GRAY_CELL_H: 8 },
};

function usage() {
  console.error('usage: node public/engine/pixel/internal/atlasgen/extract-atlas.mjs <pxpipe-root>');
  process.exit(2);
}

const pxpipeRoot = process.argv[2] ? resolve(process.argv[2]) : '';
if (!pxpipeRoot) usage();

const repoRoot = resolve(new URL('../../../../..', import.meta.url).pathname);
const outDir = join(repoRoot, 'public/engine/pixel/assets');
mkdirSync(outDir, { recursive: true });

function readSource(rel) {
  return readFileSync(join(pxpipeRoot, rel), 'utf8');
}

function constNumber(src, name) {
  const re = new RegExp(`export\\s+const\\s+${name}\\s*=\\s*(\\d+)\\s*;`);
  const m = src.match(re);
  if (!m) throw new Error(`[extract-atlas] missing numeric const ${name}`);
  return Number(m[1]);
}

function constB64(src, name) {
  const re = new RegExp(`const\\s+${name}\\s*=\\s*"([^"]+)"\\s*;`);
  const m = src.match(re);
  if (!m) throw new Error(`[extract-atlas] missing base64 const ${name}`);
  return Buffer.from(m[1], 'base64');
}

function assertHeader(src, expected) {
  for (const [name, want] of Object.entries(expected)) {
    const got = constNumber(src, name);
    if (got !== want) {
      throw new Error(`[extract-atlas] ${name}=${got}, want ${want}`);
    }
  }
}

function writeBlob(name, bytes) {
  const out = join(outDir, name);
  writeFileSync(out, gzipSync(bytes, { level: 9 }));
  console.log(`${basename(out)} raw=${bytes.length} gzip=${readFileSync(out).length}`);
}

const atlas = readSource('src/core/atlas.ts');
const gray = readSource('src/core/atlas-gray.ts');
assertHeader(atlas, HEADER.atlas);
assertHeader(gray, HEADER.gray);

writeBlob('atlas-codepoints.bin.gz', constB64(atlas, 'CODEPOINTS_B64'));
writeBlob('atlas-offsets.bin.gz', constB64(atlas, 'OFFSETS_B64'));
writeBlob('atlas-wideflags.bin.gz', constB64(atlas, 'WIDE_FLAGS_B64'));
writeBlob('atlas-pixels.bin.gz', constB64(atlas, 'PIXELS_B64'));
writeBlob('atlasgray-codepoints.bin.gz', constB64(gray, 'GRAY_CODEPOINTS_B64'));
writeBlob('atlasgray-offsets.bin.gz', constB64(gray, 'GRAY_OFFSETS_B64'));
writeBlob('atlasgray-wideflags.bin.gz', constB64(gray, 'GRAY_WIDE_FLAGS_B64'));
writeBlob('atlasgray-pixels.bin.gz', constB64(gray, 'GRAY_PIXELS_B64'));

