mkdirSync(outDir, { recursive: true });

const render = await import(pathToFileURL(join(pxpipeRoot, 'src/core/render.ts')).href);

const corpus = [
  {
    id: 'ascii_code',
    text: [
      'func main() {',
      '\tfmt.Println("caveman pixel")   ',
      '}',
      '',
      '// byte-stable render sample',
