      file,
      width: images[i].width,
      height: images[i].height,
      charsRendered: images[i].charsRendered,
      droppedChars: images[i].droppedChars,
    });
  }
  entries.push({
    id: `${input.id}/${mode}`,
    text: input.text,
    mode,
    options,
    images: imageMeta,
  });
}

for (const input of corpus) {
  await addEntry(
    input,
    'single',
    (text) => render.renderTextToPngs(text, 80, {}),
