// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.
//
// The 2-layer red/blue overlay renderer for the `max` density level. Two full
// pages of text are drawn into ONE image as red and blue ink layers and
// subtractively composited, porting the overlay operation from pxcore.py.

package pixel

import (
	"math"
	"strings"
)

// overlayLayerColors are the two ink colours for a max-level overlay page, taken
// verbatim from pxcore.py overlay(): layer 1 dark red, layer 2 dark blue, both
// drawn in place (dx=dy=0, configured geometry). White stays white; where red and
// blue ink overlap the subtractive multiply drives the pixel dark.
var overlayLayerColors = [2][3]uint8{
	{215, 15, 15}, // layer 1 (red)
	{15, 15, 215}, // layer 2 (blue)
}

// compositeTwoLayers is the subtractive multiply from pxcore.py overlay(). Each
// layer is inked over white using its coverage alpha (region*(1-a)+color*a),
// then the layers multiply: out = (L1/255)·(L2/255)·255, rounded once at the
// end. cov1/cov2 hold per-pixel ink coverage (0..255) for the red/blue layers.
func compositeTwoLayers(cov1, cov2 []uint8, c1, c2 [3]uint8) []uint8 {
	n := len(cov1)
	rgb := make([]uint8, n*3)
	for i := 0; i < n; i++ {
		a1 := float64(cov1[i]) / 255
		a2 := float64(cov2[i]) / 255
		for ch := 0; ch < 3; ch++ {
			l1 := 255*(1-a1) + float64(c1[ch])*a1
			l2 := 255*(1-a2) + float64(c2[ch])*a2
			v := math.Round(l1 * l2 / 255)
			if v < 0 {
				v = 0
			} else if v > 255 {
				v = 255
			}
			rgb[i*3+ch] = uint8(v)
		}
	}
	return rgb
}

// blitLayerCoverage stamps one glyph's grayscale coverage (max-blend) into a
// coverage framebuffer. It mirrors blitGlyphGray but is bounds-guarded on both
// axes so a stray wide glyph at the page edge can never panic the request path.
func blitLayerCoverage(cov []uint8, fbW, fbH, x, y int, cp rune) int {
	rank := AtlasGrayRank(cp)
	if rank < 0 {
		return 0
	}
	wide := atlasGrayWideFlags[rank] == 1
	srcW := AtlasGrayCellW
	if wide {
		srcW = 2 * AtlasGrayCellW
	}
	srcOff := int(atlasGrayOffsets[rank])
	for gy := 0; gy < AtlasGrayCellH; gy++ {
		py := y + gy
		if py < 0 || py >= fbH {
			continue
		}
		srcRow := srcOff + gy*srcW
		for gx := 0; gx < srcW; gx++ {
			px := x + gx
			if px < 0 || px >= fbW {
				continue
			}
			coverage := atlasGrayPixels[srcRow+gx]
			if coverage > 0 {
				idx := py*fbW + px
				if coverage > cov[idx] {
					cov[idx] = coverage
				}
			}
		}
	}
	if wide {
		return 2
	}
	return 1
}

// renderLayerCoverage rasterises one layer's wrapped lines into a coverage
// framebuffer of the shared geometry. Advance-based columns match WrapLines and
// the single-layer renderer; dropped glyphs are counted, not drawn.
func renderLayerCoverage(lines []string, width, height, cols, cellW, pitch int) ([]uint8, int, map[rune]int) {
	cov := make([]uint8, width*height)
	dropped := make(map[rune]int)
	droppedChars := 0
	for row, line := range lines {
		baseY := PadY + row*pitch
		col := 0
		for _, r := range line {
			if col >= cols {
				break
			}
			baseX := PadX + col*cellW
			advance := blitLayerCoverage(cov, width, height, baseX, baseY, r)
			if advance == 0 {
				droppedChars++
				dropped[r]++
				col++
			} else {
				col += advance
			}
		}
	}
	return cov, droppedChars, dropped
}

// renderTwoLayerChunk draws one overlay page: redLines in the red layer and
// blueLines in the blue layer, sharing identical geometry. When blueLines is
// empty the page holds a single layer, so it renders exactly like a 1-layer page
// in mono BLACK ink (never red) and carries no 2-layer reader burden. Both
// layers' rendered/dropped chars are counted.
func renderTwoLayerChunk(redLines, blueLines []string, cols int, style RenderStyle, maxHeightPx int) (RenderedImage, error) {
	if cols < 1 {
		cols = 1
	}
	if maxHeightPx == 0 {
		maxHeightPx = MaxHeightPx
	}
	if len(blueLines) == 0 {
		// Single-layer fallback: a page with only a red layer is drawn as an
		// ordinary mono-black page (not red) so no red/blue instruction is owed.
		mono := RenderStyle{
			AA:         style.AA,
			CellWBonus: style.CellWBonus,
			CellHBonus: style.CellHBonus,
			PitchY:     style.PitchY,
		}
		img, err := RenderChunkToPNG(strings.Join(redLines, "\n"), cols, mono, maxHeightPx, "")
		if err != nil {
			return RenderedImage{}, err
		}
		img.Layers = 1
		return img, nil
	}

	atlasW := AtlasGrayCellW
	glyphH := AtlasGrayCellH
	pitch := glyphH + max(0, style.CellHBonus+defaultCellHBonus)
	if style.PitchY > 0 {
		pitch = style.PitchY
	}
	cellW := max(1, atlasW+style.CellWBonus+defaultCellWBonus)
	nMax := max(len(redLines), len(blueLines))
	width := 2*PadX + cols*cellW + max(0, atlasW-cellW)
	height := 2 * PadY
	if nMax > 0 {
		height += (nMax-1)*pitch + glyphH
	}

	cov1, drop1, dc1 := renderLayerCoverage(redLines, width, height, cols, cellW, pitch)
	cov2, drop2, dc2 := renderLayerCoverage(blueLines, width, height, cols, cellW, pitch)
	pngBytes, err := encodeRGBPNG(compositeTwoLayers(cov1, cov2, overlayLayerColors[0], overlayLayerColors[1]), width, height)
	if err != nil {
		return RenderedImage{}, err
	}

	// Reading order red-then-blue is the page's contiguous text, so its char
	// count equals runeLen(join(red,\n) + "\n" + join(blue,\n)) — both layers.
	charsRendered := runeLen(strings.Join(redLines, "\n"))
	if len(blueLines) > 0 {
		charsRendered += 1 + runeLen(strings.Join(blueLines, "\n"))
	}
	mergeDropped(dc1, dc2)
	return RenderedImage{
		PNG:               pngBytes,
		Width:             width,
		Height:            height,
		CharsRendered:     charsRendered,
		DroppedChars:      drop1 + drop2,
		DroppedCodepoints: dc1,
		Layers:            2,
	}, nil
}

// RenderTextToTwoLayerPNGs splits wrapped text into max-level overlay pages. Each
// image holds up to 2×N lines: the first N in the red layer, the next N in the
// blue layer, where N is the per-layer row capacity of the canvas. Reading order
// is red top-to-bottom, then blue top-to-bottom, then the next image. A trailing
// page with ≤N lines renders single-layer black (see renderTwoLayerChunk).
func RenderTextToTwoLayerPNGs(text string, cols, maxCharsPerImage int, style RenderStyle, maxHeightPx int) ([]RenderedImage, error) {
	if cols < 1 {
		cols = DefaultCols
	}
	if maxHeightPx == 0 {
		maxHeightPx = MaxHeightPx
	}
	if maxCharsPerImage <= 0 {
		maxCharsPerImage = ReadableCharsPerImage
	}
	markerScale := max(1, style.MarkerScale)
	glyphH := AtlasGrayCellH
	pitch := glyphH + max(0, style.CellHBonus+defaultCellHBonus)
	if style.PitchY > 0 {
		pitch = style.PitchY
	}
	lines := WrapLines(text, cols, markerScale)
	// Per-layer rows that fit the canvas; each image stacks two such layers.
	linesPerLayer := max(1, (maxHeightPx-2*PadY-glyphH)/pitch+1)
	linesPerImage := 2 * linesPerLayer
	images := make([]RenderedImage, 0)
	for _, page := range splitWrappedLinesIntoReadablePages(lines, linesPerImage, maxCharsPerImage) {
		n := min(len(page), linesPerLayer)
		img, err := renderTwoLayerChunk(page[:n], page[n:], cols, style, maxHeightPx)
		if err != nil {
			return nil, err
		}
		images = append(images, img)
	}
	return images, nil
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"image/color"
	"math"
	"strings"
	"testing"
)

// maxOverlayStyle is the resolved max geometry (cell advance 4, pitch 6) that the
// overlay renderer draws at.
var maxOverlayStyle = RenderStyle{AA: true, PitchY: 6, CellWBonus: -1}

// TestCompositeTwoLayersReferenceNumbers pins the subtractive multiply against
// hand-computed pixel values, including the canonical full red+blue overlap from
// pxcore.py overlay(): (215,15,15)·(15,15,215)/255 → (13,1,13).
func TestCompositeTwoLayersReferenceNumbers(t *testing.T) {
	red := overlayLayerColors[0]  // (215,15,15)
	blue := overlayLayerColors[1] // (15,15,215)
	cases := []struct {
		name   string
		c1, c2 uint8
		want   [3]uint8
	}{
		{"full-overlap-goes-dark", 255, 255, [3]uint8{13, 1, 13}},
		{"white-stays-white", 0, 0, [3]uint8{255, 255, 255}},
		{"red-only", 255, 0, [3]uint8{215, 15, 15}},
		{"blue-only", 0, 255, [3]uint8{15, 15, 215}},
		// Half red coverage over full blue (a1=128/255, a2=1):
		//   R: l1=255-40·a1=234.92, l2=15 → 234.92·15/255 = 13.82 → 14
		//   G: l1=255-240·a1=134.53, l2=15 → 134.53·15/255 =  7.91 →  8
		//   B: l1=134.53, l2=215 → 134.53·215/255 = 113.42 → 113
		{"half-red-over-full-blue", 128, 255, [3]uint8{14, 8, 113}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := compositeTwoLayers([]uint8{tc.c1}, []uint8{tc.c2}, red, blue)
			if [3]uint8{got[0], got[1], got[2]} != tc.want {
				t.Fatalf("cov(%d,%d) = %v, want %v", tc.c1, tc.c2, got[:3], tc.want)
			}
		})
	}
}

// composePixelRef reproduces the reference composite for one pixel — used to
// verify the rendered overlap against the formula independently of encoding.
func composePixelRef(c1, c2 uint8, col1, col2 [3]uint8) color.RGBA {
	a1 := float64(c1) / 255
	a2 := float64(c2) / 255
	var out [3]uint8
	for ch := 0; ch < 3; ch++ {
		l1 := 255*(1-a1) + float64(col1[ch])*a1
		l2 := 255*(1-a2) + float64(col2[ch])*a2
		v := math.Round(l1 * l2 / 255)
		if v < 0 {
			v = 0
		} else if v > 255 {
			v = 255
		}
		out[ch] = uint8(v)
	}
	return color.RGBA{R: out[0], G: out[1], B: out[2], A: 255}
}

// TestTwoLayerOverlapMatchesReferenceComposite renders the SAME glyph in both
// layers at the same cell (so red and blue coverage are identical at every
// pixel) and checks each decoded pixel equals the subtractive multiply computed
// from the gray atlas coverage.
func TestTwoLayerOverlapMatchesReferenceComposite(t *testing.T) {
	img, err := renderTwoLayerChunk([]string{"M"}, []string{"M"}, 1, maxOverlayStyle, MaxHeightPx)
	if err != nil {
		t.Fatal(err)
	}
	if img.Layers != 2 {
		t.Fatalf("Layers = %d, want 2", img.Layers)
	}
	decoded := decodePNG(t, img.PNG)
	rank := AtlasGrayRank('M')
	if rank < 0 {
		t.Fatal("no gray glyph for 'M'")
	}
	red := overlayLayerColors[0]
	blue := overlayLayerColors[1]
	inked := false
	for row := 0; row < AtlasGrayCellH; row++ {
		for col := 0; col < AtlasGrayCellW; col++ {
			cov := atlasGrayByte(rank, row, col)
			want := composePixelRef(cov, cov, red, blue)
			got := rgba8(decoded, PadX+col, PadY+row)
			if got != want {
				t.Fatalf("pixel (%d,%d) cov=%d got=%v want=%v", col, row, cov, got, want)
			}
			if cov > 0 {
				inked = true
			}
		}
	}
	if !inked {
		t.Fatal("no inked pixel exercised — glyph render produced no coverage")
	}
	// A padding pixel far from any glyph must stay pure white.
	if got := rgba8(decoded, 0, 0); got != (color.RGBA{255, 255, 255, 255}) {
		t.Fatalf("corner pixel = %v, want white", got)
	}
}

// TestTwoLayerSplitter covers page-by-page halving across layers: exact 2N,
// odd (shorter blue), single-line (black not red), empty, and spill into a
// second image whose tail is a single-layer black page.
func TestTwoLayerSplitter(t *testing.T) {
	// maxHeightPx 28 → linesPerLayer = (28-8-8)/6 + 1 = 3; each image holds ≤6.
	const maxH = 28
	line := "aaa"
	body := func(n int) string {
		s := ""
		for i := 0; i < n; i++ {
			if i > 0 {
				s += "\n"
			}
			s += line
		}
		return s
	}
	render := func(n int) []RenderedImage {
		imgs, err := RenderTextToTwoLayerPNGs(body(n), 3, 1<<20, maxOverlayStyle, maxH)
		if err != nil {
			t.Fatalf("render %d lines: %v", n, err)
		}
		return imgs
	}

	// Exact 2N (6 lines): one 2-layer image, red 3 + blue 3, chars count BOTH
	// layers = runeLen("aaa"×6 joined) = 6*3 + 5 = 23.
	if imgs := render(6); len(imgs) != 1 || imgs[0].Layers != 2 {
		t.Fatalf("6 lines: got %d imgs layers=%v, want 1 image Layers 2", len(imgs), layersOf(imgs))
	} else if imgs[0].CharsRendered != 23 {
		t.Fatalf("6-line CharsRendered = %d, want 23 (both layers)", imgs[0].CharsRendered)
	}

	// Odd (5 lines): one 2-layer image, red 3 + blue 2 (shorter blue). Chars =
	// runeLen of all 5 lines = 5*3 + 4 = 19 (proves the blue layer is counted).
	if imgs := render(5); len(imgs) != 1 || imgs[0].Layers != 2 {
		t.Fatalf("5 lines: got %d imgs layers=%v, want 1 image Layers 2", len(imgs), layersOf(imgs))
	} else if imgs[0].CharsRendered != 19 {
		t.Fatalf("5-line CharsRendered = %d, want 19 (both layers)", imgs[0].CharsRendered)
	}

	// Single line (blue empty): one single-layer image, mono BLACK ink, not red.
	if imgs := render(1); len(imgs) != 1 || imgs[0].Layers != 1 {
		t.Fatalf("1 line: got %d imgs layers=%v, want 1 image Layers 1", len(imgs), layersOf(imgs))
	} else if hasColorPixel(decodePNG(t, imgs[0].PNG)) {
		t.Fatal("single-line max page has coloured ink — must render mono black, not red")
	}

	// Empty text: must not panic, one (blank, single-layer) image.
	if imgs, err := RenderTextToTwoLayerPNGs("", 3, 1<<20, maxOverlayStyle, maxH); err != nil {
		t.Fatalf("empty text: %v", err)
	} else if len(imgs) != 1 {
		t.Fatalf("empty text produced %d images, want 1", len(imgs))
	}

	// Spill (7 lines): image 0 full 2-layer (6 lines), image 1 the single-line
	// tail as a mono-black single-layer page.
	imgs := render(7)
	if len(imgs) != 2 {
		t.Fatalf("7 lines: %d images, want 2", len(imgs))
	}
	if imgs[0].Layers != 2 || imgs[1].Layers != 1 {
		t.Fatalf("7-line layers = %v, want [2 1]", layersOf(imgs))
	}
	if hasColorPixel(decodePNG(t, imgs[1].PNG)) {
		t.Fatal("7-line tail page is coloured — single-layer tail must be mono black")
	}
}

func layersOf(imgs []RenderedImage) []int {
	out := make([]int, len(imgs))
	for i, img := range imgs {
		out[i] = img.Layers
	}
	return out
}

// TestTwoLayerGateParityAndCapacity asserts the two invariants of the max gate:
// a max image costs the SAME tokens as a balanced page (identical pixels) while
// holding double the characters, so for equal text volume max is cheaper.
func TestTwoLayerGateParityAndCapacity(t *testing.T) {
	bal := ResolveDensity("gpt-5.6", DensityBalanced) // std, 1 layer
	mx := ResolveDensity("gpt-5.6", DensityMax)       // std, 2 layers, same geometry

	// Capacity doubling: a max image holds two layers of text.
	if mx.charBudget() != 2*bal.charBudget() {
		t.Fatalf("max charBudget = %d, want 2× balanced = %d", mx.charBudget(), 2*bal.charBudget())
	}

	cols := bal.pageCols()
	rows := bal.pageRows()
	if cols != mx.pageCols() || rows != mx.pageRows() {
		t.Fatalf("balanced/max geometry diverged: bal %dx%d vs max %dx%d", cols, rows, mx.pageCols(), mx.pageRows())
	}

	// Gate parity: one full max image (2×rows lines) prices identically to one
	// full balanced page (rows lines) — same pixels, same tokens.
	balPage := imageTokensForRows(rows, cols, 1, 0, bal.charBudget(), bal)
	maxImage := imageTokensForRows(2*rows, cols, 1, 0, mx.charBudget(), mx)
	if maxImage != balPage {
		t.Fatalf("max full-image cost %v != balanced full-page cost %v (parity broken)", maxImage, balPage)
	}

	// For the SAME row volume, max needs fewer/cheaper images (the capacity win).
	volume := 3 * rows
	if maxTok, balTok := imageTokensForRows(volume, cols, 1, 0, mx.charBudget(), mx), imageTokensForRows(volume, cols, 1, 0, bal.charBudget(), bal); !(maxTok < balTok) {
		t.Fatalf("max tokens %v not cheaper than balanced %v for %d rows", maxTok, balTok, volume)
	}
}

// TestTwoLayerCapacitySeam pins that the layer-aware capacity flows through the
// SAME seam into EstimateImageCount and TruncateForBudget: a tool result sized
// just under 2×N lines fits ONE max image with zero omitted chars, while the
// identical content needs two balanced images (and truncates at maxImages=1).
func TestTwoLayerCapacitySeam(t *testing.T) {
	bal := ResolveDensity("gpt-5.6", DensityBalanced) // std, 1 layer, N rows/image
	mx := ResolveDensity("gpt-5.6", DensityMax)       // std, 2 layers, 2N rows/image
	cols := bal.pageCols()
	N := bal.pageRows()

	if got := bal.imageLineCapacity(cols, 1, bal.charBudget()); got != N {
		t.Fatalf("balanced imageLineCapacity = %d, want %d", got, N)
	}
	if got := mx.imageLineCapacity(cols, 1, mx.charBudget()); got != 2*N {
		t.Fatalf("max imageLineCapacity = %d, want %d (2×N)", got, 2*N)
	}

	// (2N-1) full-width lines: one visual row each.
	lines := make([]string, 2*N-1)
	for i := range lines {
		lines[i] = strings.Repeat("x", cols)
	}
	text := strings.Join(lines, "\n")

	if got := EstimateImageCount(text, cols, 1, mx.charBudget(), mx); got != 1 {
		t.Fatalf("max EstimateImageCount(2N-1 lines) = %d, want 1", got)
	}
	if got := EstimateImageCount(text, cols, 1, bal.charBudget(), bal); got != 2 {
		t.Fatalf("balanced EstimateImageCount(2N-1 lines) = %d, want 2", got)
	}

	// maxImages=1: max keeps the whole payload; balanced must truncate.
	if out, omitted, trunc := TruncateForBudget(text, 1, cols, 1, mx.charBudget(), mx); trunc || omitted != 0 || out != text {
		t.Fatalf("max truncated a one-image payload: trunc=%v omitted=%d", trunc, omitted)
	}
	if _, omitted, trunc := TruncateForBudget(text, 1, cols, 1, bal.charBudget(), bal); !trunc || omitted <= 0 {
		t.Fatalf("balanced did not truncate a two-image payload at maxImages=1: trunc=%v omitted=%d", trunc, omitted)
	}
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"bytes"
	"fmt"
	"image"
	"image/color"
	"image/png"
)

type RenderedImage struct {
	PNG               []byte
	Width, Height     int
	CharsRendered     int
	DroppedChars      int
	DroppedCodepoints map[rune]int
	// Layers is the number of interleaved text layers baked into this image: 1
	// for an ordinary page, 2 for a max-level red/blue overlay page. Zero is
	// treated as 1 by callers (existing single-layer renderers leave it unset).
	Layers int
}

func encodeGrayPNG(pixels []uint8, width, height int) ([]byte, error) {
	if len(pixels) != width*height {
		return nil, fmt.Errorf("encodeGrayPNG: pixels length %d != %dx%d", len(pixels), width, height)
	}
	img := image.NewGray(image.Rect(0, 0, width, height))
	copy(img.Pix, pixels)
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func encodeRGBPNG(pixels []uint8, width, height int) ([]byte, error) {
	if len(pixels) != width*height*3 {
		return nil, fmt.Errorf("encodeRGBPNG: pixels length %d != %dx%dx3", len(pixels), width, height)
	}
	img := image.NewNRGBA(image.Rect(0, 0, width, height))
	for i := 0; i < width*height; i++ {
		img.SetNRGBA(i%width, i/width, color.NRGBA{
			R: pixels[i*3],
			G: pixels[i*3+1],
			B: pixels[i*3+2],
			A: 255,
		})
	}
	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import "math"

// AnthropicPatchPx is the side length of an Anthropic vision patch. Image input
// tokens are billed per 28×28 patch: ⌈w/28⌉ × ⌈h/28⌉. The older w·h/750 area
// formula is obsolete.
const AnthropicPatchPx = 28

// PixelTier describes an Anthropic vision pricing tier. Anthropic downscales an
// image server-side when EITHER trigger fires: the long edge exceeds MaxPx, or
// the patch-token count exceeds MaxTokens. Both are resize triggers, not just
// billing ceilings — see AnthropicImageTokens.
type PixelTier struct {
	MaxPx     int // server-side downscale trigger on the long edge (px)
	MaxTokens int // patch-token cap; Anthropic's second downscale trigger
}

// StandardPixelTier is the default vision tier (all models). HiResPixelTier is
// unlocked by newer readers — density.go's isHiResModel (Fable 5, Mythos 5,
// Opus 4.8+, Sonnet 5) is the authority on which; unknown models fail closed
// to standard.
var (
	StandardPixelTier = PixelTier{MaxPx: 1568, MaxTokens: 1568}
	HiResPixelTier    = PixelTier{MaxPx: 2576, MaxTokens: 4784}
)

// AnthropicImageTokens returns the Anthropic input-token cost of a w×h image
// under tier, without the safety margin (callers apply ImageCostSafetyMargin).
//
// It models Anthropic's two server-side downscale triggers:
//  1. Long-edge downscale: if the long edge exceeds tier.MaxPx, both dimensions
//     are scaled down proportionally so the long edge lands on MaxPx (the gate
//     must never price resolution that will not survive upload).
//  2. Token-budget clamp: the patch count is capped at tier.MaxTokens. Anthropic
//     enforces this cap by a further proportional resize; we model its effect as
//     an upper-bound clamp, which is the conservative direction for a cost
//     estimate (it never under-prices the image). For every geometry the engine
//     actually emits neither trigger fires, so the two are numerically identical.
func AnthropicImageTokens(w, h int, tier PixelTier) int {
	if w <= 0 || h <= 0 {
		return 0
	}
	longEdge := max(w, h)
	if tier.MaxPx > 0 && longEdge > tier.MaxPx {
		s := float64(tier.MaxPx) / float64(longEdge)
		// Floor each post-downscale dimension at 1px: an extreme aspect ratio can
		// round the short edge to 0, which would zero out its patch count and
		// price a real image at 0 tokens — the non-conservative direction. A 1px
		// dimension still costs one patch row/column, which is the honest floor.
		w = max(1, int(math.Round(float64(w)*s)))
		h = max(1, int(math.Round(float64(h)*s)))
	}
	patchesW := ceilDiv(w, AnthropicPatchPx)
	patchesH := ceilDiv(h, AnthropicPatchPx)
	tokens := patchesW * patchesH
	if tier.MaxTokens > 0 && tokens > tier.MaxTokens {
		tokens = tier.MaxTokens
	}
	return tokens
}

func ceilDiv(a, b int) int {
	if a <= 0 {
		return 0
	}
	return (a + b - 1) / b
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"math"
	"testing"
)

// TestAnthropicImageTokensWorkedExamples asserts the raw patch-token math
// (⌈w/28⌉ × ⌈h/28⌉, capped) against Anthropic's own worked examples, with no
// safety margin applied so the geometry is pinned exactly.
func TestAnthropicImageTokensWorkedExamples(t *testing.T) {
	cases := []struct {
		name string
		w, h int
		tier PixelTier
		want int
	}{
		// 1092/28 = 39 exactly → 39×39 = 1521, under the 1568 cap.
		{"square standard", 1092, 1092, StandardPixelTier, 1521},
		// 56×26 = 1456, the engine's default full page — under the cap.
		{"engine full page", 1568, 728, StandardPixelTier, 1456},
		// Long edge 2576 > 1568 → downscale to 1568×886 → 56×32 = 1792 → cap 1568.
		{"oversize standard downscale+cap", 2576, 1456, StandardPixelTier, 1568},
		// 92×52 = 4784, exactly the high-res no-resize ceiling.
		{"hires full canvas", 2576, 1456, HiResPixelTier, 4784},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := AnthropicImageTokens(tc.w, tc.h, tc.tier); got != tc.want {
				t.Fatalf("AnthropicImageTokens(%d, %d) = %d, want %d", tc.w, tc.h, got, tc.want)
			}
		})
	}
}

// TestAnthropicImageTokensEdges pins the degenerate inputs and the cap boundary.
func TestAnthropicImageTokensEdges(t *testing.T) {
	if got := AnthropicImageTokens(0, 728, StandardPixelTier); got != 0 {
		t.Fatalf("zero width = %d, want 0", got)
	}
	if got := AnthropicImageTokens(1568, -1, StandardPixelTier); got != 0 {
		t.Fatalf("negative height = %d, want 0", got)
	}
	// Standard cap must never be exceeded even at the tier's max canvas.
	if got := AnthropicImageTokens(1568, 1568, StandardPixelTier); got != StandardPixelTier.MaxTokens {
		t.Fatalf("standard max canvas = %d, want cap %d", got, StandardPixelTier.MaxTokens)
	}
	// Extreme aspect ratio: a 15680×4 strip downscales the short edge to
	// round(4 * 1568/15680) = round(0.4) = 0. Without a 1px floor that would
	// zero out patchesH and price the image at 0 tokens — a non-conservative
	// "free" image. The short edge must floor at 1px → 56×1 = 56 patches.
	if got := AnthropicImageTokens(15680, 4, StandardPixelTier); got != 56 {
		t.Fatalf("extreme aspect ratio = %d, want 56 (short edge floored at 1px)", got)
	}
}

// TestImageCostSafetyMarginApplication asserts the 1.10 margin is applied on
// top of the raw patch tokens, tested separately from the raw geometry.
func TestImageCostSafetyMarginApplication(t *testing.T) {
	raw := AnthropicImageTokens(1568, 728, StandardPixelTier) // 1456
	if raw != 1456 {
		t.Fatalf("raw = %d, want 1456", raw)
	}
	withMargin := int(math.Ceil(float64(raw) * ImageCostSafetyMargin))
	if withMargin != 1602 { // ceil(1456 * 1.10) = ceil(1601.6)
		t.Fatalf("withMargin = %d, want 1602", withMargin)
	}
}

// Ported from pxpipe (https://github.com/teamchong/pxpipe), MIT License, Copyright (c) 2026 claude-image-proxy contributors.

package pixel

import (
	"math"
	"regexp"
	"strings"
	"unicode/utf8"
)

type RenderStyle struct {
	Grid        bool
	GridCols    int
	MarkerScale int
	MarkerRed   bool
	CellHBonus  int
	CellWBonus  int
	AA          bool
	ColorCycle  bool
	ColorByRole bool
	// PitchY overrides the vertical line pitch in px. Zero uses the default
	// (glyph height plus CellHBonus). A value below glyph height makes rows
	// interpenetrate; the drawing path blends dark-ink-wins so both rows render.
	PitchY int
	// Zebra colours each visual row from a 3-colour cycle so row membership
	// survives tight pitch. It reuses the colour-cycle mask path.
	Zebra bool
}

const (
	MaxHeightPx               = 728
	ReadableCharsPerImage     = 28080
	DenseContentCharsPerImage = 28080
	DenseContentCols          = 312
	DefaultCols               = 312
	PadX                      = 4
	PadY                      = 4
	CellW                     = 5
	CellH                     = 8
	NLSentinel                = '↵'
	NLSentinelLiteral         = '⏎'
	GutterCells               = 4
	MaxWidthPx                = 1568
)

const (
	tabWidth             = 4
	defaultCellWBonus    = 0
	defaultCellHBonus    = 0
	gridInk              = 25
	gutterDividerInk     = 64
	gutterDividerInsetPx = 2
	SlotMarkUser         = "\x01"
	SlotMarkAssistant    = "\x02"
	slotNeutral          = "\x03"
)

var DenseRenderStyle = RenderStyle{AA: true}

var trailingRenderWhitespaceRE = regexp.MustCompile(`[ \t]+$`)
var blankRunRenderRE = regexp.MustCompile(`\n{4,}`)

var glyphPalette = [][3]uint8{
	{20, 20, 20},
	{20, 40, 160},
	{150, 20, 20},
	{20, 110, 40},
}

var rolePalette = [][3]uint8{
	{20, 120, 50},
	{30, 70, 180},
}

// zebraPalette cycles per visual row so row membership survives tight pitch.
// Order: dark red, dark blue, black (row % 3) at pitch 6.
var zebraPalette = [][3]uint8{
	{165, 15, 15},
	{15, 30, 175},
	{15, 15, 15},
}

func cellsFor(cp rune, markerScale int) int {
	if cp == NLSentinel && markerScale > 1 {
		return markerScale
	}
	rank := AtlasRank(cp)
	if rank < 0 {
		return 1
	}
	if atlasWideFlags[rank] == 1 {
		return 2
	}
	return 1
}

func jsLen(s string) int {
	n := 0
	for _, r := range s {
		if r > 0xFFFF {
			n += 2
		} else {
			n++
		}
	}
	return n
}

func runeLen(s string) int {
	return utf8.RuneCountInString(s)
}

func MinifyForRender(text string) string {
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		lines[i] = trailingRenderWhitespaceRE.ReplaceAllString(line, "")
	}
	return blankRunRenderRE.ReplaceAllString(strings.Join(lines, "\n"), "\n\n\n")
}

func Reflow(text string) (string, bool) {
	if strings.ContainsRune(text, NLSentinel) {
		return "", false
	}
	lines := strings.Split(MinifyForRender(text), "\n")
	for i, line := range lines {
		lines[i] = ExpandTabsInLine(line)
	}
	return strings.Join(lines, string(NLSentinel)), true
}

func Dereflow(s string) string {
	return strings.ReplaceAll(s, string(NLSentinel), "\n")
}

func NeutralizeSentinel(s string) string {
	return strings.ReplaceAll(s, string(NLSentinel), string(NLSentinelLiteral))
}

func ExpandTabsInLine(line string) string {
	if !strings.ContainsRune(line, '\t') {
		return line
	}
	var b strings.Builder
	col := 0
	for _, r := range line {
		if r == '\t' {
			span := tabWidth - (col % tabWidth)
			b.WriteRune('→')
			if span > 1 {
				b.WriteString(strings.Repeat(" ", span-1))
			}
			col += span
			continue
		}
		b.WriteRune(r)
		col += cellsFor(r, 1)
	}
	return b.String()
}

func MeasureLineCols(line string, markerScale int) int {
	if markerScale < 1 {
		markerScale = 1
	}
	w := 0
	for _, r := range line {
		w += cellsFor(r, markerScale)
	}
	return w
}

func MeasureContentCols(text string, maxCols, markerScale int) int {
	if maxCols < 1 {
		maxCols = 1
	}
	if markerScale < 1 {
		markerScale = 1
	}
	widest := 1
	for _, line := range strings.Split(text, "\n") {
		w := MeasureLineCols(ExpandTabsInLine(line), markerScale)
		if w > widest {
			widest = w
		}
		if widest >= maxCols {
			return maxCols
		}
	}
	return min(maxCols, widest)
}

func WrapLines(text string, cols, markerScale int) []string {
	if cols < 1 {
		cols = 1
	}
	if markerScale < 1 {
		markerScale = 1
	}
	var out []string
	for _, rawWithTabs := range strings.Split(MinifyForRender(text), "\n") {
		raw := ExpandTabsInLine(rawWithTabs)
		if raw == "" {
			out = append(out, "")
			continue
		}
		var cur strings.Builder
		curCols := 0
		for _, r := range raw {
			w := cellsFor(r, markerScale)
			if curCols+w > cols {
				out = append(out, cur.String())
				cur.Reset()
				cur.WriteRune(r)
				curCols = w
			} else {
				cur.WriteRune(r)
				curCols += w
			}
		}
		if cur.Len() > 0 {
			out = append(out, cur.String())
		}
	}
	return out
}

func SlotCopyBody(body string) string {
	if !strings.Contains(body, SlotMarkUser) && !strings.Contains(body, SlotMarkAssistant) {
		return body
	}
	body = strings.ReplaceAll(body, SlotMarkUser, slotNeutral)
	return strings.ReplaceAll(body, SlotMarkAssistant, slotNeutral)
}

func RoleSlotSegment(tag, body, mark string, attr string) string {
	open := "<" + tag + attr + ">"
	close := "</" + tag + ">"
	return strings.Repeat(mark, runeLen(open)) + "\n" + SlotCopyBody(body) + "\n" + strings.Repeat(mark, runeLen(close))
}

func splitWrappedLinesIntoReadablePages(lines []string, maxLines, maxChars int) [][]string {
	lineLimit := max(1, maxLines)
	charLimit := max(1, maxChars)
	var pages [][]string
	var cur []string
	curChars := 0
	for _, line := range lines {
		lineChars := jsLen(line)
		if len(cur) > 0 {
			lineChars++
		}
		if len(cur) > 0 && (len(cur) >= lineLimit || curChars+lineChars > charLimit) {
			pages = append(pages, cur)
			cur = nil
			curChars = 0
		}
		cur = append(cur, line)
		curChars += jsLen(line)
		if len(cur) > 1 {
			curChars++
		}
	}
	if len(cur) > 0 {
		pages = append(pages, cur)
	}
	if len(pages) == 0 {
		return [][]string{{}}
	}
	return pages
}

func readableLinesPerColumn(cols int) int {
	return max(1, ReadableCharsPerImage/max(1, cols))
}

func blitGlyph(fb []uint8, fbW, x, y int, cp rune, markerMask []uint8) int {
	rank := AtlasRank(cp)
	if rank < 0 {
		return 0
	}
	wide := atlasWideFlags[rank] == 1
	srcW := AtlasCellW
	if wide {
		srcW = 2 * AtlasCellW
	}
	srcOff := int(atlasOffsets[rank])
	for gy := 0; gy < AtlasCellH; gy++ {
		dstRow := (y+gy)*fbW + x
		bitRowStart := srcOff + gy*srcW
		for gx := 0; gx < srcW; gx++ {
			bitIdx := bitRowStart + gx
			b := atlasPixels[bitIdx>>3]
			bit := (b >> (7 - (bitIdx & 7))) & 1
			if bit != 0 {
				idx := dstRow + gx
				fb[idx] = 255
				if markerMask != nil {
					markerMask[idx] = 1
				}
			}
		}
	}
	if wide {
		return 2
	}
	return 1
}

func blitGlyphGray(fb []uint8, fbW, x, y int, cp rune) int {
	rank := AtlasGrayRank(cp)
	if rank < 0 {
		return 0
	}
	wide := atlasGrayWideFlags[rank] == 1
	srcW := AtlasGrayCellW
	if wide {
		srcW = 2 * AtlasGrayCellW
	}
	srcOff := int(atlasGrayOffsets[rank])
	for gy := 0; gy < AtlasGrayCellH; gy++ {
		dstRow := (y+gy)*fbW + x
		srcRow := srcOff + gy*srcW
		for gx := 0; gx < srcW; gx++ {
			coverage := atlasGrayPixels[srcRow+gx]
			if coverage > 0 {
				idx := dstRow + gx
				if coverage > fb[idx] {
					fb[idx] = coverage
				}
			}
		}
	}
	if wide {
		return 2
	}
	return 1
}

func blitGlyphScaled(fb, markerMask []uint8, fbW, fbH, x, y int, cp rune, scaleX int) int {
	rank := AtlasRank(cp)
	if rank < 0 {
		return 0
	}
	wide := atlasWideFlags[rank] == 1
	srcW := AtlasCellW
	if wide {
		srcW = 2 * AtlasCellW
	}
	srcOff := int(atlasOffsets[rank])
	for gy := 0; gy < AtlasCellH; gy++ {
		py := y + gy
		if py >= fbH {
			break
		}
		bitRowStart := srcOff + gy*srcW
		for gx := 0; gx < srcW; gx++ {
			bitIdx := bitRowStart + gx
			b := atlasPixels[bitIdx>>3]
			if ((b >> (7 - (bitIdx & 7))) & 1) == 0 {
				continue
			}
			for sx := 0; sx < scaleX; sx++ {
				px := x + gx*scaleX + sx
				if px >= fbW {
					break
				}
				idx := py*fbW + px
				fb[idx] = 255
				if markerMask != nil {
					markerMask[idx] = 1
				}
			}
		}
	}
	if wide {
		return 2 * scaleX
	}
	return scaleX
}

func drawGrid(fb []uint8, fbW, fbH, rows, gridCols, cellH, cellW, glyphH int) {
	for row := 0; row < rows; row++ {
		y := PadY + row*cellH + (glyphH - 1)
		if y >= fbH {
			break
		}
		rowStart := y * fbW
		for x := 0; x < fbW; x++ {
			if fb[rowStart+x] == 0 {
				fb[rowStart+x] = gridInk
			}
		}
	}
	if gridCols > 0 {
		for col := gridCols; ; col += gridCols {
			x := PadX + col*cellW
			if x >= fbW-PadX {
				break
			}
			for y := 0; y < fbH; y++ {
				idx := y*fbW + x
				if fb[idx] == 0 {
					fb[idx] = gridInk
				}
			}
		}
	}
}

func slotForMark(r rune) int {
	switch r {
	case 0x0001:
		return 1
	case 0x0002:
		return 2
	default:
		return 0
	}
}

func RenderChunkToPNG(text string, cols int, style RenderStyle, maxHeightPx int, slotText string) (RenderedImage, error) {
	if cols == 0 {
		cols = DefaultCols
	}
	if cols < 1 {
		cols = 1
	}
	if maxHeightPx == 0 {
		maxHeightPx = MaxHeightPx
	}
	useAA := style.AA
	atlasH := AtlasCellH
	atlasW := AtlasCellW
	if useAA {
		atlasH = AtlasGrayCellH
		atlasW = AtlasGrayCellW
	}
	markerScale := max(1, style.MarkerScale)
	// glyphH is the drawn glyph height; pitch is the vertical line advance. When
	// pitch < glyphH rows interpenetrate (the drawing path blends dark-ink-wins).
	glyphH := atlasH
	pitch := atlasH + max(0, style.CellHBonus+defaultCellHBonus)
	if style.PitchY > 0 {
		pitch = style.PitchY
	}
	cellW := max(1, atlasW+style.CellWBonus+defaultCellWBonus)
	lines := WrapLines(text, cols, markerScale)
	var slotLines []string
	if style.ColorByRole {
		slotLines = WrapLines(slotText, cols, markerScale)
	}
	maxLines := max(1, (maxHeightPx-2*PadY-glyphH)/pitch+1)
	fitLines := lines
	if len(fitLines) > maxLines {
		fitLines = fitLines[:maxLines]
	}
	fitSlotLines := slotLines
	if len(fitSlotLines) > maxLines {
		fitSlotLines = fitSlotLines[:maxLines]
	}
	charsRendered := 0
	if len(fitLines) == len(lines) {
		charsRendered = runeLen(text)
	} else {
		for _, line := range fitLines {
			charsRendered += runeLen(line)
		}
		charsRendered += max(0, len(fitLines)-1)
	}
	width := 2*PadX + cols*cellW + max(0, atlasW-cellW)
	// Reference page height: 2*pad + (rows-1)*pitch + glyphH, so the final row
	// keeps its full glyph height even when intermediate rows advance by pitch.
	height := 2 * PadY
	if len(fitLines) > 0 {
		height += (len(fitLines)-1)*pitch + glyphH
	}
	fb := make([]uint8, width*height)
	var markerMask []uint8
	if style.MarkerRed {
		markerMask = make([]uint8, width*height)
	}
	useColorCycle := style.ColorCycle
	useColorByRole := style.ColorByRole
	useZebra := style.Zebra
	var colorMask []uint8
	if useColorCycle || useColorByRole || useZebra {
		colorMask = make([]uint8, width*height)
	}
	dropped := make(map[rune]int)
	droppedChars := 0
	glyphIndex := 0
	for row, line := range fitLines {
		baseY := PadY + row*pitch
		col := 0
		var slotRow []rune
		if fitSlotLines != nil && row < len(fitSlotLines) {
			slotRow = []rune(fitSlotLines[row])
		}
		charIdx := 0
		for _, r := range line {
			if col >= cols {
				break
			}
			baseX := PadX + col*cellW
			isMarker := r == NLSentinel
			colorSlot := 0
			if useColorByRole {
				if charIdx < len(slotRow) {
					colorSlot = slotForMark(slotRow[charIdx])
				}
			} else if useZebra {
				colorSlot = (row % len(zebraPalette)) + 1
			} else {
				colorSlot = (glyphIndex % len(glyphPalette)) + 1
			}
			advance := 0
			if isMarker && markerScale > 1 {
				advance = blitGlyphScaled(fb, markerMask, width, height, baseX, baseY, r, markerScale)
				paintColorMask(colorMask, fb, width, height, baseX, baseY, advance*cellW, atlasH, colorSlot)
			} else if useAA {
				advance = blitGlyphGray(fb, width, baseX, baseY, r)
				if advance > 0 {
					paintColorMask(colorMask, fb, width, height, baseX, baseY, advance*atlasW, atlasH, colorSlot)
				}
			} else {
				var mark []uint8
				if isMarker {
					mark = markerMask
				}
				advance = blitGlyph(fb, width, baseX, baseY, r, mark)
				if advance > 0 {
					paintColorMask(colorMask, fb, width, height, baseX, baseY, advance*atlasW, atlasH, colorSlot)
				}
			}
			glyphIndex++
			charIdx++
			if advance == 0 {
				droppedChars++
				dropped[r]++
				col++
			} else {
				col += advance
			}
		}
	}
	if style.Grid {
		drawGrid(fb, width, height, len(fitLines), max(0, style.GridCols), pitch, cellW, atlasH)
	}
	for i := range fb {
		fb[i] = 255 - fb[i]
	}
	var pngBytes []byte
	var err error
	if colorMask != nil {
		palette := glyphPalette
		if useColorByRole {
			palette = rolePalette
		} else if useZebra {
			palette = zebraPalette
		}
		pngBytes, err = encodeRGBPNG(renderColorMaskRGB(fb, colorMask, palette), width, height)
	} else if markerMask != nil {
		rgb := make([]uint8, width*height*3)
		for i, g := range fb {
			if markerMask[i] == 1 && g < 128 {
				rgb[i*3] = 220
				rgb[i*3+1] = 0
				rgb[i*3+2] = 0
			} else {
				rgb[i*3] = g
				rgb[i*3+1] = g
				rgb[i*3+2] = g
			}
		}
		pngBytes, err = encodeRGBPNG(rgb, width, height)
	} else {
		pngBytes, err = encodeGrayPNG(fb, width, height)
	}
	if err != nil {
		return RenderedImage{}, err
	}
	return RenderedImage{
		PNG:               pngBytes,
		Width:             width,
		Height:            height,
		CharsRendered:     charsRendered,
		DroppedChars:      droppedChars,
		DroppedCodepoints: dropped,
	}, nil
}

func paintColorMask(colorMask, fb []uint8, width, height, baseX, baseY, w, h, slot int) {
	if colorMask == nil {
		return
	}
	for gy := 0; gy < h; gy++ {
		py := baseY + gy
		if py >= height {
			break
		}
		for gx := 0; gx < w; gx++ {
			px := baseX + gx
			if px >= width {
				break
			}
			idx := py*width + px
			if fb[idx] > 0 {
				colorMask[idx] = uint8(slot)
			}
		}
	}
}

func renderColorMaskRGB(fb, colorMask []uint8, palette [][3]uint8) []uint8 {
	rgb := make([]uint8, len(fb)*3)
	for i, g := range fb {
		slot := colorMask[i]
		if slot > 0 {
			coverage := float64(255 - g)
			p := palette[(int(slot)-1)%len(palette)]
			rgb[i*3] = uint8(math.Round(255 - coverage*float64(255-p[0])/255))
			rgb[i*3+1] = uint8(math.Round(255 - coverage*float64(255-p[1])/255))
			rgb[i*3+2] = uint8(math.Round(255 - coverage*float64(255-p[2])/255))
		} else {
			rgb[i*3] = g
			rgb[i*3+1] = g
			rgb[i*3+2] = g
		}
	}
	return rgb
}

func RenderTextToPNGs(text string, cols int, style RenderStyle) ([]RenderedImage, error) {
	return RenderTextToPNGsWithCharLimit(text, cols, ReadableCharsPerImage, style, MaxHeightPx, "")
}

func RenderTextToPNGsWithCharLimit(text string, cols, maxCharsPerImage int, style RenderStyle, maxHeightPx int, slotText string) ([]RenderedImage, error) {
	if cols == 0 {
		cols = DefaultCols
	}
	if cols < 1 {
		cols = 1
	}
	if maxCharsPerImage == 0 {
		maxCharsPerImage = ReadableCharsPerImage
	}
	if maxHeightPx == 0 {
		maxHeightPx = MaxHeightPx
	}
	markerScale := max(1, style.MarkerScale)
	glyphH := AtlasCellH
	pitch := AtlasCellH + max(0, style.CellHBonus+defaultCellHBonus)
	if style.PitchY > 0 {
		pitch = style.PitchY
	}
	lines := WrapLines(text, cols, markerScale)
	var slotLines []string
	if style.ColorByRole {
		slotLines = WrapLines(slotText, cols, markerScale)
	}
	hardLinesPerImg := max(1, (maxHeightPx-2*PadY-glyphH)/pitch+1)
	linesPerImg := min(hardLinesPerImg, max(1, maxCharsPerImage/cols))
	images := make([]RenderedImage, 0)
	slotCursor := 0
	for _, page := range splitWrappedLinesIntoReadablePages(lines, linesPerImg, maxCharsPerImage) {
		chunk := strings.Join(page, "\n")
		slotChunk := ""
		if slotLines != nil {
			end := min(len(slotLines), slotCursor+len(page))
			slotChunk = strings.Join(slotLines[slotCursor:end], "\n")
		}
		slotCursor += len(page)
		img, err := RenderChunkToPNG(chunk, cols, style, maxHeightPx, slotChunk)
		if err != nil {
			return nil, err
		}
		images = append(images, img)
	}
	return images, nil
}

func MultiColWidth(cols, numCols int) int {
	n := max(1, numCols)
	return 2*PadX + n*cols*CellW + (n-1)*GutterCells*CellW
}

func MaxFittingCols(cols int) int {
	n := 1
	for MultiColWidth(cols, n+1) <= MaxWidthPx {
		n++
	}
	return n
}

func renderMultiColChunkFromLines(lines []string, cols, numCols, charsCovered, linesPerCol int) (RenderedImage, error) {
	width := MultiColWidth(cols, numCols)
	rowsPerCol := max(1, linesPerCol)
	usedRows := min(len(lines), rowsPerCol)
	if usedRows < 1 {
		usedRows = 1
	}
	height := 2*PadY + usedRows*CellH
	fb := make([]uint8, width*height)
	dropped := make(map[rune]int)
	droppedChars := 0
	colStride := cols*CellW + GutterCells*CellW
	for c := 0; c < numCols; c++ {
		colBaseX := PadX + c*colStride
		colStart := c * rowsPerCol
		if colStart >= len(lines) {
			break
		}
		colEnd := min(colStart+rowsPerCol, len(lines))
		for r := 0; r < colEnd-colStart; r++ {
			line := lines[colStart+r]
			baseY := PadY + r*CellH
			col := 0
			for _, cp := range line {
				if col >= cols {
					break
				}
				baseX := colBaseX + col*CellW
				advance := blitGlyph(fb, width, baseX, baseY, cp, nil)
				if advance == 0 {
					droppedChars++
					dropped[cp]++
					col++
				} else {
					col += advance
				}
			}
		}
	}
	if numCols >= 2 {
		gutterPxPerSide := GutterCells * CellW
		yStart := gutterDividerInsetPx
		yEnd := height - gutterDividerInsetPx
		for c := 0; c < numCols-1; c++ {
			colEndX := PadX + c*colStride + cols*CellW
			dividerX := colEndX + gutterPxPerSide/2
			for y := yStart; y < yEnd; y++ {
				idx := y*width + dividerX
				if fb[idx] == 0 {
					fb[idx] = gutterDividerInk
				}
			}
		}
	}
	for i := range fb {
		fb[i] = 255 - fb[i]
	}
	pngBytes, err := encodeGrayPNG(fb, width, height)
	if err != nil {
		return RenderedImage{}, err
	}
	return RenderedImage{
		PNG:               pngBytes,
		Width:             width,
		Height:            height,
		CharsRendered:     charsCovered,
		DroppedChars:      droppedChars,
		DroppedCodepoints: dropped,
	}, nil
}

func RenderTextToPNGsMultiCol(text string, cols, numCols int) ([]RenderedImage, error) {
	if cols == 0 {
		cols = DefaultCols
	}
	if numCols <= 1 {
		return RenderTextToPNGs(text, cols, RenderStyle{})
	}
	if MultiColWidth(cols, numCols) > MaxWidthPx {
		numCols = MaxFittingCols(cols)
		if numCols <= 1 {
			return RenderTextToPNGs(text, cols, RenderStyle{})
		}
	}
	lines := WrapLines(text, cols, 1)
	hardLinesPerImg := max(1, (MaxHeightPx-2*PadY)/CellH)
	linesPerImg := min(hardLinesPerImg, readableLinesPerColumn(cols))
	linesPerImage := linesPerImg * numCols
	totalChars := runeLen(text)
	images := make([]RenderedImage, 0)
	coveredChars := 0
	pages := splitWrappedLinesIntoReadablePages(lines, linesPerImage, ReadableCharsPerImage*max(1, numCols))
	for i, page := range pages {
		isLast := i == len(pages)-1
		chars := 0
		if isLast {
			chars = max(0, totalChars-coveredChars)
		} else {
			for _, line := range page {
				chars += runeLen(line)
			}
			chars += max(0, len(page)-1)
		}
		coveredChars += chars
		img, err := renderMultiColChunkFromLines(page, cols, numCols, chars, linesPerImg)
		if err != nil {
			return nil, err
		}
		images = append(images, img)
	}
	return images, nil
}

type DensePagesOptions struct {
	Cols             int
	Shrink           *bool
	MultiCol         int
	Reflow           bool
	MaxCharsPerImage int
	Style            *RenderStyle
	MaxHeightPx      int
}

func RenderDensePages(text string, opts DensePagesOptions) ([]RenderedImage, error) {
	source := text
	if opts.Reflow {
		if packed, ok := Reflow(text); ok {
			source = packed
		}
	}
	maxCols := opts.Cols
	if maxCols == 0 {
		maxCols = DenseContentCols
	}
	maxCols = max(1, maxCols)
	shrink := true
	if opts.Shrink != nil {
		shrink = *opts.Shrink
	}
	cols := maxCols
	if shrink {
		cols = MeasureContentCols(source, maxCols, 1)
	}
	requestedCols := opts.MultiCol
	if requestedCols == 0 {
		requestedCols = max(1, MaxFittingCols(cols))
	} else {
		requestedCols = max(1, requestedCols)
	}
	numCols := requestedCols
	if cols < maxCols {
		numCols = 1
	}
	style := DenseRenderStyle
	if opts.Style != nil {
		style = *opts.Style
	}
	maxChars := opts.MaxCharsPerImage
	if maxChars == 0 {
		maxChars = DenseContentCharsPerImage
	}
	maxHeight := opts.MaxHeightPx
	if maxHeight == 0 {
		maxHeight = MaxHeightPx
	}
	if numCols > 1 {
		return RenderTextToPNGsMultiCol(source, cols, numCols)
	}
	return RenderTextToPNGsWithCharLimit(source, cols, maxChars, style, maxHeight, "")
}

