	}

	t.Setenv("CAVE_PIXEL_GPT_PROFILES", `{"gpt-5.6":{"stripCols":176},"gpt-5.6-special":{"vision":{"regime":"tile","base":1,"perTile":2},"maxHeightPx":2400}}`)
