func countDataImages(v any) int {
	return len(collectDataImageStrings(v))
}

func collectDataImageStrings(v any) []string {
	var out []string
	var walk func(any)
	walk = func(x any) {
		switch t := x.(type) {
		case string:
			if strings.HasPrefix(t, "data:image/png;base64,") {
				out = append(out, t)
			}
		case []any:
			for _, child := range t {
				walk(child)
			}
		case map[string]any:
			for _, child := range t {
				walk(child)
			}
		}
	}
	walk(v)
	return out
}

func normalizeDataImages(v any) any {
	switch t := v.(type) {
	case string:
		if strings.HasPrefix(t, "data:image/png;base64,") {
			return "<image>"
		}
		return t
	case []any:
		out := make([]any, len(t))
		for i, child := range t {
			out[i] = normalizeDataImages(child)
		}
		return out
	case map[string]any:
		out := make(map[string]any, len(t))
		for k, child := range t {
			out[k] = normalizeDataImages(child)
		}
		return out
	default:
		return v
	}
}

func decodeDataImageTest(t *testing.T, uri string) image.Image {
	t.Helper()
	raw := strings.TrimPrefix(uri, "data:image/png;base64,")
	pngBytes, err := base64.StdEncoding.DecodeString(raw)
	if err != nil {
		t.Fatal(err)
	}
	return decodePNGTest(t, pngBytes)
}

func decodePNGTest(t *testing.T, pngBytes []byte) image.Image {
	t.Helper()
	img, err := png.Decode(bytes.NewReader(pngBytes))
	if err != nil {
		t.Fatal(err)
	}
	return img
}

func assertImagePixelsEqual(t *testing.T, got, want image.Image) {
	t.Helper()
	if got.Bounds() != want.Bounds() {
		t.Fatalf("bounds got %v want %v", got.Bounds(), want.Bounds())
	}
	for y := got.Bounds().Min.Y; y < got.Bounds().Max.Y; y++ {
		for x := got.Bounds().Min.X; x < got.Bounds().Max.X; x++ {
			gr, gg, gb, ga := got.At(x, y).RGBA()
			wr, wg, wb, wa := want.At(x, y).RGBA()
			if gr != wr || gg != wg || gb != wb || ga != wa {
				t.Fatalf("pixel mismatch at %d,%d", x, y)
			}
		}
	}
}

func containsTextPart(parts []any, text string) bool {
	for _, part := range parts {
		m, ok := part.(map[string]any)
		if !ok {
			continue
		}
		if strings.Contains(stringOr(m["text"], ""), text) {
			return true
		}
	}
	return false
}

package engine

// BasisInferred identifies token figures produced by the engine's local counter.
const BasisInferred = "inferred"

// Mode controls whether the engine transforms bytes.
type Mode string

const (
	// ModeRecord is always pass-through: the output is byte-identical to the
	// input and no recovery is stored. It is the default.
	ModeRecord Mode = "record"
	// ModeCompress runs the routed compressor.
	ModeCompress Mode = "compress"
)

// Options configures a single Compress call.
type Options struct {
	// Mode defaults to ModeRecord (pass-through) when empty. Any unknown mode
	// also falls back to ModeRecord — unknown enum cases fail closed.
	Mode Mode
	// Type forces a content type; empty means auto-detect.
	Type string
	// Query, when non-empty, lets a query-aware compressor bias what it keeps
	// toward items relevant to it (deterministic BM25; no embeddings). Empty
	// means query-agnostic — identical to the historical behavior. The field is
	// additive and optional: a compressor that does not implement
	// compressors.QueryAwareCompressor ignores it entirely.
	Query string
	// ExternalRecovery lets an embedding gateway provide byte-exact recovery
	// outside the engine's local CCR store. It may only be used when the caller
	// stores the original before forwarding compressed bytes.
	ExternalRecovery bool
}

func (m Mode) normalized() Mode {
	switch m {
	case ModeCompress:
		return ModeCompress
	default:
		// Empty or unknown → record (pass-through). Fail closed.
		return ModeRecord
	}
}

// Result is the outcome of a Compress call.
type Result struct {
	// Output is the compressed bytes, or the original bytes on pass-through.
	Output []byte `json:"-"`
	// ContentType is the detected (or forced) content type.
	ContentType string `json:"content_type"`
	// TokensBefore / TokensAfter are local token estimates.
	TokensBefore int `json:"tokens_before"`
	TokensAfter  int `json:"tokens_after"`
	// TokenCountBasis names estimator used for both token counts. Provider usage
	// is not available before compression.
	TokenCountBasis string `json:"token_count_basis"`
	// Ratio is the fraction of tokens removed (0..1); 0 on pass-through.
	Ratio float64 `json:"ratio"`
	// Basis identifies the token-count basis.
	Basis string `json:"basis"`
	// RecoveryHandle is the CCR handle for the original; empty on pass-through.
	RecoveryHandle string `json:"recovery_handle,omitempty"`
	// Method identifies the concrete transform chosen by a compressor.
	Method string `json:"method,omitempty"`
	// LosslessToModel is present on transformed outputs and tells callers
	// whether the model-visible output kept the full value without data dropped.
	LosslessToModel *bool `json:"lossless_to_model,omitempty"`
}

// PassedThrough reports whether the call returned the input unchanged.
func (r Result) PassedThrough() bool { return r.RecoveryHandle == "" && r.Method == "" && r.Ratio == 0 }

// SimResult is the dry-run accounting from Simulate: what Compress WOULD do to a
// payload, computed without storing anything (no CCR Put) or making any network
// call. Its token figures are local estimates, not provider usage or billing.
type SimResult struct {
	// ContentType is the detected (or forced) content type.
	ContentType string `json:"content_type"`
	// Compressor is the compressor that would run; empty on pass-through.
	Compressor string `json:"compressor,omitempty"`
	// SafetyClass is the S0..S4 class of the matched compressor; empty on pass-through.
	SafetyClass string `json:"safety_class,omitempty"`
	// TokensBefore / TokensAfter / TokensSaved are local token estimates.
	TokensBefore int `json:"tokens_before"`
	TokensAfter  int `json:"tokens_after"`
	TokensSaved  int `json:"tokens_saved"`
	// TokenCountBasis names the estimator used for before/after/saved.
	TokenCountBasis string `json:"token_count_basis"`
	// Ratio is the fraction of tokens removed (0..1); 0 on pass-through.
	Ratio float64 `json:"ratio"`
	// Lossy is true when the model-visible output dropped data.
	Lossy bool `json:"lossy"`
	// RequiresCCR is true when byte-exact recovery requires a stored original.
	RequiresCCR bool `json:"requires_ccr"`
	// Recoverable reports whether a real Compress could actually emit this reduction
	// in the current engine configuration: always true for byte-safe compressors,
	// but false for a lossy compressor when no store backs recovery. A false here
	// marks the reduction as requiring CCR before it can be emitted; callers must
	// not treat it as available when recovery is not configured.
	Recoverable bool `json:"recoverable"`
	// Method identifies the concrete transform chosen by a compressor.
	Method string `json:"method,omitempty"`
	// LosslessToModel is present on simulated transformed outputs and tells
	// callers whether the model-visible output keeps the full value.
	LosslessToModel *bool `json:"lossless_to_model,omitempty"`
	// Basis identifies the token-count basis.
	Basis string `json:"basis"`
}

package engine

import (
	"bytes"
	"encoding/csv"
	"encoding/json"
	"io"
	"sort"
	"strings"
	"unicode/utf8"

	"github.com/JuliusBrussee/caveman/engine/contextwindow"
)

// maxRetrieveSections caps a query-targeted recovery at the top-N most relevant
// sections, with a bounded top-k (k=20).
const maxRetrieveSections = 20

// nonAdjacentMarker stands between two returned units that were not neighbours in
// the original, and at either end when the view starts or stops short of it.
//
// It exists because of wrong answers, not wasted tokens. A ranked line view of
// pretty-printed JSON can place a field from one record beside an identifier from
// another. Without an explicit gap marker, an agent can attribute the field to the
// wrong record and report a result the source never contained.
//
// A retrieval view therefore never emits a fragment of a unit, and never lets two
// units touch unless they touched in the original.
const nonAdjacentMarker = "… [caveman: non-adjacent] …"

// RetrieveQuery recovers the content behind a CCR handle, narrowed to the sections
// most relevant to query (BM25-rank the stored content's sections, keep the
// matches). With an empty query it is identical
// to Retrieve (byte-exact recovery). It never drops detail it cannot rank: if the
// stored content yields no rankable units, or nothing matches the query, it
// returns the full original.
func (e *Engine) RetrieveQuery(handle, query string) ([]byte, error) {
	original, err := e.Retrieve(handle)
	if err != nil {
		return nil, err
	}
	if strings.TrimSpace(query) == "" {
		return original, nil
	}
	if narrowed, ok := narrowToQuery(original, query); ok && len(narrowed) < len(original) {
		return narrowed, nil
	}
	return original, nil
}

// narrowToQuery splits stored content into whole units, BM25-ranks them against
// the query, and returns the relevant ones in their original order, marking every
// gap. ok is false when the content cannot be decomposed into units or nothing
// matched, so the caller recovers the full original: over-returning is safe,
// returning a fragment is not.
func narrowToQuery(content []byte, query string) ([]byte, bool) {
	units, prelude := retrievalUnits(content)
	if len(units) == 0 {
		return nil, false
	}
	scores := contextwindow.BM25(query, units)
	type ranked struct {
		idx   int
		score float64
	}
	hits := make([]ranked, 0, len(units))
	for i, s := range scores {
		if s > 0 {
			hits = append(hits, ranked{idx: i, score: s})
		}
	}
	if len(hits) == 0 {
		return nil, false
	}
	sort.SliceStable(hits, func(i, j int) bool { return hits[i].score > hits[j].score })
	if len(hits) > maxRetrieveSections {
		hits = hits[:maxRetrieveSections]
	}
	sort.SliceStable(hits, func(i, j int) bool { return hits[i].idx < hits[j].idx })

	var b strings.Builder
	if prelude != "" {
		b.WriteString(prelude)
		b.WriteString("\n")
	}
	previous := -1
	for _, h := range hits {
		switch {
		case previous < 0 && h.idx > 0:
			// The view starts short of the content: say so before the first unit,
			// or a reader counts what is shown as everything there was.
			b.WriteString(nonAdjacentMarker)
			b.WriteString("\n\n")
		case previous >= 0 && h.idx == previous+1:
			b.WriteString("\n\n")
		case previous >= 0:
			b.WriteString("\n\n")
			b.WriteString(nonAdjacentMarker)
			b.WriteString("\n\n")
		}
		b.WriteString(units[h.idx])
		previous = h.idx
	}
	if previous < len(units)-1 {
		b.WriteString("\n\n")
		b.WriteString(nonAdjacentMarker)
	}
	return []byte(b.String()), true
}

// retrievalUnits decomposes stored content into the smallest pieces that are
// self-delimiting — a piece a reader can interpret without its neighbours. prelude
// is emitted once above the units (a table's header row) or empty.
//
// It returns no units at all rather than a decomposition it does not trust; the
// caller then recovers the whole original.
func retrievalUnits(content []byte) ([]string, string) {
	var root any
	decoder := json.NewDecoder(bytes.NewReader(content))
	decoder.UseNumber()
	if err := decoder.Decode(&root); err == nil && !decoder.More() {
		// JSON units are complete object records, never bare values taken from a
		// field named content/text. Those names are ordinary tool-output fields;
		// extracting their strings would orphan them from record ids and recreate
		// the wrong-attribution bug this path exists to prevent.
		var groups [][]string
		collectJSONRecordGroups(root, &groups)
		if len(groups) > 0 {
			// Empty sentinel units preserve source gaps without entering the ranked
			// output: one before/after the extracted records marks omitted envelope
			// bytes, and one between arrays prevents records from separate arrays
			// being rendered as adjacent. BM25 assigns empty units no score.
			units := []string{""}
			for i, group := range groups {
				if i > 0 {
					units = append(units, "")
				}
				units = append(units, group...)
			}
			units = append(units, "")
			return units, ""
		}
		// JSON we cannot decompose into records. Its source is NOT line-splittable
		// — `"status": "unfulfilled",` is a fragment, not a unit — so claim nothing
		// and let the caller return the whole thing.
		return nil, ""
	}
	if rows, header, ok := tabularRetrievalUnits(content); ok {
		return rows, header
	}
	// Line-oriented content: logs, NDJSON, plain text. A line (or a paragraph,
	// where blank lines separate them) is already a whole unit.
	return appendSections(nil, string(content)), ""
}

// collectJSONRecordGroups walks the decoded payload and takes each array that
// holds nothing but objects as a separate group — an orders page's `orders`, a
// report's `rows`. It does not descend into a group it has taken: each object is
// one unit, and group boundaries preserve source non-adjacency.
func collectJSONRecordGroups(node any, out *[][]string) {
	switch v := node.(type) {
	case map[string]any:
		keys := make([]string, 0, len(v))
		for key := range v {
			keys = append(keys, key)
		}
		sort.Strings(keys) // map order is random; a recovery view must not be
		for _, key := range keys {
			collectJSONRecordGroups(v[key], out)
		}
	case []any:
		objects := 0
		for _, element := range v {
			if _, isObject := element.(map[string]any); isObject {
				objects++
			}
		}
		if objects > 0 && objects == len(v) {
			group := make([]string, 0, len(v))
			for _, element := range v {
				if encoded, err := json.MarshalIndent(element, "", "  "); err == nil {
					group = append(group, string(encoded))
				}
			}
			if len(group) > 0 {
				*out = append(*out, group)
			}
			return
		}
		for _, element := range v {
			collectJSONRecordGroups(element, out)
		}
	}
}

// tabularRetrievalUnits splits a CSV/TSV payload into whole records, with the
// header returned separately so it can head the view exactly once. Records are
// sliced out of the ORIGINAL bytes by input offset, so quoting, spacing, and
// embedded newlines survive untouched.
func tabularRetrievalUnits(content []byte) ([]string, string, bool) {
	trimmed := bytes.TrimSpace(content)
	if !utf8.Valid(content) || len(trimmed) == 0 || trimmed[0] == '{' || trimmed[0] == '[' {
		return nil, "", false
	}
	firstLine, _, _ := bytes.Cut(trimmed, []byte("\n"))
	delimiter := ','
	if bytes.Count(firstLine, []byte("\t")) > bytes.Count(firstLine, []byte(",")) {
		delimiter = '\t'
	}
	if !bytes.ContainsRune(firstLine, delimiter) {
		return nil, "", false
	}

	reader := csv.NewReader(bytes.NewReader(content))
	reader.Comma = delimiter
	reader.FieldsPerRecord = 0 // every record must match the header's field count
	reader.ReuseRecord = true
	var (
		units  []string
		header string
		offset int64
		fields int
	)
	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, "", false
		}
		next := reader.InputOffset()
		text := strings.TrimRight(string(content[offset:next]), "\r\n")
		offset = next
		if header == "" && units == nil {
			header, fields = text, len(record)
			continue
		}
		units = append(units, text)
	}
	if fields < 2 || len(units) < 2 {
		return nil, "", false // not a table worth splitting
	}
	return units, header, true
}

func appendSections(into []string, text string) []string {
	for _, sec := range splitSections(text) {
		if trimmed := strings.TrimSpace(sec); trimmed != "" {
			into = append(into, trimmed)
		}
	}
	return into
}

func splitSections(text string) []string {
	if strings.Contains(text, "\n\n") {
		return strings.Split(text, "\n\n")
	}
	return strings.Split(text, "\n")
}

package engine

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

// ordersPage is the payload shape that produced the wrong answer: pretty-printed
// JSON records where one order carries `"status": "unfulfilled"` and the next
// record's `order_id` line follows it immediately in the source text.
func ordersPage(t *testing.T) []byte {
	t.Helper()
	var b strings.Builder
	b.WriteString("{\n  \"orders\": [\n")
	for i := 0; i < 12; i++ {
		status := "fulfilled"
		switch {
		case i == 3:
			status = "unfulfilled"
		case i == 7:
			status = "processing"
		}
		if i > 0 {
			b.WriteString(",\n")
		}
		fmt.Fprintf(&b, "    {\n      \"order_id\": \"ord-%04d\",\n      \"amount\": \"%d.50\",\n      \"status\": \"%s\"\n    }",
			1040+i, 100+i*37, status)
	}
	b.WriteString("\n  ],\n  \"page\": 2\n}\n")
	return []byte(b.String())
}

// TestQueryViewNeverOrphansAJSONField covers wrong-record attribution when a
// answer. A match on a field line must yield that field's WHOLE record, so no
// status can be read against a neighbouring record's id.
func TestQueryViewNeverOrphansAJSONField(t *testing.T) {
	view, ok := narrowToQuery(ordersPage(t), "unfulfilled orders with order_id, amount, status")
	if !ok {
		t.Fatal("an orders page must narrow")
	}
	text := string(view)

	// Every returned record must parse on its own — that is what "whole unit"
	// means, and it is exactly what line-plucking could not promise.
	records := 0
	for _, block := range strings.Split(text, "\n\n") {
		block = strings.TrimSpace(block)
		if block == "" || block == nonAdjacentMarker {
			continue
		}
		var order map[string]any
		if err := json.Unmarshal([]byte(block), &order); err != nil {
			t.Fatalf("a returned block is not a complete JSON record: %q", block)
		}
		for _, key := range []string{"order_id", "amount", "status"} {
			if _, present := order[key]; !present {
				t.Fatalf("record is missing %s, so it was returned in pieces: %q", key, block)
			}
		}
		records++
	}
	if records == 0 {
		t.Fatal("no records came back")
	}

	// The specific misreading: the only `unfulfilled` in the view must sit in the
	// same record as ord-1043, and no other id may follow it before its record
	// closes.
	index := strings.Index(text, `"status": "unfulfilled"`)
	if index < 0 {
		t.Fatal("the unfulfilled order should rank for this query")
	}
	record := text[strings.LastIndex(text[:index], "{"):]
	record = record[:strings.Index(record, "}")+1]
	if !strings.Contains(record, "ord-1043") {
		t.Fatalf("the unfulfilled status landed in the wrong record: %q", record)
	}
	if strings.Count(record, `"order_id"`) != 1 {
		t.Fatalf("a record carries more than one id: %q", record)
	}
}

// A field named text/content is ordinary tool data, not permission to detach its
// value from the record that identifies it.
func TestQueryViewKeepsTextBearingJSONRecordsWhole(t *testing.T) {
	content := []byte(`{"items":[{"id":"row-1","text":"delivery failed"},{"id":"row-2","text":"delivery ok"}]}`)
	view, ok := narrowToQuery(content, "failed")
	if !ok {
		t.Fatal("text-bearing records must narrow")
	}
	var matched map[string]any
	for _, block := range strings.Split(string(view), "\n\n") {
		block = strings.TrimSpace(block)
		if block == "" || block == nonAdjacentMarker {
			continue
		}
		if err := json.Unmarshal([]byte(block), &matched); err != nil {
			t.Fatalf("text field was orphaned from its record: %q", block)
		}
	}
	if matched["id"] != "row-1" || matched["text"] != "delivery failed" {
		t.Fatalf("query returned wrong or incomplete record: %#v", matched)
	}
}

// A top-level messages array is not proof that JSON came from a provider. Tool
// output can use the same shape, so message ids must remain attached to content.
func TestQueryViewKeepsToolMessageContentWithItsID(t *testing.T) {
	content := []byte(`{"messages":[{"id":"msg-1","role":"customer","content":"refund failed"},{"id":"msg-2","role":"customer","content":"refund complete"}]}`)
	view, ok := narrowToQuery(content, "failed")
	if !ok {
		t.Fatal("message-shaped tool records must narrow")
	}
	text := string(view)
	if !strings.Contains(text, `"id": "msg-1"`) || !strings.Contains(text, `"content": "refund failed"`) {
		t.Fatalf("message content was detached from its id: %q", text)
	}
	if strings.Contains(text, `"id": "msg-2"`) {
		t.Fatalf("irrelevant message unexpectedly ranked: %q", text)
	}
}

// Mixed provider-style content shapes stay as whole message records. Array-form
// content and its sibling facts may not disappear through a string-only path.
func TestQueryViewKeepsMixedMessageContentShapesWhole(t *testing.T) {
	content := []byte(`{"messages":[{"id":"msg-1","role":"user","content":"refund failed"},{"id":"msg-2","role":"user","content":[{"type":"text","text":"image evidence"}]}]}`)
	view, ok := narrowToQuery(content, "refund image evidence")
	if !ok {
		t.Fatal("mixed message content must narrow")
	}
	text := string(view)
	for _, want := range []string{`"id": "msg-1"`, `"content": "refund failed"`, `"id": "msg-2"`, `"text": "image evidence"`} {
		if !strings.Contains(text, want) {
			t.Fatalf("mixed message fact %s disappeared: %q", want, text)
		}
	}
}

// Records from different JSON arrays are not neighbours even when each record
// is the only hit in its array. A visible gap must separate them.
func TestQueryViewMarksSeparateJSONArraysAsNonAdjacent(t *testing.T) {
	content := []byte(`{"errors":[{"id":"err-1","state":"target"}],"warnings":[{"id":"warn-1","state":"target"}]}`)
	view, ok := narrowToQuery(content, "target")
	if !ok {
		t.Fatal("separate record arrays must narrow")
	}
	text := string(view)
	start := strings.Index(text, `"id": "err-1"`)
	end := strings.Index(text, `"id": "warn-1"`)
	if start < 0 || end < 0 || start >= end {
		t.Fatalf("both array records must be present in deterministic source order: %q", text)
	}
	if !strings.Contains(text[start:end], nonAdjacentMarker) {
		t.Fatalf("records from separate arrays were rendered as adjacent: %q", text)
	}
}

// Even when every record matches, extracting them drops the JSON envelope and
// scalar metadata. Leading/trailing markers make that omission explicit.
func TestQueryViewMarksOmittedJSONEnvelope(t *testing.T) {
	content := []byte(`{"system":"policy facts stay outside record units","page":2,"items":[{"id":"row-1","state":"target"},{"id":"row-2","state":"target"}],"total":2}`)
	view, ok := narrowToQuery(content, "target")
	if !ok {
		t.Fatal("record envelope must narrow")
	}
	text := string(view)
	if !strings.HasPrefix(text, nonAdjacentMarker) || !strings.HasSuffix(text, nonAdjacentMarker) {
		t.Fatalf("omitted JSON envelope was not marked at both ends: %q", text)
	}
}

// TestQueryViewMarksEveryGap is the other half: whole units are not enough if two
// of them touch when they did not touch in the original.
func TestQueryViewMarksEveryGap(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 40; i++ {
		subject := "heartbeat ok"
		if i == 2 || i == 30 {
			subject = "delivery failed for endpoint alpha"
		}
		fmt.Fprintf(&b, "ts=t%02d event=%d %s\n", i, i, subject)
	}
	view, ok := narrowToQuery([]byte(b.String()), "delivery failed endpoint alpha")
	if !ok {
		t.Fatal("a log must narrow")
	}
	text := string(view)
	if !strings.Contains(text, "event=2 ") || !strings.Contains(text, "event=30 ") {
		t.Fatalf("both matches should be returned: %q", text)
	}
	between := text[strings.Index(text, "event=2 "):strings.Index(text, "event=30 ")]
	if !strings.Contains(between, nonAdjacentMarker) {
		t.Fatalf("two non-adjacent lines were returned touching: %q", text)
	}
	if !strings.HasPrefix(text, nonAdjacentMarker) {
		t.Fatalf("a view that starts short of the content must say so: %q", text)
	}
	if !strings.HasSuffix(text, nonAdjacentMarker) {
		t.Fatalf("a view that stops short of the content must say so: %q", text)
	}
}

// TestQueryViewKeepsCSVRowsWhole covers the tabular path: whole records sliced out
// of the original bytes, and the header exactly once so the columns can be read.
func TestQueryViewKeepsCSVRowsWhole(t *testing.T) {
	var b strings.Builder
	b.WriteString("txn_id,order_id,state,amount,note\n")
	for i := 0; i < 40; i++ {
		state, note := "charged", "ok"
		if i == 5 || i == 25 {
			state, note = "refunded", "customer dispute, chargeback"
		}
		fmt.Fprintf(&b, "txn-%05d,ord-%04d,%s,%d.03,%q\n", 40000+i, 1000+i, state, 10+i*7, note)
	}
	view, ok := narrowToQuery([]byte(b.String()), "refunded chargeback dispute")
	if !ok {
		t.Fatal("a CSV must narrow")
	}
	text := string(view)
	lines := strings.Split(text, "\n")
	if lines[0] != "txn_id,order_id,state,amount,note" {
		t.Fatalf("the header must head the view: %q", lines[0])
	}
	if strings.Count(text, "txn_id,order_id,state") != 1 {
		t.Fatalf("the header must appear exactly once: %q", text)
	}
	for _, line := range lines[1:] {
		line = strings.TrimSpace(line)
		if line == "" || line == nonAdjacentMarker {
			continue
		}
		// A whole row carries every column; a plucked fragment would not.
		if got := strings.Count(line, ","); got < 4 {
			t.Fatalf("a returned row is not whole (%d separators): %q", got, line)
		}
		if !strings.HasPrefix(line, "txn-") {
			t.Fatalf("a returned row does not start at a record boundary: %q", line)
		}
	}
	if !strings.Contains(text, nonAdjacentMarker) {
		t.Fatalf("the two matching rows are 20 apart and must be separated: %q", text)
	}
}

// TestQueryViewFallsBackToTheWholeOriginal is the safety valve: JSON whose records
// cannot be identified is never line-split, because a line of JSON is a fragment.
// Over-returning is safe; a fragment is not.
func TestQueryViewFallsBackToTheWholeOriginal(t *testing.T) {
	// A deeply nested config object — no array of records anywhere in it.
	nested := []byte(`{
  "service": {
    "name": "ledger",
    "limits": { "rps": 400, "burst": 900 },
    "status": "unfulfilled orders are retried"
  }
}`)
	if _, ok := narrowToQuery(nested, "unfulfilled status"); ok {
		t.Fatal("record-less JSON must fall back to the full original, not be line-split")
	}

	units, prelude := retrievalUnits(nested)
	if len(units) != 0 || prelude != "" {
		t.Fatalf("record-less JSON must yield no units, got %d: %q", len(units), units)
	}
}

// TestQueryViewKeepsNDJSONLinesWhole covers the one-JSON-object-per-line shape:
// event per line. Each line is already a whole unit, so the fix there is that
// non-adjacent events may never be returned touching.
func TestQueryViewKeepsNDJSONLinesWhole(t *testing.T) {
	var b strings.Builder
	for i := 0; i < 40; i++ {
		status := "attempted"
		if i%2 == 0 {
			status = "delivered"
		}
		fmt.Fprintf(&b, `{"delivery_id":"dlv-%04d","endpoint":"https://hooks.example/%d","status":"%s"}`+"\n",
			2000+i, i%3, status)
	}
	view, ok := narrowToQuery([]byte(b.String()), "delivered dlv-2018 dlv-2034")
	if !ok {
		t.Fatal("an NDJSON stream must narrow")
	}
	for _, line := range strings.Split(string(view), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || line == nonAdjacentMarker {
			continue
		}
		var event map[string]any
		if err := json.Unmarshal([]byte(line), &event); err != nil {
			t.Fatalf("an NDJSON event came back in pieces: %q", line)
		}
		if _, ok := event["delivery_id"]; !ok {
			t.Fatalf("event is missing its id: %q", line)
		}
	}
}

// TestEmptyQueryIsStillByteExact guards the contract the whole recovery path rests
// on: without a query, nothing about this file may touch the bytes.
func TestEmptyQueryIsStillByteExact(t *testing.T) {
	page := ordersPage(t)
	if narrowed, ok := narrowToQuery(page, "   "); ok {
		t.Fatalf("a blank query must not narrow: %q", narrowed)
	}
}

// Package safety is the engine's S0–S4 safety-class registry. Every compressor
// declares its class; the class is inherent to the compression method, not a
// user choice. The registry is the single place that answers two honesty
// questions about a class: does it change model-visible bytes, and does it
// require a recoverable record (CCR) before it may run.
//
// It is a leaf package (no engine dependency) so both the engine core and the
// compressors can import it without an import cycle.
package safety

// Class is a position on the engine's safety ladder.
type Class int

const (
	// S0 — byte-safe behavior (metadata, accounting). No model-visible bytes change.
	S0 Class = iota
	// S1 — provider-native hints (cache, routing). No model-visible bytes change.
	S1
	// S2 — structural changes that need SDK cooperation.
	S2
	// S3 — behavioral changes (routing, reasoning); eval-gated in Cloud.
	S3
	// S4 — lossy structural compression. Alters model-visible bytes, so it is
	// opt-in, must be reversible (CCR), and discloses what it dropped.
	S4
)

// Info describes the honesty contract of a safety class.
type Info struct {
	Class Class
	Name  string
	// ByteSafe is true when the class never alters model-visible bytes.
	ByteSafe bool
	// RequiresCCR is true when the class is lossy and may only run if the
	// original bytes are first stored for recovery.
	RequiresCCR bool
	// Reversible is true when the model-visible output retains the full value
	// without data dropped. S4 defaults false; method metadata can override for
	// lossless-to-model S4 transforms such as TOON.
	Reversible bool
}

var registry = map[Class]Info{
	S0: {Class: S0, Name: "S0", ByteSafe: true, RequiresCCR: false, Reversible: true},
	S1: {Class: S1, Name: "S1", ByteSafe: true, RequiresCCR: false, Reversible: true},
	S2: {Class: S2, Name: "S2", ByteSafe: false, RequiresCCR: false, Reversible: true},
	S3: {Class: S3, Name: "S3", ByteSafe: false, RequiresCCR: false, Reversible: false},
	S4: {Class: S4, Name: "S4", ByteSafe: false, RequiresCCR: true, Reversible: false},
}

// Lookup returns the Info for a class. The second return is false for an
// unknown class — callers fail closed (treat an unknown class as unsafe to run).
func Lookup(c Class) (Info, bool) {
	info, ok := registry[c]
	return info, ok
}

// Valid reports whether c is a registered class.
func (c Class) Valid() bool {
	_, ok := registry[c]
	return ok
}

// String returns the class name, or "S?" for an unknown class.
func (c Class) String() string {
	if info, ok := registry[c]; ok {
		return info.Name
	}
	return "S?"
}

package safety_test

import (
	"testing"

	"github.com/JuliusBrussee/caveman/engine/safety"
)

func TestKnownClasses(t *testing.T) {
	for _, c := range []safety.Class{safety.S0, safety.S1, safety.S2, safety.S3, safety.S4} {
		info, ok := safety.Lookup(c)
		if !ok {
			t.Fatalf("class %v should be registered", c)
		}
		if !c.Valid() {
			t.Errorf("class %v should be valid", c)
		}
		if info.Class != c {
			t.Errorf("info.Class = %v, want %v", info.Class, c)
		}
	}
}

func TestS4IsLossyAndRequiresCCR(t *testing.T) {
	info, _ := safety.Lookup(safety.S4)
	if info.ByteSafe {
		t.Error("S4 must not be byte-safe")
	}
	if !info.RequiresCCR {
		t.Error("S4 must require CCR recovery")
	}
	if info.Reversible {
		t.Error("S4 is not reversible by class; method metadata may override for TOON")
	}
}

func TestByteSafeClasses(t *testing.T) {
	for _, c := range []safety.Class{safety.S0, safety.S1} {
		info, _ := safety.Lookup(c)
		if !info.ByteSafe {
			t.Errorf("%v should be byte-safe", c)
		}
		if info.RequiresCCR {
			t.Errorf("%v must not require CCR", c)
		}
	}
}

func TestReversibleClasses(t *testing.T) {
	for _, c := range []safety.Class{safety.S0, safety.S1, safety.S2} {
		info, _ := safety.Lookup(c)
		if !info.Reversible {
			t.Errorf("%v should be reversible by class", c)
		}
	}
	for _, c := range []safety.Class{safety.S3, safety.S4} {
		info, _ := safety.Lookup(c)
		if info.Reversible {
			t.Errorf("%v should not be reversible by class", c)
		}
	}
}

func TestUnknownClassFailsClosed(t *testing.T) {
	unknown := safety.Class(99)
	if _, ok := safety.Lookup(unknown); ok {
		t.Error("unknown class must not be found")
	}
	if unknown.Valid() {
		t.Error("unknown class must not be valid")
	}
	if unknown.String() != "S?" {
		t.Errorf("unknown class String() = %q, want S?", unknown.String())
	}
}

package engine_test

import (
	"testing"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/compressors"
	"github.com/JuliusBrussee/caveman/engine/safety"
)

// fakeNonLossy is a byte-safe (S1, non-CCR) compressor used to exercise the
// Recoverable=true-by-class branch — no shipped compressor is non-lossy, so the
// only way to cover it is a synthetic one.
type fakeNonLossy struct{}

func (fakeNonLossy) ContentType() string               { return "fake" }
func (fakeNonLossy) SafetyClass() safety.Class         { return safety.S1 }
func (fakeNonLossy) Compress(in []byte) ([]byte, bool) { return []byte("x"), true }

// TestSimulateReportsReductionAndStoresNothing is the S13 acceptance: a unit dry-run
// on a fixture, no network, and — critically — no CCR write. It reports the token
// reduction a real Compress would achieve and leaves the recovery store empty.
func TestSimulateReportsReductionAndStoresNothing(t *testing.T) {
	e := newEngine(t) // backed by an in-memory CCR store

	sim := e.Simulate([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress})

	if sim.ContentType != engine.TypeJSON {
		t.Errorf("content type = %q, want json", sim.ContentType)
	}
	if sim.TokensSaved <= 0 || sim.TokensAfter >= sim.TokensBefore {
		t.Fatalf("expected a positive saving, got saved=%d (%d->%d)", sim.TokensSaved, sim.TokensBefore, sim.TokensAfter)
	}
	if sim.TokensSaved != sim.TokensBefore-sim.TokensAfter {
		t.Errorf("TokensSaved=%d inconsistent with before-after=%d", sim.TokensSaved, sim.TokensBefore-sim.TokensAfter)
	}
	if sim.TokenCountBasis == "" {
		t.Error("token_count_basis must disclose estimator")
	}
	if sim.Ratio <= 0 {
		t.Errorf("ratio = %v, want > 0", sim.Ratio)
	}
	if sim.SafetyClass != "S4" || !sim.Lossy {
		t.Errorf("json compressor is S4/lossy; got class=%q lossy=%v", sim.SafetyClass, sim.Lossy)
	}
	if sim.Method != "elision" {
		t.Errorf("method = %q, want elision", sim.Method)
	}
	if sim.LosslessToModel == nil || *sim.LosslessToModel {
		t.Errorf("lossless_to_model = %v, want explicit false", sim.LosslessToModel)
	}
	if !sim.Recoverable {
		t.Error("with a store present the saving is recoverable")
	}
	if sim.Basis != engine.BasisInferred {
		t.Errorf("basis = %q, want %q", sim.Basis, engine.BasisInferred)
	}

	// The defining property: Simulate performed NO CCR Put.
	stats, err := e.Stats()
	if err != nil {
		t.Fatalf("stats: %v", err)
	}
	if stats.Totals.Count != 0 {
		t.Errorf("Simulate must store nothing; CCR holds %d recoveries", stats.Totals.Count)
	}
}

// TestSimulateMatchesCompressAccounting checks that the dry-run matches Compress: its token
// accounting equals what a real Compress reports for the same input.
func TestSimulateMatchesCompressAccounting(t *testing.T) {
	e := newEngine(t)
	opts := engine.Options{Mode: engine.ModeCompress}

	sim := e.Simulate([]byte(arrayJSON), opts)
	res, err := e.Compress([]byte(arrayJSON), opts)
	if err != nil {
		t.Fatalf("compress: %v", err)
	}
	if sim.TokensBefore != res.TokensBefore || sim.TokensAfter != res.TokensAfter {
		t.Errorf("simulate (%d->%d) != compress (%d->%d)", sim.TokensBefore, sim.TokensAfter, res.TokensBefore, res.TokensAfter)
	}
	if sim.ContentType != res.ContentType || sim.Ratio != res.Ratio {
		t.Errorf("simulate (type=%q ratio=%v) != compress (type=%q ratio=%v)", sim.ContentType, sim.Ratio, res.ContentType, res.Ratio)
	}
}

// TestSimulateRecordAndPassThroughClaimNothing covers the pass-through conditions.
func TestSimulateRecordAndPassThroughClaimNothing(t *testing.T) {
	e := newEngine(t)

	// record mode never transforms.
	rec := e.Simulate([]byte(arrayJSON), engine.Options{Mode: engine.ModeRecord})
	if rec.TokensSaved != 0 || rec.Compressor != "" || rec.Ratio != 0 {
		t.Errorf("record mode must claim nothing: %+v", rec)
	}
	if !rec.Recoverable {
		t.Error("a pass-through is trivially recoverable")
	}

	// plain prose has no compressor → pass-through.
	txt := e.Simulate([]byte("just some ordinary prose with nothing to compress"), engine.Options{Mode: engine.ModeCompress})
	if txt.TokensSaved != 0 || txt.Compressor != "" {
		t.Errorf("plain text must claim nothing: %+v", txt)
	}
}

// TestSimulateLossyUnrecoverableWithoutStore is the honesty case: a lossy (S4)
// compressor with NO store. A real Compress fails closed to pass-through (zero
// reduction), but Simulate surfaces the would-be reduction as requiring CCR
// potential flagged Recoverable=false — never silently counted as achievable today.
func TestSimulateLossyUnrecoverableWithoutStore(t *testing.T) {
	e := engine.New(nil, nil) // no store

	sim := e.Simulate([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress})
	if sim.TokensSaved <= 0 {
		t.Fatalf("Simulate should surface the would-be saving even without a store, got %d", sim.TokensSaved)
	}
	if !sim.Lossy {
		t.Error("json is S4/lossy")
	}
	if sim.Recoverable {
		t.Error("without a store a lossy saving is NOT recoverable; must be flagged false")
	}

	// Contrast: a real Compress with no store passes through and claims nothing.
	res, err := e.Compress([]byte(arrayJSON), engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatalf("compress: %v", err)
	}
	if !res.PassedThrough() || res.Ratio != 0 {
		t.Errorf("Compress with no store must pass through (claim nothing); got ratio=%v handle=%q", res.Ratio, res.RecoveryHandle)
	}
}

// TestSimulateNonLossyRecoverableWithoutStore exercises the byte-safe branch: a
// non-lossy (S1) compressor's reduction is Recoverable even with NO store, because it
// needs no CCR. (Forces Options.Type since Detect never routes to "fake".)
func TestSimulateNonLossyRecoverableWithoutStore(t *testing.T) {
	reg := compressors.NewRegistry()
	reg.Register(fakeNonLossy{})
	e := engine.NewWithRegistry(nil, nil, reg) // no store

	sim := e.Simulate([]byte("a reasonably long input the fake compressor shrinks to one token"),
		engine.Options{Mode: engine.ModeCompress, Type: "fake"})

	if sim.TokensSaved <= 0 {
		t.Fatalf("expected a saving from the non-lossy compressor, got %d", sim.TokensSaved)
	}
	if sim.Lossy {
		t.Error("an S1 compressor is not lossy")
	}
	if !sim.Recoverable {
		t.Error("a byte-safe (non-CCR) saving is recoverable even with no store")
	}
	if sim.SafetyClass != "S1" {
		t.Errorf("safety class = %q, want S1", sim.SafetyClass)
	}
	if sim.Method != "fake" {
		t.Errorf("method = %q, want fake", sim.Method)
	}
	if sim.LosslessToModel == nil || !*sim.LosslessToModel {
		t.Errorf("lossless_to_model = %v, want true for S1", sim.LosslessToModel)
	}
}

func TestSimulateBestOfTOONIsLosslessToModelButNeedsCCRForByteExactRecovery(t *testing.T) {
	t.Setenv("CAVE_ENGINE_TOON", "best-of")
	counter := bestOfCounter{inputTokens: 100, toonTokens: 10, elisionTokens: 20}
	e := engine.New(nil, counter)

	sim := e.Simulate([]byte(bestOfJSONInput), engine.Options{Mode: engine.ModeCompress})
	if sim.Method != "toon" {
		t.Fatalf("method = %q, want toon", sim.Method)
	}
	if sim.Lossy {
		t.Fatal("TOON is lossless-to-model and must not be marked lossy")
	}
	if sim.LosslessToModel == nil || !*sim.LosslessToModel {
		t.Fatalf("lossless_to_model = %v, want true", sim.LosslessToModel)
	}
	if !sim.RequiresCCR {
		t.Fatal("TOON is S4 in v1 and still requires CCR for byte-exact recovery")
	}
	if sim.Recoverable {
		t.Fatal("without a store, byte-exact recovery must be false")
	}
}

func TestSimulateBestOfElisionRemainsLossy(t *testing.T) {
	t.Setenv("CAVE_ENGINE_TOON", "best-of")
	counter := bestOfCounter{inputTokens: 100, toonTokens: 20, elisionTokens: 10}
	e := engine.New(nil, counter)

	sim := e.Simulate([]byte(bestOfJSONInput), engine.Options{Mode: engine.ModeCompress})
	if sim.Method != "elision" {
		t.Fatalf("method = %q, want elision", sim.Method)
	}
	if !sim.Lossy {
		t.Fatal("elision drops data and must be marked lossy")
	}
	if sim.LosslessToModel == nil || *sim.LosslessToModel {
		t.Fatalf("lossless_to_model = %v, want false", sim.LosslessToModel)
	}
	if !sim.RequiresCCR {
		t.Fatal("elision requires CCR")
	}
}

