func TestDetectTerminal(t *testing.T) {
	e := engine.New(nil, nil)
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"ansi colors", "\x1b[32mPASS\x1b[0m all green\nbuilding...\ndone\n", engine.TypeTerminal},
		{"progress redraws", "fetch 10%\rfetch 40%\rfetch 80%\rfetch done\n", engine.TypeTerminal},
		{"plain prose stays text", "The quick brown fox jumps over the lazy dog.", engine.TypeText},
		{"crlf text not terminal", "line one\r\nline two\r\nline three\r\n", engine.TypeText},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := e.Detect([]byte(c.in)); got != c.want {
				t.Errorf("Detect(%s) = %q, want %q", c.name, got, c.want)
			}
		})
	}
}

// TestTerminalCompressRoundTrip checks the recoverable-RTK contract end to end:
// noisy command output is auto-detected as terminal, compressed (lossy, S4), and
// the byte-exact original is restored from the disclosed CCR handle.
func TestTerminalCompressRoundTrip(t *testing.T) {
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	e := engine.New(store, nil)

	var b strings.Builder
	b.WriteString("$ pytest -q\n")
	for i := 0; i < 60; i++ {
		fmt.Fprintf(&b, "\x1b[32m.\x1b[0m collected test_module_%d ok\n", i)
	}
	b.WriteString("E   AssertionError: token expiry uses < not <=\n")
	b.WriteString("auth/token.py:42: AssertionError\n")
	b.WriteString("1 failed, 60 passed in 2.10s\n")
	in := []byte(b.String())

	res, err := e.Compress(in, engine.Options{Mode: engine.ModeCompress})
	if err != nil {
		t.Fatal(err)
	}
	if res.ContentType != engine.TypeTerminal {
		t.Errorf("content type = %q, want terminal", res.ContentType)
	}
	if res.PassedThrough() {
		t.Fatal("expected noisy terminal output to compress")
	}
	if res.Ratio <= 0 || res.TokensAfter >= res.TokensBefore {
		t.Errorf("expected a positive ratio, got %v (%d->%d)", res.Ratio, res.TokensBefore, res.TokensAfter)
	}
	if res.Basis != engine.BasisInferred {
		t.Errorf("basis = %q, want inferred", res.Basis)
	}
	original, err := e.Retrieve(res.RecoveryHandle)
	if err != nil {
		t.Fatalf("retrieve: %v", err)
	}
	if !bytes.Equal(original, in) {
		t.Error("retrieve must return the byte-exact original (ANSI escapes and all)")
	}
}

// Package tokens counts tokens for the engine's compression ratios. Counts are
// local estimates; provider usage is authoritative downstream.
//
// The default counter is a real BPE tokenizer (OpenAI o200k_base) whose vocab is
// embedded in the binary, so counting is deterministic and fully offline. The
// Counter interface lets a per-provider tokenizer drop in later without touching
// any compressor.
package tokens

import (
	"sync"
	"unicode/utf8"

	"github.com/tiktoken-go/tokenizer"
)

// Counter estimates the token length of a payload. Implementations must be
// deterministic: the same bytes always yield the same count.
type Counter interface {
	// Count returns a local token estimate for b.
	Count(b []byte) int
	// Name identifies the counting basis (e.g. the encoding name) for display
	// and cross-surface parity.
	Name() string
}

// bpeCounter wraps an offline tiktoken codec.
type bpeCounter struct {
	name  string
	codec tokenizer.Codec
}

// NewBPECounter builds a counter for a tiktoken encoding (vocab is embedded, so
// no network access occurs).
func NewBPECounter(enc tokenizer.Encoding) (Counter, error) {
	codec, err := tokenizer.Get(enc)
	if err != nil {
		return nil, err
	}
	return &bpeCounter{name: string(enc), codec: codec}, nil
}

func (c *bpeCounter) Name() string { return c.name }

func (c *bpeCounter) Count(b []byte) int {
	if len(b) == 0 {
		return 0
	}
	n, err := c.codec.Count(string(b))
	if err != nil {
		// A counting error never breaks compression; fall back to the
		// deterministic approximation rather than guessing or panicking.
		return approxTokens(b)
	}
	return n
}

// approxCounter is a deterministic byte/rune-based estimate used as a fallback
// and where a BPE codec is unnecessary. ~4 characters per token is the widely
// used rule of thumb for English-weighted text.
type approxCounter struct{}

// NewApproxCounter returns the deterministic ~chars/4 estimator.
func NewApproxCounter() Counter { return approxCounter{} }

func (approxCounter) Name() string { return "approx-chars/4" }

func (approxCounter) Count(b []byte) int { return approxTokens(b) }

func approxTokens(b []byte) int {
	if len(b) == 0 {
		return 0
	}
	runes := utf8.RuneCount(b)
	n := runes / 4
	if n < 1 {
		n = 1
	}
	return n
}

var (
	defaultOnce sync.Once
	defaultCtr  Counter
)

// Default returns the engine's shared default counter: the o200k_base BPE
// tokenizer (the GPT-4o-family encoding), used across every content type. If
// the embedded codec cannot be loaded — a build-time
// invariant that should never fail at runtime — it degrades to the deterministic
// approximation so the engine never crashes.
func Default() Counter {
	defaultOnce.Do(func() {
		if c, err := NewBPECounter(tokenizer.O200kBase); err == nil {
			defaultCtr = c
		} else {
			defaultCtr = NewApproxCounter()
		}
	})
	return defaultCtr
}

package tokens_test

import (
	"testing"

	"github.com/JuliusBrussee/caveman/engine/tokens"
)

func TestDefaultCounterCountsAndIsDeterministic(t *testing.T) {
	c := tokens.Default()
	text := []byte("the quick brown fox jumps over the lazy dog")
	n1 := c.Count(text)
	n2 := c.Count(text)
	if n1 <= 0 {
		t.Fatalf("expected a positive token count, got %d", n1)
	}
	if n1 != n2 {
		t.Errorf("counting must be deterministic: %d != %d", n1, n2)
	}
}

func TestEmptyIsZero(t *testing.T) {
	if n := tokens.Default().Count(nil); n != 0 {
		t.Errorf("empty input must count 0, got %d", n)
	}
}

func TestApproxCounter(t *testing.T) {
	c := tokens.NewApproxCounter()
	if got := c.Count([]byte("abcdefgh")); got != 2 { // 8 runes / 4
		t.Errorf("approx count = %d, want 2", got)
	}
	if got := c.Count([]byte("x")); got != 1 {
		t.Errorf("non-empty must count at least 1, got %d", got)
	}
}

func TestLongerTextCountsMore(t *testing.T) {
	c := tokens.Default()
	short := c.Count([]byte("hello"))
	long := c.Count([]byte("hello hello hello hello hello hello hello hello"))
	if long <= short {
		t.Errorf("longer text should count more tokens: long=%d short=%d", long, short)
	}
}

package engine

import (
	"encoding/json"
	"fmt"

	"github.com/JuliusBrussee/caveman/engine/compressors"
)

// EncodeTOON converts JSON to the lossless TOON subset without CCR or size
// gating. It is for explicit agent/CLI requests, not automatic proxy routing.
func (e *Engine) EncodeTOON(input []byte) ([]byte, error) {
	out, ok := compressors.NewTOON().Compress(input)
	if !ok {
		return nil, fmt.Errorf("not losslessly TOON-encodable (invalid JSON, or nested/non-uniform shape); keep JSON")
	}
	return out, nil
}

// DecodeTOON converts TOON back to compact JSON. Malformed TOON fails closed.
func (e *Engine) DecodeTOON(input []byte) ([]byte, error) {
	v, ok := compressors.DecodeTOON(input)
	if !ok {
		return nil, fmt.Errorf("not valid TOON")
	}
	out, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return out, nil
}
